INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('re-cinq/wave/tui', 'community', 're-cinq', 'wave', 're-cinq/wave', 'tui', 7, 0, 60, '2026-02-27T09:06:00Z', '2026-03-06T06:50:49.695Z', '38a4e850c74a203ce59b49bcb41baf0b603f677b652a412c2a90bdae775812e5', '{"id":"re-cinq/wave/tui","name":"tui","description":{"en":"The tui skill enables developers to create interactive terminal applications and command-line interfaces with rich UI. It specializes in cross-platform terminal libraries and responsive terminal layouts.","zh":"TUI是一种用于创建交互式终端应用程序和命令行界面的技术，支持跨平台终端库和响应式终端布局","ja":"TUIは、インタラクティブなターミナルアプリケーションとコマンドラインインターフェースを作成するための技術です。クロスプラットフォームのターミナルライブラリとレスポンシブターミナルレイアウトをサポートします","ko":"TUI는 상호 작용형 터미널 애플리케이션과 명령줄 인터페이스를 생성하기 위한 기술로, 크로스 플랫폼 터미널 라이브러리 및 반응형 터미널 레이아웃을 지원합니다","es":"TUI es un experto en interfaces de usuario de terminal que ayuda a crear aplicaciones de terminal interactivas y paneles de control de terminal","fr":"TUI est un expert en interfaces utilisateur de terminal qui aide à créer des applications de terminal interactives et des tableaux de bord de terminal","de":"TUI ist ein Experte für Terminalbenutzeroberflächen, der bei der Erstellung interaktiver Terminalanwendungen und Terminal-Steuerungselementen hilft","pt":"TUI é uma tecnologia para criar aplicações de console interativas, incluindo interfaces de linha de comando e painéis baseados em terminal","ru":"TUI - это технология для создания интерактивных терминальных приложений, включая командные интерфейсы и панели управления","ar":"TUI هو تكنولوجيا لإنشاء تطبيقات واجهة المستخدم终端 التفاعلية، بما في ذلك واجهات سطر الأوامر واللوحات المعتمدة على الطرفية"},"seo":{"title":{"en":"tui: Setup Guide for AI-Assisted Terminal Applications | ...","zh":"TUI Setup Guide: AI助手终端用户界面开发","ja":"TUIベストプラクティス: AIエージェントのターミナルユーザーインターフェース","ko":"TUI 구축 가이드: AI 에이전트 터미널 사용자 인터페이스","es":"Guía de configuración de TUI para aplicaciones de termina...","fr":"Guide de mise en place de TUI pour des applications de te...","de":"TUI-Setup-Leitfaden für interaktive Terminalanwendungen","pt":"Guia de Configuração TUI para Desenvolvimento de Interfac...","ru":"ИИ Агенты: Руководство по Настройке TUI для Терминальных ...","ar":"دليل إعداد واجهة المستخدم终端 TUI للأجهزة الذكية"},"description":{"en":"Discover how to leverage tui for building interactive terminal applications and cross-platform terminal libraries. Learn more and get started today!","zh":"学习如何使用TUI创建交互式终端应用程序、命令行界面和基于终端的仪表板","ja":"TUIを使用してインタラクティブなターミナルアプリケーション、コマンドラインインターフェース、ターミナルベースのダッシュボードを構築する方法を学びましょう","ko":"TUI를 사용하여 상호 작용형 터미널 애플리케이션, 명령줄 인터페이스 및 터미널 기반 대시보드를 구축하는 방법을 알아보세요","es":"Aprende a crear aplicaciones de terminal interactivas con TUI, incluyendo interfaces de línea de comandos y paneles de control de terminal","fr":"Découvrez comment créer des applications de terminal interactives avec TUI, y compris des interfaces de ligne de commande et des tableaux de bord de terminal","de":"Erfahren Sie, wie Sie interaktive Terminalanwendungen mit TUI erstellen, einschließlich Kommandozeilen-Schnittstellen und Terminal-Steuerungselementen","pt":"Aprenda a criar aplicações de console interativas com TUI, incluindo interfaces de linha de comando e painéis baseados em terminal","ru":"Откройте для себя возможности TUI для создания интерактивных терминальных приложений и панелей управления","ar":"اكتشف كيف يمكنك إنشاء تطبيقات واجهة المستخدم终端 التفاعلية باستخدام TUI، بما في ذلك واجهات سطر الأوامر واللوحات المعتمدة على الطرفية"},"definition":{"en":"tui is a Terminal User Interface expert specializing in interactive console applications and cross-platform terminal libraries.","zh":"TUI是终端用户界面的缩写，指的是一种用于创建交互式终端应用程序的技术","ja":"TUIはターミナルユーザーインターフェースの略称であり、インタラクティブなターミナルアプリケーションを作成するための技術を指します","ko":"TUI는 터미널 사용자 인터페이스의 약자이며, 상호 작용형 터미널 애플리케이션을 생성하기 위한 기술을指します","es":"TUI es una tecnología de interfaz de usuario de terminal que permite crear aplicaciones de terminal interactivas y personalizadas","fr":"TUI est une technologie d''interface utilisateur de terminal qui permet de créer des applications de terminal interactives et personnalisées","de":"TUI ist eine Technologie für Terminalbenutzeroberflächen, die die Erstellung interaktiver und anpassbarer Terminalanwendungen ermöglicht","pt":"TUI é uma tecnologia de interface de usuário para criar aplicações de console interativas","ru":"TUI - это технология интерфейса пользователя для создания интерактивных терминальных приложений","ar":"TUI هو تكنولوجيا واجهة المستخدم لإنشاء تطبيقات واجهة المستخدم终端 التفاعلية"},"features":{"en":["Creates interactive terminal applications with rich UI","Builds command-line interfaces using cross-platform terminal libraries","Implements terminal-based dashboards and tools","Supports responsive terminal layouts for enhanced user experience","Utilizes multi-agent pipelines for AI-assisted development"],"zh":["创建交互式终端应用程序","构建命令行界面","实现基于终端的仪表板","支持跨平台终端库","响应式终端布局"],"ja":["インタラクティブなターミナルアプリケーションの作成","コマンドラインインターフェースの構築","ターミナルベースのダッシュボードの実装","クロスプラットフォームのターミナルライブラリのサポート","レスポンシブターミナルレイアウト"],"ko":["상호 작용형 터미널 애플리케이션 생성","명령줄 인터페이스 구축","터미널 기반 대시보드 구현","크로스 플랫폼 터미널 라이브러리 지원","반응형 터미널 레이아웃"],"es":["Creación de aplicaciones de terminal interactivas","Interfaces de línea de comandos enriquecidas","Paneles de control de terminal personalizables","Compatibilidad con bibliotecas de terminal multiplataforma","Diseños de terminal responsivos"],"fr":["Création d''applications de terminal interactives","Interfaces de ligne de commande enrichies","Tableaux de bord de terminal personnalisables","Compatibilité avec des bibliothèques de terminal multiplateformes","Conceptions de terminal réactives"],"de":["Erstellung interaktiver Terminalanwendungen","Erweiterte Kommandozeilen-Schnittstellen","Anpassbare Terminal-Steuerungselemente","Unterstützung für multiplattformfähige Terminalbibliotheken","Reaktive Terminal-Layouts"],"pt":["Criação de aplicações de console interativas","Interfaces de linha de comando ricas","Painéis baseados em terminal responsivos","Bibliotecas de terminal cross-platform","Layouts de terminal personalizáveis"],"ru":["Создание интерактивных терминальных приложений","Богатые командные интерфейсы","Панели управления на основе терминала","Кроссплатформенные терминальные библиотеки","Настраиваемые макеты терминала"],"ar":["إنشاء تطبيقات واجهة المستخدم终端 التفاعلية","واجهات سطر الأوامر الغنية","اللوحات المعتمدة على الطرفية المتفاعلة","مكتبات الطرفية متعددة المنصات","تخطيطات الطرفية القابلة للتعديل"]},"keywords":{"en":["how to use tui","tui setup guide","tui alternative","tui vs terminal libraries","what is tui","tui install","tui for AI-assisted development","cross-platform terminal applications","interactive terminal UI"],"zh":["TUI","终端用户界面","交互式终端应用程序","命令行界面","基于终端的仪表板","跨平台终端库","响应式终端布局","AI助手","终端开发"],"ja":["TUI","ターミナルユーザーインターフェース","インタラクティブなターミナルアプリケーション","コマンドラインインターフェース","ターミナルベースのダッシュボード","クロスプラットフォームのターミナルライブラリ","レスポンシブターミナルレイアウト","AIエージェント","ターミナル開発"],"ko":["TUI","터미널 사용자 인터페이스","상호 작용형 터미널 애플리케이션","명령줄 인터페이스","터미널 기반 대시보드","크로스 플랫폼 터미널 라이브러리","반응형 터미널 레이아웃","AI 에이전트","터미널 개발"],"es":["TUI","aplicaciones de terminal interactivas","interfaces de línea de comandos","paneles de control de terminal","bibliotecas de terminal multiplataforma","diseños de terminal responsivos","herramientas de terminal","desarrollo de aplicaciones de terminal"],"fr":["TUI","applications de terminal interactives","interfaces de ligne de commande","tableaux de bord de terminal","bibliothèques de terminal multiplateformes","conceptions de terminal réactives","outils de terminal","développement d''applications de terminal"],"de":["TUI","interaktive Terminalanwendungen","Kommandozeilen-Schnittstellen","Terminal-Steuerungselemente","multiplattformfähige Terminalbibliotheken","reaktive Terminal-Layouts","Terminal-Tools","Entwicklung von Terminalanwendungen"],"pt":["tui","interface de console","aplicações de terminal","desenvolvimento de interfaces","bibliotecas de terminal","layout de terminal","terminal cross-platform"],"ru":["tui","ИИ Агенты","терминальные приложения","интерфейс пользователя","командные интерфейсы","панели управления","кроссплатформенные библиотеки"],"ar":["tui","واجهة المستخدم终端","تطبيقات الطرفية","تطوير واجهات","مكتبات الطرفية","تخطيط الطرفية","الطرفية متعددة المنصات"]}},"owner":"re-cinq","repo":"wave","repoPath":"re-cinq/wave","stars":7,"forks":0,"updatedAt":"2026-02-27T09:06:00Z","topics":["agentic-workflow","ai-as-code","multi-agent-systems"],"category":"community","skillMd":{"name":"tui","description":"Expert terminal user interface development including interactive console applications, cross-platform TUI libraries, and responsive terminal layouts","bodyPreview":"## User Input\n\n```text\n$ARGUMENTS\n```\n\nYou **MUST** consider the user input before proceeding (if not empty).\n\n## Outline\n\nYou are a Terminal User Interface (TUI) expert specializing in interactive console applications, cross-platform terminal libraries, and responsive terminal layouts. Use this skill when the user needs help with:\n\n- Creating interactive terminal applications\n- Building command-line interfaces with rich UI\n- Implementing terminal-based dashboards and tools\n- Cross-platform TUI","body":"## User Input\n\n```text\n$ARGUMENTS\n```\n\nYou **MUST** consider the user input before proceeding (if not empty).\n\n## Outline\n\nYou are a Terminal User Interface (TUI) expert specializing in interactive console applications, cross-platform terminal libraries, and responsive terminal layouts. Use this skill when the user needs help with:\n\n- Creating interactive terminal applications\n- Building command-line interfaces with rich UI\n- Implementing terminal-based dashboards and tools\n- Cross-platform TUI development\n- Terminal event handling and input processing\n- Layout management and responsive design in terminals\n\n## TUI Libraries and Frameworks\n\n### 1. Go TUI Libraries\n- **Bubbletea**: Modern, idiomatic Go TUI framework\n- **tview**: Rich interactive widgets and flexible layouts\n- **tcell**: Low-level terminal manipulation library\n- **termui**: Dashboard and monitoring UI components\n- **lipgloss**: Styling and colors for terminal applications\n\n### 2. Rust TUI Libraries\n- **ratatui**: Modern Rust TUI library (successor to tui-rs)\n- **crossterm**: Cross-platform terminal handling\n- **tui-rs**: Original terminal UI library\n- **iced**: GUI and TUI hybrid framework\n\n### 3. Python TUI Libraries\n- **Rich**: Rich text and beautiful formatting\n- **Textual**: Modern TUI framework for Python\n- **curses**: Traditional terminal interface library\n- **urwid**: Flexible console UI library\n\n### 4. Node.js TUI Libraries\n- **Inquirer.js**: Interactive command-line prompts\n- **Blessed**: Terminal interface library\n- **ink**: React for CLIs\n- **oclif**: CLI framework with rich output\n\n## Core TUI Concepts\n\n### 1. Terminal Capabilities\n- **Screen size detection**: Handle resizing and variable dimensions\n- **Color support**: ANSI colors, 256-color, RGB\n- **Input handling**: Keyboard, mouse, clipboard events\n- **Cross-platform**: Windows (cmd/PowerShell), macOS (Terminal.app), Linux (xterm/gnome-terminal)\n- **Performance**: Efficient rendering and event loops\n\n### 2. Layout Systems\n- **Grid layouts**: CSS Grid-like arrangements\n- **Flexbox**: Flexible box layouts\n- **Absolute positioning**: Precise coordinate placement\n- **Responsive design**: Adaptive layouts for different terminal sizes\n- **Scrolling**: Viewports and content pagination\n\n### 3. Interactive Components\n- **Menus and navigation**: Keyboard-driven interfaces\n- **Forms and input**: Text fields, checkboxes, radio buttons\n- **Tables and lists**: Sortable, filterable data displays\n- **Progress indicators**: Bars, spinners, status displays\n- **Dialogs**: Modals, confirmations, notifications\n\n## TUI Development Patterns\n\n### Bubbletea (Go) Example\n```go\npackage main\n\nimport (\n    \"fmt\"\n    \"strings\"\n    tea \"github.com/charmbracelet/bubbletea\"\n    \"github.com/charmbracelet/lipgloss\"\n)\n\ntype model struct {\n    choices []string\n    cursor  int\n    selected string\n}\n\nfunc initialModel() model {\n    return model{\n        choices: []string{\"Option 1\", \"Option 2\", \"Option 3\"},\n        cursor:  0,\n    }\n}\n\nfunc (m model) Init() tea.Cmd {\n    return nil\n}\n\nfunc (m model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {\n    switch msg := msg.(type) {\n    case tea.KeyMsg:\n        switch msg.Type {\n        case tea.KeyUp:\n            if m.cursor > 0 {\n                m.cursor--\n            }\n        case tea.KeyDown:\n            if m.cursor < len(m.choices)-1 {\n                m.cursor++\n            }\n        case tea.KeyEnter:\n            m.selected = m.choices[m.cursor]\n            return m, tea.Quit\n        }\n    }\n    return m, nil\n}\n\nfunc (m model) View() string {\n    s := strings.Builder{}\n    s.WriteString(\"What should we buy at the market?\\n\\n\")\n\n    for i, choice := range m.choices {\n        cursor := \" \"\n        if m.cursor == i {\n            cursor = \">\"\n        }\n        s.WriteString(fmt.Sprintf(\"%s %s\\n\", cursor, choice))\n    }\n\n    s.WriteString(\"\\nPress q to quit.\\n\")\n    return s.String()\n}\n\nfunc main() {\n    p := tea.NewProgram(initialModel())\n    if _, err := p.Run(); err != nil {\n        fmt.Printf(\"Alas, there''s been an error: %v\", err)\n    }\n}\n```\n\n### Ratatui (Rust) Example\n```rust\nuse ratatui::{\n    backend::CrosstermBackend,\n    layout::{Constraint, Direction, Layout},\n    style::{Color, Modifier, Style},\n    text::Span,\n    widgets::{Block, Borders, List, ListItem, Paragraph},\n    Terminal,\n};\n\nstruct App {\n    items: Vec<String>,\n    selected: usize,\n}\n\nimpl App {\n    fn new() -> Self {\n        Self {\n            items: vec![\n                \"Item 1\".to_string(),\n                \"Item 2\".to_string(),\n                \"Item 3\".to_string(),\n            ],\n            selected: 0,\n        }\n    }\n\n    fn next(&mut self) {\n        self.selected = (self.selected + 1) % self.items.len();\n    }\n\n    fn previous(&mut self) {\n        self.selected = if self.selected > 0 {\n            self.selected - 1\n        } else {\n            self.items.len() - 1\n        };\n    }\n}\n\nfn ui(f: &mut Frame, app: &App) {\n    let chunks = Layout::default()\n        .direction(Direction::Vertical)\n        .margin(1)\n        .constraints(\n            [\n                Constraint::Percentage(50),\n                Constraint::Percentage(50),\n            ]\n            .as_ref(),\n        )\n        .split(f.size());\n\n    let items: Vec<ListItem> = app\n        .items\n        .iter()\n        .enumerate()\n        .map(|(i, item)| {\n            let style = if i == app.selected {\n                Style::default().bg(Color::LightBlue)\n            } else {\n                Style::default()\n            };\n            ListItem::new(Span::styled(item.as_str(), style))\n        })\n        .collect();\n\n    let list = List::new(items)\n        .block(Block::default().borders(Borders::ALL).title(\"List\"));\n    f.render_widget(list, chunks[0]);\n\n    let paragraph = Paragraph::new(format!(\"Selected item: {}\", app.items[app.selected]))\n        .block(Block::default().borders(Borders::ALL).title(\"Details\"));\n    f.render_widget(paragraph, chunks[1]);\n}\n\nfn main() -> Result<(), Box<dyn std::error::Error>> {\n    let stdout = io::stdout();\n    let backend = CrosstermBackend::new(stdout, TerminalOptions::default())?;\n    let mut terminal = Terminal::new(backend)?;\n    \n    let mut app = App::new();\n    \n    loop {\n        terminal.draw(|f| ui(f, &app))?;\n        \n        if let Event::Key(key) = event::read()? {\n            match key {\n                KeyEvent::Left => app.previous(),\n                KeyEvent::Right => app.next(),\n                KeyEvent::Char(''q'') => break,\n                _ => {}\n            }\n        }\n    }\n    \n    Ok(())\n}\n```\n\n### Rich (Python) Example\n```python\nfrom rich.console import Console\nfrom rich.layout import Layout\nfrom rich.panel import Panel\nfrom rich.table import Table\nfrom rich.progress import Progress, SpinnerColumn, TextColumn\n\nconsole = Console()\n\n# Create a layout\nlayout = Layout()\nlayout.split_column(\n    Layout(name=\"header\", size=3),\n    Layout(name=\"main\"),\n    Layout(name=\"footer\", size=3)\n)\n\n# Create a table\ntable = Table(title=\"Projects\")\ntable.add_column(\"ID\", style=\"cyan\", no_wrap=True)\ntable.add_column(\"Name\", style=\"magenta\")\ntable.add_column(\"Status\", style=\"green\")\n\ntable.add_row(\"1\", \"Project Alpha\", \"Active\")\ntable.add_row(\"2\", \"Project Beta\", \"Complete\")\n\n# Main loop\nwith console.screen() as screen:\n    while True:\n        layout[\"header\"].update(Panel(\"Dashboard\", style=\"bold blue\"))\n        layout[\"main\"].update(Panel(table))\n        layout[\"footer\"].update(Panel(\"Press ''q'' to quit\"))\n        \n        console.print(layout)\n        \n        # Handle input (simplified)\n        if console.input(\"Continue? (y/n): \").lower() == ''n'':\n            break\n```\n\n## Input Handling Patterns\n\n### Cross-Platform Input Events\n```go\n// Go with Bubbletea - platform-abstracted\nfunc (m model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {\n    switch msg := msg.(type) {\n    case tea.KeyMsg:\n        switch msg.Type {\n        case tea.KeyCtrlC:\n            return m, tea.Quit\n        case tea.KeyUp, tea.KeyCtrlP:\n            // Up arrow or Ctrl+P\n            if m.cursor > 0 {\n                m.cursor--\n            }\n        case tea.KeyDown, tea.KeyCtrlN:\n            // Down arrow or Ctrl+N\n            if m.cursor < len(m.items)-1 {\n                m.cursor++\n            }\n        case tea.KeyEnter:\n            m.selected = m.items[m.cursor]\n        }\n    case tea.WindowSizeMsg:\n        m.width = msg.Width\n        m.height = msg.Height\n    }\n    return m, nil\n}\n```\n\n### Complex Input Handling\n```rust\n// Rust with crossterm\nuse crossterm::{\n    event::{self, Event, KeyCode, KeyEvent},\n    execute,\n    terminal::{disable_raw_mode, enable_raw_mode},\n};\n\nfn handle_input() -> Result<(), Box<dyn std::error::Error>> {\n    enable_raw_mode()?;\n    \n    loop {\n        match event::read()? {\n            Event::Key(KeyEvent { code, .. }) => match code {\n                KeyCode::Char(''q'') => break,\n                KeyCode::Up => handle_up(),\n                KeyCode::Down => handle_down(),\n                KeyCode::Enter => handle_select(),\n                KeyCode::Esc => handle_escape(),\n                _ => {}\n            },\n            Event::Resize(_, _) => redraw_ui(),\n            Event::Mouse(_) => handle_mouse_event(),\n        }\n    }\n    \n    disable_raw_mode()?;\n    Ok(())\n}\n```\n\n## Layout and Responsive Design\n\n### Responsive Layout Algorithm\n```go\ntype LayoutConstraints struct {\n    MinWidth  int\n    MaxWidth  int\n    MinHeight int\n    MaxHeight int\n}\n\nfunc calculateLayout(termWidth, termHeight int, items []Widget) []Rect {\n    var layout []Rect\n    \n    // Simple responsive grid\n    cols := max(1, termWidth/40) // Minimum 40 chars per column\n    rows := (len(items) + cols - 1) / cols\n    \n    itemWidth := termWidth / cols\n    itemHeight := termHeight / rows\n    \n    for i, item := range items {\n        row := i / cols\n        col := i % cols\n        \n        x := col * itemWidth\n        y := row * itemHeight\n        \n        layout = append(layout, Rect{\n            X: x, Y: y,\n            Width: itemWidth, Height: itemHeight,\n        })\n    }\n    \n    return layout\n}\n```\n\n### Adaptive Component Layout\n```rust\nstruct ResponsiveLayout {\n    layouts: HashMap<TerminalSize, Layout>,\n    current: Layout,\n}\n\nimpl ResponsiveLayout {\n    fn update_for_size(&mut self, size: TerminalSize) {\n        self.current = self.layouts\n            .get(&size)\n            .unwrap_or_else(|| self.calculate_adaptive_layout(size))\n    }\n    \n    fn calculate_adaptive_layout(&self, size: TerminalSize) -> Layout {\n        if size.width < 80 {\n            // Mobile-style vertical layout\n            self.vertical_layout()\n        } else if size.width < 120 {\n            // Tablet-style mixed layout\n            self.mixed_layout()\n        } else {\n            // Desktop-style horizontal layout\n            self.horizontal_layout()\n        }\n    }\n}\n```\n\n## When to Use This Skill\n\nUse this skill when you need to:\n- Create interactive terminal applications\n- Build command-line tools with rich user interfaces\n- Design terminal dashboards and monitoring tools\n- Implement cross-platform console applications\n- Handle complex user input in terminals\n- Create responsive terminal layouts\n- Build interactive system administration tools\n- Develop terminal-based productivity applications\n\n## Best Practices\n\n### 1. Performance\n- Use efficient rendering (double buffering, differential updates)\n- Minimize redraws and optimize event loops\n- Handle large datasets with virtual scrolling\n\n### 2. Accessibility\n- Provide keyboard navigation for all interactions\n- Support high contrast and color-blind friendly themes\n- Include clear visual indicators and status messages\n\n### 3. Cross-Platform Compatibility\n- Test on Windows, macOS, and Linux terminals\n- Handle different terminal capabilities gracefully\n- Provide fallbacks for limited terminal features\n\n### 4. User Experience\n- Include help text and keyboard shortcuts\n- Provide progress indicators for long operations\n- Implement undo/redo where appropriate\n- Save and restore application state\n\n## Testing TUI Applications\n\n### Unit Testing Components\n```go\nfunc TestModelUpdate(t *testing.T) {\n    tests := []struct {\n        name     string\n        model    model\n        msg       tea.Msg\n        expected  model\n    }{\n        {\n            name:     \"cursor up from first item\",\n            model:    model{cursor: 0, items: []string{\"a\", \"b\"}},\n            msg:       tea.KeyMsg{Type: tea.KeyUp},\n            expected:  model{cursor: 0, items: []string{\"a\", \"b\"}}, // Can''t go up from first\n        },\n    }\n    \n    for _, tt := range tests {\n        t.Run(tt.name, func(t *testing.T) {\n            updated, _ := tt.model.Update(tt.msg)\n            assert.Equal(t, tt.expected, updated)\n        })\n    }\n}\n```\n\n### Integration Testing\n```python\ndef test_full_workflow(capsys):\n    \"\"\"Test complete TUI workflow\"\"\"\n    # Simulate user input\n    with patch(''builtins.input'', return_value=''test\\n''):\n        app.run()\n    \n    # Check output\n    captured = capsys.readouterr()\n    assert ''Welcome'' in captured.out\n    assert ''Goodbye'' in captured.out\n```\n\nAlways prioritize:\n- Responsive design for different terminal sizes\n- Intuitive keyboard navigation\n- Clear visual hierarchy and feedback\n- Cross-platform compatibility\n- Performance and efficiency"},"lastSynced":"2026-03-06T06:50:49.695Z","agentAnalysis":{"suitability":{"en":"Ideal for Terminal-based Agents needing to create interactive command-line interfaces with cross-platform compatibility","zh":"适用于需要创建具有跨平台兼容性的交互式命令行接口的基于终端的代理","ja":"ターミナルベースのエージェントがクロスプラットフォーム互換性のあるインタラクティブなコマンドラインインターフェイスを作成する必要がある場合に適している","ko":"터미널 기반 에이전트가 크로스 플랫폼 호환성을 갖춘 대화형 명령줄 인터페이스를 생성해야 하는 경우에 적합합니다","es":"Ideal para Agentes basados en Terminal que necesitan crear interfaces de línea de comandos interactivas con compatibilidad entre plataformas","fr":"Idéal pour les Agents basés sur Terminal nécessitant la création d''interfaces de ligne de commande interactives avec une compatibilité multiplateforme","de":"Ideal für Terminal-basierte Agenten, die interaktive K