INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('re-cinq/wave/tui', 'tui', 're-cinq', 'wave', 'community', 'tui re-cinq wave community agentic-workflow ai-as-code multi-agent-systems The tui skill enables developers to create interactive terminal applications and command-line interfaces with rich UI. It specializes in cross-platform terminal libraries and responsive terminal layouts. TUI是一种用于创建交互式终端应用程序和命令行界面的技术，支持跨平台终端库和响应式终端布局 TUIは、インタラクティブなターミナルアプリケーションとコマンドラインインターフェースを作成するための技術です。クロスプラットフォームのターミナルライブラリとレスポンシブターミナルレイアウトをサポートします TUI는 상호 작용형 터미널 애플리케이션과 명령줄 인터페이스를 생성하기 위한 기술로, 크로스 플랫폼 터미널 라이브러리 및 반응형 터미널 레이아웃을 지원합니다 TUI es un experto en interfaces de usuario de terminal que ayuda a crear aplicaciones de terminal interactivas y paneles de control de terminal TUI est un expert en interfaces utilisateur de terminal qui aide à créer des applications de terminal interactives et des tableaux de bord de terminal TUI ist ein Experte für Terminalbenutzeroberflächen, der bei der Erstellung interaktiver Terminalanwendungen und Terminal-Steuerungselementen hilft TUI é uma tecnologia para criar aplicações de console interativas, incluindo interfaces de linha de comando e painéis baseados em terminal TUI - это технология для создания интерактивных терминальных приложений, включая командные интерфейсы и панели управления TUI هو تكنولوجيا لإنشاء تطبيقات واجهة المستخدم终端 التفاعلية، بما في ذلك واجهات سطر الأوامر واللوحات المعتمدة على الطرفية how to use tui tui setup guide tui alternative tui vs terminal libraries what is tui tui install tui for AI-assisted development cross-platform terminal applications interactive terminal UI TUI 终端用户界面 交互式终端应用程序 命令行界面 基于终端的仪表板 跨平台终端库 响应式终端布局 AI助手 终端开发 Creates interactive terminal applications with rich UI Builds command-line interfaces using cross-platform terminal libraries Implements terminal-based dashboards and tools Supports responsive terminal layouts for enhanced user experience Utilizes multi-agent pipelines for AI-assisted development tui is a Terminal User Interface expert specializing in interactive console applications and cross-platform terminal libraries.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('conornash/dot-emacs/emacs', 'community', 'conornash', 'dot-emacs', 'conornash/dot-emacs', 'emacs', 6, 0, 60, '2026-01-07T06:44:18Z', '2026-03-06T06:52:13.589Z', 'a2aa19f26ac9ca66184d4d33337787e7daf7ac1ca871f9fbbf511b9b45806d36', '{"id":"conornash/dot-emacs/emacs","name":"emacs","description":{"en":"The Emacs skill enables AI agents to evaluate Emacs Lisp in a running Emacs instance, ideal for developers seeking to leverage semantic operations and project-aware file finding.","zh":"Emacs配置是提高开发效率的关键，了解Elisp和LSP-aware操作可以帮助您更好地使用Emacs","ja":"Emacsの設定は開発の生産性を向上させる鍵です。ElispとLSP-aware操作をマスターしましょう","ko":"Emacs 설정은 개발 생산성을 향상시키는 핵심입니다. Elisp와 LSP-aware操作을 알아보세요","es":"Emacs es un editor de texto altamente configurable que admite operaciones semánticas con herramientas como eglot-rename y xref-find-references","fr":"Emacs est un éditeur de texte hautement personnalisable qui prend en charge les opérations sémantiques avec des outils tels que eglot-rename et xref-find-references","de":"Emacs ist ein hoch konfigurierbarer Texteditor, der semantische Operationen mit Tools wie eglot-rename und xref-find-references unterstützt","pt":"O Emacs é um editor de texto poderoso que pode ser personalizado com configurações avançadas. Aprenda a usá-lo para operações semânticas e outras funcionalidades.","ru":"Emacs - это мощный текстовый редактор, который можно настроить с помощью продвинутых конфигураций. Узнайте, как использовать его для семантических операций и других функций.","ar":"الemacs هو محرر نص قوي يمكن تخصيصه باستخدام إعدادات متقدمة. تعلم كيفية استخدامه للعمليات الدلالية والوظائف الأخرى"},"seo":{"title":{"en":"Emacs: Mastering Emacs Config for AI Agents | AI Agent Skill","zh":"Emacs 配置最佳实践","ja":"Emacs 設定ガイド - AIエージェントを活用する","ko":"Emacs 설정 가이드 - 효율적인 개발을 위한 팁","es":"Guía de configuración de Emacs para desarrolladores","fr":"Guide de configuration d''Emacs pour les développeurs","de":"Emacs-Konfigurationsleitfaden für Entwickler","pt":"Guia de Configuração do Emacs: Melhores Práticas","ru":"Настройка Emacs: Руководство по ИИ Агентам","ar":"دليل إعداد Emacs: أفضل الممارسات لاستخدام الأدوات الذكية"},"description":{"en":"Unlock the full potential of Emacs with our expert guide. Learn how to configure Emacs for seamless AI agent integration and discover the power of elisp","zh":"了解如何配置Emacs以提高开发效率，包括Elisp和LSP-aware操作","ja":"Emacsの設定方法をマスターし、開発の生産性を向上させる - AIエージェントを活用する","ko":"Emacs 설정을 마스터하고 개발 생산성을 향상시키는 방법을 알아보세요","es":"Aprende a configurar Emacs para mejorar tu productividad con herramientas como eglot-rename y xref-find-references","fr":"Découvrez comment configurer Emacs pour améliorer votre productivité avec des outils tels que eglot-rename et xref-find-references","de":"Erfahren Sie, wie Sie Emacs konfigurieren, um Ihre Produktivität mit Tools wie eglot-rename und xref-find-references zu verbessern","pt":"Aprenda a configurar o Emacs com nossas dicas e truques. Descubra como usar o Emacs para operações semânticas e muito mais.","ru":"Узнайте, как настроить Emacs с нашей помощью. Откройте для себя возможности Emacs для семантических операций и других функций.","ar":"تعلم كيفية تكوين Emacs باستخدام نصائحنا وأفكارنا. اكتشف كيفية استخدام Emacs للعمليات الدلالية وأكثر من ذلك"},"definition":{"en":"Emacs is a highly customizable text editor that supports Emacs Lisp configuration for advanced editing capabilities","zh":"Emacs配置是指使用Elisp和其他工具来定制Emacs的行为和外观","ja":"Emacs設定とは、Elispやその他のツールを使用してEmacsの動作や外観をカスタマイズすることです","ko":"Emacs 설정은 Elisp와 다른 도구를 사용하여 Emacs의 동작과 외觀을 맞춤 설정하는 것을 의미합니다","es":"Emacs es un editor de texto que admite la configuración y la personalización mediante el lenguaje de programación Elisp","fr":"Emacs est un éditeur de texte qui prend en charge la configuration et la personnalisation via le langage de programmation Elisp","de":"Emacs ist ein Texteditor, der die Konfiguration und Anpassung über die Programmiersprache Elisp unterstützt","pt":"O que é Emacs? É um editor de texto personalizável com suporte a operações semânticas e outras funcionalidades avançadas.","ru":"Что такое Emacs? Это настраиваемый текстовый редактор с поддержкой семантических операций и других продвинутых функций.","ar":"ما هو Emacs؟ إنه محرر نص قابل للتخصيص مع دعم للعمليات الدلالية والوظائف المتقدمة الأخرى"},"features":{"en":["Evaluates Emacs Lisp using the mcp__emacs__emacs_eval tool","Supports semantic operations like eglot-rename and xref-find-references","Enables project-aware file finding with project-find-file","Integrates with LSP-aware tools for enhanced editing experience","Provides flymake-diagnostics for type error detection"],"zh":["使用Elisp进行语义操作","支持LSP-aware操作，如重命名和查找引用","集成Flymake进行类型错误检查","使用Project-aware文件查找功能"],"ja":["Elispを使用したセマンティック操作","LSP-aware操作のサポート（リネーム、参照の検索など）","Flymakeを使用したタイプエラーのチェック","プロジェクト認識のファイル検索機能"],"ko":["Elisp를 사용한 의미적 연산","LSP-aware 연산 지원 (이름 변경, 참조 찾기 등)","Flymake를 사용한 타입 오류 확인","프로젝트 인식 파일 찾기 기능"],"es":["Evaluación de expresiones Elisp con mcp__emacs__emacs_eval","Operaciones semánticas con eglot-rename y xref-find-references","Compatibilidad con LSP para operaciones de refactorización","Búsqueda de archivos en proyectos con project-find-file","Análisis de código con flymake-diagnostics"],"fr":["Évaluation d''expressions Elisp avec mcp__emacs__emacs_eval","Opérations sémantiques avec eglot-rename et xref-find-references","Compatibilité avec LSP pour les opérations de refactoring","Recherche de fichiers dans les projets avec project-find-file","Analyse de code avec flymake-diagnostics"],"de":["Auswertung von Elisp-Ausdrücken mit mcp__emacs__emacs_eval","Semantische Operationen mit eglot-rename und xref-find-references","Unterstützung für LSP für Refactoring-Operationen","Dateisuche in Projekten mit project-find-file","Code-Analyse mit flymake-diagnostics"],"pt":["Suporte a operações semânticas com LSP","Renomeação de símbolos com eglot-rename","Busca de referências com xref-find-references","Análise de diagnósticos com flymake-diagnostics","Busca de arquivos com project-find-file"],"ru":["Поддержка семантических операций с LSP","Переименование символов с помощью eglot-rename","Поиск ссылок с помощью xref-find-references","Анализ диагностик с помощью flymake-diagnostics","Поиск файлов с помощью project-find-file"],"ar":["دعم للعمليات الدلالية مع LSP","إعادة تسمية الرموز باستخدام eglot-rename","بحث المراجع باستخدام xref-find-references","تحليل التشخيصات باستخدام flymake-diagnostics","بحث الملفات باستخدام project-find-file"]},"keywords":{"en":["emacs config guide","emacs vs vim","how to use emacs","emacs install","emacs alternative","emacs setup for ai agents","elisp programming","emacs lsp integration"],"zh":["Emacs配置","Elisp","LSP-aware","Flymake","Project-aware","Emacs设置最佳实践","Emacs开发工具"],"ja":["Emacs設定","Elisp","LSP-aware","Flymake","プロジェクト認識","AIエージェント","Emacs開発ツール"],"ko":["Emacs 설정","Elisp","LSP-aware","Flymake","프로젝트 인식","AI 에이전트","Emacs 개발 도구"],"es":["emacs configuración","herramientas de desarrollo emacs","elisp emacs","operaciones semánticas en emacs","configuración de emacs para desarrolladores","mejora de productividad con emacs","herramientas de refactorización en emacs","búsqueda de archivos en proyectos emacs","análisis de código en emacs"],"fr":["configuration d''emacs","outils de développement emacs","elisp emacs","opérations sémantiques dans emacs","configuration d''emacs pour les développeurs","amélioration de la productivité avec emacs","outils de refactoring dans emacs","recherche de fichiers dans les projets emacs","analyse de code dans emacs"],"de":["emacs konfiguration","entwicklerwerkzeuge für emacs","elisp emacs","semantische operationen in emacs","emacs konfiguration für entwickler","produktivitätssteigerung mit emacs","refactoring tools in emacs","dateisuche in projekten emacs","code-analyse in emacs"],"pt":["emacs config","elisp","emacs configuration","operaciones semânticas","LSP","eglot-rename","xref-find-references","flymake-diagnostics","project-find-file"],"ru":["emacs конфиг","elisp","emacs настройка","семантические операции","LSP","eglot-rename","xref-find-references","flymake-diagnostics","project-find-file","ИИ Агенты"],"ar":["إعدادات emacs","elisp","تكوين emacs","العمليات الدلالية","LSP","eglot-rename","xref-find-references","flymake-diagnostics","project-find-file","الأدوات الذكية"]}},"owner":"conornash","repo":"dot-emacs","repoPath":"conornash/dot-emacs","stars":6,"forks":0,"updatedAt":"2026-01-07T06:44:18Z","topics":["elisp","emacs","emacs-configuration"],"category":"community","skillMd":{"name":"emacs","description":"Interact with a running Emacs instance via MCP. Use this skill when the user asks to interact with Emacs buffers, set up automation, or coordinate between Claude Code and Emacs. Access Elisp documentation directly via (describe-function fn) or (describe-variable var).","bodyPreview":"# Emacs Integration\n\nThe `mcp__emacs__emacs_eval` tool evaluates Emacs Lisp in the running Emacs instance.\n\n## When to Use Emacs vs CLI Tools\n\n**Use Emacs (`emacs_eval`) for:**\n\n1. **Semantic operations** (LSP-aware):\n```elisp\n(eglot-rename \"new_name\")          ; LSP knows scope, not just text\n(xref-find-references \"func\")      ; Understands imports, aliases\n(flymake-diagnostics)              ; Type errors, not just syntax\n(project-find-file)                ; Project-aware file finding\n```\n\n2. *","body":"# Emacs Integration\n\nThe `mcp__emacs__emacs_eval` tool evaluates Emacs Lisp in the running Emacs instance.\n\n## When to Use Emacs vs CLI Tools\n\n**Use Emacs (`emacs_eval`) for:**\n\n1. **Semantic operations** (LSP-aware):\n```elisp\n(eglot-rename \"new_name\")          ; LSP knows scope, not just text\n(xref-find-references \"func\")      ; Understands imports, aliases\n(flymake-diagnostics)              ; Type errors, not just syntax\n(project-find-file)                ; Project-aware file finding\n```\n\n2. **Elisp codebase exploration** (STRONGLY PREFERRED over grep/glob):\n```elisp\n;; Discover symbols matching a pattern\n(apropos-internal \"agent-shell.*hook\" ''boundp)  ; Find variables\n(apropos-internal \"^gptel-make\" ''fboundp)       ; Find functions\n\n;; Get function/variable documentation instantly\n(describe-function ''agent-shell-mcp-server-start)\n(describe-variable ''agent-shell-mode-hook)\n\n;; Check current runtime state\n(agent-shell-mcp-server-running-p)              ; Live state check\n(symbol-value ''some-variable)                   ; Current value\n\n;; Find files\n(directory-files-recursively \"~/.emacs.d\" \"\\\\.el$\")\n```\n\n**Use CLI tools (Bash/Grep) only for:**\n```bash\ngrep -r \"TODO\" --include=\"*.py\" .  # Bulk text search in non-Elisp\nsed -i ''s/old/new/g'' *.py          # Global text replace\nfind . -name \"*.test.js\"           ; File finding by pattern\n```\n\n**Rule of thumb**: For Emacs/Elisp codebases, ALWAYS use `emacs_eval` first. It''s more token-efficient (returns only what you need), provides live runtime state, and understands Elisp semantics. Only fall back to grep/glob for non-Elisp code or bulk text operations.\n\n## Why Elisp is Powerful for Agents\n\n1. **No access control** - Everything is public, agent can modify anything\n2. **Advice system** - Wrap any function without modifying source: `(advice-add ''fn :before #''my-fn)`\n3. **Instant eval** - No compilation step, immediate feedback\n4. **Self-documenting** - `(describe-function ''fn)` at runtime\n5. **Hooks everywhere** - Event-driven observation and intervention\n\n## Documentation Discovery\n\nQuery Emacs directly for any Elisp documentation:\n\n```elisp\n(describe-function ''function-name)\n(describe-variable ''variable-name)\n(apropos \"search-term\")\n```\n\n## Current Context\n\nThe Claude Code session runs in an `agent-shell-mode` buffer. Get context:\n\n```elisp\nmajor-mode                        ; => agent-shell-mode\n(buffer-name)                     ; => \"Claude Code Agent @ project-name\"\n(agent-shell--current-shell)      ; Get the shell object\n```\n\n## Self-Prompting with Timers\n\nSet up a timer to automatically queue a prompt after idle time:\n\n```elisp\n(defvar my-agent-idle-timer nil)\n\n(defun my-agent-idle-prompt ()\n  \"Queue a nudge to the agent after idle timeout.\"\n  (when-let ((shell-buf (get-buffer \"Claude Code Agent @ .emacs.d\")))\n    (with-current-buffer shell-buf\n      ;; Use enqueue - agent-shell-insert errors if agent is busy\n      (agent-shell--enqueue-request\n       :prompt \"Continue working on the current task.\"))))\n\n;; Start: prompt after 15 minutes (900 seconds) of no activity\n(setq my-agent-idle-timer\n      (run-with-idle-timer 900 t #''my-agent-idle-prompt))\n\n;; Stop the timer\n(when my-agent-idle-timer\n  (cancel-timer my-agent-idle-timer)\n  (setq my-agent-idle-timer nil))\n```\n\n**Edge case**: `agent-shell-insert` with `:submit t` returns \"Busy\" or \"Not yet supported\" errors while the agent is processing. Use `agent-shell--enqueue-request` instead - it queues the request to run after the current task completes.\n\n## Queueing Requests\n\nQueue prompts that execute when the agent is no longer busy:\n\n```elisp\n;; Queue a request (runs when current task completes)\n(agent-shell--enqueue-request :prompt \"Next task to do\")\n\n;; Check pending queue\n(with-current-buffer (agent-shell--current-shell)\n  (alist-get :pending-requests agent-shell--state))\n```\n\n## Response Size Limits\n\nLarge return values may exceed the MCP response limit. Strategies:\n\n```elisp\n;; Truncate long strings\n(substring (buffer-string) 0 (min 10000 (length (buffer-string))))\n\n;; Return counts instead of full lists\n(length (buffer-list))\n\n;; Filter before returning\n(seq-take (buffer-list) 10)\n\n;; Write to file, return path\n(with-temp-file \"/tmp/output.txt\"\n  (insert large-content))\n\"/tmp/output.txt\"  ; Return just the path\n```\n\n## Buffer Context Gotcha\n\nEvaluations run in the agent-shell buffer by default. To operate on other buffers:\n\n```elisp\n;; WRONG: operates on agent-shell buffer\n(buffer-string)\n\n;; RIGHT: explicitly target a buffer\n(with-current-buffer \"target-buffer\"\n  (buffer-string))\n\n;; Or use a temp buffer for scratch work\n(with-temp-buffer\n  (insert-file-contents \"/path/to/file\")\n  (buffer-string))\n```\n\n## Periodic Background Tasks\n\nUse `run-at-time` for scheduled operations:\n\n```elisp\n;; Run once after 5 minutes\n(run-at-time 300 nil #''my-function)\n\n;; Run every 60 seconds\n(run-at-time t 60 #''my-repeating-function)\n\n;; Cancel a timer\n(cancel-timer timer-object)\n```\n\n## Coordinating Multiple Agents\n\nIf multiple agent-shell sessions exist:\n\n```elisp\n;; List all agent buffers\n(agent-shell-buffers)\n\n;; Get project-specific buffers  \n(agent-shell-project-buffers)\n\n;; Queue request to a specific shell (safe even if busy)\n(with-current-buffer \"Claude Code Agent @ other-project\"\n  (agent-shell--enqueue-request :prompt \"message\"))\n```\n\n## Inspecting Agent State\n\nAccess internal state for debugging or coordination:\n\n```elisp\n(with-current-buffer (agent-shell--current-shell)\n  ;; Available state keys\n  (mapcar #''car agent-shell--state)\n  ;; => (:agent-config :buffer :client :request-count :pending-requests ...)\n  \n  ;; Check request count\n  (alist-get :request-count agent-shell--state)\n  \n  ;; Check if authenticated\n  (alist-get :authenticated agent-shell--state))\n```\n\n## Error Handling\n\nErrors return with `isError: true`. To handle gracefully in Elisp:\n\n```elisp\n(condition-case err\n    (potentially-failing-operation)\n  (error (format \"Failed: %s\" (error-message-string err))))\n```\n\n## Event-Driven Agent Behavior (Hooks)\n\nEmacs''s hook system enables event-driven agent behavior:\n\n```elisp\n;; OBSERVE user actions\n(add-hook ''after-save-hook #''agent-on-file-saved)\n(add-hook ''compilation-finish-functions #''agent-on-compile-done)\n(add-hook ''flymake-diagnostic-functions #''agent-on-diagnostics)\n(add-hook ''buffer-list-update-hook #''agent-on-focus-change)\n\n;; INTERVENE at key moments  \n(add-hook ''before-save-hook #''agent-maybe-format)\n(add-hook ''find-file-hook #''agent-setup-buffer)\n\n;; ADVICE any function non-invasively\n(advice-add ''compile :before #''agent-log-compile-command)\n(advice-add ''save-buffer :after #''agent-notify-save)\n```\n\nThis enables proactive assistance without polling - the agent becomes an event-driven observer that reacts to user actions in real-time.\n\n## Key Insight: Dynamic Modification\n\nUnlike static languages, Elisp lets agents modify behavior at runtime:\n\n```elisp\n;; Add logging to ANY function, instantly, no rebuild\n(advice-add ''some-function :before \n  (lambda (&rest args) (message \"Called with: %S\" args)))\n\n;; Remove it just as easily\n(advice-remove ''some-function #''my-advice-fn)\n```\n\nThis is the core advantage over TypeScript/VS Code extensions - no compilation, no packaging, no restart. The agent can experiment and iterate in real-time.\n\n## Repository Structure\n\nThis is a **literate Emacs configuration** using Org-Babel. Assumes Emacs 30+ as baseline.\n\n### Configuration Hierarchy\n\nAll modules are loaded at startup via `org-babel-load-file`:\n\n```\ninit.org (2,288 lines) - MAIN ENTRY POINT\n├── emacs24.helm.org - Helm completion\n├── emacs24.smartparens.org - Structural editing\n├── emacs24.hacky.org - Misc utilities\n├── emacs24.python.org - Python dev\n├── emacs24.eshell.org - Shell with Git prompt\n├── emacs24.ess.org - R/statistics\n├── emacs24.elisp.org - Elisp dev\n├── emacs24.js2.org - JavaScript\n├── emacs24.sql.org - SQL (5 formatters, sqlfluff preferred)\n├── emacs24.scheme.org - Scheme\n├── emacs29.llm.org - LLM/AI integration\n└── private.org - API keys (external, not in repo)\n```\n\nNote: \"emacs24\" naming is historical, not version-specific.\n\n### Key Sections in init.org\n\n| Lines | Purpose |\n|-------|---------|\n| 1-150 | Core setup: GC, keybindings, platform detection, straight.el |\n| 150-450 | Org mode configuration |\n| 374-450 | External module loading |\n| 450-2100 | Language modes, UI, navigation |\n| 2100+ | Themes, finalization, auto-tangle |\n\n### Runtime Data (do not commit)\n\n- `bookmarks` - Emacs bookmark locations\n- `keyfreq` - Key frequency statistics\n- `prompts/` - LLM prompt templates\n- `snippets/` - Yasnippet templates\n- `elpa/`, `straight/repos/` - Package caches\n- `eln-cache/` - Native compilation cache\n\n### Package Management\n\nUses `straight.el` with `use-package` for declarative configuration. ~116 packages configured.\n\n### Known Issues (documented for cleanup)\n\n- **emacs24.eshell.org**: Git status runs shell commands on every keystroke (performance)\n- **emacs24.hacky.org**: `date2unix` defined twice; legacy keyboard macros\n- **emacs24.scheme.org**: xscheme is ancient/unmaintained\n- **emacs24.js2.org**: js2-mode superseded by js-ts-mode\n"},"lastSynced":"2026-03-06T06:52:13.589Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents needing advanced project-aware file finding and semantic operations in Emacs.","zh":"非常适合需要高级项目感知文件查找和语义操作的开发者代理，特别是在 Emacs 中。","ja":"Emacs で高度なプロジェクト認識ファイル検索とセマンティクス操作を必要とする Developer エージェントに最適です。","ko":"Emacs에서 고급 프로젝트 인식 파일 찾기 및 의미操作이 필요한 개발자 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollador que necesitan búsqueda de archivos avanzada y conciencia de proyecto y operaciones semánticas en Emacs.","fr":"Parfait pour les Agents de Développeur ayant besoin d''une recherche de fichiers avancée et d''opérations sémantiques conscientes du projet dans Emacs.","de":"Perfekt für Entwickleragenten, die erweiterte projektbezogene Dateisuche und semantische Operationen in Emacs benötigen.","pt":"Perfeito para Agentes de Desenvolvedor que necessitam de capacidades avançadas de encontrar arquivos e operações semânticas no Emacs.","ru":"Идеально подходит для агентов разработчиков, которым требуются продвинутые возможности поиска файлов и семантических операций в Emacs.","ar":"مثالي لعميل المطور الذي يحتاج إلى إمكانيات متقدمة للعثور على الملفات والعمليات الدلالية في Emacs."},"recommendation":{"en":"Empowers agents to leverage Emacs Lisp for LSP-aware operations, such as renaming variables with eglot-rename, finding references with xref-find-references, and running diagnostics with flymake-diagnostics, all within a running Emacs instance.","zh":"赋予代理使用 Emacs Lisp 进行 LSP 感知操作的能力，例如使用 eglot-rename 重命名变量，使用 xref-find-references 查找引用，并使用 flymake-diagnostics 运行诊断，所有操作都在运行的 Emacs 实例中进行。","ja":"エージェントが Emacs Lisp を使用して LSP 感知操作を実行する能力を提供します。たとえば、eglot-rename を使用して変数を名前変更したり、xref-find-references を使用して参照を検索したり、flymake-diagnostics を使用して診断を実行したりします。すべての操作は、実行中の Emacs インスタンス内で実行されます。","ko":"에이전트가 Emacs Lisp를 사용하여 LSP 인식 작업을 수행할 수 있는 능력을 제공합니다. 예를 들어, eglot-rename을 사용하여 변수 이름을 변경하거나 xref-find-references를 사용하여 참조를 찾거나 flymake-diagnostics를 사용하여 진단을 실행하는 등 모든 작업은 실행 중인 Emacs 인스턴스 내에서 수행됩니다.","es":"Habilita a los agentes a aprovechar Emacs Lisp para operaciones conscientes de LSP, como renombrar variables con eglot-rename, encontrar referencias con xref-find-references y ejecutar diagnósticos con flymake-diagnostics, todo dentro de una instancia de Emacs en ejecución.","fr":"Permet aux agents d''exploiter Emacs Lisp pour des opérations conscientes de LSP, telles que le renommage de variables avec eglot-rename, la recherche de références avec xref-find-references et l''exécution de diagnostics avec flymake-diagnostics, le tout dans une instance Emacs en cours d''exécution.","de":"Ermächtigt Agenten, Emacs Lisp für LSP-bewusste Operationen wie Umbenennen von Variablen mit eglot-rename, Finden von Referenzen mit xref-find-references und Ausführen von Diagnosen mit flymake-diagnostics zu nutzen, alles innerhalb einer laufenden Emacs-Instanz.","pt":"Habilita os agentes a aproveitar Emacs Lisp para operações LSP, como renomear variáveis com eglot-rename, encontrar referências com xref-find-references e executar diagnósticos com flymake-diagnostics, tudo dentro de uma instância do Emacs em execução.","ru":"Позволяет агентам использовать Emacs Lisp для операций LSP, таких как переименование переменных с помощью eglot-rename, поиск ссылок с помощью xref-find-references и запуск диагностических инструментов с помощью flymake-diagnostics, все это внутри работающей экземпляра Emacs.","ar":"يمكن للعميل الاستفادة من Emacs Lisp لعمليات LSP ، مثل إعادة تسمية المتغيرات باستخدام eglot-rename ، العثور على المراجع باستخدام xref-find-references ، و运行 التشخيصات باستخدام flymake-diagnostics ، كل ذلك داخل مثيل Emacs قيد التشغيل."},"useCases":{"en":["Evaluating Emacs Lisp code for project-specific tasks","Performing semantic operations like renaming and refactoring","Utilizing project-aware file finding with project-find-file"],"zh":["评估Emacs Lisp代码以执行项目特定任务","执行重命名和重构等语义操作","使用project-find-file进行项目感知文件查找"],"ja":["プロジェクト固有のタスクを実行するためにEmacs Lispコードを評価する","名前変更やリファクタリングなどのセマンティクス操作を実行する","project-find-fileを使用したプロジェクト認識ファイル検索"],"ko":["프로젝트 특정 작업을 수행하기 위해 Emacs Lisp 코드를 평가하는 것","이름 변경 및 리팩토링과 같은 의미 분석 작업을 수행하는 것","project-find-file을 사용한 프로젝트 인식 파일 찾기"],"es":["Evaluación de código Emacs Lisp para tareas específicas de proyecto","Realización de operaciones semánticas como renombrar y refactorizar","Utilización de la búsqueda de archivos consciente del proyecto con project-find-file"],"fr":["Évaluation de code Emacs Lisp pour des tâches spécifiques de projet","Réalisations d''opérations sémantiques comme renommer et réorganiser","Utilisation de la recherche de fichiers consciente du projet avec project-find-file"],"de":["Auswertung von Emacs-Lisp-Code für projektspezifische Aufgaben","Durchführung semantischer Operationen wie Umbenennen und Refaktorisieren","Nutzung der projektbezogenen Dateisuche mit project-find-file"],"pt":["Avaliar código Emacs Lisp para tarefas específicas de projeto","Realizar operações semânticas como renomear e reestruturar","Utilizar a busca de arquivos com conhecimento de projeto com project-find-file"],"ru":["Оценка кода Emacs Lisp для задач конкретного проекта","Выполнение семантических операций, таких как переименование и рефакторинг","Использование поиска файлов с учетом проекта с помощью project-find-file"],"ar":["تقييم رمز Emacs Lisp لمهام مشروع محدد","إجراء عمليات دلالية مثل إعادة التسمية وإعادة الهيكلة","استخدام العثور على الملفات مع معرفة المشروع مع project-find-file"]},"limitations":{"en":["Requires a running Emacs instance","Emacs Lisp evaluation only"],"zh":["需要运行的Emacs实例","仅限Emacs Lisp评估"],"ja":["実行中のEmacsインスタンスが必要","Emacs Lisp評価のみ"],"ko":["실행 중인 Emacs 인스턴스가 필요","Emacs Lisp 평가만"],"es":["Requiere una instancia de Emacs en ejecución","Evaluación de Emacs Lisp solo"],"fr":["Nécessite une instance Emacs en cours d''exécution","Évaluation de Emacs Lisp uniquement"],"de":["Erfordert eine laufende Emacs-Instanz","Nur Auswertung von Emacs Lisp"],"pt":["Requer uma instância do Emacs em execução","Avaliação do Emacs Lisp apenas"],"ru":["Требуется работающий экземпляр Emacs","Только оценка Emacs Lisp"],"ar":["يتطلب مثيل Emacs قيد التشغيل","التقييم Emacs Lisp فقط"]},"version":4},"contentHash":"a2aa19f26ac9ca66184d4d33337787e7daf7ac1ca871f9fbbf511b9b45806d36","qualityScore":60}');
