INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('conornash/dot-emacs/emacs', 'emacs', 'conornash', 'dot-emacs', 'community', 'emacs conornash dot-emacs community elisp emacs emacs-configuration The Emacs skill enables AI agents to evaluate Emacs Lisp in a running Emacs instance, ideal for developers seeking to leverage semantic operations and project-aware file finding. Emacs配置是提高开发效率的关键，了解Elisp和LSP-aware操作可以帮助您更好地使用Emacs Emacsの設定は開発の生産性を向上させる鍵です。ElispとLSP-aware操作をマスターしましょう Emacs 설정은 개발 생산성을 향상시키는 핵심입니다. Elisp와 LSP-aware操作을 알아보세요 Emacs es un editor de texto altamente configurable que admite operaciones semánticas con herramientas como eglot-rename y xref-find-references Emacs est un éditeur de texte hautement personnalisable qui prend en charge les opérations sémantiques avec des outils tels que eglot-rename et xref-find-references Emacs ist ein hoch konfigurierbarer Texteditor, der semantische Operationen mit Tools wie eglot-rename und xref-find-references unterstützt O Emacs é um editor de texto poderoso que pode ser personalizado com configurações avançadas. Aprenda a usá-lo para operações semânticas e outras funcionalidades. Emacs - это мощный текстовый редактор, который можно настроить с помощью продвинутых конфигураций. Узнайте, как использовать его для семантических операций и других функций. الemacs هو محرر نص قوي يمكن تخصيصه باستخدام إعدادات متقدمة. تعلم كيفية استخدامه للعمليات الدلالية والوظائف الأخرى emacs config guide emacs vs vim how to use emacs emacs install emacs alternative emacs setup for ai agents elisp programming emacs lsp integration Emacs配置 Elisp LSP-aware Flymake Project-aware Emacs设置最佳实践 Emacs开发工具 Evaluates Emacs Lisp using the mcp__emacs__emacs_eval tool Supports semantic operations like eglot-rename and xref-find-references Enables project-aware file finding with project-find-file Integrates with LSP-aware tools for enhanced editing experience Provides flymake-diagnostics for type error detection Emacs is a highly customizable text editor that supports Emacs Lisp configuration for advanced editing capabilities');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('lawless-m/claude-skills/Nawin', 'community', 'lawless-m', 'claude-skills', 'lawless-m/claude-skills', 'Nawin', 6, 0, 60, '2026-02-19T07:16:55Z', '2026-03-06T06:52:19.210Z', '8b8d259287b0bbd531c1056ef3641fd217da8f7d5425a5f6c3f87a3c5efe63fb', '{"id":"lawless-m/claude-skills/Nawin","name":"Nawin","description":{"en":"Nawin is a .NET 9 implementation of the 9P2000 protocol, providing clients, servers, and authentication for Windows/Linux systems. It benefits developers working with 9front file servers.","zh":"Nawin是一个.NET 9实现的9P2000协议，用于连接Windows/Linux系统到9front文件服务器，提供客户端、服务器、认证和CPU远程shell功能","ja":"Nawinは、Windows/Linuxシステムを9frontファイルサーバーに接続するための9P2000プロトコルの.NET 9実装です。クライアント、サーバー、認証、CPUリモートシェル機能を提供します","ko":"Nawin은 Windows/Linux 시스템을 9front 파일 서버에 연결하기 위한 .NET 9 구현의 9P2000 프로토콜입니다. 클라이언트, 서버, 인증, CPU 원격 셸 기능을 제공합니다","es":"Nawin es una implementación de .NET 9 del protocolo 9P2000 que permite la conexión de sistemas Windows/Linux a servidores de archivos 9front","fr":"Nawin est une implémentation .NET 9 du protocole 9P2000 qui permet la connexion de systèmes Windows/Linux aux serveurs de fichiers 9front","de":"Nawin ist eine .NET-9-Implementierung des 9P2000-Protokolls, die die Verbindung von Windows/Linux-Systemen mit 9front-Dateiservern ermöglicht","pt":"O Nawin é uma implementação .NET 9 do protocolo 9P2000 que fornece clientes, servidores, autenticação e capacidades de shell remoto","ru":"Nawin - это реализация .NET 9 протокола 9P2000, обеспечивающая клиенты, серверы, аутентификацию и возможности удаленного_shell","ar":"Nawin هو تنفيذ .NET 9 لبروتوكول 9P2000 يوفر عملاء، خوادم، مصادقة وإمكانيات Shell عن بعد"},"seo":{"title":{"en":"Nawin: 9P2000 Protocol Implementation for Windows/Linux |...","zh":"Nawin_SETUP_GUIDE:.NET 9","ja":"NawinSetupGuide: 9P2000AIエージェント","ko":"Nawin설치 가이드: .NET 9 구현","es":"Guía de configuración de Nawin: Conexión de sistemas Wind...","fr":"Guide de configuration de Nawin : Connexion de systèmes W...","de":"Nawin-Konfigurationsleitfaden: Verbindung von Windows/Lin...","pt":"Nawin: Guia de Configuração do Protocolo 9P2000","ru":"Nawin: Настройка ИИ Агента для 9P2000 Протокола","ar":"Nawin: دليل إعداد بروتوكول 9P2000"},"description":{"en":"Discover how to connect Windows/Linux systems to 9front file servers using Nawin. Learn setup, authentication, and CPU remote shell capabilities now!","zh":"了解Nawin的功能和特点，.NET 9实现的9P2000协议连接Windows/Linux系统到9front文件服务器","ja":"Nawinの機能と特徴を紹介。9P2000プロトコルを使用したWindows/Linuxシステムと9frontファイルサーバーの接続","ko":"Nawin의 기능과 특징을 알아보세요. .NET 9 구현의 9P2000 프로토콜을 사용하여 Windows/Linux 시스템과 9front 파일 서버를 연결합니다","es":"Aprende a configurar Nawin, una implementación de .NET 9 del protocolo 9P2000 para conectar sistemas Windows/Linux a servidores de archivos 9front","fr":"Découvrez comment configurer Nawin, une implémentation .NET 9 du protocole 9P2000 pour connecter les systèmes Windows/Linux aux serveurs de fichiers 9front","de":"Erfahren Sie, wie Sie Nawin konfigurieren, eine .NET-9-Implementierung des 9P2000-Protokolls zur Verbindung von Windows/Linux-Systemen mit 9front-Dateiservern","pt":"Aprenda a configurar o Nawin, uma implementação .NET 9 do protocolo 9P2000 para conectar sistemas Windows/Linux a servidores de arquivos 9front","ru":"Узнайте, как настроить Nawin, реализацию .NET 9 протокола 9P2000 для подключения систем Windows/Linux к серверам файлов 9front","ar":"تعلم كيفية cấu hình Nawin، تنفيذ .NET 9 لبروتوكول 9P2000 للوصول إلى خوادم الملفات 9front"},"definition":{"en":"Nawin is a .NET 9 implementation of the 9P2000 protocol for connecting Windows/Linux systems to 9front file servers.","zh":"Nawin是一个.NET 9实现的9P2000协议，用于连接Windows/Linux系统到9front文件服务器","ja":"Nawinは、Windows/Linuxシステムを9frontファイルサーバーに接続するための9P2000プロトコルの.NET 9実装","ko":"Nawin은 Windows/Linux 시스템을 9front 파일 서버에 연결하기 위한 .NET 9 구현의 9P2000 프로토콜","es":"Nawin es un agente de inteligencia artificial que implementa el protocolo 9P2000 en .NET 9","fr":"Nawin est un agent d''intelligence artificielle qui implémente le protocole 9P2000 en .NET 9","de":"Nawin ist ein künstlicher Intelligenzagent, der das 9P2000-Protokoll in .NET 9 implementiert","pt":"O que é Nawin? É uma implementação .NET 9 do protocolo 9P2000 para conectar sistemas Windows/Linux a servidores de arquivos 9front","ru":"Что такое Nawin? Это реализация .NET 9 протокола 9P2000 для подключения систем Windows/Linux к серверам файлов 9front","ar":"ما هو Nawin؟ هو تنفيذ .NET 9 لبروتوكول 9P2000 للوصول إلى خوادم الملفات 9front"},"features":{"en":["Implements 9P2000 protocol for file server connections","Provides clients and servers for Windows/Linux systems","Supports authentication for secure connections","Offers CPU remote shell capabilities","Utilizes dotnet run command for tool execution","Requires root access for privileged ports like 564"],"zh":[".NET 9实现的9P2000协议","连接Windows/Linux系统到9front文件服务器","提供客户端、服务器、认证和CPU远程shell功能","使用dotnet run --project Nawin.<Project>运行工具","支持privileged ports，例如端口564"],"ja":["9P2000プロトコルの.NET 9実装","Windows/Linuxシステムと9frontファイルサーバーの接続","クライアント、サーバー、認証、CPUリモートシェルの機能","dotnet run --project Nawin.<Project>を使用してツールを実行","privileged portsのサポート、たとえばポート564"],"ko":[".NET 9 구현의 9P2000 프로토콜","Windows/Linux 시스템과 9front 파일 서버의 연결","클라이언트, 서버, 인증, CPU 원격 셸 기능","dotnet run --project Nawin.<Project>를 사용하여 도구를 실행","privileged ports의 지원, 예를 들어 포트 564"],"es":["Implementación de .NET 9 del protocolo 9P2000","Conexión de sistemas Windows/Linux a servidores de archivos 9front","Capacidades de autenticación y shell remoto de CPU","Uso de dotnet run para ejecutar herramientas","Requiere privilegios de root para el puerto 564"],"fr":["Implémentation .NET 9 du protocole 9P2000","Connexion de systèmes Windows/Linux aux serveurs de fichiers 9front","Capacités d''authentification et de shell distant de CPU","Utilisation de dotnet run pour exécuter des outils","Nécessite des privilèges de root pour le port 564"],"de":["Implementierung von .NET 9 des 9P2000-Protokolls","Verbindung von Windows/Linux-Systemen mit 9front-Dateiservern","Authentifizierungs- und CPU-Fernshell-Funktionen","Verwendung von dotnet run zum Ausführen von Tools","Benötigt Root-Rechte für den Port 564"],"pt":["Implementação .NET 9 do protocolo 9P2000","Clientes e servidores para conectar sistemas Windows/Linux a servidores de arquivos 9front","Autenticação e capacidades de shell remoto","Uso de dotnet run para executar ferramentas","Requer root para portas privilegiadas como a 564"],"ru":["Реализация .NET 9 протокола 9P2000","Клиенты и серверы для подключения систем Windows/Linux к серверам файлов 9front","Аутентификация и возможности удаленного_shell","Использование dotnet run для запуска инструментов","Требуется root для привилегированных портов, таких как 564"],"ar":["تنفيذ .NET 9 لبروتوكول 9P2000","عملاء وخوادم للوصول إلى خوادم الملفات 9front","مصادقة وإمكانيات Shell عن بعد","استخدام dotnet run لتشغيل الأدوات","يتطلب س حق الوصول إلى المنافذ المميزة مثل 564"]},"keywords":{"en":["Nawin setup guide","9P2000 protocol implementation","Windows/Linux file server connections","how to use Nawin","Nawin alternative","Nawin vs 9front","Nawin install","dotnet run command","9front file server setup"],"zh":["Nawin",".NET 9","9P2000协议","Windows/Linux系统","9front文件服务器","dotnet run","privileged ports"],"ja":["Nawin",".NET 9","9P2000プロトコル","Windows/Linuxシステム","9frontファイルサーバー","dotnet run","privileged ports","AIエージェント"],"ko":["Nawin",".NET 9","9P2000 프로토콜","Windows/Linux 시스템","9front 파일 서버","dotnet run","privileged ports","AI 툴"],"es":["Nawin","9P2000",".NET 9","conexión de sistemas","servidores de archivos 9front","autenticación","shell remoto de CPU","dotnet run","Agente de inteligencia artificial"],"fr":["Nawin","9P2000",".NET 9","connexion de systèmes","serveurs de fichiers 9front","authentification","shell distant de CPU","dotnet run","Agent d''intelligence artificielle"],"de":["Nawin","9P2000",".NET 9","Verbindung von Systemen","9front-Dateiserver","Authentifizierung","CPU-Fernshell","dotnet run","Künstlicher Intelligenzagent"],"pt":["Nawin","Protocolo 9P2000","Implementação .NET 9","Conexão de sistemas Windows/Linux","Servidores de arquivos 9front","Autenticação e shell remoto","Dotnet run","Portas privilegiadas"],"ru":["Nawin","Протокол 9P2000","Реализация .NET 9","Подключение систем Windows/Linux","Серверы файлов 9front","Аутентификация и удаленный_shell","Dotnet run","Привилегированные порты"],"ar":["Nawin","بروتوكول 9P2000","تنفيذ .NET 9","الوصول إلى خوادم الملفات 9front","مصادقة و Shell عن بعد","dotnet run","المنافذ المميزة","نظام التشغيل Windows/Linux"]}},"owner":"lawless-m","repo":"claude-skills","repoPath":"lawless-m/claude-skills","stars":6,"forks":0,"updatedAt":"2026-02-19T07:16:55Z","topics":[],"category":"community","skillMd":{"name":"Nawin","description":"9P2000 protocol implementation for .NET - connect to 9front/Plan9, serve files, CPU remote shell, authentication servers","bodyPreview":"# Nawin\n\nNawin is a .NET 9 implementation of the 9P2000 protocol for connecting Windows/Linux systems to 9front (Plan 9) file servers. It provides clients, servers, authentication, and CPU remote shell capabilities.\n\n## Instructions\n\nWhen helping users with Nawin, follow these guidelines:\n\n1. **Project Location**: The codebase is at `/home/matt/Git/Nawin`\n2. **Running Tools**: Use `dotnet run --project Nawin.<Project>` to run tools\n3. **Privileged Ports**: Port 564 requires root. Use `sudo $(whi","body":"# Nawin\n\nNawin is a .NET 9 implementation of the 9P2000 protocol for connecting Windows/Linux systems to 9front (Plan 9) file servers. It provides clients, servers, authentication, and CPU remote shell capabilities.\n\n## Instructions\n\nWhen helping users with Nawin, follow these guidelines:\n\n1. **Project Location**: The codebase is at `/home/matt/Git/Nawin`\n2. **Running Tools**: Use `dotnet run --project Nawin.<Project>` to run tools\n3. **Privileged Ports**: Port 564 requires root. Use `sudo $(which dotnet) run` or use a high port like 5640\n4. **Authentication**: Support for `none`, `simple:user:pass`, `p9sk1` (Plan 9), and `dp9ik` (9front modern)\n5. **9front Testing**: CPU into 9front using the auth server at localhost:17019\n\n## Available Tools\n\n| Project | Purpose | Default Port |\n|---------|---------|--------------|\n| Nawin.Cli | Interactive 9P client (ls, cat, mount, copy) | connects to 564 |\n| Nawin.Serve | Serve local directories over 9P (U9FS replacement) | 564 |\n| Nawin.Cpu | CPU client - remote shell with namespace export | 17010 |\n| Nawin.CpuServer | Accept inbound CPU connections | 17010 |\n| Nawin.Auth | Authentication server (p9sk1/dp9ik) | 567 |\n| Nawin.Jerq | Graphics app with /dev/draw export | N/A |\n\n## Examples\n\n### Example 1: Serve a Directory (U9FS Replacement)\n```\nUser: How do I share a directory over 9P?\n\nClaude: Use Nawin.Serve to expose a local directory:\n\n# Serve current directory on high port (no root needed)\ndotnet run --project Nawin.Serve -- -p 5640 .\n\n# Serve with simple auth\ndotnet run --project Nawin.Serve -- -p 5640 --auth simple:matt:secret /home/matt/share\n\n# On port 564 (requires root)\nsudo $(which dotnet) run --project Nawin.Serve -- /home/matt/share\n```\n\n### Example 2: Connect to 9front\n```\nUser: How do I list files on a 9front server?\n\nClaude: Use Nawin.Cli with dp9ik auth:\n\ndotnet run --project Nawin.Cli -- -H 9front.local -u glenda -p password -a dp9ik ls /\n\n# Read a file\ndotnet run --project Nawin.Cli -- -H 9front.local -u glenda -p password -a dp9ik cat /lib/motd\n\n# Copy file from remote\ndotnet run --project Nawin.Cli -- -H 9front.local -u glenda -p password -a dp9ik cp :/etc/profile ./profile\n```\n\n### Example 3: CPU into 9front\n```\nUser: How do I get a remote shell on 9front?\n\nClaude: Use Nawin.Cpu for Plan 9 style CPU connection:\n\n# Interactive shell\ndotnet run --project Nawin.Cpu -- --host 9front.local --user glenda --password secret --protocol dp9ik\n\n# Run a command\ndotnet run --project Nawin.Cpu -- --host 9front.local -u glenda -P secret --protocol dp9ik \"cat /dev/sysname\"\n\n# With local auth server (p9sk1)\ndotnet run --project Nawin.Cpu -- --host localhost --port 17019 --user glenda --password test1234 --protocol p9sk1 \"echo hello\"\n```\n\n### Example 4: Run the Auth Server\n```\nUser: How do I start the authentication server?\n\nClaude: Nawin.Auth runs as a systemd service or manually:\n\n# Check status\nsystemctl status nawin-auth\n\n# Restart\nsudo systemctl restart nawin-auth && sleep 2 && systemctl status nawin-auth 2>&1 | head -15\n\n# Run manually\ndotnet run --project Nawin.Auth -- serve --port 567 --authdom mydom --keys ~/.nawin/keys\n\n# Manage users\ndotnet run --project Nawin.Auth -- adduser glenda\ndotnet run --project Nawin.Auth -- listusers\n```\n\n### Example 5: Mount Remote Filesystem\n```\nUser: Can I mount a 9P filesystem locally?\n\nClaude: Yes, Nawin.Cli supports mounting via FUSE (Linux) or ProjFS (Windows):\n\n# Linux (FUSE) - runs in foreground with -f\ndotnet run --project Nawin.Cli -- -H 9front.local -u glenda -a dp9ik mount -f /mnt/9front\n\n# Windows (ProjFS)\ndotnet run --project Nawin.Cli -- -H 9front.local -u glenda -a dp9ik mount C:\\9front\n```\n\n---\n\n# Reference Implementation Details\n\n## Project Structure\n\n```\nNawin/\n├── Nawin.Protocol/     # Wire format, message serialization, Qid/Stat types\n├── Nawin.Transport/    # TCP connection, tag multiplexing\n├── Nawin.Client/       # High-level client API, sessions, file handles\n├── Nawin.Server/       # Server-side: listener, file tree interface\n├── Nawin.Auth/         # p9sk1 and dp9ik authentication\n├── Nawin.Cli/          # Command-line client\n├── Nawin.Cpu/          # CPU client (rcpu equivalent)\n├── Nawin.CpuServer/    # CPU server\n├── Nawin.Serve/        # File server (U9FS replacement)\n├── Nawin.Jerq/         # Graphics with /dev/draw export\n├── Nawin.Mount.Linux/  # FUSE integration\n├── Nawin.Mount.Windows/# ProjFS integration\n└── Nawin.Tests/        # Unit and integration tests\n```\n\n## Authentication Protocols\n\n| Protocol | Description | Use Case |\n|----------|-------------|----------|\n| `none` | No authentication | Trusted networks |\n| `simple` | Username/password (plaintext) | Simple setups |\n| `p9sk1` | DES-based Plan 9 auth | Original Plan 9 |\n| `dp9ik` | ChaCha20-Poly1305 + PBKDF2 | Modern 9front |\n\n## Nawin.Serve Options\n\n```bash\ndotnet run --project Nawin.Serve -- [options] <directory>\n\nOptions:\n  -p, --port <port>      Port to listen on (default: 564)\n  -a, --address <addr>   Address to bind (default: 0.0.0.0)\n  --auth <type>          Auth: none, simple:user:pass (default: none)\n```\n\n## Nawin.Cli Options\n\n```bash\ndotnet run --project Nawin.Cli -- [options] <command> [args]\n\nOptions:\n  -H, --host <host>      Server hostname (default: localhost)\n  -P, --port <port>      Server port (default: 564)\n  -u, --user <user>      Username\n  -p, --password <pass>  Password\n  -a, --auth <type>      Auth: none, simple, p9sk1, dp9ik\n  --authserver <h:p>     Auth server for p9sk1/dp9ik\n  --aname <name>         Attach name (file tree)\n\nCommands:\n  ls [-l] <path>         List directory\n  cat <path>             Read file\n  write <path> <text>    Write to file\n  stat <path>            Show file metadata\n  mkdir <path>           Create directory\n  rm <path>              Remove file/directory\n  cp [-r] <src> <dst>    Copy (: prefix for remote)\n  mount [-f] <path>      Mount filesystem\n  shell                  Interactive shell\n```\n\n## Nawin.Cpu Options\n\n```bash\ndotnet run --project Nawin.Cpu -- [options] [command]\n\nOptions:\n  --host <host>          CPU server hostname\n  --port <port>          CPU server port (default: 17010)\n  -u, --user <user>      Username\n  -P, --password <pass>  Password\n  --protocol <proto>     Auth: p9sk1, dp9ik\n  -e, --export <dir>     Export local directory to remote\n  --jerq                 Enable graphics mode\n```\n\n## Testing with 9front\n\nThe local 9front VM (barn) can be started with:\n```bash\n/opt/isos/9front.sh\n```\n\n9front source code is available at:\n```bash\n/mnt/  # When /opt/isos/9front-11321.amd64.iso is mounted\n```\n\nCPU into 9front with local auth server:\n```bash\ndotnet run --project Nawin.Cpu -- --host localhost --port 17019 --user glenda --password test1234 --protocol p9sk1 \"command\"\n```\n\n## Troubleshooting\n\n### \"dotnet: command not found\" with sudo\n\n```bash\n# Use full path\nsudo $(which dotnet) run --project Nawin.Serve\n\n# Or preserve PATH\nsudo env \"PATH=$PATH\" dotnet run --project Nawin.Serve\n```\n\n### Permission denied on port 564\n\nUse a high port or grant capability:\n```bash\n# Option 1: Use high port\ndotnet run --project Nawin.Serve -- -p 5640 .\n\n# Option 2: Grant capability to published binary\ndotnet publish -c Release Nawin.Serve\nsudo setcap ''cap_net_bind_service=+ep'' ./Nawin.Serve/bin/Release/net9.0/publish/Nawin.Serve\n```\n\n### Auth server not running\n\n```bash\nsudo systemctl restart nawin-auth && sleep 2 && systemctl status nawin-auth 2>&1 | head -15\n```\n"},"lastSynced":"2026-03-06T06:52:19.210Z","agentAnalysis":{"suitability":{"en":"Perfect for Systems Administration Agents needing 9P2000 protocol implementation for Windows/Linux systems.","zh":"非常适合需要为 Windows/Linux 系统实现 9P2000 协议的系统管理代理。","ja":"Windows/Linux システムで 9P2000 プロトコルを実装する必要があるシステム管理エージェントに最適です。","ko":"Windows/Linux 시스템에서 9P2000 프로토콜을 구현해야 하는 시스템 관리 에이전트에 적합합니다.","es":"Perfecto para Agentes de Administración de Sistemas que necesitan implementación del protocolo 9P2000 para sistemas Windows/Linux.","fr":"Parfait pour les Agents d''Administration de Systèmes nécessitant une mise en œuvre du protocole 9P2000 pour les systèmes Windows/Linux.","de":"Perfekt für Systemadministration-Agenten, die eine Implementierung des 9P2000-Protokolls für Windows/Linux-Systeme benötigen.","pt":"Perfeito para Agentes de Administração de Sistemas que necessitam de implementação do protocolo 9P2000 para sistemas Windows/Linux.","ru":"Идеально подходит для агентов системного администрирования, которым необходима реализация протокола 9P2000 для систем Windows/Linux.","ar":"مثالي لعمليات وكالات الإدارة التي تحتاج إلى تنفيذ بروتوكول 9P2000 لنظم Windows/Linux."},"recommendation":{"en":"Empowers agents to connect to 9front file servers using the 9P2000 protocol, providing clients, servers, authentication, and CPU remote shell capabilities, all within a .NET 9 framework.","zh":"赋予代理连接到 9front 文件服务器的能力，使用 9P2000 协议，提供客户端、服务器、身份验证和 CPU 远程 shell 能力，所有这些都在 .NET 9 框架内。","ja":"9P2000 プロトコルを使用して 9front ファイルサーバーに接続するエージェントの能力を提供し、クライアント、サーバー、認証、および CPU リモート シェル機能をすべて .NET 9 フレームワーク内で提供します。","ko":".NET 9 프레임워크 내에서 9P2000 프로토콜을 사용하여 9front 파일 서버에 연결할 수 있는 에이전트의 능력을 제공하여 클라이언트, 서버, 인증 및 CPU 원격 쉘 기능을 모두 제공합니다.","es":"Habilita a los agentes a conectarse a servidores de archivos 9front utilizando el protocolo 9P2000, proporcionando clientes, servidores, autenticación y capacidades de shell remota de CPU, todo dentro de un marco .NET 9.","fr":"Permet aux agents de se connecter à des serveurs de fichiers 9front en utilisant le protocole 9P2000, fournissant des clients, des serveurs, une authentification et des capacités de shell distant CPU, le tout dans un cadre .NET 9.","de":"Ermächtigt Agenten, eine Verbindung zu 9front-Dateiservern mit dem 9P2000-Protokoll herzustellen, wodurch Clients, Server, Authentifizierung und CPU-Remote-Shell-Funktionen innerhalb eines .NET 9-Rahmenwerks bereitgestellt werden.","pt":"Habilita os agentes a se conectarem a servidores de arquivos 9front usando o protocolo 9P2000, fornecendo clientes, servidores, autenticação e capacidades de shell remoto de CPU, tudo dentro de um framework .NET 9.","ru":"Предоставляет агентам возможность подключения к серверам файлов 9front с помощью протокола 9P2000, обеспечивая клиентов, серверы, аутентификацию и возможности удаленного оболочки CPU, все в рамках framework .NET 9.","ar":"يمنح الوكالات القدرة على الاتصال بخوادئ ملفات 9front باستخدام بروتوكول 9P2000، مع توفير العملاء والخوادئ والتحقق من الصحة وقدرات Shell عن بعد CPU، كل ذلك داخل إطار .NET 9."},"useCases":{"en":["Authenticating with 9front file servers","Establishing remote shell connections via CPU","Developing custom clients and servers for 9P2000 protocol"],"zh":["使用 9front 文件服务器进行身份验证","通过 CPU 建立远程 shell 连接","为 9P2000 协议开发自定义客户端和服务器"],"ja":["9front ファイルサーバーを使用した認証","CPU 経由でのリモート シェル接続の確立","9P2000 プロトコル用のカスタム クライアントおよびサーバーの開発"],"ko":["9front 파일 서버를 사용한 인증","CPU를 통해 원격 쉘 연결 설정","9P2000 프로토콜을 위한 사용자 정의 클라이언트 및 서버 개발"],"es":["Autenticación con servidores de archivos 9front","Establecimiento de conexiones de shell remoto a través de CPU","Desarrollo de clientes y servidores personalizados para el protocolo 9P2000"],"fr":["Authentification avec des serveurs de fichiers 9front","Établissement de connexions de shell distant via CPU","Développement de clients et serveurs personnalisés pour le protocole 9P2000"],"de":["Authentifizierung bei 9front-Dateiservern","Herstellung von Remote-Shell-Verbindungen über CPU","Entwicklung von benutzerdefinierten Clients und Servern für das 9P2000-Protokoll"],"pt":["Autenticar com servidores de arquivos 9front","Estabelecer conexões de shell remoto via CPU","Desenvolver clientes e servidores personalizados para o protocolo 9P2000"],"ru":["Аутентификация с серверами файлов 9front","Установление удаленных подключений shell через CPU","Разработка пользовательских клиентов и серверов для протокола 9P2000"],"ar":["التحقق من الصحة مع خوادئ ملفات 9front","إنشاء اتصالات Shell عن بعد عبر CPU","تطوير العملاء والخوادئ المخصصة لبروتوكول 9P2000"]},"limitations":{"en":["Requires .NET 9 implementation","Limited to Windows/Linux systems","Privileged ports like 564 require root access"],"zh":[".NET 9 实现是必需的","仅限于 Windows/Linux 系统","像 564 这样的特权端口需要根访问"],"ja":[".NET 9 の実装が必要","Windows/Linux システムのみ","564 のような特権ポートにはルート アクセスが必要"],"ko":[".NET 9 구현이 필요함","Windows/Linux 시스템에만 국한됨","564와 같은 특권 포트는 루트 액세스가 필요함"],"es":["Requiere implementación de .NET 9","Limitado a sistemas Windows/Linux","Puertos con privilegios como el 564 requieren acceso de root"],"fr":["Nécessite une mise en œuvre de .NET 9","Limité aux systèmes Windows/Linux","Les ports privilégiés comme 564 nécessitent un accès root"],"de":["Erfordert .NET 9-Implementierung","Begrenzt auf Windows/Linux-Systeme","Privilegierte Ports wie 564 erfordern Root-Zugriff"],"pt":["Requer implementação .NET 9","Limitado a sistemas Windows/Linux","Portas privilegiadas como 564 exigem acesso de root"],"ru":["Требуется реализация .NET 9","Ограничен для систем Windows/Linux","Привилегированные порты, такие как 564, требуют доступа root"],"ar":["يتطلب تنفيذ .NET 9","محدود لنظم Windows/Linux","منافذ امتياز مثل 564 تتطلب الوصول الجذري"]},"version":4},"contentHash":"8b8d259287b0bbd531c1056ef3641fd217da8f7d5425a5f6c3f87a3c5efe63fb","qualityScore":60}');
