INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('lawless-m/claude-skills/Nawin', 'Nawin', 'lawless-m', 'claude-skills', 'community', 'Nawin lawless-m claude-skills community Nawin is a .NET 9 implementation of the 9P2000 protocol, providing clients, servers, and authentication for Windows/Linux systems. It benefits developers working with 9front file servers. Nawin是一个.NET 9实现的9P2000协议，用于连接Windows/Linux系统到9front文件服务器，提供客户端、服务器、认证和CPU远程shell功能 Nawinは、Windows/Linuxシステムを9frontファイルサーバーに接続するための9P2000プロトコルの.NET 9実装です。クライアント、サーバー、認証、CPUリモートシェル機能を提供します Nawin은 Windows/Linux 시스템을 9front 파일 서버에 연결하기 위한 .NET 9 구현의 9P2000 프로토콜입니다. 클라이언트, 서버, 인증, CPU 원격 셸 기능을 제공합니다 Nawin es una implementación de .NET 9 del protocolo 9P2000 que permite la conexión de sistemas Windows/Linux a servidores de archivos 9front Nawin est une implémentation .NET 9 du protocole 9P2000 qui permet la connexion de systèmes Windows/Linux aux serveurs de fichiers 9front Nawin ist eine .NET-9-Implementierung des 9P2000-Protokolls, die die Verbindung von Windows/Linux-Systemen mit 9front-Dateiservern ermöglicht O Nawin é uma implementação .NET 9 do protocolo 9P2000 que fornece clientes, servidores, autenticação e capacidades de shell remoto Nawin - это реализация .NET 9 протокола 9P2000, обеспечивающая клиенты, серверы, аутентификацию и возможности удаленного_shell Nawin هو تنفيذ .NET 9 لبروتوكول 9P2000 يوفر عملاء، خوادم، مصادقة وإمكانيات Shell عن بعد Nawin setup guide 9P2000 protocol implementation Windows/Linux file server connections how to use Nawin Nawin alternative Nawin vs 9front Nawin install dotnet run command 9front file server setup Nawin .NET 9 9P2000协议 Windows/Linux系统 9front文件服务器 dotnet run privileged ports Implements 9P2000 protocol for file server connections Provides clients and servers for Windows/Linux systems Supports authentication for secure connections Offers CPU remote shell capabilities Utilizes dotnet run command for tool execution Requires root access for privileged ports like 564 Nawin is a .NET 9 implementation of the 9P2000 protocol for connecting Windows/Linux systems to 9front file servers.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('osoleve/the-fold/doc-forms', 'community', 'osoleve', 'the-fold', 'osoleve/the-fold', 'doc-forms', 5, 2, 60, '2026-02-24T20:15:36Z', '2026-03-06T06:54:21.856Z', '1a88c32acb179e3bcecdd3b28a6985561b1e27f7447091aca1754fd33623ca73', '{"id":"osoleve/the-fold/doc-forms","name":"doc-forms","description":{"en":"doc-forms is a content-addressed homoiconic skill tree for agentic AI, providing searchable and introspectable annotations. It benefits AI developers by surviving in source code.","zh":"doc-forms是一种内容寻址的同像技能树，用于agentic AI，提供可搜索和可introspect的注释","ja":"doc-formsは、AIエージェントのためのホモアイコニックスキルツリーであり、検索可能でintrospect可能な注釈を提供する","ko":"doc-forms는 동형 스킬 트리로서 agentic AI를 위한 내용 주소 지정된 注釈를 제공","es":"doc-forms es una habilidad de árbol de habilidades homoicónicas para Agentes de IA que permite agregar anotaciones de código introspectables y búsqueda","fr":"doc-forms est une compétence d''arbre de compétences homoiconiques pour Outils d''IA qui permet d''ajouter des annotations de code introspectables et de recherche","de":"doc-forms ist eine Fähigkeit eines homoikonischen Skillbaums für KI-Agenten, die die Hinzufügung von introspektierbaren und suchbaren Code-Anmerkungen ermöglicht","pt":"O doc-forms é uma habilidade de IA que fornece anotações de código-fonte introspectáveis e pesquisáveis. Ele utiliza a sintaxe (doc ...)","ru":"Doc-forms - это навык ИИ, который предоставляет интроспективные и поисковые аннотации исходного кода. Он использует синтаксис (doc ...)","ar":"doc-forms هو مهارة ذكاء اصطناعي توفر تعليقات متوفرة و قابلة للبحث. يستخدم بنية (doc ...)"},"seo":{"title":{"en":"doc-forms: Setup Guide for AI Agents | Homoiconic Skill Tree","zh":"doc-forms 技术指南：内容寻址的同像技能树","ja":"doc-forms セットアップガイド：AIエージェントのためのホモアイコニックスキルツリー","ko":"doc-forms 설정 가이드: 내용 주소 지정 동형 스킬 트리","es":"Guía de Configuración de doc-forms para Agentes de IA","fr":"Guide de Mise en Place de doc-forms pour Outils d''IA","de":"Einrichtungsleitfaden für doc-forms in KI-Agenten","pt":"Guia de Configuração do doc-forms para Ferramentas de IA","ru":"Настройка doc-forms для ИИ Агентов: Лучшие Практики","ar":"دليل إعداد doc-forms لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to leverage doc-forms for searchable annotations in your AI agent''s source code. Learn to implement contextual and targeted documentation with o...","zh":"了解doc-forms的优势和用法，提高您的AI工具开发效率","ja":"AIエージェント開発を効率化するdoc-formsの特徴と使い方を紹介","ko":"AI 도구 개발 효율성을 높이는 doc-forms의 장점과 사용법을 알아보세요","es":"Aprende a utilizar doc-forms para agregar anotaciones de código introspectables y búsqueda en tus proyectos de Agentes de IA","fr":"Découvrez comment utiliser doc-forms pour ajouter des annotations de code introspectables et de recherche dans vos projets d''Outils d''IA","de":"Erfahren Sie, wie Sie doc-forms verwenden, um introspektierbare und suchbare Code-Anmerkungen in Ihre KI-Agenten-Projekte zu integrieren","pt":"Aprenda a configurar o doc-forms para melhorar a documentação e a introspecção do seu código-fonte em Ferramentas de IA","ru":"Узнайте, как настроить doc-forms для улучшения документации и интроспекции вашего исходного кода в ИИ Агентах","ar":"تعرف على كيفية إعداد doc-forms لتحسين توثيق وintrospecção شفرتك المصدرية في أدوات الذكاء الاصطناعي"},"definition":{"en":"doc-forms is a skill tree for agentic AI that utilizes `(doc ...)` forms for annotations, enabling contextual and targeted documentation.","zh":"doc-forms是一种用于AI工具的同像技能树，提供内容寻址的注释功能","ja":"doc-formsは、AIエージェントのためのホモアイコニックスキルツリーであり、内容アドレッシングの注釈機能を提供する","ko":"doc-forms는 AI 도구를 위한 동형 스킬 트리로서 내용 주소 지정된 注釈 기능을 제공","es":"¿Qué es doc-forms? Es una habilidad de árbol de habilidades para Agentes de IA que utiliza formas de documento para anotaciones de código","fr":"Qu''est-ce que doc-forms? C''est une compétence d''arbre de compétences pour Outils d''IA qui utilise des formes de document pour les annotations de code","de":"Was ist doc-forms? Es ist eine Fähigkeit eines Skillbaums für KI-Agenten, die Dokumentformen für Code-Anmerkungen verwendet","pt":"O que é doc-forms? É uma habilidade de IA que fornece anotações de código-fonte introspectáveis e pesquisáveis","ru":"Что такое doc-forms? Это навык ИИ, который предоставляет интроспективные и поисковые аннотации исходного кода","ar":"ما هو doc-forms؟ هو مهارة ذكاء اصطناعي توفر تعليقات متوفرة و قابلة للبحث"},"features":{"en":["Utilizes `(doc ...)` forms for searchable and introspectable annotations","Supports contextual documentation with `(define ...)` syntax","Enables targeted documentation with `(doc ...)` syntax","Survives in source code for future reference","Uses scheme syntax for defining functions and annotations"],"zh":["支持内容寻址的注释","提供可搜索和可introspect的注释","支持基本语法和目标语法","支持语义属性定义"],"ja":["内容アドレッシングの注釈をサポート","検索可能でintrospect可能な注釈を提供","基本構文とターゲット構文をサポート","セマンティック属性の定義をサポート"],"ko":["내용 주소 지정된 注釈을 지원","검색 가능하고 introspect 가능한 注釈을 제공","기본 구문과 대상 구문을 지원","시맨틱 속성 정의를 지원"],"es":["Anotaciones de código introspectables","Búsqueda de anotaciones en el código","Sintaxis básica para definir anotaciones","Soporte para anotaciones contextualizadas y dirigidas","Uso de la forma (doc ...)","Compatibilidad con la definición de tipos y descripciones"],"fr":["Annotations de code introspectables","Recherche d''annotations dans le code","Syntaxe de base pour définir des annotations","Prise en charge d''annotations contextuelles et ciblées","Utilisation de la forme (doc ...)","Compatibilité avec la définition de types et de descriptions"],"de":["Introspektierbare Code-Anmerkungen","Suche nach Anmerkungen im Code","Grundlegende Syntax für die Definition von Anmerkungen","Unterstützung für kontextuelle und gezielte Anmerkungen","Verwendung der Form (doc ...)","Kompatibilität mit der Definition von Typen und Beschreibungen"],"pt":["Suporte à sintaxe (doc ...)","Anotações introspectáveis e pesquisáveis","Compatibilidade com definições de contexto e alvo","Utilização de propriedades como ''type'' e ''description''","Integração com código-fonte em Scheme"],"ru":["Поддержка синтаксиса (doc ...)","Интроспективные и поисковые аннотации","Совместимость с контекстными и целевыми определениями","Использование свойств как ''type'' и ''description''","Интеграция с исходным кодом на Scheme"],"ar":["دعم بنية (doc ...)","تعليقات متوفرة و قابلة للبحث","التوافق مع التعريفات السياقية والمرمزة","استخدام خصائص مثل ''type'' و ''description''","التكامل مع شفرة المصدر في Scheme"]},"keywords":{"en":["how to use doc-forms","doc-forms setup guide","homoiconic skill tree for AI","searchable annotations in AI code","doc-forms alternative for AI documentation","implementing doc-forms in scheme syntax"],"zh":["doc-forms","内容寻址","同像技能树","agentic AI","AI工具开发","可搜索注释","introspect注释"],"ja":["doc-forms","AIエージェント","ホモアイコニックスキルツリー","内容アドレッシング","検索可能な注釈","introspect可能な注釈","AIツール開発"],"ko":["doc-forms","AI 도구","동형 스킬 트리","내용 주소 지정","검색 가능한 注釈","introspect 가능한 注釈","AI 개발 효율성"],"es":["Agentes de IA","Herramientas de IA","Anotaciones de código","Búsqueda de código","Sintaxis de código","Definición de tipos","Descripciones de código","Configuración de doc-forms","Guía de doc-forms"],"fr":["Outils d''IA","Agents d''IA","Annotations de code","Recherche de code","Syntaxe de code","Définition de types","Descriptions de code","Configuration de doc-forms","Guide de doc-forms"],"de":["KI-Agenten","KI-Tools","Code-Anmerkungen","Code-Suche","Code-Syntax","Typ-Definition","Code-Beschreibungen","Konfiguration von doc-forms","Leitfaden für doc-forms"],"pt":["doc-forms","Ferramentas de IA","Anotações introspectáveis","Código-fonte pesquisável","Scheme","Desenvolvimento de software","IA","Inteligência artificial","programação funcional"],"ru":["doc-forms","ИИ Агенты","Интроспективные аннотации","Поисковый исходный код","Scheme","Разработка программного обеспечения","ИИ","Искусственный интеллект","Функциональное программирование"],"ar":["doc-forms","أدوات الذكاء الاصطناعي","تعليقات متوفرة","شفرة المصدر قابلة للبحث","Scheme","تطوير البرمجيات","الذكاء الاصطناعي","برمجة وظيفية","تطوير التطبيقات"]}},"owner":"osoleve","repo":"the-fold","repoPath":"osoleve/the-fold","stars":5,"forks":2,"updatedAt":"2026-02-24T20:15:36Z","topics":[],"category":"community","skillMd":{"name":"doc-forms","description":"Reference for The Folds typed comments and doc forms system. Use when adding type annotations, documentation, todos, or other metadata to Scheme code. Covers (doc ...) syntax, standard tags, search commands, and type checker integration.","bodyPreview":"# Doc Forms (Typed Comments)\n\nThe Fold uses `(doc ...)` forms for searchable, introspectable annotations that survive in source code.\n\n## Basic Syntax\n\n### Contextual (belongs to enclosing definition)\n\n```scheme\n(define (add x y)\n  (doc ''type (-> Int Int Int))\n  (doc ''description \"Adds two numbers\")\n  (+ x y))\n```\n\n### Targeted (names what it documents)\n\n```scheme\n(doc factorial ''type (-> Int Int))\n(define (factorial n)\n  (if (= n 0) 1 (* n (factorial (- n 1)))))\n```\n\n## Semantics\n\n| Property |","body":"# Doc Forms (Typed Comments)\n\nThe Fold uses `(doc ...)` forms for searchable, introspectable annotations that survive in source code.\n\n## Basic Syntax\n\n### Contextual (belongs to enclosing definition)\n\n```scheme\n(define (add x y)\n  (doc ''type (-> Int Int Int))\n  (doc ''description \"Adds two numbers\")\n  (+ x y))\n```\n\n### Targeted (names what it documents)\n\n```scheme\n(doc factorial ''type (-> Int Int))\n(define (factorial n)\n  (if (= n 0) 1 (* n (factorial (- n 1)))))\n```\n\n## Semantics\n\n| Property | Behavior |\n|----------|----------|\n| Arguments | NOT evaluated (pure metadata) |\n| Return value | `void` — use in sequences, not value positions |\n| Normalization | Stripped — code with/without docs hashes identically |\n| Extraction | Tooling reads from source (`lf-todo`, `lf-types`) |\n| Type authority | **Authoritative** — `(doc f ''type ...)` takes precedence over inference |\n\n## Standard Tags\n\n| Tag | Purpose | Example |\n|-----|---------|---------|\n| `''type` | Type signature | `(doc ''type (-> Int Int))` |\n| `''description` | Human-readable description | `(doc ''description \"Adds two numbers\")` |\n| `''param` | Parameter documentation | `(doc ''param ''x \"The first operand\")` |\n| `''returns` | Return value description | `(doc ''returns \"The sum\")` |\n| `''todo` | Work to be done | `(doc ''todo \"Optimize for large inputs\")` |\n| `''fixme` | Known issue | `(doc ''fixme \"Edge case with negative numbers\")` |\n| `''deprecated` | Deprecation notice | `(doc ''deprecated \"Use add-safe instead\")` |\n| `''since` | Version introduced | `(doc ''since \"1.2.0\")` |\n| `''see` | Related items | `(doc ''see ''subtract)` |\n| `''note` | Implementation note | `(doc ''note \"Uses memoization internally\")` |\n\n## Search Commands\n\nAfter loading `lattice/meta/docs.ss`:\n\n```scheme\n(lf-todo)           ; Find all todos in codebase\n(lf-types)          ; Find all type annotations\n(docs-for ''symbol)  ; Find docs for specific target\n(doc-stats)         ; Count docs by tag\n```\n\n## Type Checker Integration\n\nDoc type annotations integrate with both the LSP and type inference:\n\n| Component | Behavior |\n|-----------|----------|\n| LSP hover | Shows doc-declared types with highest priority |\n| Type inference | Uses declared types via `lookup-declared-type` in `core/types/infer.ss` |\n| Bridge | `load-doc-types-into-checker!` populates type checker from doc index |\n\n### Example: Declaring Types for Inference\n\n```scheme\n;; The type checker will trust this annotation\n(doc my-complex-fn ''type (-> (List Int) (Maybe Int)))\n(define (my-complex-fn lst)\n  ;; Complex implementation...\n  )\n```\n\n## Todos vs BBS Issues\n\n| Use Case | When to Use |\n|----------|-------------|\n| `(doc ''todo ...)` | Colocated with code, for localized improvements (performance, refactoring, cleanup) |\n| BBS issue | Tracked work items, features, bugs, cross-cutting concerns, things needing scheduling |\n\n**Rule of thumb:** If it needs to be scheduled or tracked across sessions, use BBS. If it''s a note-to-self next to the code, use `(doc ''todo ...)`.\n\n## Examples\n\n### Full Function Documentation\n\n```scheme\n(define (binary-search vec target)\n  (doc ''type (-> (Vector Int) Int (Maybe Int)))\n  (doc ''description \"Binary search for target in sorted vector\")\n  (doc ''param ''vec \"Sorted vector of integers\")\n  (doc ''param ''target \"Value to find\")\n  (doc ''returns \"Index wrapped in Just, or Nothing if not found\")\n  (doc ''todo \"Add bounds checking\")\n  ;; implementation...\n  )\n```\n\n### Deprecation\n\n```scheme\n(doc old-api ''deprecated \"Use new-api instead. Will be removed in 2.0\")\n(define (old-api x) (new-api x))\n```\n\n### Module-Level Documentation\n\n```scheme\n;; At top of file\n(doc ''description \"Matrix operations for linear algebra\")\n(doc ''since \"1.0.0\")\n(doc ''see ''linalg/vec)\n```\n"},"lastSynced":"2026-03-06T06:54:21.856Z","agentAnalysis":{"suitability":{"en":"Essential for AI Code Analysis Agents performing deep semantic understanding of codebases through typed annotations.","zh":"对于通过类型化注释执行深度语义代码库理解的AI代码分析代理至关重要。","ja":"型付き注釈を通じてコードベースの深い意味理解を実行するAIコード分析エージェントにとって必須です。","ko":"타입화된 주석을 통해 코드베이스의 깊은 의미론적 이해를 수행하는 AI 코드 분석 에이전트에게 필수적입니다.","es":"Esencial para los agentes de análisis de código de IA que realizan una comprensión semántica profunda de las bases de código a través de anotaciones tipadas.","fr":"Essentiel pour les agents d''analyse de code d''IA effectuant une compréhension sémantique approfondie des bases de code via des annotations typées.","de":"Wesentlich für AI-Code-Analyse-Agenten, die ein tiefes semantisches Verständnis von Codebasen durch typisierte Annotationen durchführen.","pt":"Essencial para Agentes de Análise de Código de IA que realizam uma compreensão semântica profunda de codebases por meio de anotações tipadas.","ru":"Необходим для Агентов Анализа Кодов ИИ, выполняющих глубокое семантическое понимание кодовых баз посредством типизированных аннотаций.","ar":"ضروري لعميل تحليل كود الذكاء الاصطناعي الذي يقوم بفهم دقيق.semantic للكود من خلال التعليقات المكتوبة"},"recommendation":{"en":"Enables agents to extract and process content-addressed, homoiconic skill trees directly from source code. Provides structured metadata through searchable and introspectable doc forms that survive compilation, enhancing code comprehension and tooling capabilities.","zh":"使代理能够直接从源代码中提取和处理内容寻址、同像性技能树。通过可搜索和可内省的doc forms提供结构化元数据，这些数据在编译后仍然存在，从而增强代码理解能力和工具支持。","ja":"エージェントがソースコードから直接コンテンツアドレス可能なホモイコニックなスキルツリーを抽出および処理することを可能にします。コンパイル後も存続する検索可能で内省可能なdoc formsを通じて構造化メタデータを提供し、コード理解とツーリング機能を強化します。","ko":"에이전트가 소스 코드에서 직접 콘텐츠 주소 지정 가능한 동형 스킬 트리를 추출하고 처리할 수 있게 합니다. 컴파일 후에도 남아 있는 검색 가능하고 내성 가능한 doc forms를 통해 구조화된 메타데이터를 제공하여 코드 이해력과 도구 기능을 향상시킵니다.","es":"Permite a los agentes extraer y procesar árboles de habilidades homoicónicos y direccionados por contenido directamente desde el código fuente. Proporciona metadatos estructurados a través de formularios de documentos búsqueda e introspectables que sobreviven a la compilación, mejorando la comprensión y las capacidades de herramientas de código.","fr":"Permet aux agents d''extraire et de traiter des arbres de compétences homoiconiques et adressés par contenu directement à partir du code source. Fournit des métadonnées structurées via des formulaires de documents introspectables et recherchables qui survivent à la compilation, améliorant la compréhension et les capacités d''outils de code.","de":"Ermöglicht es Agenten, inhaltsadressierte, homoikone Fähigkeitsbäume direkt aus dem Quellcode zu extrahieren und zu verarbeiten. Bietet strukturierte Metadaten durch suchbare und introspektierbare Dokformen, die die Kompilierung überstehen, und verbessert so das Code-Verständnis und die Werkzeugfähigkeiten.","pt":"Permite que os agentes extraiam e processem árvores de habilidades homoicônicas e endereçadas por conteúdo diretamente do código-fonte. Fornece metadados estruturados por meio de formulários de documentos pesquisáveis e introspectáveis que sobrevivem à compilação, melhorando a compreensão do código e as capacidades de ferramentas.","ru":"Позволяет агентам извлекать и обрабатывать деревья навыков, адресованные по содержимому и гомоиконные, непосредственно из исходного кода. Предоставляет структурированные метаданные посредством поисковых и интроспективных форм документов, которые переживают компиляцию, повышая понимание кода и возможности инструментов.","ar":"يسمح للعميل باستخراج و معالجة شجرة المهارات ذات العنونة المحتوى و المتشابهة بشكل مباشر من الكود المصدري. يوفر البيانات الهيكلية من خلال استمارات وثائق قابلة للبحث و التفتيش التي تنجو من الترجمة ، وتحسين فهم الكود و قدرات الأدوات."},"useCases":{"en":["Extracting type signatures from legacy codebases","Building semantic search indexes for code documentation","Generating API documentation from inline annotations","Validating function contracts against declared types"],"zh":["从遗留代码库中提取类型签名","为代码文档构建语义搜索索引","从内联注释生成API文档","根据声明的类型验证函数契约"],"ja":["レガシーコードベースからの型シグネチャの抽出","コードドキュメントのためのセマンティック検索インデックスの構築","インライン注釈からのAPIドキュメント生成","宣言された型に対する関数契約の検証"],"ko":["레거시 코드베이스에서 타입 시그니처 추출","코드 문서화를 위한 의미론적 검색 인덱스 구축","인라인 주석에서 API 문서 생성","선언된 타입에 대한 함수 계약 검증"],"es":["Extraer firmas de tipo de código legado","Crear índices de búsqueda semántica para la documentación del código","Generar documentación de API a partir de anotaciones en línea","Validar contratos de función contra tipos declarados"],"fr":["Extraire des signatures de type à partir de bases de code legacy","Construire des indexes de recherche sémantique pour la documentation de code","Générer une documentation d''API à partir d''annotations en ligne","Valider des contrats de fonction contre des types déclarés"],"de":["Typsignatur aus Legacy-Codebasen extrahieren","Semantische Suchindizes für die Kodokumentation erstellen","API-Dokumentation aus Inline-Anotationen generieren","Funktionsverträge gegen deklarierte Typen überprüfen"],"pt":["Extração de assinaturas de tipo de codebases legadas","Construção de índices de pesquisa semântica para documentação de código","Geração de documentação de API a partir de anotações inline","Validação de contratos de função contra tipos declarados"],"ru":["Извлечение подписей типов из устаревших кодовых баз","Построение семантических индексов поиска для документации кода","Генерация документации API из встроенных аннотаций","Проверка функциональных контрактов против объявленных типов"],"ar":["استخراج التوقيعات النمطية من قواعد الكود القديمة","بناء فهارس بحث семантиك للوثائق الكود","توليد توثيق واجهة برمجة التطبيقات من التعليقات المضمنة","التحقق من عقود الوظائف المعلنة مقابل الأنواع المعلنة"]},"limitations":{"en":["Requires Scheme-like syntax support","Depends on source code accessibility","Limited to codebases implementing doc-form annotations"],"zh":["需要类似Scheme的语法支持","依赖于源代码的可访问性","仅限于实现了doc-form注释的代码库"],"ja":["Schemeのような構文サポートが必要","ソースコードのアクセス可能性に依存","doc-form注釈を実装したコードベースに限定"],"ko":["Scheme과 유사한 구문 지원 필요","소스 코드 접근성에 의존","doc-form 주석을 구현한 코드베이스로 제한됨"],"es":["Requiere soporte de sintaxis similar a Scheme","Depende de la accesibilidad del código fuente","Limitado a codebases que implementan anotaciones de formulario de documento"],"fr":["Nécessite un support de syntaxe similaire à Scheme","Dépend de l''accessibilité du code source","Limité aux bases de code qui implémentent des annotations de formulaire de document"],"de":["Benötigt Scheme-ähnliche Syntax-Unterstützung","Hängt von der Zugänglichkeit des Quellcodes ab","Begrenzt auf Codebasen, die Dokform-Anotationen implementieren"],"pt":["Exige suporte à sintaxe semelhante ao Scheme","Depende da acessibilidade do código-fonte","Limitado a codebases que implementam anotações de formulários de documentos"],"ru":["Требует поддержки синтаксиса, подобного Scheme","Зависит от доступности исходного кода","Ограничен кодовыми базами, реализующими аннотации форм документов"],"ar":["يتطلب دعم بنية مشابهة لسكيم","يعتمد على إمكانية الوصول إلى الكود المصدري","محدود بقواعد الكود التي تنفذ تعليقات استمارة الوثائق"]},"version":4},"contentHash":"1a88c32acb179e3bcecdd3b28a6985561b1e27f7447091aca1754fd33623ca73","qualityScore":60}');
