INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('osoleve/the-fold/doc-forms', 'doc-forms', 'osoleve', 'the-fold', 'community', 'doc-forms osoleve the-fold community doc-forms is a content-addressed homoiconic skill tree for agentic AI, providing searchable and introspectable annotations. It benefits AI developers by surviving in source code. doc-forms是一种内容寻址的同像技能树，用于agentic AI，提供可搜索和可introspect的注释 doc-formsは、AIエージェントのためのホモアイコニックスキルツリーであり、検索可能でintrospect可能な注釈を提供する doc-forms는 동형 스킬 트리로서 agentic AI를 위한 내용 주소 지정된 注釈를 제공 doc-forms es una habilidad de árbol de habilidades homoicónicas para Agentes de IA que permite agregar anotaciones de código introspectables y búsqueda doc-forms est une compétence d''arbre de compétences homoiconiques pour Outils d''IA qui permet d''ajouter des annotations de code introspectables et de recherche doc-forms ist eine Fähigkeit eines homoikonischen Skillbaums für KI-Agenten, die die Hinzufügung von introspektierbaren und suchbaren Code-Anmerkungen ermöglicht O doc-forms é uma habilidade de IA que fornece anotações de código-fonte introspectáveis e pesquisáveis. Ele utiliza a sintaxe (doc ...) Doc-forms - это навык ИИ, который предоставляет интроспективные и поисковые аннотации исходного кода. Он использует синтаксис (doc ...) doc-forms هو مهارة ذكاء اصطناعي توفر تعليقات متوفرة و قابلة للبحث. يستخدم بنية (doc ...) how to use doc-forms doc-forms setup guide homoiconic skill tree for AI searchable annotations in AI code doc-forms alternative for AI documentation implementing doc-forms in scheme syntax doc-forms 内容寻址 同像技能树 agentic AI AI工具开发 可搜索注释 introspect注释 Utilizes `(doc ...)` forms for searchable and introspectable annotations Supports contextual documentation with `(define ...)` syntax Enables targeted documentation with `(doc ...)` syntax Survives in source code for future reference Uses scheme syntax for defining functions and annotations doc-forms is a skill tree for agentic AI that utilizes `(doc ...)` forms for annotations, enabling contextual and targeted documentation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('yusifeng/formax/formax-skill-capture', 'community', 'yusifeng', 'formax', 'yusifeng/formax', 'formax-skill-capture', 5, 1, 60, '2026-02-28T12:04:09Z', '2026-03-06T06:55:17.262Z', '6e397a539a4d58b44c4300cbeaeba39368b607edc3d08b37ba123a4d3dac86ab', '{"id":"yusifeng/formax/formax-skill-capture","name":"formax-skill-capture","description":{"en":"formax-skill-capture is a terminal-first AI assistant for software engineering tasks, helping developers convert workflows into repo-local skills. It benefits developers by providing a reliable way to create skills.","zh":"Formax Skill Capture是一个终端优先的AI助手，用于软件工程任务，包括repo-local skills和Formax约定","ja":"Formax Skill Captureは、開発ツールの効率化を実現するAIエージェントです","ko":"Formax Skill Capture는 개발 효율성을 높일 수 있는 AI 에이전트 도구입니다","es":"Formax Skill Capture es un asistente de terminal para tareas de ingeniería de software, que complementa el sistema de creación de habilidades con convenciones de Formax.","fr":"Formax Skill Capture est un assistant de terminal pour les tâches d''ingénierie logicielle, qui complète le système de création de compétences avec des conventions Formax.","de":"Formax Skill Capture ist ein Terminal-Assistent für Software-Engineering-Aufgaben, der das System zur Erstellung von Fähigkeiten mit Formax-Konventionen ergänzt.","pt":"O Formax Skill Capture é uma ferramenta de desenvolvimento de software que ajuda a criar habilidades personalizadas para tarefas de engenharia de software, inspirada no Claude Code v2.0.67","ru":"Formax Skill Capture - это инструмент разработки программного обеспечения, который помогает создавать пользовательские навыки для задач разработки программного обеспечения, вдохновленный Claude Code v2.0.67","ar":"Formax Skill Capture هو أداة مساعدة الطرفية لعمليات هندسة البرمجيات التي تساعد على إنشاء مهارات مخصصة لعمليات هندسة البرمجيات، مستوحاة من Claude Code v2.0.67"},"seo":{"title":{"en":"formax-skill-capture: CLI Workflow Automation for AI Agen...","zh":"Formax Skill Capture Setup Guide - AIエージェント终端助手","ja":"Formax Skill Capture Setup Guide - AIエージェントによる開発ツール","ko":"Formax Skill Capture Setup Guide - AI 에이전트 개발 도구","es":"Guía de configuración de Formax Skill Capture para agente...","fr":"Guide d''installation de Formax Skill Capture pour les age...","de":"Einrichtungsleitfaden für Formax Skill Capture für KI-Agents","pt":"Guia de Configuração do Formax Skill Capture: Ferramenta ...","ru":"ИИ Агенты: Настройка Formax Skill Capture для задач разра...","ar":"دليل إعداد Formax Skill Capture: أداة مساعدة الطرفية لعمل..."},"description":{"en":"Unlock efficient skill creation with formax-skill-capture. Learn how to automate your CLI workflow and streamline AI agent development. Get started now!","zh":"了解Formax Skill Capture，一个终端优先的AI助手，用于软件工程任务，包括repo-local skills和_Formax约定","ja":"Formax Skill Captureを導入して、AIエージェントによる開発ツールの効率化を実現しよう","ko":"Formax Skill Capture에 대한 정보를 확인하고, 개발 효율성을 높일 수 있는 AI 에이전트 도구를 활용해보세요","es":"Aprende a utilizar Formax Skill Capture, un asistente de terminal para tareas de ingeniería de software, inspirado en Claude Code v2.0.67","fr":"Découvrez comment utiliser Formax Skill Capture, un assistant de terminal pour les tâches d''ingénierie logicielle, inspiré de Claude Code v2.0.67","de":"Erfahren Sie, wie Sie Formax Skill Capture verwenden, einen Terminal-Assistenten für Software-Engineering-Aufgaben, inspiriert von Claude Code v2.0.67","pt":"Aprenda a configurar o Formax Skill Capture, uma ferramenta de desenvolvimento de software inspirada no Claude Code v2.0.67, para melhorar a produtividade do...","ru":"Узнайте, как настроить Formax Skill Capture, инструмент разработки программного обеспечения, вдохновленный Claude Code v2.0.67, для повышения производительно...","ar":"تعرف على كيفية إعداد Formax Skill Capture، أداة مساعدة الطرفية لعمليات هندسة البرمجيات، مستوحاة من Claude Code v2.0.67، لتحسين إنتاجية المطورين"},"definition":{"en":"formax-skill-capture is a Formax-specific wrapper around skill authoring, enabling the creation of repo-local skills with UI parity and model injection orthogonality.","zh":"Formax Skill Capture是一个AI助手，用于软件工程任务，包括repo-local skills和Formax约定","ja":"Formax Skill Captureは、開発ツールの効率化を実現するAIエージェントの1つです","ko":"Formax Skill Capture는 개발 효율성을 높일 수 있는 AI 에이전트의 일종입니다","es":"Un asistente de terminal para la creación de habilidades de software, basado en Claude Code v2.0.67","fr":"Un assistant de terminal pour la création de compétences logicielles, basé sur Claude Code v2.0.67","de":"Ein Terminal-Assistent für die Erstellung von Software-Fähigkeiten, basierend auf Claude Code v2.0.67","pt":"O Formax Skill Capture é uma ferramenta de desenvolvimento de software que permite criar habilidades personalizadas para tarefas de engenharia de software","ru":"Formax Skill Capture - это инструмент разработки программного обеспечения, который позволяет создавать пользовательские навыки для задач разработки программного обеспечения","ar":"Formax Skill Capture هو أداة مساعدة الطرفية لعمليات هندسة البرمجيات التي تمكن من إنشاء مهارات مخصصة لعمليات هندسة البرمجيات"},"features":{"en":["Complements built-in skill-creator with Formax conventions","Supports repo-local skills checked into git","Provides a ''where to change what'' file map for easy navigation","Ensures invariants such as UI parity and model injection orthogonality","Enables minimu for efficient skill creation"],"zh":["repo-local skills","Formax约定","终端优先的AI助手","支持React和CLI","skill authoring功能"],"ja":["リポジトリローカルスキル","Formax規約","ターミナル優先のAIエージェント","ReactとCLIのサポート","スキルオーサリング機能"],"ko":["리포지토리 로컬 스킬","Formax 규약","터미널 우선의 AI 에이전트","React와 CLI 지원","스킬 작성 기능"],"es":["Compatibilidad con habilidades locales en el repositorio","Mapa de archivos para cambiar la configuración","Invarianza de la interfaz de usuario y la inyección de modelos","Minimización de la complejidad","Integración con React y CLI"],"fr":["Compatibilité avec les compétences locales dans le référentiel","Carte de fichiers pour modifier la configuration","Invariance de l''interface utilisateur et de l''injection de modèles","Minimisation de la complexité","Intégration avec React et CLI"],"de":["Kompatibilität mit lokalen Fähigkeiten im Repository","Dateikarte zur Änderung der Konfiguration","Invarianz der Benutzeroberfläche und der Modellinjektion","Minimierung der Komplexität","Integration mit React und CLI"],"pt":["Criação de habilidades personalizadas para tarefas de engenharia de software","Integração com o Claude Code v2.0.67","Suporte a habilidades locais no repositório Git","Mapeamento de arquivos para alterações","Invariâncias para manter a paridade da interface do usuário","Injeção de modelos para melhorar a produtividade"],"ru":["Создание пользовательских навыков для задач разработки программного обеспечения","Интеграция с Claude Code v2.0.67","Поддержка локальных навыков в репозитории Git","Карта файлов для изменений","Инварианты для поддержания паритета интерфейса пользователя","Внедрение моделей для повышения производительности"],"ar":["إنشاء مهارات مخصصة لعمليات هندسة البرمجيات","التكامل مع Claude Code v2.0.67","دعم المهارات المحلية في مستودع Git","خريطة الملفات للتعديلات","الثوابت ل الحفاظ على تعادل واجهة المستخدم","الحقن النمطي لتحسين الإنتاجية"]},"keywords":{"en":["how to use formax-skill-capture","formax-skill-capture alternative","formax-skill-capture setup guide","what is formax-skill-capture","formax-skill-capture vs claude code","formax-skill-capture install","cli workflow automation","ai agent development","repo-local skills"],"zh":["AIエージェント","终端优先的AI助手","软件工程任务","repo-local skills","Formax约定","React","CLI","开发工具"],"ja":["AIエージェント","ターミナル優先のAIエージェント","開発ツール","リポジトリローカルスキル","Formax規約","React","CLI","開発効率化"],"ko":["AI 에이전트","터미널 우선의 AI 에이전트","개발 도구","리포지토리 로컬 스킬","Formax 규약","React","CLI","개발 효율성"],"es":["agentes de IA","herramientas de IA para desarrolladores","Formax Skill Capture","asistentes de terminal","ingeniería de software","Claude Code v2.0.67","React","CLI"],"fr":["agents d''IA","outils d''IA pour les développeurs","Formax Skill Capture","assistants de terminal","ingénierie logicielle","Claude Code v2.0.67","React","CLI"],"de":["KI-Agents","KI-Tools für Entwickler","Formax Skill Capture","Terminal-Assistenten","Software-Engineering","Claude Code v2.0.67","React","CLI"],"pt":["Formax Skill Capture","desenvolvimento de software","engenharia de software","Claude Code v2.0.67","ferramentas de desenvolvimento","produtividade de desenvolvedores","habilidades personalizadas","integração com Git"],"ru":["Formax Skill Capture","разработка программного обеспечения","ИИ Агенты","Claude Code v2.0.67","инструменты разработки","производительность разработчиков","пользовательские навыки","интеграция с Git"],"ar":["Formax Skill Capture","هندسة البرمجيات","أدوات مساعدة الطرفية","Claude Code v2.0.67","تحسين إنتاجية المطورين","مهارات مخصصة","التكامل مع Git","أدوات تطوير البرمجيات"]}},"owner":"yusifeng","repo":"formax","repoPath":"yusifeng/formax","stars":5,"forks":1,"updatedAt":"2026-02-28T12:04:09Z","topics":["agent","ai","ai-agent","assistant","claude-code","cli","developer-tools","ink","react","terminal"],"category":"community","skillMd":{"name":"formax-skill-capture","description":"Use when we want to turn a just-finished Formax workflow (e.g. commands, overlays, tools, hooks, permissions, UI parity) into a reusable Codex Skill under .codex/skills, including scaffolding, guardrails, and the minimum test checklist.","bodyPreview":"# Formax skill capture (create skills from our workflow)\n\n## What this is\n\nThis skill is a **Formax-specific wrapper** around skill authoring: it helps us reliably convert “we just figured out how to do X” into a repo-local skill under `.codex/skills/<skill-name>/`.\n\nIt complements the built-in `skill-creator` (system skill) by adding Formax conventions:\n- repo-local skills (checked into git)\n- “where to change what” file map\n- invariants (UI parity, model injection orthogonality, etc.)\n- minimu","body":"# Formax skill capture (create skills from our workflow)\n\n## What this is\n\nThis skill is a **Formax-specific wrapper** around skill authoring: it helps us reliably convert “we just figured out how to do X” into a repo-local skill under `.codex/skills/<skill-name>/`.\n\nIt complements the built-in `skill-creator` (system skill) by adding Formax conventions:\n- repo-local skills (checked into git)\n- “where to change what” file map\n- invariants (UI parity, model injection orthogonality, etc.)\n- minimum regression tests to lock behavior\n\n## When to use\n\nTrigger this when the user says:\n- “把这个流程沉淀成 skill”\n- “以后别再忘了怎么改 /xxx”\n- “给我一个复用的修改清单/固定套路”\n\n## Minimal questions to ask (do not proceed until answered)\n\n1) Skill name (kebab-case), e.g. `formax-slash-command-workflow`\n2) 1–2 sentence description: **when** should Codex use it?\n3) Scope: which subsystem? (pick one)\n   - slash commands / overlays\n   - tools (spec/handler/presenter)\n   - hooks\n   - permissions/policy\n   - stability/input routing\n4) Any explicit “don’t change” constraints? (UI copy/spacing/colors, contracts, etc.)\n\n## Output requirements\n\nThe resulting skill must include:\n- a short “Goal” section\n- “Where to change what” (file list)\n- “Patterns” (2–4 common patterns)\n- “Tests to update” (minimum regression set)\n- “Guardrails” (what must not regress)\n\nAvoid long prose; prefer checklists.\n\n## Create a new skill (scaffold)\n\nUse the scaffold script:\n\n```sh\nbash .codex/skills/formax-skill-capture/scripts/new-skill.sh <skill-name> \"<description>\"\n```\n\nThen fill `SKILL.md` body with the content above.\n\n## Refactor policy for skills\n\nWhen a skill is created from a workflow we already shipped:\n- **Do not broaden scope** (no extra features)\n- **Do not rewrite UI** (unless explicitly requested)\n- **Write/extend tests first** if behavior has regressed before\n\n"},"lastSynced":"2026-03-06T06:55:17.262Z","agentAnalysis":{"suitability":{"en":"Ideal for Developer Productivity Agents specializing in workflow automation and skill repository management.","zh":"适用于专注于工作流自动化和技能库管理的开发者生产力代理。","ja":"ワークフロー自動化とスキルリポジトリ管理に特化したデベロッパー生産性エージェントに最適。","ko":"워크플ロー 자동화 및 스킬 저장소 관리에 chuyên注하는 개발자 생산성 에이전트에 적합합니다.","es":"Ideal para Agentes de Productividad de Desarrolladores especializados en automatización de flujo de trabajo y gestión de repositorio de habilidades.","fr":"Idéal pour les Agents de Productivité des Développeurs spécialisés dans l''automatisation des flux de travail et la gestion du référentiel de compétences.","de":"Ideal für Entwickler-Produktivitätsagenten, die sich auf Workflow-Automatisierung und Skill-Repository-Management spezialisieren.","pt":"Ideal para Agentes de Produtividade de Desenvolvedor especializados em automação de fluxo de trabalho e gerenciamento de repositório de habilidades.","ru":"Идеально подходит для агентов производительности разработчиков, специализирующихся на автоматизации рабочих процессов и управлении репозиторием навыков.","ar":"مثالي لعميل إنتاجية المطورين المتخصصين في otomasi تدفق العمل وإدارة مستودع المهارات."},"recommendation":{"en":"Enables reliable conversion of developer workflows into repo-local skills with Formax-specific conventions, including git-checked skills, file mapping for changes, and UI parity invariants. Provides a structured approach to skill creation that complements system-level skill-authoring tools.","zh":"实现开发者工作流可靠地转换为repo本地技能，遵循Formax特定约定，包括git检查的技能、文件映射更改和UI一致性不变量。提供一种结构化的技能创建方法，补充系统级技能创建工具。","ja":"開発者のワークフローを信頼性の高い方法でリポジトリローカルスキルに変換することを可能にし、Formax固有の規約、gitチェック済みのスキル、変更のファイルマッピング、およびUIの一貫性の不変量を含む。システムレベルのスキルオーサリングツールを補完する構造化されたスキル作成アプローチを提供する。","ko":"개발자의 워크플ロー가 신뢰할 수 있는 방법으로 저장소 로컬 스킬로 변환되도록 하여 Formax 특정 규칙을 따르며 git 확인된 스킬, 변경에 대한 파일 매핑 및 UI 일관성 불변량을 포함합니다. 시스템 수준의 스킬 작성 도구를 보완하는 구조화된 스킬 생성 방법을 제공합니다.","es":"Permite la conversión fiable de flujos de trabajo de desarrolladores en habilidades locales del repositorio con convenciones específicas de Formax, incluyendo habilidades verificadas con git, asignación de archivos para cambios y invariantes de paridad de UI. Proporciona un enfoque estructurado para la creación de habilidades que complementa las herramientas de autoría de habilidades a nivel de sistema.","fr":"Permet la conversion fiable des flux de travail des développeurs en compétences locales du référentiel avec des conventions spécifiques à Formax, y compris des compétences vérifiées avec git, un mappage de fichiers pour les modifications et des invariants de parité d''UI. Fournit une approche structurée pour la création de compétences qui complète les outils d''authoring de compétences au niveau du système.","de":"Ermöglicht die zuverlässige Umwandlung von Entwickler-Workflows in repo-lokale Fähigkeiten mit Formax-spezifischen Konventionen, einschließlich git-geprüfter Fähigkeiten, Dateizuordnung für Änderungen und UI-Paritätsinvarianten. Bietet einen strukturierten Ansatz für die Erstellung von Fähigkeiten, der die systemweiten Fähigkeits-Authoring-Tools ergänzt.","pt":"Permite a conversão confiável de fluxos de trabalho de desenvolvedor em habilidades locais do repositório com convenções específicas do Formax, incluindo habilidades verificadas pelo git, mapeamento de arquivos para alterações e invariantes de paridade de UI. Fornece uma abordagem estruturada para a criação de habilidades que complementa as ferramentas de criação de habilidades de nível de sistema.","ru":"Позволяет осуществлять надежное преобразование рабочих процессов разработчиков в локальные навыки репозитория с учетом специфических конвенций Formax, включая навыки, проверенные через git, сопоставление файлов для изменений и инварианты паритета UI. Предоставляет структурированный подход к созданию навыков, который дополняет системные инструменты для создания навыков.","ar":"يسمح بالتحويل الموثوق لتدفقات العمل التطويرية إلى مهارات محلية للمستودع باستخدام الاتفاقيات المحددة من Formax، بما في ذلك المهارات المعتمدة من git، وتصحيح الملفات للتغييرات، ومواثيق توازن واجهة المستخدم. يوفر نهجًا منظمًا لإنشاء المهارات التي تکمل أدوات إنشاء المهارات على مستوى النظام."},"useCases":{"en":["Converting discovered workflows into reusable skills","Maintaining UI parity across skill implementations","Creating repo-local skills under .codex/skills/ directory","Establishing development workflow invariants"],"zh":["将发现的工作流转换为可重用技能","在技能实现中保持UI一致性","在.codox/skills/目录下创建repo本地技能","建立开发工作流不变量"],"ja":["検出されたワークフローを再利用可能なスキルに変換する","スキル実装全体でUIの一貫性を維持する",".codex/skills/ディレクトリ下にリポジトリローカルスキルを作成する","開発ワークフローの不変量を確立する"],"ko":["검색된 워크플ロー는 재사용 가능한 스킬로 변환합니다","스킬 구현 전체에서 UI 일관성을 유지합니다",".codex/skills/ 디렉토리 아래에 저장소 로컬 스킬을 생성합니다","개발 워크플로우의 불변량을 설정합니다"],"es":["Conversión de flujos de trabajo descubiertos en habilidades reutilizables","Mantenimiento de la paridad de UI en implementaciones de habilidades","Creación de habilidades locales del repositorio en el directorio .codex/skills/","Establecimiento de invariantes de flujo de trabajo de desarrollo"],"fr":["Conversion de flux de travail découverts en compétences réutilisables","Maintenance de la parité d''UI dans les implementations de compétences","Création de compétences locales du référentiel dans le répertoire .codex/skills/","Établissement d''invariants de flux de travail de développement"],"de":["Umwandlung von entdeckten Workflows in wiederverwendbare Fähigkeiten","Aufrechterhaltung der UI-Parität bei der Implementierung von Fähigkeiten","Erstellung von repo-lokalen Fähigkeiten im Verzeichnis .codex/skills/","Festlegung von Entwicklungs-Workflow-Invarianten"],"pt":["Converter fluxos de trabalho descobertos em habilidades reutilizáveis","Manter a paridade de UI em diferentes implementações de habilidades","Criar habilidades locais do repositório no diretório .codex/skills/","Estabelecer invariantes de fluxo de trabalho de desenvolvimento"],"ru":["Преобразование обнаруженных рабочих процессов в многократно используемые навыки","Поддержание паритета UI в различных реализациях навыков","Создание локальных навыков репозитория в каталоге .codex/skills/","Установление инвариантов рабочих процессов разработки"],"ar":["تحويل تدفقات العمل المكتشفة إلى مهارات قابلة لإعادة الاستخدام","الحفاظ على مواثيق واجهة المستخدم عبر تنفيذات المهارات المختلفة","إنشاء مهارات محلية للمستودع في الدليل .codex/skills/","تأسيس مواثيق تدفق العمل التطويرية"]},"limitations":{"en":["Formax-specific wrapper (not general-purpose)","Requires existing skill-creator system skill","Designed for repo-local skills only","Assumes git version control integration"],"zh":["Formax特定包装器（非通用）","需要现有的技能创建系统技能","仅适用于repo本地技能","假设git版本控制集成"],"ja":["Formax特有のラッパー（汎用ではありません）","既存のスキル作成システムスキルが必要","リポジトリローカルスキルのみを対象","gitバージョン管理の統合を前提"],"ko":["Formax 특정 래퍼(일반용이 아님)","기존의 스킬 작성 시스템 스킬이 필요","저장소 로컬 스킬만을 대상","git 버전 관리 통합을 가정"],"es":["Envoltura específica de Formax (no de propósito general)","Requiere sistema de creación de habilidades existente","Diseñado solo para habilidades locales del repositorio","Supone integración de control de versión git"],"fr":["Enveloppe spécifique à Formax (pas à usage général)","Nécessite un système de création de compétences existant","Conçu uniquement pour les compétences locales du référentiel","Suppose une intégration de contrôle de version git"],"de":["Formax-spezifische Hülle (nicht allgemeingültig)","Benötigt vorhandenes Fähigkeits-Erstellungssystem","Nur für repo-lokale Fähigkeiten konzipiert","Geht von git-Versionierung-Integration aus"],"pt":["Wraper específico do Formax (não de propósito geral)","Exige sistema de habilidade de criador de habilidades existente","Projetado apenas para habilidades locais do repositório","Pressupõe integração de controle de versão do git"],"ru":["Оболочка, специфичная для Formax (не общего назначения)","Требует существующей системы навыков для создания навыков","Предназначен только для локальных навыков репозитория","Предполагает интеграцию с системой контроля версий git"],"ar":["غلاف محدد من Formax (غير عام الغرض)","يتطلب نظام مهارات موجود لإنشاء المهارات","مصمم فقط للمهارات المحلية للمستودع","يفترض التكامل مع نظام التحكم في الإصدار git"]},"version":4},"contentHash":"6e397a539a4d58b44c4300cbeaeba39368b607edc3d08b37ba123a4d3dac86ab","qualityScore":60}');
