INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('yusifeng/formax/formax-skill-capture', 'formax-skill-capture', 'yusifeng', 'formax', 'community', 'formax-skill-capture yusifeng formax community agent ai ai-agent assistant claude-code cli developer-tools ink react terminal formax-skill-capture is a terminal-first AI assistant for software engineering tasks, helping developers convert workflows into repo-local skills. It benefits developers by providing a reliable way to create skills. Formax Skill Capture是一个终端优先的AI助手，用于软件工程任务，包括repo-local skills和Formax约定 Formax Skill Captureは、開発ツールの効率化を実現するAIエージェントです Formax Skill Capture는 개발 효율성을 높일 수 있는 AI 에이전트 도구입니다 Formax Skill Capture es un asistente de terminal para tareas de ingeniería de software, que complementa el sistema de creación de habilidades con convenciones de Formax. Formax Skill Capture est un assistant de terminal pour les tâches d''ingénierie logicielle, qui complète le système de création de compétences avec des conventions Formax. Formax Skill Capture ist ein Terminal-Assistent für Software-Engineering-Aufgaben, der das System zur Erstellung von Fähigkeiten mit Formax-Konventionen ergänzt. O Formax Skill Capture é uma ferramenta de desenvolvimento de software que ajuda a criar habilidades personalizadas para tarefas de engenharia de software, inspirada no Claude Code v2.0.67 Formax Skill Capture - это инструмент разработки программного обеспечения, который помогает создавать пользовательские навыки для задач разработки программного обеспечения, вдохновленный Claude Code v2.0.67 Formax Skill Capture هو أداة مساعدة الطرفية لعمليات هندسة البرمجيات التي تساعد على إنشاء مهارات مخصصة لعمليات هندسة البرمجيات، مستوحاة من Claude Code v2.0.67 how to use formax-skill-capture formax-skill-capture alternative formax-skill-capture setup guide what is formax-skill-capture formax-skill-capture vs claude code formax-skill-capture install cli workflow automation ai agent development repo-local skills AIエージェント 终端优先的AI助手 软件工程任务 repo-local skills Formax约定 React CLI 开发工具 Complements built-in skill-creator with Formax conventions Supports repo-local skills checked into git Provides a ''where to change what'' file map for easy navigation Ensures invariants such as UI parity and model injection orthogonality Enables minimu for efficient skill creation formax-skill-capture is a Formax-specific wrapper around skill authoring, enabling the creation of repo-local skills with UI parity and model injection orthogonality.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('stancld/templify/seo-audit', 'community', 'stancld', 'templify', 'stancld/templify', 'seo-audit', 5, 0, 60, '2026-03-06T10:52:09Z', '2026-03-07T01:52:34.216Z', '27ea738c81bec24d0af3ad467e47281f4c33408c77a5016a929ed46f4e00e72d', '{"id":"stancld/templify/seo-audit","name":"seo-audit","description":{"en":"The seo-audit skill conducts an ultra-detailed technical and on-page SEO audit, optimized for both traditional search engines and AI-powered search/chat systems, benefiting developers and website owners seeking to improve search visibility and discoverability.","zh":"seo-audit 技能是一个超详细的技术和页面 SEO 审计工具，用于优化传统搜索引擎和 AI 驱动的搜索/聊天系统","ja":"seo-audit スキルは、伝統的な検索エンジンと AI駆動の検索/チャットシステムの両方を最適化するための超詳細な技術とページ SEO 監査ツールです","ko":"SEO 감사 도구는 전통적인 검색 엔진과 AI 기반 검색/채팅 시스템을 모두 최적화하기 위한 초 상세한 기술 및 페이지 SEO 감사 도구입니다","es":"La habilidad seo-audit realiza un análisis técnico y de página detallado para optimizar la visibilidad en buscadores tradicionales y sistemas de búsqueda y chat impulsados por IA.","fr":"La compétence seo-audit effectue une analyse technique et de page détaillée pour optimiser la visibilité sur les moteurs de recherche traditionnels et les systèmes de recherche et de chat alimentés par l''IA.","de":"Die Fähigkeit seo-audit führt eine detaillierte technische und Onpage-Analyse durch, um die Sichtbarkeit in herkömmlichen Suchmaschinen und AI-Search-/Chat-Systemen zu optimieren.","pt":"Realize uma auditoria de SEO técnica e de página com nossa ferramenta de IA, para melhorar a visibilidade nos motores de busca.","ru":"Проведите техническую и на-page SEO-аудит с помощью нашей ИИ-функции, чтобы улучшить видимость в поисковых системах.","ar":"أجرِ تحليل أداء محركات البحث الفني والصفحة باستخدام أداة الذكاء الاصطناعي لدينا، لتحسين الرؤية في محركات البحث."},"seo":{"title":{"en":"seo-audit: Ultra-Detailed Technical SEO Audit for AI Agen...","zh":"SEO 审计工具：AIエージェント优化指南","ja":"seo-audit スキル：AIエージェントを使用したウェブサイト最適化","ko":"SEO 감사 도구: AI 에이전트를 사용한 웹사이트 최적화","es":"Guía de configuración para seo-audit: Optimización técnic...","fr":"Guide de configuration pour seo-audit : Audit technique e...","de":"Einrichtungsleitfaden für seo-audit: Technische und Onpag...","pt":"Guia de Configuração de Auditoria de SEO para Ferramentas...","ru":"Настройка ИИ Агентов для Технической SEO-аудит","ar":"دليل ضبط تحليل أداء محركات البحث للوكلاء الذكاء الاصطناعي"},"description":{"en":"Unlock your website''s full potential with our seo-audit skill, performing thorough technical and on-page SEO audits for traditional and AI-powered search sys...","zh":"了解如何使用 seo-audit 技能来优化您的网站，提高搜索引擎排名和用户体验","ja":"seo-audit スキルを使用してウェブサイトを最適化し、検索エンジンランキングとユーザーエクスペリエンスを向上させる方法を学びます","ko":"SEO 감사 도구를 사용하여 웹사이트를 최적화하고 검색 엔진 순위 및 사용자 경험을 개선하는 방법에 대해 알아보세요","es":"Realiza un auditoría técnica y de página SEO detallada con nuestra herramienta seo-audit para mejorar la visibilidad en buscadores como Google y Bing","fr":"Effectuez un audit technique et de page SEO détaillé avec notre outil seo-audit pour améliorer la visibilité sur les moteurs de recherche comme Google et Bing","de":"Führen Sie eine detaillierte technische und Onpage-SEO-Audit mit unserem Tool seo-audit durch, um die Sichtbarkeit in Suchmaschinen wie Google und Bing zu ve...","pt":"Aprenda a realizar uma auditoria de SEO detalhada com nossa ferramenta de IA, otimizada para motores de busca tradicionais e sistemas de busca/chat com IA","ru":"Проведите техническую SEO-аудит с помощью нашего ИИ Агента, оптимизированного для традиционных поисковых систем и систем поиска/чат с ИИ","ar":"تعلم كيفية إجراء تحليل أداء محركات البحث مفصل باستخدام أداة الذكاء الاصطناعي لدينا، محسّن لعمليات البحث التقليدية وأنظمة البحث/الدردشة بالذكاء الاصطناعي"},"definition":{"en":"seo-audit is a technical skill that performs an in-depth analysis of a website''s SEO, covering both on-page and technical aspects to optimize for search engines and AI-powered systems.","zh":"seo-audit 是一种超详细的技术和页面 SEO 审计工具，用于优化搜索引擎排名和用户体验","ja":"seo-audit は、検索エンジンランキングとユーザーエクスペリエンスを最適化するための超詳細な技術とページ SEO 監査ツールです","ko":"SEO 감사 도구는 검색 엔진 순위와 사용자 경험을 최적화하기 위한 초 상세한 기술 및 페이지 SEO 감사 도구입니다","es":"Un seo-audit es una auditoría técnica y de página detallada para optimizar la visibilidad en buscadores","fr":"Un seo-audit est un audit technique et de page détaillé pour optimiser la visibilité sur les moteurs de recherche","de":"Ein seo-audit ist eine detaillierte technische und Onpage-Audit, um die Sichtbarkeit in Suchmaschinen zu optimieren","pt":"Auditoria de SEO é um processo de análise detalhada de um site para identificar problemas de SEO","ru":"SEO-аудит - это процесс детального анализа сайта для выявления проблем с SEO","ar":"تحليل أداء محركات البحث هو عملية تحليل مفصل للموقع لتحديد مشاكل في أداء محركات البحث"},"features":{"en":["Performs ultra-detailed technical and on-page SEO audits","Optimizes for traditional search engines like Google and Bing","Supports AI-powered search and chat systems","Analyzes website details for improved search visibility and discoverability","Suitable for pre-production website audits","Covers extreme detail for comprehensive SEO analysis"],"zh":["超详细的技术和页面 SEO 审计","优化传统搜索引擎和 AI 驱动的搜索/聊天系统","提高搜索引擎排名和用户体验","支持 Google、Bing 和 AI 搜索","详细的审计报告和建议"],"ja":["超詳細な技術とページ SEO 監査","伝統的な検索エンジンと AI駆動の検索/チャットシステムの両方を最適化","検索エンジンランキングとユーザーエクスペリエンスの向上","Google、Bing、AI 検索のサポート","詳細な監査レポートと提案"],"ko":["초 상세한 기술 및 페이지 SEO 감사","전통적인 검색 엔진과 AI 기반 검색/채팅 시스템을 모두 최적화","검색 엔진 순위와 사용자 경험의 개선","Google, Bing, AI 검색의 지원","詳細한 감사 보고서와 제안"],"es":["Análisis técnico detallado de la página web","Optimización para motores de búsqueda tradicionales como Google y Bing","Optimización para sistemas de búsqueda y chat impulsados por IA","Análisis de la visibilidad y la descubribilidad en buscadores","Informe detallado de problemas de SEO y recomendaciones de mejora"],"fr":["Analyse technique détaillée de la page web","Optimisation pour les moteurs de recherche traditionnels tels que Google et Bing","Optimisation pour les systèmes de recherche et de chat alimentés par l''IA","Analyse de la visibilité et de la découvrabilité sur les moteurs de recherche","Rapport détaillé des problèmes de SEO et des recommandations d''amélioration"],"de":["Detaillierte technische Analyse der Website","Optimierung für herkömmliche Suchmaschinen wie Google und Bing","Optimierung für AI-Search-/Chat-Systeme","Analyse der Sichtbarkeit und Auffindbarkeit in Suchmaschinen","Detaillierter Bericht über SEO-Probleme und Empfehlungen zur Verbesserung"],"pt":["Análise técnica de SEO","Análise de página de SEO","Otimização para motores de busca tradicionais","Otimização para sistemas de busca/chat com IA","Identificação de problemas de SEO","Relatório detalhado de auditoria de SEO"],"ru":["Техническая SEO-аудит","На-page SEO-аудит","Оптимизация для традиционных поисковых систем","Оптимизация для систем поиска/чат с ИИ","Выявление проблем с SEO","Подробный отчет о SEO-аудите"],"ar":["تحليل فني لتحليل أداء محركات البحث","تحليل صفحة لتحليل أداء محركات البحث","تحسين لعمليات البحث التقليدية","تحسين لأنظمة البحث/الدردشة بالذكاء الاصطناعي","تحديد مشاكل في أداء محركات البحث","تقرير مفصل عن تحليل أداء محركات البحث"]},"keywords":{"en":["how to use seo-audit","seo-audit setup guide","seo-audit alternative","seo-audit vs traditional SEO","what is seo-audit","seo-audit install","seo-audit for AI search","technical SEO audit tools","on-page SEO optimization techniques","seo-audit best practices"],"zh":["SEO 审计","AI 驱动的搜索","传统搜索引擎","页面 SEO","技术 SEO","搜索引擎排名","用户体验","Google 优化","Bing 优化"],"ja":["SEO 監査","AI駆動の検索","伝統的な検索エンジン","ページ SEO","技術 SEO","検索エンジンランキング","ユーザーエクスペリエンス","Google 最適化","Bing 最適化"],"ko":["SEO 감사","AI 기반 검색","전통적인 검색 엔진","페이지 SEO","기술 SEO","검색 엔진 순위","사용자 경험","Google 최적화","Bing 최적화"],"es":["seo-audit","optimización técnica","optimización de página","visibilidad en buscadores","mejora de SEO","herramientas de SEO","auditoría de SEO","IA y búsqueda","Google y Bing"],"fr":["seo-audit","optimisation technique","optimisation de page","visibilité sur les moteurs de recherche","amélioration de SEO","outils de SEO","audit de SEO","IA et recherche","Google et Bing"],"de":["seo-audit","technische Optimierung","Onpage-Optimierung","Sichtbarkeit in Suchmaschinen","SEO-Verbesserung","SEO-Tools","SEO-Audit","KI und Suche","Google und Bing"],"pt":["auditoria de SEO","otimização de SEO","motores de busca","sistemas de busca/chat com IA","ferramentas de IA para SEO","tecnologias de SEO","desenvolvedores de SEO","consultores de SEO"],"ru":["SEO-аудит","Оптимизация SEO","поисковые системы","системы поиска/чат с ИИ","ИИ-функции для SEO","технологии SEO","разработчики SEO","консультанты по SEO"],"ar":["تحليل أداء محركات البحث","تحسين أداء محركات البحث","محركات البحث","أنظمة البحث/الدردشة بالذكاء الاصطناعي","أدوات الذكاء الاصطناعي لتحليل أداء محركات البحث","تكنولوجيا تحليل أداء محركات البحث","مطورو تحليل أداء محركات البحث","استشاريو تحليل أداء محركات البحث"]}},"owner":"stancld","repo":"templify","repoPath":"stancld/templify","stars":5,"forks":0,"updatedAt":"2026-03-06T10:52:09Z","topics":[],"category":"community","skillMd":{"name":"seo-audit","description":"Performs comprehensive SEO audit for Google Search and AI-powered search engines (ChatGPT, Perplexity, Claude). Use when asked to audit SEO, optimize for search, or improve discoverability.","bodyPreview":"# SEO Audit Skill\n\nPerforms an ultra-detailed technical and on-page SEO audit optimized for both traditional search engines and AI-powered search/chat systems.\n\n## When to Use\n\n- User asks to \"audit SEO\" or \"check SEO issues\"\n- User wants to optimize for Google, Bing, or AI search\n- User asks about search visibility or discoverability\n- Before deploying a website to production\n\n## Audit Process\n\nGo through the website in extreme detail. Ultra think about this. Find ALL technical and on-page SEO","body":"# SEO Audit Skill\n\nPerforms an ultra-detailed technical and on-page SEO audit optimized for both traditional search engines and AI-powered search/chat systems.\n\n## When to Use\n\n- User asks to \"audit SEO\" or \"check SEO issues\"\n- User wants to optimize for Google, Bing, or AI search\n- User asks about search visibility or discoverability\n- Before deploying a website to production\n\n## Audit Process\n\nGo through the website in extreme detail. Ultra think about this. Find ALL technical and on-page SEO issues.\n\n### Phase 1: Technical SEO Foundation\n\n#### 1.1 Crawlability & Indexing\n- [ ] Check for `robots.txt` in `/public/robots.txt`\n- [ ] Verify XML sitemap exists and is valid\n- [ ] Check for proper canonical URLs\n- [ ] Verify no accidental `noindex` tags\n- [ ] Check for orphaned pages (no internal links)\n\n#### 1.2 Performance & Core Web Vitals\n- [ ] Analyze bundle size (target < 200KB initial JS)\n- [ ] Check for code-splitting and lazy loading\n- [ ] Verify image optimization (WebP, lazy loading, sizing)\n- [ ] Check for render-blocking resources\n- [ ] Verify proper caching headers\n\n#### 1.3 Mobile & Accessibility\n- [ ] Verify responsive meta viewport tag\n- [ ] Check touch target sizes (min 44x44px)\n- [ ] Verify semantic HTML structure\n- [ ] Check color contrast ratios\n- [ ] Verify keyboard navigation support\n\n### Phase 2: On-Page SEO\n\n#### 2.1 Meta Tags (in `index.html` or per-page)\n```html\n<!-- Essential -->\n<title>Primary Keyword - Brand Name</title>\n<meta name=\"description\" content=\"150-160 chars, include keywords naturally\">\n\n<!-- Open Graph (Facebook, LinkedIn) -->\n<meta property=\"og:title\" content=\"Page Title\">\n<meta property=\"og:description\" content=\"Description\">\n<meta property=\"og:image\" content=\"https://example.com/og-image.png\">\n<meta property=\"og:url\" content=\"https://example.com/page\">\n<meta property=\"og:type\" content=\"website\">\n\n<!-- Twitter Cards -->\n<meta name=\"twitter:card\" content=\"summary_large_image\">\n<meta name=\"twitter:title\" content=\"Page Title\">\n<meta name=\"twitter:description\" content=\"Description\">\n<meta name=\"twitter:image\" content=\"https://example.com/twitter-image.png\">\n```\n\n#### 2.2 Heading Structure\n- [ ] Single `<h1>` per page with primary keyword\n- [ ] Logical heading hierarchy (h1 → h2 → h3)\n- [ ] Descriptive headings (not \"Section 1\")\n- [ ] Keywords in headings where natural\n\n#### 2.3 Content Quality\n- [ ] Unique, valuable content on each page\n- [ ] Internal linking between related pages\n- [ ] External links to authoritative sources\n- [ ] Alt text for all images\n\n### Phase 3: Schema Markup (Structured Data)\n\nAdd JSON-LD schema to `index.html` for rich snippets:\n\n#### 3.1 WebApplication Schema (for SaaS/Tools)\n```json\n{\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"WebApplication\",\n  \"name\": \"App Name\",\n  \"description\": \"What it does\",\n  \"url\": \"https://example.com\",\n  \"applicationCategory\": \"BusinessApplication\",\n  \"operatingSystem\": \"Web Browser\",\n  \"offers\": {\n    \"@type\": \"Offer\",\n    \"price\": \"0\",\n    \"priceCurrency\": \"USD\"\n  }\n}\n```\n\n#### 3.2 Organization Schema\n```json\n{\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"Organization\",\n  \"name\": \"Company Name\",\n  \"url\": \"https://example.com\",\n  \"logo\": \"https://example.com/logo.png\",\n  \"sameAs\": [\n    \"https://twitter.com/handle\",\n    \"https://github.com/handle\"\n  ]\n}\n```\n\n#### 3.3 FAQ Schema (if applicable)\n```json\n{\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"FAQPage\",\n  \"mainEntity\": [{\n    \"@type\": \"Question\",\n    \"name\": \"Question text?\",\n    \"acceptedAnswer\": {\n      \"@type\": \"Answer\",\n      \"text\": \"Answer text.\"\n    }\n  }]\n}\n```\n\n### Phase 4: AI Search Optimization (LLM/ChatGPT/Perplexity)\n\nAI-powered search engines extract and cite information differently than traditional crawlers.\n\n#### 4.1 Content Structure for AI\n- [ ] Use clear, factual statements that can be quoted\n- [ ] Structure content with clear Q&A patterns\n- [ ] Include \"What is X?\" and \"How to Y?\" sections\n- [ ] Use bullet points and numbered lists\n- [ ] Provide concise definitions and explanations\n\n#### 4.2 Cite-Worthy Information\n- [ ] Include unique data, statistics, or insights\n- [ ] Provide step-by-step instructions\n- [ ] Add comparison tables\n- [ ] Include pricing and feature information\n- [ ] Date content when relevant for freshness\n\n#### 4.3 Entity Clarity\n- [ ] Clearly state what the product/service IS\n- [ ] Define the target audience explicitly\n- [ ] List specific use cases\n- [ ] Compare to known alternatives (helps AI categorize)\n\n#### 4.4 llms.txt (Optional - Emerging Standard)\nCreate `/public/llms.txt` for AI crawlers:\n```\n# App Name\n\n> Brief description of what this is\n\n## About\nDetailed description for AI systems.\n\n## Features\n- Feature 1: Description\n- Feature 2: Description\n\n## Use Cases\n- Use case 1\n- Use case 2\n```\n\n### Phase 5: Files Checklist\n\nGenerate or verify these files exist:\n\n| File | Purpose |\n|------|---------|\n| `/public/robots.txt` | Crawler instructions |\n| `/public/sitemap.xml` | Page discovery |\n| `/public/favicon.ico` | Browser tab icon |\n| `/public/apple-touch-icon.png` | iOS home screen |\n| `/public/og-image.png` | Social sharing (1200x630) |\n| `/public/llms.txt` | AI search optimization |\n\n## Output Format\n\nAfter completing the audit, provide:\n\n1. **Critical Issues** - Must fix before launch\n2. **High Priority** - Significant SEO impact\n3. **Medium Priority** - Improvements for better ranking\n4. **Low Priority** - Nice to have optimizations\n5. **Implementation Plan** - Ordered list of fixes with code snippets\n\n## Quick Commands\n\nRun these to check common issues:\n\n```bash\n# Check for meta tags in index.html\ngrep -E \"<title>|<meta\" index.html\n\n# Find images without alt text\ngrep -r \"<img\" src/ | grep -v \"alt=\"\n\n# Check bundle size\nnpm run build && ls -la dist/assets/*.js\n\n# Validate HTML structure\nnpx html-validate dist/index.html\n```\n"},"lastSynced":"2026-03-07T01:52:34.216Z","agentAnalysis":{"suitability":{"en":"Perfect for Digital Marketing Agents needing advanced SEO analysis and optimization capabilities for traditional and AI-powered search systems.","zh":"非常适合需要高级SEO分析和优化能力的数字营销代理，适用于传统和AI驱动的搜索系统。","ja":"デジタルマーケティングエージェントが従来の検索システムとAI駆動の検索システムの両方に対する高度なSEO分析および最適化機能を必要とする場合に最適です。","ko":"전통적인 검색 시스템과 AI 기반 검색 시스템 모두에 대한 고급 SEO 분석 및 최적화 기능이 필요한 디지털 마케팅 에이전트에게 적합합니다.","es":"Perfecto para agentes de marketing digital que necesitan un análisis y capacidades de optimización de SEO avanzadas para sistemas de búsqueda tradicionales y impulsados por IA.","fr":"Parfait pour les agents de marketing numérique ayant besoin d''une analyse et de capacités d''optimisation de SEO avancées pour les systèmes de recherche traditionnels et alimentés par l''IA.","de":"Perfekt für digitale Marketingagenten, die erweiterte SEO-Analyse- und Optimierungsfunktionen für traditionelle und künstliche Intelligenz-basierte Suchsysteme benötigen.","pt":"Perfeito para Agentes de Marketing Digital que necessitam de capacidades avançadas de análise e otimização de SEO para sistemas de busca tradicionais e impulsionados por IA.","ru":"Идеально для цифровых маркетинговых агентов, которым необходимы расширенные возможности анализа и оптимизации SEO для традиционных и оснащенных ИИ систем поиска.","ar":"مثالي لوكلاء التسويق الرقمي الذين يحتاجون إلى قدرات متقدمة لتحليل وضبط جودة SEO لأنظمة البحث التقليدية والمدعومة بالذكاء الاصطناعي."},"recommendation":{"en":"Empowers agents to conduct ultra-detailed technical and on-page SEO audits, optimized for Google, Bing, and AI search, utilizing protocols like HTTP and HTTPS, and analyzing file formats such as HTML, CSS, and JavaScript.","zh":"赋予代理商进行超详细的技术和页面SEO审计的能力，针对Google、Bing和AI搜索进行优化，利用HTTP和HTTPS等协议，并分析HTML、CSS和JavaScript等文件格式。","ja":"Google、Bing、AI検索向けに最適化された、超詳細な技術およびオンページSEO監査を実施できる機能をエージェントに提供します。HTTPおよびHTTPSなどのプロトコルを利用し、HTML、CSS、JavaScriptなどのファイル形式を分析します。","ko":"에이전트가 초고해상도의 기술 및 온페이지 SEO 감사를 수행할 수 있는 기능을 제공합니다. Google, Bing 및 AI 검색을 최적화하고 HTTP 및 HTTPS와 같은 프로토콜을 사용하며 HTML, CSS 및 JavaScript와 같은 파일 형식을 분석합니다.","es":"Habilita a los agentes a realizar auditorías técnicas y de página ultra-detalladas de SEO, optimizadas para Google, Bing y búsqueda de IA, utilizando protocolos como HTTP y HTTPS, y analizando formatos de archivo como HTML, CSS y JavaScript.","fr":"Permet aux agents de réaliser des audits techniques et de page ultra-détaillés de SEO, optimisés pour Google, Bing et la recherche par IA, en utilisant des protocoles tels que HTTP et HTTPS, et en analysant des formats de fichiers tels que HTML, CSS et JavaScript.","de":"Ermöglicht es Agenten, ultra-detaillierte technische und Onpage-SEO-Audits durchzuführen, die für Google, Bing und künstliche Intelligenz-basierte Suche optimiert sind, unter Verwendung von Protokollen wie HTTP und HTTPS und Analyse von Dateiformaten wie HTML, CSS und JavaScript.","pt":"Habilita os agentes a realizar auditorias técnicas e de página ultra-detalladas de SEO, otimizadas para Google, Bing e busca por IA, utilizando protocolos como HTTP e HTTPS, e analisando formatos de arquivo como HTML, CSS e JavaScript.","ru":"Наделяет агентов возможностью проводить сверхдетальные технические и настроенные на страницу аудиты SEO, оптимизированные для Google, Bing и поиска с ИИ, использующие протоколы như HTTP и HTTPS, и анализирующие форматы файлов, такие как HTML, CSS и JavaScript.","ar":"تمكن الوكلاء من إجراء عمليات تدقيق تقنية وصفحة شاملة وفائقة الدقة لجودة SEO، مُحسنة لجوجل و بينج والبحث المدعوم بالذكاء الاصطناعي، باستخدام بروتوكولات مثل HTTP وHTTPS، وتحليل صيغ الملفات مثل HTML وCSS وJavaScript."},"useCases":{"en":["Auditing website SEO issues for improved search visibility","Optimizing website content for AI-powered search and chat systems","Debugging technical SEO problems for better discoverability","Analyzing on-page SEO elements for enhanced user experience"],"zh":["审核网站SEO问题以提高搜索可见性","优化网站内容以适应AI驱动的搜索和聊天系统","调试技术SEO问题以提高可发现性","分析页面SEO元素以增强用户体验"],"ja":["検索の可視性を向上させるためにWebサイトのSEO問題を監査する","AI駆動の検索およびチャットシステムに対応したWebサイトコンテンツを最適化する","発見性を向上させるために技術SEO問題をデバッグする","ユーザーエクスペリエンスを強化するためにオンページSEO要素を分析する"],"ko":["검색 가시성을 개선하기 위해 웹사이트의 SEO 문제 점검","AI 기반 검색 및 채팅 시스템을 위한 웹사이트 콘텐츠 최적화","발견 가능성을 개선하기 위해 기술 SEO 문제 디버깅","사용자 경험 개선을 위한 페이지 SEO 요소 분석"],"es":["Auditoría de problemas de SEO del sitio web para mejorar la visibilidad de búsqueda","Optimización del contenido del sitio web para sistemas de búsqueda y chat impulsados por IA","Depuración de problemas técnicos de SEO para una mejor capacidad de descubrimiento","Análisis de elementos de SEO de página para una experiencia de usuario mejorada"],"fr":["Audit des problèmes de SEO du site Web pour améliorer la visibilité de recherche","Optimisation du contenu du site Web pour les systèmes de recherche et de chat alimentés par l''IA","Débogage des problèmes techniques de SEO pour une meilleure découverte","Analyse des éléments de SEO de page pour une expérience utilisateur améliorée"],"de":["Prüfung von SEO-Problemen der Website zur Verbesserung der Suchsichtbarkeit","Optimierung des Website-Inhalts für künstliche Intelligenz-basierte Such- und Chat-Systeme","Fehlerbehebung bei technischen SEO-Problemen für eine bessere Auffindbarkeit","Analyse von Onpage-SEO-Elementen für ein verbessertes Benutzererlebnis"],"pt":["Auditoria de problemas de SEO do site para melhor visibilidade de pesquisa","Otimização do conteúdo do site para sistemas de busca e chat impulsionados por IA","Depuração de problemas técnicos de SEO para melhor descoberta","Análise de elementos de SEO de página para experiência do usuário aprimorada"],"ru":["Аудит проблем SEO веб-сайта для улучшения видимости поиска","Оптимизация контента веб-сайта для систем поиска и чата с ИИ","Отладка технических проблем SEO для лучшей обнаруживаемости","Анализ элементов SEO на странице для улучшения пользовательского опыта"],"ar":["تدقيق مشاكل جودة SEO لموقع الويب لتحسين الرؤية في البحث","تحسين محتوى موقع الويب لأنظمة البحث والتشات المدعمة بالذكاء الاصطناعي","تصحيح أخطاء فنية لمشاكل جودة SEO لتحسين khảية الاكتشاف","تحليل عناصر جودة SEO في الصفحة لتجربة مستخدم محسنة"]},"limitations":{"en":["Requires website access for analysis","Limited to traditional and AI-powered search systems","No support for offline or local website audits"],"zh":["需要网站访问权限进行分析","仅限传统和AI驱动的搜索系统","不支持离线或本地网站审计"],"ja":["分析のためにWebサイトへのアクセスが必要","従来の検索システムとAI駆動の検索システムのみに対応","オフラインまたはローカルWebサイト監査はサポートされていません"],"ko":["분석을 위해 웹사이트 액세스가 필요함","전통적인 검색 시스템 및 AI 기반 검색 시스템만 지원","오프라인 또는 로컬 웹사이트 감사가 지원되지 않음"],"es":["Requiere acceso al sitio web para análisis","Limitado a sistemas de búsqueda tradicionales y impulsados por IA","No admite auditorías de sitios web offline o locales"],"fr":["Nécessite un accès au site Web pour analyse","Limité aux systèmes de recherche traditionnels et alimentés par l''IA","Ne prend pas en charge les audits de sites Web hors ligne ou locaux"],"de":["Benötigt Zugriff auf die Website für die Analyse","Begrenzt auf traditionelle und künstliche Intelligenz-basierte Suchsysteme","Unterstützt keine Offline- oder Lokal-Website-Audits"],"pt":["Exige acesso ao site para análise","Limitado a sistemas de busca tradicionais e impulsionados por IA","Sem suporte para auditorias de site offline ou local"],"ru":["Требует доступа к веб-сайту для анализа","Ограничен для традиционных и оснащенных ИИ систем поиска","Нет поддержки для автономных или локальных аудитов веб-сайта"],"ar":["يتطلب الوصول إلى موقع الويب للتحليل","محدود لأنظمة البحث التقليدية والمدعومة بالذكاء الاصطناعي","بدون دعم لتدقيق موقع الويب بدون اتصال أو محلي"]},"version":4},"contentHash":"27ea738c81bec24d0af3ad467e47281f4c33408c77a5016a929ed46f4e00e72d","qualityScore":60}');
