INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('stancld/templify/seo-audit', 'seo-audit', 'stancld', 'templify', 'community', 'seo-audit stancld templify community The seo-audit skill conducts an ultra-detailed technical and on-page SEO audit, optimized for both traditional search engines and AI-powered search/chat systems, benefiting developers and website owners seeking to improve search visibility and discoverability. seo-audit 技能是一个超详细的技术和页面 SEO 审计工具，用于优化传统搜索引擎和 AI 驱动的搜索/聊天系统 seo-audit スキルは、伝統的な検索エンジンと AI駆動の検索/チャットシステムの両方を最適化するための超詳細な技術とページ SEO 監査ツールです SEO 감사 도구는 전통적인 검색 엔진과 AI 기반 검색/채팅 시스템을 모두 최적화하기 위한 초 상세한 기술 및 페이지 SEO 감사 도구입니다 La habilidad seo-audit realiza un análisis técnico y de página detallado para optimizar la visibilidad en buscadores tradicionales y sistemas de búsqueda y chat impulsados por IA. La compétence seo-audit effectue une analyse technique et de page détaillée pour optimiser la visibilité sur les moteurs de recherche traditionnels et les systèmes de recherche et de chat alimentés par l''IA. Die Fähigkeit seo-audit führt eine detaillierte technische und Onpage-Analyse durch, um die Sichtbarkeit in herkömmlichen Suchmaschinen und AI-Search-/Chat-Systemen zu optimieren. Realize uma auditoria de SEO técnica e de página com nossa ferramenta de IA, para melhorar a visibilidade nos motores de busca. Проведите техническую и на-page SEO-аудит с помощью нашей ИИ-функции, чтобы улучшить видимость в поисковых системах. أجرِ تحليل أداء محركات البحث الفني والصفحة باستخدام أداة الذكاء الاصطناعي لدينا، لتحسين الرؤية في محركات البحث. how to use seo-audit seo-audit setup guide seo-audit alternative seo-audit vs traditional SEO what is seo-audit seo-audit install seo-audit for AI search technical SEO audit tools on-page SEO optimization techniques seo-audit best practices SEO 审计 AI 驱动的搜索 传统搜索引擎 页面 SEO 技术 SEO 搜索引擎排名 用户体验 Google 优化 Bing 优化 Performs ultra-detailed technical and on-page SEO audits Optimizes for traditional search engines like Google and Bing Supports AI-powered search and chat systems Analyzes website details for improved search visibility and discoverability Suitable for pre-production website audits Covers extreme detail for comprehensive SEO analysis seo-audit is a technical skill that performs an in-depth analysis of a website''s SEO, covering both on-page and technical aspects to optimize for search engines and AI-powered systems.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pwittchen/varun.surf/review', 'community', 'pwittchen', 'varun.surf', 'pwittchen/varun.surf', 'review', 4, 0, 60, '2026-02-21T13:14:23Z', '2026-03-06T06:56:33.125Z', 'dc43ec27cdaa19f82ea23434b73f0f7312eec67bf564c278727252004c69e665', '{"id":"pwittchen/varun.surf/review","name":"review","description":{"en":"The review skill performs focused code reviews on specified files or recent git changes, benefiting developers and teams. It determines review scope and gathers files for efficient code examination.","zh":"Review Skill 是一个代码审查工具，支持快速审查指定文件或最近的 Git 变更","ja":"Review Skill はコードレビュー AIエージェントで、指定されたファイルや最近の Git 変更を迅速にレビュー","ko":"리뷰 스킬은 코드 리뷰 도구로 지정된 파일이나 최근 Git 변경 사항을 빠르게 리뷰","es":"La habilidad de revisión de código permite realizar una revisión rápida y enfocada de archivos específicos o cambios recientes en Git","fr":"La fonction de revue de code permet de réaliser une revue rapide et ciblée de fichiers spécifiques ou de modifications récentes dans Git","de":"Die Code-Review-Funktion ermöglicht eine schnelle und fokussierte Überprüfung von bestimmten Dateien oder aktuellen Änderungen in Git","pt":"A ferramenta de revisão de código Review é uma ferramenta poderosa para melhorar a qualidade do código. Ela permite uma revisão rápida e focada de arquivos específicos ou alterações recentes no Git.","ru":"ИИ Агент Review - это мощный инструмент для улучшения качества кода. Он позволяет быстро и эффективно обозревать отдельные файлы или недавние изменения в Git.","ar":"أداة المراجعة هي أداة قوية لتحسين جودة الكود. تمكنك من مراجعة سريعة ومتعمقة للملفات أو التغييرات الأخيرة في Git."},"seo":{"title":{"en":"Review: Code Review Setup Guide for AI Agents","zh":"代码审查工具 Review Skill 快速指南","ja":"Review Skill の設定方法: コードレビュー AIエージェント","ko":"리뷰 스킬 설정 가이드: 코드 리뷰와 Git 변경 사항","es":"Guía de configuración de la habilidad de revisión de código","fr":"Guide de mise en place de la fonction de revue de code","de":"Einrichtungsleitfaden für die Code-Review-Funktion","pt":"Guia de Configuração do Review: Ferramenta de Revisão de ...","ru":"Настройка ИИ Агента Review: Руководство по Обзору Кодов","ar":"دليل إعداد أداة المراجعة: أفضل الممارسات لمراجعة الكود"},"description":{"en":"Unlock efficient code reviews with the review skill - discover how to determine review scope, gather files, and optimize your workflow","zh":"了解 Review Skill 的技术细节和使用方法，实现快速代码审查和 Git 变更跟踪","ja":"Review Skill を使用してコードレビューを効率化し、Git 変更を簡単に追跡","ko":"리뷰 스킬을 사용하여 코드 리뷰를 빠르고 효율적으로 수행하고 Git 변경 사항을 추적","es":"Aprende a utilizar la habilidad de revisión de código para mejorar la calidad de tu proyecto con Git y CLI","fr":"Découvrez comment utiliser la fonction de revue de code pour améliorer la qualité de votre projet avec Git et CLI","de":"Erfahren Sie, wie Sie die Code-Review-Funktion nutzen können, um die Qualität Ihres Projekts mit Git und CLI zu verbessern","pt":"Aprenda a configurar e utilizar a ferramenta de revisão de código Review para melhorar a qualidade do seu código","ru":"Узнайте, как настроить и использовать ИИ Агент Review для обзора кода и улучшения его качества","ar":"تعلم كيفية إعداد أداة المراجعة و استخدامها لتحسين جودة الكود الخاص بك"},"definition":{"en":"Review is a skill that performs quick, focused code reviews on specified files or recent git changes, utilizing commands like /review src/main/java/.../MyService.java","zh":"Review Skill 是一种代码审查工具，用于快速审查代码和跟踪 Git 变更","ja":"Review Skill はコードレビュー AIエージェントで、コードと Git 変更を迅速にレビュー","ko":"리뷰 스킬은 코드 리뷰 도구로 코드와 Git 변경 사항을 빠르게 리뷰","es":"La revisión de código es una función que analiza y evalúa el código para detectar errores y mejoras","fr":"La revue de code est une fonction qui analyse et évalue le code pour détecter des erreurs et des améliorations","de":"Die Code-Review ist eine Funktion, die den Code analysiert und bewertet, um Fehler und Verbesserungsmöglichkeiten zu erkennen","pt":"O que é Review? É uma ferramenta de revisão de código que realiza uma análise rápida e focada de arquivos ou alterações no Git.","ru":"Что такое Review? Это ИИ Агент, который выполняет быстрый и сфокусированный обзор кода в отдельных файлах или изменениях в Git.","ar":"ما هي أداة المراجعة؟ هي أداة لمراجعة الكود التي تقوم بمراجعة سريعة ومتعمقة للملفات أو التغييرات في Git."},"features":{"en":["Determines review scope by parsing user requests","Gathers files for review using commands like /review staged or /review diff","Supports reviewing specific files, recent changes, staged changes, and last commit","Finds and reviews related files for a feature or component using /review ForecastService","Utilizes git changes and commands like /review changes for efficient code review"],"zh":["支持审查指定文件","支持审查最近的 Git 变更","支持审查暂存的变更","支持审查最后一次提交的变更","支持根据特征或组件查找和审查相关文件"],"ja":["特定ファイルのレビューをサポート","最近の Git 変更のレビューをサポート","ステージングされた変更のレビューをサポート","最後のコミットの変更のレビューをサポート","特性またはコンポーネントに基づいて関連ファイルを検索してレビュー"],"ko":["지정된 파일의 리뷰를 지원","最近의 Git 변경 사항의 리뷰를 지원","스테이징된 변경의 리뷰를 지원","마지막 커밋의 변경의 리뷰를 지원","특성 또는 컴포넌트에 따라 관련 파일을 검색하여 리뷰"],"es":["Revisión de archivos específicos con Git","Análisis de cambios recientes en el repositorio","Revisión de cambios en espera con Git","Análisis del último commit en el repositorio","Búsqueda y revisión de archivos relacionados con una función o componente específico"],"fr":["Revue de fichiers spécifiques avec Git","Analyse des modifications récentes dans le référentiel","Revue des modifications en attente avec Git","Analyse du dernier commit dans le référentiel","Recherche et revue de fichiers liés à une fonction ou un composant spécifique"],"de":["Überprüfung von bestimmten Dateien mit Git","Analyse von aktuellen Änderungen im Repository","Überprüfung von Änderungen in der Warteschlange mit Git","Analyse des letzten Commits im Repository","Suche und Überprüfung von Dateien in Verbindung mit einer bestimmten Funktion oder Komponente"],"pt":["Revisão de arquivos específicos","Revisão de alterações recentes no Git","Revisão de alterações em estágio","Revisão do último commit","Revisão de recursos ou componentes específicos"],"ru":["Обзор отдельных файлов","Обзор недавних изменений в Git","Обзор изменений в стадии","Обзор последнего коммита","Обзор определенных функций или компонентов"],"ar":["مراجعة الملفات الخاصة","مراجعة التغييرات الحديثة في Git","مراجعة التغييرات في مرحلة الإعداد","مراجعة آخر تعديل","مراجعة الميزات أو المكونات الخاصة"]},"keywords":{"en":["how to use review skill","review skill alternative","review skill vs git review","review skill install guide","what is review skill","review skill setup for AI agents","review skill for code optimization","review skill for developers","review skill tutorial"],"zh":["代码审查工具","Review Skill","Git 变更跟踪","代码 REVIEW","AI 代码审查","代码审查最佳实践","Git 代码管理"],"ja":["コードレビューツール","Review Skill","Git 変更追跡","コードレビュー","AI コードレビュー","コードレビューベストプラクティス","Git コード管理"],"ko":["코드 리뷰 도구","리뷰 스킬","Git 변경 사항 추적","코드 리뷰","AI 코드 리뷰","코드 리뷰最佳实践","Git 코드 관리"],"es":["revisión de código","Git","CLI","desarrollo de software","mejora de la calidad del código","herramientas de desarrollo","revisión de archivos","análisis de cambios"],"fr":["revue de code","Git","CLI","développement de logiciels","amélioration de la qualité du code","outils de développement","revue de fichiers","analyse de modifications"],"de":["Code-Review","Git","CLI","Software-Entwicklung","Qualitätsverbesserung des Codes","Entwicklungstools","Datei-Überprüfung","Änderungs-Analyse"],"pt":["revisão de código","ferramenta de revisão","Git","revisão de arquivos","revisão de alterações","desenvolvimento de software","qualidade de código","melhoria de código"],"ru":["обзор кода","ИИ Агент","Git","обзор файлов","обзор изменений","разработка программного обеспечения","качество кода","улучшение кода"],"ar":["مراجعة الكود","أداة المراجعة","Git","مراجعة الملفات","مراجعة التغييرات","تطوير البرمجيات","جودة الكود","تحسين الكود"]}},"owner":"pwittchen","repo":"varun.surf","repoPath":"pwittchen/varun.surf","stars":4,"forks":0,"updatedAt":"2026-02-21T13:14:23Z","topics":["kiteboarding","kitesurfing","weather-forecast","wind-forecast"],"category":"community","skillMd":{"name":"review","description":"Quick code review for files or recent changes, checking for bugs, best practices, and potential improvements","bodyPreview":"# Review Skill\n\nPerform a quick, focused code review on specified files or recent git changes.\n\n## Instructions\n\n### 1. Determine Review Scope\n\nParse the user''s request to determine what to review:\n- **Specific file(s)**: `/review src/main/java/.../MyService.java`\n- **Recent changes**: `/review changes` or `/review diff`\n- **Staged changes**: `/review staged`\n- **Last commit**: `/review last-commit`\n- **Feature/component**: `/review ForecastService` (find and review related files)\n\n### 2. Gather","body":"# Review Skill\n\nPerform a quick, focused code review on specified files or recent git changes.\n\n## Instructions\n\n### 1. Determine Review Scope\n\nParse the user''s request to determine what to review:\n- **Specific file(s)**: `/review src/main/java/.../MyService.java`\n- **Recent changes**: `/review changes` or `/review diff`\n- **Staged changes**: `/review staged`\n- **Last commit**: `/review last-commit`\n- **Feature/component**: `/review ForecastService` (find and review related files)\n\n### 2. Gather Code to Review\n\nBased on scope:\n\n**For specific files:**\n- Use `Read` to load the file content\n\n**For git changes:**\n- Use `Bash` with `git diff` for unstaged changes\n- Use `Bash` with `git diff --cached` for staged changes\n- Use `Bash` with `git show HEAD` for last commit\n- Use `Bash` with `git diff HEAD~N` for recent N commits\n\n**For component/feature:**\n- Use `Glob` and `Grep` to find relevant files\n- Read the main files involved\n\n### 3. Review Checklist\n\nAnalyze the code for:\n\n#### Correctness\n- Logic errors or bugs\n- Off-by-one errors\n- Null/undefined handling\n- Edge cases not covered\n- Incorrect assumptions\n\n#### Security\n- Input validation issues\n- Injection vulnerabilities (SQL, command, XSS)\n- Hardcoded secrets or credentials\n- Unsafe data handling\n\n#### Performance\n- Inefficient algorithms (O(n²) when O(n) possible)\n- Unnecessary iterations or allocations\n- Missing caching opportunities\n- Blocking calls in reactive code\n\n#### Best Practices\n- Code style consistency\n- Naming conventions\n- Error handling patterns\n- Resource cleanup (try-with-resources, close())\n- Thread safety in concurrent code\n\n#### Maintainability\n- Code duplication\n- Overly complex methods (consider splitting)\n- Missing or misleading comments\n- Dead code\n\n#### Project-Specific (varun.surf)\n- Reactive patterns (WebFlux compliance)\n- Proper use of virtual threads/StructuredTaskScope\n- Cache invalidation concerns\n- External API error handling\n\n### 4. Severity Levels\n\nCategorize findings:\n\n- **Critical**: Bugs, security issues, data loss risks\n- **Warning**: Performance issues, bad practices, potential bugs\n- **Suggestion**: Style improvements, minor optimizations, readability\n\n## Output Format\n\n```markdown\n## Code Review: [File/Scope]\n\n### Summary\n- Files reviewed: X\n- Lines analyzed: Y\n- Issues found: Z (X critical, Y warnings, Z suggestions)\n\n### Critical Issues\n\n#### [Issue Title]\n**File**: `path/to/file.java:line`\n**Problem**: [Description]\n**Fix**: [Suggested solution]\n```java\n// Before\nproblematic code\n\n// After\nfixed code\n```\n\n### Warnings\n\n#### [Issue Title]\n**File**: `path/to/file.java:line`\n**Problem**: [Description]\n**Suggestion**: [How to improve]\n\n### Suggestions\n\n- `file.java:42` - Consider extracting this to a method\n- `file.java:78` - Variable name could be more descriptive\n\n### What Looks Good\n\n- Proper error handling in [location]\n- Good use of [pattern/practice]\n- Clean separation of concerns\n\n### Files Reviewed\n- `path/to/file1.java` - [brief note]\n- `path/to/file2.java` - [brief note]\n```\n\n## Examples\n\n```bash\n# Review a specific file\n/review src/main/java/com/github/pwittchen/varun/service/ForecastService.java\n\n# Review recent uncommitted changes\n/review changes\n\n# Review staged changes before commit\n/review staged\n\n# Review the last commit\n/review last-commit\n\n# Review a component by name\n/review AggregatorService\n\n# Review multiple files\n/review src/main/java/.../controller/*.java\n```\n\n## Notes\n\n- Keep reviews focused and actionable\n- Prioritize critical issues over style nitpicks\n- Provide concrete fix suggestions, not just problem descriptions\n- Reference project patterns from CLAUDE.md when relevant\n- For large diffs, focus on the most impactful changes\n- Don''t repeat issues that appear multiple times; note \"X similar occurrences\"\n"},"lastSynced":"2026-03-06T06:56:33.125Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Analysis Agents needing advanced git change examination and review capabilities.","zh":"非常适合需要高级 git 变更检查和审查能力的代码分析代理。","ja":"コード分析エージェントが高度な git 変更の検査およびレビュー機能を必要とする場合に最適です。","ko":"고급 git 변경 사항 검사 및 검토 기능이 필요한 코드 분석 에이전트에 적합합니다.","es":"Perfecto para Agentes de Análisis de Código que necesitan un examen y revisión avanzados de cambios de git.","fr":"Parfait pour les Agents d''Analyse de Code nécessitant un examen et une révision avancés des modifications Git.","de":"Perfekt für Code-Analyse-Agents, die eine erweiterte Untersuchung und Überprüfung von Git-Änderungen benötigen.","pt":"Perfeito para Agentes de Análise de Código que precisam de exame e capacidades de revisão avançadas de alterações git.","ru":"Идеально подходит для агентов анализа кода, которым необходимы передовые возможности осмотра и рассмотрения изменений git.","ar":"مثالي لعميل تحليل الشفرة الذي يحتاج إلى فحص ومراجعة متقدمة لتغييرات جيت."},"recommendation":{"en":"Empowers agents to perform quick, focused code reviews on specified files or recent git changes, utilizing git protocols and parsing user requests to determine review scope, including staged changes and last commit analysis.","zh":"赋予代理快速、集中地对指定文件或最近的 git 变更进行代码审查的能力，利用 git 协议并解析用户请求以确定审查范围，包括暂存的变更和最后一次提交分析。","ja":"エージェントが指定されたファイルまたは最近の git 変更に対して迅速かつ集中したコードレビューを実行できるようにし、git プロトコルを利用してユーザーのリクエストを解析してレビュースコープを決定し、ステージされた変更と最後のコミット分析を含む。","ko":"에이전트가 지정된 파일 또는 최근의 git 변경 사항에 대한 빠르고 집중적인 코드 검토를 수행할 수 있도록 하며, git 프로토콜을 사용하여 사용자 요청을 구문 분석하여 검토 범위를 결정하며, चरण 변경 사항 및 마지막 커밋 분석을 포함합니다.","es":"Habilita a los agentes a realizar revisiones de código rápidas y enfocadas en archivos específicos o cambios recientes de git, utilizando protocolos de git y analizando solicitudes de usuario para determinar el alcance de la revisión, incluyendo cambios en espera y análisis del último compromiso.","fr":"Permet aux agents d''effectuer des revues de code rapides et ciblées sur des fichiers spécifiques ou des modifications Git récentes, en utilisant les protocoles Git et en analysant les requêtes utilisateur pour déterminer la portée de la revue, y compris les modifications en attente et l''analyse du dernier commit.","de":"Ermächtigt Agents, schnelle und fokussierte Code-Reviews auf bestimmte Dateien oder kürzliche Git-Änderungen durchzuführen, indem Git-Protokolle verwendet und Benutzeranfragen analysiert werden, um den Überprüfungsumfang zu bestimmen, einschließlich gestagter Änderungen und Analyse des letzten Commits.","pt":"Habilita os agentes a realizar revisões de código rápidas e focadas em arquivos específicos ou alterações git recentes, utilizando protocolos git e analisando solicitações de usuário para determinar o escopo da revisão, incluindo alterações em estágio e análise do último commit.","ru":"Позволяет агентам выполнять быстрые и сосредоточенные обзоры кода для определенных файлов или недавних изменений git, используя протоколы git и парся запросы пользователей для определения объема рассмотрения, включая изменения в стадии и анализ последнего коммита.","ar":"يمكن للوكلاء أداء مراجعات الشفرة السريعة والمتخصصة لأي ملفات أو تغييرات جيت حديثة، باستخدام بروتوكولات جيت وتحليل طلبات المستخدم لتحديد نطاق المراجعة، بما في ذلك التغييرات في مرحلة والتغييرات الأخيرة للالتزام."},"useCases":{"en":["Automating code reviews for specific files or recent changes","Debugging issues by examining staged or last commit changes","Generating review reports for feature or component-level code analysis"],"zh":["为特定文件或最近的变化自动执行代码审查","通过检查暂存或最后一次提交的变化来调试问题","为功能或组件级别的代码分析生成审查报告"],"ja":["特定ファイルまたは最近の変更に対するコードレビューを自動化する","ステージされた変更または最後のコミット変更を調べることで問題をデバッグする","機能またはコンポーネントレベルのコード分析のレビュー報告を生成する"],"ko":["특정 파일 또는 최근 변경 사항에 대한 코드 검토를 자동화하는 것","스테이지된 변경 사항 또는 마지막 커밋 변경 사항을 조사하여 문제를 디버깅하는 것","기능 또는 구성 요소 수준의 코드 분석을 위한 검토 보고서를 생성하는 것"],"es":["Automatización de revisiones de código para archivos o cambios específicos","Depuración de problemas examinando cambios en espera o del último compromiso","Generación de informes de revisión para análisis de código a nivel de características o componentes"],"fr":["Automatisation des revues de code pour des fichiers ou des modifications spécifiques","Débogage des problèmes en examinant les modifications en attente ou du dernier commit","Génération de rapports de revue pour l''analyse de code au niveau des fonctionnalités ou des composants"],"de":["Automatisierung von Code-Reviews für bestimmte Dateien oder Änderungen","Fehlerbehebung durch Untersuchung von gestagten oder letzten Commit-Änderungen","Erstellung von Review-Berichten für Code-Analyse auf Feature- oder Komponentenebene"],"pt":["Automatizar revisões de código para arquivos ou alterações específicas","Depurar problemas examinando alterações em estágio ou últimas alterações do commit","Gerar relatórios de revisão para análise de código em nível de recurso ou componente"],"ru":["Автоматизировать обзоры кода для определенных файлов или изменений","Отлаживать проблемы, рассматривая изменения в стадии или последние изменения коммита","Генерировать отчеты об обзоре для анализа кода на уровне функции или компонента"],"ar":["تأتمتة مراجعات الشفرة لأي ملفات أو تغييرات محددة","تصحيح الأخطاء من خلال فحص التغييرات في مرحلة أو آخر التغييرات في الالتزام","توليد تقارير المراجعة لتحليل الشفرة على مستوى الميزة أو المكون"]},"limitations":{"en":["Requires git repository access","Limited to reviewing files or changes within the git repository"],"zh":["需要 git 仓库访问","仅限于 git 仓库内的文件或变化审查"],"ja":["git リポジトリへのアクセスが必要","git リポジトリ内のファイルまたは変更のみをレビューする"],"ko":["git 저장소 액세스가 필요함","git 저장소 내의 파일 또는 변경 사항만을 검토하는 것"],"es":["Requiere acceso al repositorio de git","Limitado a la revisión de archivos o cambios dentro del repositorio de git"],"fr":["Nécessite un accès au référentiel Git","Limité à la revue de fichiers ou de modifications à l''intérieur du référentiel Git"],"de":["Benötigt Zugriff auf das Git-Repository","Begrenzt auf die Überprüfung von Dateien oder Änderungen innerhalb des Git-Repositorys"],"pt":["Exige acesso ao repositório git","Limitado à revisão de arquivos ou alterações dentro do repositório git"],"ru":["Требует доступа к репозиторию git","Ограничен рассмотрением файлов или изменений внутри репозитория git"],"ar":["يتطلب وصول إلى مستودع جيت","محدود بمراجعة الملفات أو التغييرات داخل مستودع جيت"]},"version":4},"contentHash":"dc43ec27cdaa19f82ea23434b73f0f7312eec67bf564c278727252004c69e665","qualityScore":60}');
