INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pwittchen/varun.surf/review', 'review', 'pwittchen', 'varun.surf', 'community', 'review pwittchen varun.surf community kiteboarding kitesurfing weather-forecast wind-forecast The review skill performs focused code reviews on specified files or recent git changes, benefiting developers and teams. It determines review scope and gathers files for efficient code examination. Review Skill 是一个代码审查工具，支持快速审查指定文件或最近的 Git 变更 Review Skill はコードレビュー AIエージェントで、指定されたファイルや最近の Git 変更を迅速にレビュー 리뷰 스킬은 코드 리뷰 도구로 지정된 파일이나 최근 Git 변경 사항을 빠르게 리뷰 La habilidad de revisión de código permite realizar una revisión rápida y enfocada de archivos específicos o cambios recientes en Git La fonction de revue de code permet de réaliser une revue rapide et ciblée de fichiers spécifiques ou de modifications récentes dans Git Die Code-Review-Funktion ermöglicht eine schnelle und fokussierte Überprüfung von bestimmten Dateien oder aktuellen Änderungen in Git A ferramenta de revisão de código Review é uma ferramenta poderosa para melhorar a qualidade do código. Ela permite uma revisão rápida e focada de arquivos específicos ou alterações recentes no Git. ИИ Агент Review - это мощный инструмент для улучшения качества кода. Он позволяет быстро и эффективно обозревать отдельные файлы или недавние изменения в Git. أداة المراجعة هي أداة قوية لتحسين جودة الكود. تمكنك من مراجعة سريعة ومتعمقة للملفات أو التغييرات الأخيرة في Git. how to use review skill review skill alternative review skill vs git review review skill install guide what is review skill review skill setup for AI agents review skill for code optimization review skill for developers review skill tutorial 代码审查工具 Review Skill Git 变更跟踪 代码 REVIEW AI 代码审查 代码审查最佳实践 Git 代码管理 Determines review scope by parsing user requests Gathers files for review using commands like /review staged or /review diff Supports reviewing specific files, recent changes, staged changes, and last commit Finds and reviews related files for a feature or component using /review ForecastService Utilizes git changes and commands like /review changes for efficient code review Review is a skill that performs quick, focused code reviews on specified files or recent git changes, utilizing commands like /review src/main/java/.../MyService.java');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('DavidROliverBA/ArchitectKB/hld-review', 'community', 'DavidROliverBA', 'ArchitectKB', 'DavidROliverBA/ArchitectKB', 'hld-review', 4, 1, 60, '2026-02-24T08:55:16Z', '2026-03-06T06:56:55.287Z', 'acf3b471fbf8d5de9895f37b87ac994b46ecc3f10b1baeb0f2eed1144a7dfc37', '{"id":"DavidROliverBA/ArchitectKB/hld-review","name":"hld-review","description":{"en":"The hld-review skill evaluates High-Level Design notes against linked ADRs, requirements, and architecture principles, producing a structured review with scoring and actionable next steps for Solutions Architects.","zh":"hld-review是一种综合的知识管理系统，使用AI评估高级设计笔记，生成结构化的评审结果","ja":"hld-reviewは、AIエージェントを使用したコンセプト設計ノートの評価システムであり、構造化されたレビューレポートを生成","ko":"hld-review는 솔루션 아키텍트를 위한 지식 관리 시스템으로 AI를 사용하여 고급 설계 노트를 평가하고 구조화된 검토 결과를 생성","es":"hld-review es un sistema de gestión de conocimiento que evalúa diseños de alto nivel contra ADRs, requisitos y principios de arquitectura","fr":"hld-review est un système de gestion des connaissances qui évalue les conceptions de haut niveau par rapport aux ADR, aux exigences et aux principes d''architecture","de":"hld-review ist ein Wissensmanagementsystem, das High-Level-Designs gegen ADRs, Anforderungen und Architekturprinzipien bewertet","pt":"O hld-review é uma ferramenta de revisão de design de alto nível com IA que ajuda a avaliar e melhorar a qualidade dos projetos de arquitetura de soluções","ru":"hld-review - инструмент ИИ Агентов для обзора высокоуровневого дизайна, помогающий оценить и улучшить качество проектов архитектуры решений","ar":"أداة المراجعة المصممة للتصميم بال층 العالية باستخدام الإی آر هي أداة تقييم وتحسين جودة مشاريع التصميم المعماري للحلول"},"seo":{"title":{"en":"hld-review: Comprehensive HLD Note Review for AI Agents |...","zh":"hld-review_SETUP GUIDE：AI知识管理系统","ja":"hld-reviewセットアップガイド：AIエージェントを使用したコンセプト設計レビュー","ko":"hld-review 설정 가이드: 솔루션 아키텍트를 위한 AI 지식 관리 시스템","es":"Guía de configuración de hld-review para arquitectos de s...","fr":"Guide de configuration de hld-review pour les architectes...","de":"Einrichtungsleitfaden für hld-review für Lösungsarchitekt...","pt":"Guia de Configuração do hld-review: Ferramenta de Revisão...","ru":"Настройка hld-review: Инструмент ИИ Агентов для Обзора Вы...","ar":"دليل إعداد hld-review: أداة المراجعة المصممة للتصميم بال层..."},"description":{"en":"Unlock structured reviews with scoring and actionable next steps. Learn how to use /hld-review to evaluate High-Level Design notes against ADRs, requirements...","zh":"使用hld-review AI知识管理系统评估高级设计笔记，获取结构化的评审结果和行动步骤","ja":"hld-review AIエージェントを使用してコンセプト設計ノートを評価し、構造化されたレビューレポートを取得","ko":"hld-review를 사용하여 고급 설계 노트를 평가하고 구조화된 검토 결과 및 다음 단계를 가져옵니다","es":"Aprende a evaluar diseños de alto nivel con hld-review y mejora tus habilidades como arquitecto de soluciones con la ayuda de Agentes de IA","fr":"Découvrez comment évaluer les conceptions de haut niveau avec hld-review et améliorez vos compétences en tant qu''architecte de solutions avec les Outils d''IA","de":"Erfahren Sie, wie Sie High-Level-Designs mit hld-review bewerten und Ihre Fähigkeiten als Lösungsarchitekt mit KI-Tools verbessern","pt":"Aprenda a configurar o hld-review, uma ferramenta de revisão de design de alto nível com IA, e melhore a qualidade dos seus projetos de arquitetura de soluções","ru":"Узнайте, как настроить hld-review, инструмент ИИ Агентов для обзора высокоуровневого дизайна, и повысьте качество своих проектов архитектуры решений","ar":"تعرف على كيفية إعداد أداة المراجعة المصممة للتصميم بال층 العالية باستخدام الإی آر، وطور جودة مشاريعك المعمارية للحلول"},"definition":{"en":"hld-review is a comprehensive knowledge management system that uses AI to review High-Level Design notes, providing a structured evaluation with severity-rated findings and next steps.","zh":"hld-review是一种AI驱动的知识管理系统，用于评估高级设计笔记","ja":"hld-reviewは、AIエージェントを使用したコンセプト設計ノートの評価ツール","ko":"hld-review는 고급 설계 노트를 평가하는 AI 기반 지식 관리 시스템","es":"hld-review es un sistema de gestión de conocimiento que utiliza IA para evaluar diseños de alto nivel","fr":"hld-review est un système de gestion des connaissances qui utilise l''IA pour évaluer les conceptions de haut niveau","de":"hld-review ist ein Wissensmanagementsystem, das KI verwendet, um High-Level-Designs zu bewerten","pt":"O hld-review é uma ferramenta de revisão de design de alto nível que utiliza IA para avaliar projetos de arquitetura de soluções","ru":"hld-review - инструмент обзора высокоуровневого дизайна, использующий ИИ Агентов для оценки проектов архитектуры решений","ar":"أداة المراجعة المصممة للتصميم بال층 العالية هي أداة تقييم مشاريع التصميم المعماري للحلول باستخدام الإی آر"},"features":{"en":["Evaluates High-Level Design notes against linked ADRs and requirements","Produces a structured review with scoring across six dimensions","Generates severity-rated findings and actionable next steps","Supports command-line usage with /hld-review <HLD note title>","Requires a matching existing HLD note title as an argument","Provides a comprehensive review of architecture principles"],"zh":["评估高级设计笔记","生成结构化的评审结果","六维评分系统","严重性评级的发现","可行的下一步"],"ja":["コンセプト設計ノートの評価","構造化されたレビューレポートの生成","六つの評価軸","重大性の評価された発見","実行可能な次のステップ"],"ko":["고급 설계 노트 평가","구조화된 검토 결과 생성","6차원 평가 시스템","严重性 평가된 발견","실행 가능한 다음 단계"],"es":["Evaluación de diseños de alto nivel contra ADRs y requisitos","Producción de una revisión estructurada con puntuación en seis dimensiones","Hallazgos con calificación de gravedad y pasos siguientes acciónables","Uso de principios de arquitectura para guiar la evaluación","Compatibilidad con títulos de notas de diseño de alto nivel existentes","Generación de resultados en formato estructurado"],"fr":["Évaluation des conceptions de haut niveau par rapport aux ADR et aux exigences","Production d''une revue structurée avec notation sur six dimensions","Découvertes avec évaluation de la gravité et étapes suivantes actionnables","Utilisation de principes d''architecture pour guider l''évaluation","Compatibilité avec les titres de notes de conception de haut niveau existants","Génération de résultats au format structuré"],"de":["Bewertung von High-Level-Designs gegen ADRs und Anforderungen","Erzeugung einer strukturierten Überprüfung mit Punktzahl in sechs Dimensionen","Feststellungen mit Schweregradbewertung und handhabbaren nächsten Schritten","Verwendung von Architekturprinzipien zur Steuerung der Bewertung","Kompatibilität mit bestehenden Titeln von High-Level-Design-Notizen","Erzeugung von Ergebnissen im strukturierten Format"],"pt":["Avaliação de design de alto nível contra ADRs e requisitos","Geração de relatórios estruturados com pontuação em seis dimensões","Identificação de achados com classificação de gravidade e etapas de ação","Integração com CLI para facilidade de uso","Suporte a múltiplos projetos de arquitetura de soluções","Análise de conformidade com princípios de arquitetura"],"ru":["Оценка высокоуровневого дизайна против АDR и требований","Генерация структурированных отчетов с оценкой в шести измерениях","Определение результатов с классификацией тяжести и шагами действий","Интеграция с CLI для простоты использования","Поддержка нескольких проектов архитектуры решений","Анализ соответствия принципам архитектуры"],"ar":["تقييم التصميم بال층 العالية مقابل الأدر و المتطلبات","توليد تقارير منظم مع تقييم في ستة أبعاد","تحديد النتائج مع تصنيف الخطورة وخطوات العمل","التكامل مع CLI لسهولة الاستخدام","دعم مشاريع متعددة للتصميم المعماري للحلول","تحليل مطابقة المبادئ المعمارية"]},"keywords":{"en":["how to use hld-review","hld-review setup guide","hld-review alternative","hld-review vs architecture review tools","hld-review install","what is hld-review","hld-review for Solutions Architects","hld-review AI agent","hld-review High-Level Design note review","hld-review ADR evaluation"],"zh":["hld-review","AI知识管理系统","高级设计笔记评估","结构化评审结果","六维评分系统","AI工具","知识管理"],"ja":["hld-review","AIエージェント","コンセプト設計ノート評価","構造化されたレビューレポート","六つの評価軸","AIツール","知識管理"],"ko":["hld-review","AI 지식 관리 시스템","고급 설계 노트 평가","구조화된 검토 결과","6차원 평가 시스템","AI 에이전트","지식 관리"],"es":["hld-review","Agentes de IA","arquitectos de soluciones","diseños de alto nivel","evaluación de diseño","ADR","requisitos","principios de arquitectura","sistemas de gestión de conocimiento"],"fr":["hld-review","Outils d''IA","architectes de solutions","conceptions de haut niveau","évaluation de conception","ADR","exigences","principes d''architecture","systèmes de gestion des connaissances"],"de":["hld-review","KI-Tools","Lösungsarchitekten","High-Level-Designs","Designbewertung","ADR","Anforderungen","Architekturprinzipien","Wissensmanagementsysteme"],"pt":["hld-review","revisão de design de alto nível","IA para arquitetura de soluções","ferramenta de revisão de design","CLI para revisão de design","arquitetura de soluções","projetos de arquitetura de soluções","revisão de design com IA"],"ru":["hld-review","обзор высокоуровневого дизайна","ИИ Агенты для архитектуры решений","инструмент обзора дизайна","CLI для обзора дизайна","архитектура решений","проекты архитектуры решений","обзор дизайна с ИИ"],"ar":["hld-review","مراجعة التصميم بال층 العالية","الإی آر للأدوات المعمارية","أداة مراجعة التصميم","CLI لمراجعة التصميم","الأدوات المعمارية","مشاريع التصميم المعماري","مراجعة التصميم بالإی آر"]}},"owner":"DavidROliverBA","repo":"ArchitectKB","repoPath":"DavidROliverBA/ArchitectKB","stars":4,"forks":1,"updatedAt":"2026-02-24T08:55:16Z","topics":[],"category":"community","skillMd":{"name":"hld-review","description":"Evaluate an HLD note against linked ADRs, requirements, and architecture principles across six dimensions","bodyPreview":"# /hld-review\n\nEvaluate a High-Level Design (HLD) note against linked ADRs, requirements, and architecture principles. Produces a structured review with scoring across six dimensions, severity-rated findings, and actionable next steps.\n\n## Usage\n\n```\n/hld-review <HLD note title>\n/hld-review HLD - Remote Vault Access Architecture\n/hld-review HLD - SecureTransfer Azure Files to S3 Mirroring\n```\n\n## Arguments\n\n- **$ARGUMENTS**: The title of the HLD note to review (required). Must match an existing","body":"# /hld-review\n\nEvaluate a High-Level Design (HLD) note against linked ADRs, requirements, and architecture principles. Produces a structured review with scoring across six dimensions, severity-rated findings, and actionable next steps.\n\n## Usage\n\n```\n/hld-review <HLD note title>\n/hld-review HLD - Remote Vault Access Architecture\n/hld-review HLD - SecureTransfer Azure Files to S3 Mirroring\n```\n\n## Arguments\n\n- **$ARGUMENTS**: The title of the HLD note to review (required). Must match an existing `HLD - *.md` file in the vault root.\n\n## Review Dimensions\n\n| Dimension | What Is Checked |\n|---|---|\n| **ADR Coverage** | Does each significant design choice have a corresponding ADR? Are referenced ADRs accepted? |\n| **Requirements Traceability** | Are all referenced requirements (from `relatedTo`, project notes, linked concepts) addressed in the design? |\n| **Principle Compliance** | Does the design align with vault architecture principles (`Concept` notes with `conceptType: principle`)? |\n| **Security Architecture** | Are threat mitigations documented? Are security boundaries, encryption, and access controls explicit? |\n| **Integration Clarity** | Are system interfaces, data flows, protocols, and error handling paths clearly defined? |\n| **Operational Readiness** | Are monitoring, deployment strategy, runbook considerations, and rollback plans addressed? |\n\n## Instructions\n\n### Phase 1: Load the HLD\n\n1. **Parse the command** — extract the HLD note title from `$ARGUMENTS`\n2. **Find the HLD file** — search for the file at the vault root matching the title\n   - If not found, search using Grep for partial title matches across `HLD - *.md` files\n   - If still not found, report the error and list available HLD notes\n3. **Read the HLD note** — load the full content including frontmatter and body\n4. **Extract metadata:**\n   - `relatedTo` wiki-links from frontmatter\n   - `tags` for domain context\n   - `confidence`, `freshness`, `verified` quality indicators\n   - Any inline wiki-links in the body text (`[[...]]` references)\n\n### Phase 2: Gather Context\n\n1. **Read linked notes** — for each wiki-link found in `relatedTo` and body text:\n   - Read each linked note (ADRs, Systems, Concepts, Projects, Patterns)\n   - Categorise by type: ADR, System, Concept (principle/capability), Project, Pattern, Threat, other\n   - Note the status of each ADR (draft/proposed/accepted/deprecated/superseded)\n\n2. **Query for architecture principles** — find all `Concept` notes with `conceptType: principle`:\n   ```bash\n   node .claude/scripts/graph-query.js --type=Concept --tag=conceptType/principle\n   ```\n   If the graph query returns no results, fall back to:\n   ```bash\n   grep -rl \"conceptType: principle\" *.md\n   ```\n   Read each principle note to extract:\n   - `statement` — the principle itself\n   - `implications` — what follows from the principle\n   - `domain` — which domain it applies to\n\n3. **Query for related threats** — search for Threat notes relevant to the HLD''s domain:\n   - Check tags on the HLD for domain indicators (e.g., `domain/security`, `domain/cloud`, `domain/integration`)\n   - Search: `node .claude/scripts/graph-query.js --type=Threat`\n   - Match threats by `affectedSystems` and domain overlap\n\n4. **Check for related ADRs not yet linked** — search for ADRs whose `relatedTo` or `project` fields reference the same systems or projects as the HLD:\n   ```bash\n   node .claude/scripts/graph-query.js --type=Adr --tag=status/accepted\n   ```\n\n### Phase 3: Evaluate Each Dimension\n\nScore each dimension as **PASS**, **PARTIAL**, or **FAIL** using the criteria below.\n\n#### 3.1 ADR Coverage\n\n| Score | Criteria |\n|---|---|\n| **PASS** | Every significant design choice (technology selection, architectural pattern, integration approach) has a corresponding accepted ADR |\n| **PARTIAL** | Some design choices have ADRs but others are undocumented, or ADRs exist but are still in draft/proposed status |\n| **FAIL** | Major design choices lack ADR coverage entirely |\n\n**How to assess:**\n- Identify each significant design choice in the HLD (technology selections, architectural patterns, protocol choices)\n- Check whether an ADR exists for each choice (via `relatedTo` links or vault search)\n- Note any ADRs that are `draft` or `proposed` rather than `accepted`\n- Flag design choices that contradict accepted ADRs\n\n#### 3.2 Requirements Traceability\n\n| Score | Criteria |\n|---|---|\n| **PASS** | All requirements referenced in linked project/concept notes are explicitly addressed in the HLD |\n| **PARTIAL** | Most requirements are addressed but some are missing or only implicitly covered |\n| **FAIL** | Significant requirements gaps — linked requirements not addressed in the design |\n\n**How to assess:**\n- Extract requirements from linked Project notes (goals, constraints, scope)\n- Extract requirements from linked Concept notes (capabilities, principles)\n- Verify each requirement has a corresponding design element in the HLD\n- Check for orphaned requirements (mentioned in links but not in design)\n\n#### 3.3 Principle Compliance\n\n| Score | Criteria |\n|---|---|\n| **PASS** | Design explicitly aligns with all applicable architecture principles; no contradictions |\n| **PARTIAL** | Design is broadly consistent but some principles are not explicitly addressed |\n| **FAIL** | Design contradicts one or more architecture principles, or ignores critical principles |\n\n**How to assess:**\n- For each principle note loaded in Phase 2, check whether the HLD design aligns with the principle''s `statement` and `implications`\n- Focus on principles whose `domain` matches the HLD''s domain tags\n- Flag any contradictions between the design and established principles\n\n#### 3.4 Security Architecture\n\n| Score | Criteria |\n|---|---|\n| **PASS** | Security boundaries, encryption (in-transit and at-rest), authentication, authorisation, and threat mitigations are all explicitly documented |\n| **PARTIAL** | Some security aspects are covered but gaps exist (e.g., encryption mentioned but no auth model) |\n| **FAIL** | Security is not meaningfully addressed in the HLD |\n\n**How to assess:**\n- Check for explicit security boundaries (network isolation, trust zones)\n- Verify encryption is specified for data in transit and at rest\n- Look for authentication and authorisation mechanisms\n- Cross-reference with Threat notes — are relevant threats mitigated?\n- Check for data classification and GDPR considerations if personal data is involved\n\n#### 3.5 Integration Clarity\n\n| Score | Criteria |\n|---|---|\n| **PASS** | All system interfaces are documented with protocols, data formats, error handling, and SLAs |\n| **PARTIAL** | Interfaces are identified but details are incomplete (missing protocols, no error handling) |\n| **FAIL** | System interfaces are vague or missing — unclear how components communicate |\n\n**How to assess:**\n- Identify all system boundaries and interfaces in the HLD\n- Check each interface for: protocol, data format, authentication method, error handling\n- Verify data flow direction is explicit (which system initiates, which responds)\n- Look for SLA/latency/throughput specifications where applicable\n- Check for retry and failure handling strategies\n\n#### 3.6 Operational Readiness\n\n| Score | Criteria |\n|---|---|\n| **PASS** | Monitoring, alerting, deployment strategy, rollback plan, and operational runbook considerations are documented |\n| **PARTIAL** | Some operational aspects are covered but the design lacks deployment or monitoring detail |\n| **FAIL** | No operational considerations — the HLD focuses only on functional architecture |\n\n**How to assess:**\n- Check for monitoring and alerting strategy\n- Look for deployment approach (blue/green, rolling, canary)\n- Verify rollback/recovery procedures are considered\n- Check for logging and observability mentions\n- Look for capacity planning and scaling considerations\n- Check for runbook or operational handover references\n\n### Phase 4: Compile Findings\n\nCategorise each finding by severity:\n\n| Severity | Definition | Action Required |\n|---|---|---|\n| **BLOCKING** | Fundamental gap that must be resolved before the design can proceed to implementation | Rework required |\n| **ADVISORY** | Gap that should be addressed but does not prevent progress | Address before go-live |\n| **INFORMATIONAL** | Observation or suggestion for improvement | Consider in future iterations |\n\n### Phase 5: Determine Review Status\n\nBased on the dimension scores and finding severities:\n\n| Status | When Applied |\n|---|---|\n| **APPROVED** | All dimensions PASS, no BLOCKING findings |\n| **APPROVED WITH CONDITIONS** | No dimensions FAIL, but PARTIAL scores exist or ADVISORY findings need attention |\n| **NEEDS REWORK** | Any dimension scores FAIL, or any BLOCKING findings exist |\n\n### Phase 6: Generate Review Output\n\nOutput the review directly to the console. Use the template below.\n\n---\n\n## Output Template\n\n```markdown\n# HLD Review: [HLD Title]\n\n**Reviewed:** [today''s date]\n**HLD Created:** [created date from frontmatter]\n**Last Reviewed:** [reviewed date from frontmatter]\n**Confidence:** [confidence from frontmatter]\n\n---\n\n## Review Status: [APPROVED / APPROVED WITH CONDITIONS / NEEDS REWORK]\n\n---\n\n## Scoring Summary\n\n| Dimension | Score | Evidence | Gaps |\n|---|---|---|---|\n| ADR Coverage | [PASS/PARTIAL/FAIL] | [what ADRs exist and cover] | [what design choices lack ADRs] |\n| Requirements Traceability | [PASS/PARTIAL/FAIL] | [requirements addressed] | [requirements not addressed] |\n| Principle Compliance | [PASS/PARTIAL/FAIL] | [principles aligned with] | [principles not addressed or contradicted] |\n| Security Architecture | [PASS/PARTIAL/FAIL] | [security measures documented] | [security aspects missing] |\n| Integration Clarity | [PASS/PARTIAL/FAIL] | [interfaces documented] | [interfaces lacking detail] |\n| Operational Readiness | [PASS/PARTIAL/FAIL] | [operational aspects covered] | [operational aspects missing] |\n\n---\n\n## Findings\n\n### BLOCKING\n\n[If none: \"No blocking findings.\"]\n\n1. **[Finding Title]** — [Description of the gap, which dimension it affects, and why it blocks progress]\n   - **Dimension:** [affected dimension]\n   - **Recommendation:** [specific action to resolve]\n\n### ADVISORY\n\n[If none: \"No advisory findings.\"]\n\n1. **[Finding Title]** — [Description and recommendation]\n   - **Dimension:** [affected dimension]\n   - **Recommendation:** [specific action to resolve]\n\n### INFORMATIONAL\n\n[If none: \"No informational findings.\"]\n\n1. **[Finding Title]** — [Observation or suggestion]\n\n---\n\n## Conditions\n\n[Only include if status is APPROVED WITH CONDITIONS]\n\nThe following conditions must be addressed before implementation:\n\n- [ ] [Condition 1 — specific, actionable item]\n- [ ] [Condition 2]\n\n---\n\n## Context Analysed\n\n### Linked ADRs\n| ADR | Status | Relevance |\n|-----|--------|-----------|\n| [[ADR - Title]] | accepted | [how it relates to the HLD] |\n\n### Architecture Principles Assessed\n| Principle | Domain | Compliance |\n|-----------|--------|------------|\n| [[Concept - Principle Name]] | [domain] | [aligned/not addressed/contradicted] |\n\n### Threat Coverage\n| Threat | Severity | Mitigated? |\n|--------|----------|------------|\n| [[Threat - Name]] | [severity] | [yes/partial/no] |\n\n### Systems Referenced\n[List of System notes referenced in the HLD with their status]\n\n---\n\n## Next Steps\n\n- [ ] [Action item based on findings — e.g., \"Create ADR for Docker orchestration choice\"]\n- [ ] [Action item — e.g., \"Add monitoring section to HLD\"]\n- [ ] [Action item — e.g., \"Link Threat - Denial of Service and document mitigation\"]\n- [ ] Update HLD `reviewed` date to today\n- [ ] Update HLD `verified` to `true` once conditions are met\n```\n\n---\n\n## Examples\n\n### Example 1: Quick Review\n\n```\n/hld-review HLD - Remote Vault Access Architecture\n```\n\nReviews the HLD against all six dimensions, checking linked ADRs, vault principles, relevant threats, and operational completeness.\n\n### Example 2: Review After ADR Changes\n\n```\n/hld-review HLD - SecureTransfer Azure Files to S3 Mirroring\n```\n\nUseful after new ADRs are accepted to verify the HLD still aligns with the latest decisions.\n\n## Error Handling\n\n- **HLD not found:** List all available HLD notes in the vault and ask the user to confirm\n- **No linked notes:** Report that the HLD has an empty `relatedTo` field — this is itself a finding (ADVISORY: \"HLD lacks cross-references to ADRs, systems, and requirements\")\n- **Graph index unavailable:** Fall back to Grep-based search for principles and threats\n- **No principles found:** Note this as INFORMATIONAL — the vault may not yet have principle notes established\n\n## Related Skills\n\n- `/nfr-review` — Review an HLD against NFR requirements (complementary to this skill)\n- `/diagram-review` — Analyse architecture diagrams for readability and quality\n- `/adr` — Create new ADRs for design choices identified as gaps\n- `/diagram` — Generate architecture diagrams referenced in the HLD\n- `/impact-analysis` — Analyse the impact of changes to systems in the HLD\n\n## Related Notes\n\n- `.claude/rules/naming-conventions.md` — HLD naming patterns\n- `.claude/context/frontmatter-reference.md` — HLD frontmatter schema\n- `.claude/context/architecture.md` — Architecture governance context\n"},"lastSynced":"2026-03-06T06:56:55.287Z","agentAnalysis":{"suitability":{"en":"Perfect for Architecture Analysis Agents needing comprehensive High-Level Design review capabilities against linked ADRs and architecture principles.","zh":"非常适合需要对链接的ADR和架构原则进行全面高级设计审查的架构分析代理。","ja":"アーキテクチャ分析エージェントがリンクされたADRおよびアーキテクチャ原則に対する包括的なハイレベル設計レビュー機能を必要とする場合に最適です。","ko":"링크된 ADR 및 아키텍처 원칙에 대한 포괄적인 고급 디자인 검토 기능이 필요한 아키텍처 분석 에이전트에 적합합니다.","es":"Perfecto para agentes de análisis de arquitectura que necesitan capacidades de revisión de diseño de alto nivel integral contra ADRs y principios de arquitectura vinculados.","fr":"Parfait pour les agents d''analyse d''architecture nécessitant des capacités de révision de conception de haut niveau complètes contre les ADR et les principes d''architecture liés.","de":"Perfekt für Architekturanalyse-Agents, die umfassende High-Level-Design-Review-Funktionen gegen verknüpfte ADRs und Architekturprinzipien benötigen.","pt":"Perfeito para Agentes de Análise de Arquitetura que necessitam de capacidades de revisão de Design de Alto Nível abrangentes contra ADRs vinculados e princípios de arquitetura.","ru":"Идеально подходит для Агентов Анализа Архитектуры, которым необходимы всесторонние возможности обзора Высокоуровневого Дизайна против связанных АDR и принципов архитектуры.","ar":"مثالي للوكلاء تحليل الهندسة المعمارية الذين يحتاجون إلى قدرات مراجعة تصميم المستوى العالي الشاملة ضد الأدرات المرتبطة ومبادئ الهندسة المعمارية."},"recommendation":{"en":"Empowers agents to evaluate High-Level Design notes with structured scoring across six dimensions, severity-rated findings, and actionable next steps, leveraging linked ADRs, requirements, and architecture principles for informed decision-making.","zh":"赋予代理评估高级设计说明的能力，通过六个维度的结构化评分、严重性评级的发现结果和可行的下一步骤，利用链接的ADR、需求和架构原则进行明智的决策。","ja":"エージェントがハイレベル設計ノートを評価する能力を付与し、6つの次元の構造化スコアリング、重大性評価された発見結果、およびレビュー結果に基づく実行可能な次のステップにより、リンクされたADR、要件、およびアーキテクチャ原則を利用して情報に基づいた意思決定を行う。","ko":"에이전트가 고급 디자인 노트를 평가할 수 있는 능력을 부여하고, 6개 차원의 구조화된評分, 심각도 평가된 발견 결과 및 검토 결과를 기반으로 하는 실행 가능한 다음 단계를 통해 링크된 ADR, 요구 사항 및 아키텍처 원칙을 利用하여 정보에基づいた 의사 결정を行う。","es":"Habilita a los agentes a evaluar notas de diseño de alto nivel con puntuación estructurada en seis dimensiones, hallazgos con calificación de gravedad y pasos siguientes prácticos, aprovechando ADRs, requisitos y principios de arquitectura vinculados para la toma de decisiones informadas.","fr":"Permet aux agents d''évaluer les notes de conception de haut niveau avec un scoring structuré sur six dimensions, des résultats avec une évaluation de la gravité et des étapes suivantes pratiques, en exploitant les ADR, les exigences et les principes d''architecture liés pour une prise de décision éclairée.","de":"Ermächtigt Agents, High-Level-Design-Notizen mit strukturierter Bewertung über sechs Dimensionen, Schweregrad-bewertete Ergebnisse und praktische nächste Schritte zu bewerten, indem sie verknüpfte ADRs, Anforderungen und Architekturprinzipien für fundierte Entscheidungsfindung nutzen.","pt":"Habilita os agentes a avaliar notas de Design de Alto Nível com pontuação estruturada em seis dimensões, descobertas classificadas por gravidade e próximos passos exequíveis, aproveitando ADRs vinculados, requisitos e princípios de arquitetura para tomada de decisões informadas.","ru":"Наделяет агентов возможностью оценивать заметки Высокоуровневого Дизайна с структурированным баллом по шести измерениям, находками, оцененными по степени тяжести, и реальными следующими шагами, используя связанные АDR, требования и принципы архитектуры для обоснованного принятия решений.","ar":"يُفعِّل الوكلاء لتقييم ملاحظات تصميم المستوى العالي مع تسجيل منظم عبر ستة أبعاد ونتائج مخففة بدرجة الخطورة والخطوات التالية القابلة للتنفيذ، مستفيداً من الأدرات المرتبطة والمتطلبات ومبادئ الهندسة المعمارية لأخذ القرارات المستنيرة."},"useCases":{"en":["Evaluating High-Level Design notes against architecture principles","Generating structured reviews with scoring and severity-rated findings","Identifying actionable next steps for Solutions Architects based on review outcomes"],"zh":["对高级设计说明进行与架构原则的评估","生成具有评分和严重性评级发现结果的结构化审查","根据审查结果为解决方案架构师识别可行的下一步骤"],"ja":["ハイレベル設計ノートをアーキテクチャ原則に対して評価する","スコアリングと重大性評価された発見結果を含む構造化されたレビューを生成する","レビュー結果に基づいてソリューションアーキテクトのための実行可能な次のステップを特定する"],"ko":["고급 디자인 노트를 아키텍처 원칙에 대해 평가","평점 및 심각도 평가된 발견 결과를 포함한 구조화된 검토를 생성","검토 결과를 기반으로 솔루션 아키텍트를 위한 실행 가능한 다음 단계를 식별"],"es":["Evaluación de notas de diseño de alto nivel frente a principios de arquitectura","Generación de revisiones estructuradas con puntuación y hallazgos con calificación de gravedad","Identificación de pasos siguientes prácticos para arquitectos de soluciones en función de los resultados de la revisión"],"fr":["Évaluation de notes de conception de haut niveau face à des principes d''architecture","Génération de révisions structurées avec scoring et résultats avec évaluation de la gravité","Identification des étapes suivantes pratiques pour les architectes de solutions en fonction des résultats de la révision"],"de":["Bewertung von High-Level-Design-Notizen gegenüber Architekturprinzipien","Erzeugung von strukturierten Überprüfungen mit Bewertung und Schweregrad-bewerteten Ergebnissen","Identifizierung von praktischen nächsten Schritten für Lösungsarchitekten basierend auf den Ergebnissen der Überprüfung"],"pt":["Avaliando notas de Design de Alto Nível contra princípios de arquitetura","Gerando revisões estruturadas com pontuação e descobertas classificadas por gravidade","Identificando próximos passos exequíveis para Arquitetos de Soluções com base nos resultados da revisão"],"ru":["Оценивание заметок Высокоуровневого Дизайна против принципов архитектуры","Генерация структурированных обзоров с баллом и находками, оцененными по степени тяжести","Определение реальных следующих шагов для Архитекторов Решений на основе результатов обзора"],"ar":["تقييم ملاحظات تصميم المستوى العالي ضد مبادئ الهندسة المعمارية","توليد مراجعات منظمة مع تسجيل ونتائج مخففة بدرجة الخطورة","تحديد الخطوات التالية القابلة للتنفيذ لمهندسي الحلول على أساس نتائج المراجعة"]},"limitations":{"en":["Requires existing High-Level Design notes for review","Must match an existing HLD note title for accurate analysis"],"zh":["需要现有的高级设计说明用于审查","必须与现有的HLD说明标题匹配以进行准确的分析"],"ja":["レビューのために既存のハイレベル設計ノートが必要","正確な分析のために既存のHLDノートのタイトルと一致させる必要がある"],"ko":["검토를 위한 기존의 고급 디자인 노트가 필요","정확한 분석을 위한 기존의 HLD 노트 제목과 일치시켜야 함"],"es":["Requiere notas de diseño de alto nivel existentes para la revisión","Debe coincidir con un título de nota HLD existente para un análisis preciso"],"fr":["Nécessite des notes de conception de haut niveau existantes pour la révision","Doit correspondre à un titre de note HLD existant pour une analyse précise"],"de":["Benötigt bestehende High-Level-Design-Notizen für die Überprüfung","Muss einem bestehenden HLD-Notizentitel für eine genaue Analyse entsprechen"],"pt":["Exige notas de Design de Alto Nível existentes para revisão","Deve corresponder a um título de nota HLD existente para análise precisa"],"ru":["Требует существующих заметок Высокоуровневого Дизайна для обзора","Должно соответствовать существующему названию заметки HLD для точного анализа"],"ar":["يتطلب ملاحظات تصميم المستوى العالي موجودة من أجل المراجعة","يجب أن يطابق عنوان ملاحظة HLD موجودة لتحليل دقيق"]},"version":4},"contentHash":"acf3b471fbf8d5de9895f37b87ac994b46ecc3f10b1baeb0f2eed1144a7dfc37","qualityScore":60}');
