INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('DavidROliverBA/ArchitectKB/hld-review', 'hld-review', 'DavidROliverBA', 'ArchitectKB', 'community', 'hld-review DavidROliverBA ArchitectKB community The hld-review skill evaluates High-Level Design notes against linked ADRs, requirements, and architecture principles, producing a structured review with scoring and actionable next steps for Solutions Architects. hld-review是一种综合的知识管理系统，使用AI评估高级设计笔记，生成结构化的评审结果 hld-reviewは、AIエージェントを使用したコンセプト設計ノートの評価システムであり、構造化されたレビューレポートを生成 hld-review는 솔루션 아키텍트를 위한 지식 관리 시스템으로 AI를 사용하여 고급 설계 노트를 평가하고 구조화된 검토 결과를 생성 hld-review es un sistema de gestión de conocimiento que evalúa diseños de alto nivel contra ADRs, requisitos y principios de arquitectura hld-review est un système de gestion des connaissances qui évalue les conceptions de haut niveau par rapport aux ADR, aux exigences et aux principes d''architecture hld-review ist ein Wissensmanagementsystem, das High-Level-Designs gegen ADRs, Anforderungen und Architekturprinzipien bewertet O hld-review é uma ferramenta de revisão de design de alto nível com IA que ajuda a avaliar e melhorar a qualidade dos projetos de arquitetura de soluções hld-review - инструмент ИИ Агентов для обзора высокоуровневого дизайна, помогающий оценить и улучшить качество проектов архитектуры решений أداة المراجعة المصممة للتصميم بال층 العالية باستخدام الإی آر هي أداة تقييم وتحسين جودة مشاريع التصميم المعماري للحلول how to use hld-review hld-review setup guide hld-review alternative hld-review vs architecture review tools hld-review install what is hld-review hld-review for Solutions Architects hld-review AI agent hld-review High-Level Design note review hld-review ADR evaluation hld-review AI知识管理系统 高级设计笔记评估 结构化评审结果 六维评分系统 AI工具 知识管理 Evaluates High-Level Design notes against linked ADRs and requirements Produces a structured review with scoring across six dimensions Generates severity-rated findings and actionable next steps Supports command-line usage with /hld-review <HLD note title> Requires a matching existing HLD note title as an argument Provides a comprehensive review of architecture principles hld-review is a comprehensive knowledge management system that uses AI to review High-Level Design notes, providing a structured evaluation with severity-rated findings and next steps.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('yi-john-huang/acmg-amp-classifier-mcp/simple-task', 'community', 'yi-john-huang', 'acmg-amp-classifier-mcp', 'yi-john-huang/acmg-amp-classifier-mcp', 'simple-task', 2, 1, 60, '2026-02-07T08:16:49Z', '2026-03-06T13:07:01.756Z', '9c99da4c3560fe00cd1e96cf344ebea272f99496e68633e40915ceaae8795358', '{"id":"yi-john-huang/acmg-amp-classifier-mcp/simple-task","name":"simple-task","description":{"en":"The simple-task skill implements small features, bug fixes, or quick enhancements following best practices. It is ideal for developers working on small project tasks.","zh":"简单任务实现是指在项目中添加小功能、修复bug或进行快速增强，遵循项目的指导文档","ja":"シンプルタスクは、小さな機能の追加、バグの修正、またはクイックな強化をプロジェクトのガイドラインに従って実装すること","ko":"심플 태스크는 프로젝트에서 작은 기능을 추가하거나 버그를 수정하거나 빠른 개선을 수행하는 것을 의미합니다","es":"Simple-task es una habilidad que permite implementar pequeñas características, correcciones de errores y mejoras menores en un proyecto, siguiendo las mejores prácticas del documento de dirección del proyecto.","fr":"Simple-task est une compétence qui permet de mettre en œuvre de petites fonctionnalités, de corriger des bogues et d''apporter des améliorations mineures à un projet, en suivant les meilleures pratiques du document de direction du projet.","de":"Simple-task ist eine Fähigkeit, die die Implementierung kleiner Merkmale, Fehlerkorrekturen und geringfügiger Verbesserungen in einem Projekt ermöglicht, unter Berücksichtigung der besten Praktiken des Projektrichtliniendokuments.","pt":"A implementação de tarefas simples é uma funcionalidade que permite adicionar recursos pequenos, corrigir bugs e melhorar o código de forma eficiente","ru":"Реализация простых задач - это функция, которая позволяет добавлять небольшие функции, исправлять ошибки и улучшать код эффективно","ar":"تنفيذ المهام البسيطة هو ميزة تسمح بإضافة ميزات صغيرة وتصحيح الأخطاء وتحسين الكود بفعالية"},"seo":{"title":{"en":"simple-task: Best Practices for AI Agents | Implementatio...","zh":"简单任务实现指南 - AIエージェント最佳实践","ja":"シンプルタスク設定ガイド - AIエージェントのベストプラクティス","ko":"심플 태스크 구현 가이드 - AI 에이전트 최적화","es":"Guía de configuración para simple-task: implementación de...","fr":"Guide de mise en œuvre pour simple-task: ajout de fonctio...","de":"Einrichtungsleitfaden für simple-task: Umsetzung kleiner ...","pt":"Guia de Implementação de Tarefas Simples com Melhores Prá...","ru":"ИИ Агенты: Руководство по Реализации Простых Задач","ar":"دليل تنفيذ المهام البسيطة مع أفضل الممارسات"},"description":{"en":"Discover how to use simple-task for small feature additions, bug fixes, and minor enhancements. Learn the workflow and get started with our setup guide today!","zh":"了解简单任务的实现方法，掌握AIエージェント的最佳实践，提高开发效率","ja":"シンプルタスクの設定方法をマスターし、AIエージェントのベストプラクティスを学ぶ","ko":"심플 태스크 구현을 위한 가이드와 AI 에이전트 최적화 방법을 알아보세요","es":"Aprende a utilizar simple-task para agregar funcionalidades pequeñas, correcciones de errores y mejoras menores a tu proyecto con la ayuda de AI Agent","fr":"Découvrez comment utiliser simple-task pour ajouter des fonctionnalités petites, corriger des bogues et améliorer votre projet avec l''outil IA","de":"Erfahren Sie, wie Sie simple-task verwenden, um kleine Funktionen, Fehlerkorrekturen und geringfügige Verbesserungen an Ihr Projekt mit dem KI-Tool vorzunehmen","pt":"Aprenda a implementar tarefas simples com eficiência, seguindo as melhores práticas de desenvolvimento de software","ru":"Узнайте, как реализовать простые задачи с помощью ИИ Агентов, следуя лучшим практикам разработки программного обеспечения","ar":"تعلم كيفية تنفيذ المهام البسيطة بفعالية، مع اتباع أفضل الممارسات لتطوير البرمجيات"},"definition":{"en":"simple-task is a skill that enables the implementation of small features, bug fixes, or quick enhancements while adhering to a project''s steering documents.","zh":"简单任务是指遵循项目指导文档的小规模功能实现或bug修复","ja":"シンプルタスクとは、プロジェクトのガイドラインに従った小規模な機能実装またはバグ修正","ko":"심플 태스크란 프로젝트의 가이드라인을 따르는 작은 규모의 기능 구현 또는 버그 수정을 의미합니다","es":"Simple-task es una habilidad de AI Agent que permite la implementación de tareas pequeñas en un proyecto","fr":"Simple-task est une compétence de l''outil IA qui permet la mise en œuvre de tâches petites dans un projet","de":"Simple-task ist eine Fähigkeit des KI-Tools, die die Umsetzung kleiner Aufgaben in einem Projekt ermöglicht","pt":"O que é implementação de tarefas simples? É uma abordagem de desenvolvimento de software que visa adicionar pequenas funcionalidades de forma rápida e eficiente","ru":"Что такое реализация простых задач? Это подход к разработке программного обеспечения, целью которого является добавление небольших функций быстро и эффективно","ar":"ما هي تنفيذ المهام البسيطة؟ إنه نهج لتطوير البرمجيات يهدف إلى إضافة ميزات صغيرة بسرعة وفعالية"},"features":{"en":["Implements small feature additions using the /simple-task command","Fixes bugs and performs minor enhancements following the project''s steering documents","Uses a full SDD workflow for complex features and new modules","Supports quick refactoring for improved code efficiency","Ideal for small feature additions, such as adding a logout button"],"zh":["遵循项目指导文档","添加小功能","修复bug","快速增强","使用full SDD workflow进行复杂功能实现"],"ja":["プロジェクトのガイドラインに従う","小さな機能の追加","バグの修正","クイックな強化","full SDD workflowを使用した複雑な機能実装"],"ko":["프로젝트 가이드라인을 따름","작은 기능 추가","버그 수정","빠른 개선","full SDD workflow를 사용한 복잡한 기능 구현"],"es":["Implementación de características pequeñas, como agregar un botón de cierre de sesión","Corrección de errores y mejoras menores","Refactorización rápida","Seguimiento de las mejores prácticas del documento de dirección del proyecto","Uso de la herramienta AI Agent para agilizar el proceso"],"fr":["Mise en œuvre de fonctionnalités petites, comme l''ajout d''un bouton de déconnexion","Correction de bogues et améliorations mineures","Refactorisation rapide","Suivi des meilleures pratiques du document de direction du projet","Utilisation de l''outil IA pour accélérer le processus"],"de":["Implementierung kleiner Merkmale, wie z.B. Hinzufügen eines Abmelde-Buttons","Fehlerkorrektur und geringfügige Verbesserungen","Schnelle Refaktorisierung","Einhaltung der besten Praktiken des Projektrichtliniendokuments","Verwendung des KI-Tools, um den Prozess zu beschleunigen"],"pt":["Adição de recursos pequenos, como botões de logout","Correção de bugs e melhorias menores","Refatoração rápida de código","Uso de documentos de orientação do projeto","Implementação de melhorias eficientes","Seguimento de fluxo de trabalho simplificado"],"ru":["Добавление небольших функций, таких как кнопки выхода","Исправление ошибок и незначительные улучшения","Быстрая рефакторинг кода","Использование руководящих документов проекта","Реализация эффективных улучшений","Следование упрощенному рабочему процессу"],"ar":["إضافة ميزات صغيرة، مثل أزرار الخروج","تصحيح الأخطاء وتحسينات صغيرة","إعادة هيكلة سريعة للكود","استخدام مستندات توجيه المشروع","تنفيذ تحسينات فعالة","اتباع سير عمل مبسط"]},"keywords":{"en":["how to use simple-task","simple-task setup guide","simple-task implementation best practices","simple-task alternative","simple-task vs full SDD workflow","what is simple-task","simple-task install","simple-task workflow"],"zh":["AIエージェント","简单任务","项目指导文档","小功能添加","bug修复","快速增强","full SDD workflow","开发效率","最佳实践"],"ja":["AIエージェント","シンプルタスク","プロジェクトガイドライン","小さな機能追加","バグ修正","クイックな強化","full SDD workflow","開発効率","ベストプラクティス"],"ko":["AI 에이전트","심플 태스크","프로젝트 가이드라인","작은 기능 추가","버그 수정","빠른 개선","full SDD workflow","개발 효율","최적화"],"es":["simple-task","AI Agent","implementación de tareas pequeñas","corrección de errores","mejoras menores","refactorización rápida","mejores prácticas","documento de dirección del proyecto","desarrollo de software","herramientas de desarrollo"],"fr":["simple-task","Outil IA","mise en œuvre de tâches petites","correction de bogues","améliorations mineures","refactorisation rapide","meilleures pratiques","document de direction du projet","développement de logiciels","outils de développement"],"de":["simple-task","KI-Tool","Umsetzung kleiner Aufgaben","Fehlerkorrektur","geringfügige Verbesserungen","schnelle Refaktorisierung","beste Praktiken","Projektrichtliniendokument","Softwareentwicklung","Entwicklungstools"],"pt":["implementação de tarefas simples","desenvolvimento de software","melhores práticas","adição de recursos","correção de bugs","refatoração de código","fluxo de trabalho simplificado","guias de desenvolvimento"],"ru":["ИИ Агенты","реализация простых задач","разработка программного обеспечения","лучшие практики","добавление функций","исправление ошибок","рефакторинг кода","упрощенный рабочий процесс","руководства по разработке"],"ar":["تنفيذ المهام البسيطة","تطوير البرمجيات","أفضل الممارسات","إضافة ميزات","تصحيح الأخطاء","إعادة هيكلة الكود","سير عمل مبسط","دلائل التطوير","أدوات الذكاء الاصطناعي"]}},"owner":"yi-john-huang","repo":"acmg-amp-classifier-mcp","repoPath":"yi-john-huang/acmg-amp-classifier-mcp","stars":2,"forks":1,"updatedAt":"2026-02-07T08:16:49Z","topics":[],"category":"community","skillMd":{"name":"simple-task","description":"Implement simple features with best practices. Use when adding small features, bug fixes, or quick enhancements without the full SDD workflow. Invoked via /simple-task <description>.","bodyPreview":"# Simple Task Implementation\n\nImplement small features, bug fixes, or quick enhancements while following best practices from the project''s steering documents.\n\n## When to Use\n\nUse `/simple-task` for:\n- Small feature additions (e.g., \"add logout button\")\n- Bug fixes\n- Minor enhancements\n- Quick refactoring\n\nUse **full SDD workflow** for:\n- Complex features requiring multiple components\n- New modules or subsystems\n- Features needing formal requirements/design review\n\n## Workflow\n\n### Step 1: Under","body":"# Simple Task Implementation\n\nImplement small features, bug fixes, or quick enhancements while following best practices from the project''s steering documents.\n\n## When to Use\n\nUse `/simple-task` for:\n- Small feature additions (e.g., \"add logout button\")\n- Bug fixes\n- Minor enhancements\n- Quick refactoring\n\nUse **full SDD workflow** for:\n- Complex features requiring multiple components\n- New modules or subsystems\n- Features needing formal requirements/design review\n\n## Workflow\n\n### Step 1: Understand the Task\n\n1. Clarify what needs to be done\n2. Identify affected files/components\n3. Estimate scope (if larger than expected, suggest full SDD workflow)\n\n### Step 2: Apply TDD (Test-Driven Development)\n\n**Reference:** `.spec/steering/tdd-guideline.md`\n\nFollow the Red-Green-Refactor cycle:\n\n```\n1. RED    → Write a failing test first\n2. GREEN  → Write minimal code to pass\n3. REFACTOR → Clean up while tests pass\n```\n\n**Quick TDD Checklist:**\n- [ ] Write test before implementation\n- [ ] Test describes expected behavior\n- [ ] Minimal code to make test pass\n- [ ] Refactor without breaking tests\n\n### Step 3: Apply Design Principles\n\n**Reference:** `.spec/steering/principles.md`\n\n**SOLID Quick Reference:**\n- **S**ingle Responsibility: Each function/class does one thing\n- **O**pen/Closed: Extend behavior without modifying existing code\n- **L**iskov Substitution: Subtypes must be substitutable\n- **I**nterface Segregation: Small, focused interfaces\n- **D**ependency Inversion: Depend on abstractions\n\n**Other Principles:**\n- **DRY**: Don''t repeat yourself - extract common logic\n- **KISS**: Keep it simple - avoid unnecessary complexity\n- **YAGNI**: You aren''t gonna need it - only implement what''s required\n\n### Step 4: Code Quality Review\n\n**Reference:** `.spec/steering/linus-review.md`\n\nBefore finalizing, ask:\n1. **Taste**: Is the solution elegant? Can special cases be eliminated?\n2. **Simplicity**: Can it be simpler? Fewer lines? Less nesting?\n3. **Data Structures**: Is the right data structure used?\n4. **Breaking Changes**: Does this break existing functionality?\n\n**Quality Checklist:**\n- [ ] Functions are short and focused\n- [ ] No more than 3 levels of indentation\n- [ ] Clear, descriptive naming\n- [ ] No unnecessary complexity\n\n### Step 5: Security Check\n\n**Reference:** `.spec/steering/owasp-top10-check.md`\n\n**Quick Security Checklist:**\n- [ ] Input validation (sanitize user inputs)\n- [ ] No SQL/command injection (use parameterized queries)\n- [ ] Access control enforced\n- [ ] No secrets in code (use env vars)\n- [ ] Proper error handling (no stack traces to users)\n\n### Step 6: Implement and Test\n\n1. Write the failing test (RED)\n2. Implement minimal solution (GREEN)\n3. Run tests to confirm pass\n4. Refactor if needed\n5. Run full test suite\n6. Verify no lint/type errors\n\n## Reference Documents\n\nThese steering documents provide detailed guidance:\n\n| Document | Content |\n|----------|---------|\n| `tdd-guideline.md` | TDD methodology, test pyramid, Red-Green-Refactor |\n| `principles.md` | SOLID, DRY, KISS, YAGNI, Separation of Concerns |\n| `linus-review.md` | Code quality, \"good taste\", simplicity standards |\n| `owasp-top10-check.md` | Security checklist (OWASP Top 10) |\n\n## Output\n\nAfter implementing, provide:\n\n```markdown\n## Implementation Summary\n\n**Task:** {what was implemented}\n\n**Changes:**\n- {file1}: {what changed}\n- {file2}: {what changed}\n\n**Tests Added:**\n- {test description}\n\n**Principles Applied:**\n- TDD: {how TDD was followed}\n- Design: {which principles were applied}\n- Security: {security considerations}\n\n**Ready for:** {commit / further review / testing}\n```\n\n## Example\n\n```\nUser: /simple-task add a logout button to the navbar\n\nClaude:\n1. Understand: Add logout button that clears session and redirects to login\n2. TDD: Write test for logout functionality first\n3. Principles: Single responsibility - logout logic in AuthService\n4. Security: Ensure session is properly invalidated\n5. Implement: Button component + logout handler\n6. Test: Verify all tests pass\n```\n"},"lastSynced":"2026-03-06T13:07:01.756Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring efficient implementation of small features and bug fixes following best practices.","zh":"适用于需要高效实施小功能和错误修复的开发代理，并遵循最佳实践。","ja":"開発エージェントが小さな機能とバグの修正を効率的に実装する必要がある場合に最適で、ベストプラクティスに従ったものです。","ko":"개발 에이전트가 작은 기능과 버그 수정을 효율적으로 구현해야 하는 경우에 적합하며, 최선의 관행을 따릅니다.","es":"Ideal para agentes de desarrollo que requieren una implementación eficiente de pequeñas características y correcciones de errores siguiendo las mejores prácticas.","fr":"Idéal pour les agents de développement nécessitant une mise en œuvre efficace de petites fonctionnalités et de corrections de bogues suivant les meilleures pratiques.","de":"Ideal für Entwicklungsmittel, die eine effiziente Implementierung von kleinen Funktionen und Fehlerbehebungen unter Einhaltung der Best Practices erfordern.","pt":"Ideal para Agentes de Desenvolvimento que exigem implementação eficiente de pequenos recursos e correções de bugs seguindo as melhores práticas.","ru":"Идеально для агентов разработки, требующих эффективной реализации небольших функций и исправления ошибок в соответствии с лучшими практиками.","ar":"مثالي لعميل التطوير الذي يتطلب تنفيذا فعالا لميزات صغيرة وتصحيح أخطاء ตาม أفضل الممارسات."},"recommendation":{"en":"Empowers agents to implement small features, bug fixes, and quick enhancements while adhering to project steering documents, utilizing best practices for minor enhancements and refactoring, and supporting protocols like full SDD workflow for complex tasks.","zh":"赋予代理实现小功能、错误修复和快速增强的能力，同时遵循项目导向文档，利用小增强和重构的最佳实践，并支持诸如完整的 SDD 工作流等复杂任务的协议。","ja":"エージェントが小さな機能、バグの修正、クイックエンハンスを実装できるようにし、プロジェクトの舵取りドキュメントに従い、小さな機能拡張とリファクタリングのベストプラクティスを利用し、複雑なタスクのための完全な SDD ワークフローなどのプロトコルをサポートします。","ko":"에이전트가 작은 기능, 버그 수정 및 빠른 향상을 구현할 수 있도록 하며, 프로젝트 조정 문서를 따르고, 작은 기능 향상 및 리팩토링의 최선의 관행을 활용하며, 복잡한 작업을 위한 전체 SDD 워크플로우 등의 프로토콜을 지원합니다.","es":"Habilita a los agentes a implementar pequeñas características, correcciones de errores y mejoras rápidas mientras se adhieren a los documentos de dirección de proyectos, utilizando las mejores prácticas para mejoras menores y refactorización, y apoyando protocolos como el flujo de trabajo SDD completo para tareas complejas.","fr":"Habilite les agents à mettre en œuvre de petites fonctionnalités, des corrections de bogues et des améliorations rapides tout en respectant les documents de direction de projet, en utilisant les meilleures pratiques pour les améliorations mineures et la refactorisation, et en prenant en charge des protocoles tels que le flux de travail SDD complet pour les tâches complexes.","de":"Ermächtigt die Mittel, kleine Funktionen, Fehlerbehebungen und schnelle Verbesserungen umzusetzen, während sie den Projektleitdokumenten folgen, die besten Praktiken für kleine Verbesserungen und Refaktorisierung nutzen und Protokolle wie den vollständigen SDD-Workflow für komplexe Aufgaben unterstützen.","pt":"Habilita os agentes a implementar pequenos recursos, correções de bugs e melhorias rápidas, seguindo os documentos de direção do projeto, utilizando as melhores práticas para melhorias menores e refatoração, e apoiando protocolos como o fluxo de trabalho SDD completo para tarefas complexas.","ru":"Наделяет агентов возможностью реализовывать небольшие функции, исправлять ошибки и быстро улучшать, следуя документам управления проектом, используя лучшие практики для незначительных улучшений и рефакторинга, и поддерживая протоколы, такие как полный рабочий процесс SDD для сложных задач.","ar":"يمنح الوكيل القدرة على تنفيذ ميزات صغيرة وتصحيح أخطاء وتحسينات سريعة ، متبعةً وثائق توجيه المشروع ، واستخدام أفضل الممارسات للتحسينات الطفيفة وإعادة هيكلة الدعم وبروتوكولات مثل تدفق العمل الكامل SDD لأعمال معقدة."},"useCases":{"en":["Implementing minor UI adjustments","Fixing low-priority bugs","Refactoring small code segments"],"zh":["实现小的 UI 调整","修复低优先级的错误","重构小的代码片段"],"ja":["小さな UI 調整の実装","低優先度のバグの修正","小さなコ