INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('yi-john-huang/acmg-amp-classifier-mcp/simple-task', 'simple-task', 'yi-john-huang', 'acmg-amp-classifier-mcp', 'community', 'simple-task yi-john-huang acmg-amp-classifier-mcp community The simple-task skill implements small features, bug fixes, or quick enhancements following best practices. It is ideal for developers working on small project tasks. 简单任务实现是指在项目中添加小功能、修复bug或进行快速增强，遵循项目的指导文档 シンプルタスクは、小さな機能の追加、バグの修正、またはクイックな強化をプロジェクトのガイドラインに従って実装すること 심플 태스크는 프로젝트에서 작은 기능을 추가하거나 버그를 수정하거나 빠른 개선을 수행하는 것을 의미합니다 Simple-task es una habilidad que permite implementar pequeñas características, correcciones de errores y mejoras menores en un proyecto, siguiendo las mejores prácticas del documento de dirección del proyecto. Simple-task est une compétence qui permet de mettre en œuvre de petites fonctionnalités, de corriger des bogues et d''apporter des améliorations mineures à un projet, en suivant les meilleures pratiques du document de direction du projet. Simple-task ist eine Fähigkeit, die die Implementierung kleiner Merkmale, Fehlerkorrekturen und geringfügiger Verbesserungen in einem Projekt ermöglicht, unter Berücksichtigung der besten Praktiken des Projektrichtliniendokuments. A implementação de tarefas simples é uma funcionalidade que permite adicionar recursos pequenos, corrigir bugs e melhorar o código de forma eficiente Реализация простых задач - это функция, которая позволяет добавлять небольшие функции, исправлять ошибки и улучшать код эффективно تنفيذ المهام البسيطة هو ميزة تسمح بإضافة ميزات صغيرة وتصحيح الأخطاء وتحسين الكود بفعالية how to use simple-task simple-task setup guide simple-task implementation best practices simple-task alternative simple-task vs full SDD workflow what is simple-task simple-task install simple-task workflow AIエージェント 简单任务 项目指导文档 小功能添加 bug修复 快速增强 full SDD workflow 开发效率 最佳实践 Implements small feature additions using the /simple-task command Fixes bugs and performs minor enhancements following the project''s steering documents Uses a full SDD workflow for complex features and new modules Supports quick refactoring for improved code efficiency Ideal for small feature additions, such as adding a logout button simple-task is a skill that enables the implementation of small features, bug fixes, or quick enhancements while adhering to a project''s steering documents.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('j-greig/wibandwob-dos/ww-build-game', 'community', 'j-greig', 'wibandwob-dos', 'j-greig/wibandwob-dos', 'ww-build-game', 2, 0, 60, '2026-02-25T11:22:08Z', '2026-03-06T07:05:10.290Z', 'fdc9b83796fb36c738983b964baa0ce0012503070740f8206a7c11e5f00cddc7', '{"id":"j-greig/wibandwob-dos/ww-build-game","name":"ww-build-game","description":{"en":"ww-build-game enables developers to build playable games within WibWob-DOS''s Turbo Vision TUI, utilizing technologies like ASCII-art and MS-DOS. This skill benefits game developers and AI enthusiasts.","zh":"WW-Build-Game是一个构建游戏视图的技能，用于WibWob-DOS的Turbo Vision TUI，支持Timer-tick和ASCII艺术","ja":"WW-Build-Gameは、WibWob-DOSのTurbo Vision TUIでゲームビューを構築するスキルで、Timer-tickとASCIIアートをサポートします","ko":"WW-Build-Game는 WibWob-DOS의 Turbo Vision TUI에서 게임 뷰를 구축하는 기술로, Timer-tick 및 ASCII 아트를 지원합니다","es":"ww-build-game es una habilidad para crear juegos dentro de WibWob-DOS, un sistema operativo symbiente donde la IA y los humanos comparten el control. Ofrece ejemplos de código y patrones para desarrollar juegos de manera efectiva","fr":"ww-build-game est une compétence pour créer des jeux à l''intérieur de WibWob-DOS, un système d''exploitation symbiente où l''IA et les humains partagent le contrôle. Il propose des exemples de code et des modèles pour développer des jeux de manière efficace","de":"ww-build-game ist eine Fähigkeit, um Spiele innerhalb von WibWob-DOS zu erstellen, einem symbienten Betriebssystem, in dem KI und Menschen die Kontrolle teilen. Es bietet Codebeispiele und Muster für die effektive Entwicklung von Spielen","pt":"O ww-build-game permite criar jogos dentro do WibWob-DOS, um sistema operacional symbient que combina AI e controle humano. Aprenda com exemplos de código","ru":"Ww-build-game позволяет создавать игры внутри WibWob-DOS, симбиентной операционной системы, объединяющ