INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('j-greig/wibandwob-dos/ww-build-game', 'ww-build-game', 'j-greig', 'wibandwob-dos', 'community', 'ww-build-game j-greig wibandwob-dos community agentic-ui ai ascii-art msdos tvision ww-build-game enables developers to build playable games within WibWob-DOS''s Turbo Vision TUI, utilizing technologies like ASCII-art and MS-DOS. This skill benefits game developers and AI enthusiasts. WW-Build-Game是一个构建游戏视图的技能，用于WibWob-DOS的Turbo Vision TUI，支持Timer-tick和ASCII艺术 WW-Build-Gameは、WibWob-DOSのTurbo Vision TUIでゲームビューを構築するスキルで、Timer-tickとASCIIアートをサポートします WW-Build-Game는 WibWob-DOS의 Turbo Vision TUI에서 게임 뷰를 구축하는 기술로, Timer-tick 및 ASCII 아트를 지원합니다 ww-build-game es una habilidad para crear juegos dentro de WibWob-DOS, un sistema operativo symbiente donde la IA y los humanos comparten el control. Ofrece ejemplos de código y patrones para desarrollar juegos de manera efectiva ww-build-game est une compétence pour créer des jeux à l''intérieur de WibWob-DOS, un système d''exploitation symbiente où l''IA et les humains partagent le contrôle. Il propose des exemples de code et des modèles pour développer des jeux de manière efficace ww-build-game ist eine Fähigkeit, um Spiele innerhalb von WibWob-DOS zu erstellen, einem symbienten Betriebssystem, in dem KI und Menschen die Kontrolle teilen. Es bietet Codebeispiele und Muster für die effektive Entwicklung von Spielen O ww-build-game permite criar jogos dentro do WibWob-DOS, um sistema operacional symbient que combina AI e controle humano. Aprenda com exemplos de código Ww-build-game позволяет создавать игры внутри WibWob-DOS, симбиентной операционной системы, объединяющей ИИ и человеческий контроль. Учитесь на примерах кода يدعم ww-build-game بناء الألعاب داخل WibWob-DOS، نظام تشغيل symbient يجمع بين الذكاء الاصطناعي ومراقبة الإنسان. تعلم من الأمثلة على الكود how to use ww-build-game ww-build-game alternative ww-build-game setup guide what is ww-build-game ww-build-game vs agentic-ui install ww-build-game Turbo Vision TUI game development WibWob-DOS game building ASCII-art game rendering WW-Build-Game WibWob-DOS Turbo Vision TUI Timer-tick ASCII艺术 游戏开发 AI工具 AIエージェント Builds playable game views inside WibWob-DOS''s Turbo Vision TUI Utilizes ASCII-art for game rendering Supports MS-DOS architecture Implements timer-tick and fixed board architectures Includes key patterns like 7-bag randomizer and SRS rotation Provides working examples like Quadra game ww-build-game is a skill that allows developers to create playable game views inside WibWob-DOS''s Turbo Vision TUI, using agentic-ui and AI technologies.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jasonmichaelbell78-creator/sonash-v0/pre-commit-fixer', 'community', 'jasonmichaelbell78-creator', 'sonash-v0', 'jasonmichaelbell78-creator/sonash-v0', 'pre-commit-fixer', 2, 0, 60, '2026-02-25T23:51:48Z', '2026-03-06T07:05:19.301Z', '5140c1138f847af8a0599b70095fd89fce8a9dda6aa6e21aae9a00c042792d1c', '{"id":"jasonmichaelbell78-creator/sonash-v0/pre-commit-fixer","name":"pre-commit-fixer","description":{"en":"The pre-commit-fixer skill automates the fix-commit-retry loop, benefiting developers by reducing manual labor when pre-commit hooks fail.","zh":"Pre-Commit Fixer 是一种自动化工具，用于消除提交前钩子失败时的修复和重新提交循环","ja":"Pre-Commit Fixer は、コミット前のフックが失敗したときの修復と再提交のループを自動化するツール","ko":"Pre-Commit Fixer는 커밋 전 후크가 실패할 때의 수정과 재提交의 루프를 자동화하는 도구","es":"Pre-commit-fixer elimina el bucle de corrección y reintento en pre-commit hooks, mejorando la eficiencia del desarrollo","fr":"Pre-commit-fixer élimine la boucle de correction et de réessai dans les hooks pre-commit, améliorant l''efficacité du développement","de":"Pre-commit-fixer eliminiert den Korrektur- und Wiederholungsschleifen in Pre-Commit-Hooks, verbessert die Entwicklungs-effizienz","pt":"O Pre-Commit Fixer elimina a necessidade de loop de correção de erros de pré-compromisso, melhorando a produtividade do desenvolvedor.","ru":"Pre-Commit Fixer исключает необходимость循环 исправления ошибок предкоммита, повышая производительность разработчика.","ar":"أداة إصلاح ما قبل الالتزام تلغي الحاجة إلى حلقة إصلاح الأخطاء قبل الالتزام، وتحسن إنتاجية المطور."},"seo":{"title":{"en":"pre-commit-fixer: Automated Fix-Commit-Retry Loop Setup G...","zh":"Pre-Commit Fixer 设置指南 - 自动化提交修复","ja":"Pre-Commit Fixer 導入ガイド - コミット修復自動化","ko":"Pre-Commit Fixer 설치 가이드 - 커밋 修復 자동화","es":"Guía de configuración de pre-commit-fixer para agilizar e...","fr":"Configurer pre-commit-fixer pour optimiser le workflow de...","de":"Einrichtungsleitfaden für pre-commit-fixer zur Beschleuni...","pt":"Guia de Configuração do Pre-Commit Fixer para Desenvolved...","ru":"ИИ Агент Pre-Commit Fixer: Руководство по Настройке","ar":"إعداد أداة إصلاح ما قبل الالتزام: دليل المطورين"},"description":{"en":"Simplify your development workflow with pre-commit-fixer, eliminating manual error fixes and retries - learn how to set it up now!","zh":"通过 Pre-Commit Fixer 自动化提交修复，消除手动修复和重新提交的麻烦","ja":"Pre-Commit Fixer を使用してコミット修復を自動化し、手動での修復と再提交の手間を省く","ko":"Pre-Commit Fixer를 사용하여 커밋 修復을 자동화하고 수동으로 수정하고 다시提交하는 번거로움을 제거","es":"Automatice la corrección de errores en pre-commit hooks con pre-commit-fixer. Mejore su productividad y reduzca el tiempo de desarrollo","fr":"Automatisez la correction des erreurs dans les hooks pre-commit avec pre-commit-fixer. Améliorez votre productivité et réduisez le temps de développement","de":"Automatisieren Sie die Fehlerkorrektur in Pre-Commit-Hooks mit pre-commit-fixer. Steigern Sie Ihre Produktivität und reduzieren Sie die Entwicklungszeit","pt":"Evite o loop de correção de erros de pré-compromisso com o Pre-Commit Fixer. Descubra como configurar e usar essa ferramenta para melhorar a produtividade do...","ru":"Избегайте循环 исправления ошибок предкоммита с помощью Pre-Commit Fixer. Узнайте, как настроить и использовать эту инструмент для повышения производительности ...","ar":"تجنب حلقة إصلاح الأخطاء قبل الالتزام باستخدام أداة إصلاح ما قبل الالتزام. اكتشف كيفية 설정 واستخدام هذه الأداة لتحسين إنتاجية المطور."},"definition":{"en":"pre-commit-fixer is a skill that automates the process of fixing and re-committing files after pre-commit hooks fail, streamlining the development workflow.","zh":"Pre-Commit Fixer 是一种自动化工具，用于修复提交前钩子失败时的错误","ja":"Pre-Commit Fixer は、コミット前のフックが失敗したときのエラーを修復する自動化ツール","ko":"Pre-Commit Fixer는 커밋 전 후크가 실패할 때의 오류를 修復하는 자동화 도구","es":"Pre-commit-fixer es una herramienta que automatiza la corrección de errores en pre-commit hooks","fr":"Pre-commit-fixer est un outil qui automatise la correction des erreurs dans les hooks pre-commit","de":"Pre-commit-fixer ist ein Tool, das die Fehlerkorrektur in Pre-Commit-Hooks automatisiert","pt":"O Pre-Commit Fixer é uma ferramenta que automatiza a correção de erros de pré-compromisso.","ru":"Pre-Commit Fixer - это инструмент, автоматизирующий исправление ошибок предкоммита.","ar":"أداة إصلاح ما قبل الالتزام هي أداة تلقائية لتصحيح الأخطاء قبل الالتزام."},"features":{"en":["Eliminates the context-heavy fix-commit-retry loop","Automates fixing files after pre-commit hooks fail","Supports reduction of manual labor in development workflow","Intended for use when tasks match its specific scope","Provides an alternative to manual reading of errors and re-staging"],"zh":["自动化提交修复","消除手动修复和重新提交的麻烦","支持多种提交前钩子","提高开发效率","减少错误和 bug"],"ja":["コミット修復の自動化","手動での修復と再提交の手間を省く","複数のコミット前のフックをサポート","開発効率の向上","エラーとバグの削減"],"ko":["커밋 修復 자동화","수동으로 수정하고 다시 제출하는 번거로움을 제거","여러 가지 커밋 전 후크를 지원","개발 효율성 향상","오류와 버그 감소"],"es":["Elimina el bucle de corrección y reintento en pre-commit hooks","Automatiza la corrección de errores en pre-commit hooks","Mejora la eficiencia del desarrollo","Reduce el tiempo de desarrollo","Compatibilidad con herramientas de desarrollo como CLI"],"fr":["Élimine la boucle de correction et de réessai dans les hooks pre-commit","Automatise la correction des erreurs dans les hooks pre-commit","Améliore l''efficacité du développement","Réduit le temps de développement","Compatibilité avec des outils de développement comme CLI"],"de":["Eliminiert den Korrektur- und Wiederholungsschleifen in Pre-Commit-Hooks","Automatisiert die Fehlerkorrektur in Pre-Commit-Hooks","Verbessert die Entwicklungs-Effizienz","Reduziert die Entwicklungszeit","Kompatibilität mit Entwicklungstools wie CLI"],"pt":["Eliminação do loop de correção de erros de pré-compromisso","Automatização da correção de erros","Melhoria da produtividade do desenvolvedor","Integração com hooks de pré-compromisso","Suporte a tarefas de desenvolvimento ágeis"],"ru":["Исключение循环 исправления ошибок предкоммита","Автоматизация исправления ошибок","Повышение производительности разработчика","Интеграция с хуками предкоммита","Поддержка гибких задач разработки"],"ar":["إزالة حلقة إصلاح الأخطاء قبل الالتزام","توصيل تلقائي للأخطاء","تحسين إنتاجية المطور","التكامل مع مشابك قبل الالتزام","دعم مهام التطوير المرنة"]},"keywords":{"en":["how to use pre-commit-fixer","pre-commit-fixer setup guide","pre-commit-fixer alternative","pre-commit-fixer vs git hooks","pre-commit-fixer install","what is pre-commit-fixer","pre-commit-fixer documentation","pre-commit-fixer automation"],"zh":["Pre-Commit Fixer","AIエージェント","自动化提交修复","提交前钩子","开发效率","错误和 bug","代码质量","自动化测试"],"ja":["Pre-Commit Fixer","AIエージェント","コミット修復自動化","コミット前のフック","開発効率","エラーとバグ","コード品質","自動テスト"],"ko":["Pre-Commit Fixer","AI 에이전트","커밋 修復 자동화","커밋 전 후크","개발 효율성","오류와 버그","코드 품질","자동 테스트"],"es":["pre-commit-fixer","herramientas de desarrollo","automatización de errores","eficiencia del desarrollo","reducción del tiempo de desarrollo","CLI","agilizar el flujo de trabajo","pre-commit hooks"],"fr":["pre-commit-fixer","outils de développement","automatisation des erreurs","efficacité du développement","réduction du temps de développement","CLI","optimiser le workflow de développement","hooks pre-commit"],"de":["pre-commit-fixer","Entwicklungstools","Automatisierung von Fehlern","Entwicklungs-Effizienz","Reduzierung der Entwicklungszeit","CLI","Beschleunigung des Entwicklungsprozesses","Pre-Commit-Hooks"],"pt":["pre-commit fixer","ferramenta de correção de erros","desenvolvimento de software","produtividade do desenvolvedor","hooks de pré-compromisso","desenvolvimento ágil"],"ru":["pre-commit fixer","инструмент исправления ошибок","разработка программного обеспечения","производительность разработчика","хуки предкоммита","гибкая разработка"],"ar":["أداة إصلاح ما قبل الالتزام","أداة تصحيح الأخطاء","تطوير البرمجيات","إنتاجية المطور","مشابك قبل الالتزام","تطوير مرن"]}},"owner":"jasonmichaelbell78-creator","repo":"sonash-v0","repoPath":"jasonmichaelbell78-creator/sonash-v0","stars":2,"forks":0,"updatedAt":"2026-02-25T23:51:48Z","topics":[],"category":"community","skillMd":{"name":"pre-commit-fixer","description":"|","bodyPreview":"<!-- prettier-ignore-start -->\n**Document Version:** 1.1\n**Last Updated:** 2026-02-14\n**Status:** ACTIVE\n<!-- prettier-ignore-end -->\n\n# Pre-Commit Fixer\n\n## When NOT to Use\n\n- When the task doesn''t match this skill''s scope -- check related skills\n- When a more specialized skill exists for the specific task\n\n## Purpose\n\nEliminate the context-heavy fix-commit-retry loop that happens when pre-commit\nhooks fail. Instead of manually reading errors, fixing files, re-staging, and\nre-committing (burnin","body":"<!-- prettier-ignore-start -->\n**Document Version:** 1.1\n**Last Updated:** 2026-02-14\n**Status:** ACTIVE\n<!-- prettier-ignore-end -->\n\n# Pre-Commit Fixer\n\n## When NOT to Use\n\n- When the task doesn''t match this skill''s scope -- check related skills\n- When a more specialized skill exists for the specific task\n\n## Purpose\n\nEliminate the context-heavy fix-commit-retry loop that happens when pre-commit\nhooks fail. Instead of manually reading errors, fixing files, re-staging, and\nre-committing (burning 500+ tokens per cycle), delegate the fix to a focused\nsubagent that works in bounded context.\n\n## When to Use\n\nUse this skill when `git commit` fails with any of these pre-commit errors:\n\n| Error Category            | Detection Pattern                                |\n| ------------------------- | ------------------------------------------------ |\n| ESLint failures           | `ESLint passed (N errors)` or `eslint` in output |\n| Pattern compliance        | `Pattern compliance` failed                      |\n| Document headers          | `Missing required header` in output              |\n| Cross-doc dependencies    | `not staged` or `cross-document` in output       |\n| Documentation index stale | `DOCUMENTATION_INDEX.md not updated` in output   |\n| Skill validation          | `Skill validation` failed                        |\n\n## Workflow\n\n### Step 1: Capture the Error\n\nWhen a commit fails, capture the FULL error output. The error output contains\nthe exact information needed for the fix.\n\n### Step 2: Classify the Failure\n\nRead the error output and classify into one of these categories:\n\n**Category A: Auto-fixable (no subagent needed)**\n\nThese can be fixed inline without spawning an agent:\n\n1. **Documentation index stale** → Run\n   `npm run docs:index && git add DOCUMENTATION_INDEX.md`\n2. **Cross-doc dependency** → Stage the missing file: `git add <missing-file>`\n3. **Lint-staged formatting** → Already auto-fixed by lint-staged, just\n   re-commit\n\n**Category B: Targeted fix (spawn subagent)**\n\nThese need code analysis and changes:\n\n1. **ESLint errors** → Spawn `debugger` agent with error list and file paths\n2. **Pattern compliance** → Spawn `code-reviewer` agent with violation details\n3. **Document headers** → Add headers directly (template below)\n4. **Skill validation** → Spawn `general-purpose` agent with skill file path\n\n### Step 3: Execute Fix\n\n**For Category A (inline fix):**\n\n```bash\n# Documentation index\nnpm run docs:index && git add DOCUMENTATION_INDEX.md\n\n# Cross-doc dependency (example)\ngit add .claude/COMMAND_REFERENCE.md\n\n# Re-commit using the original message (preserved by git after hook failure)\ngit commit -F .git/COMMIT_EDITMSG\n```\n\n**For Category B (subagent fix):**\n\nSpawn a focused subagent using the Task tool:\n\n```\nTask({\n  subagent_type: \"debugger\",\n  description: \"Fix N pre-commit ESLint errors\",\n  prompt: \"Fix these ESLint errors and stage the fixes:\\n\\n<paste error output>\\n\\nFiles to fix: <list>\\n\\nDo NOT create new files. Only fix the listed errors.\"\n})\n```\n\nAfter the subagent returns, re-stage and re-commit.\n\n### Step 4: Document Header Template\n\nFor new `.md` files missing headers, add this block after the YAML frontmatter\n(if any) or at the top of the file:\n\n```markdown\n<!-- prettier-ignore-start -->\n**Document Version:** 1.0\n**Last Updated:** YYYY-MM-DD\n**Status:** ACTIVE\n<!-- prettier-ignore-end -->\n```\n\n### Step 5: Re-commit\n\nAfter all fixes are applied and staged:\n\n```bash\ngit add <fixed-files>\ngit commit -m \"original commit message\"\n```\n\nIf the commit fails again, repeat from Step 1. Cap at 3 retry cycles — if it\nstill fails after 3 attempts, report the remaining errors to the user.\n\n## Anti-Patterns\n\n- **Do NOT** use `SKIP_*` environment variables to bypass checks unless the user\n  explicitly requests it\n- **Do NOT** suppress ESLint rules with `// eslint-disable` unless the rule is\n  genuinely a false positive\n- **Do NOT** add files to pathExcludeList in check-pattern-compliance.js unless\n  they are verified false positives\n- **Do NOT** commit partial fixes — fix ALL reported errors before re-committing\n\n## Input/Output Format\n\n**Input:** The full stderr/stdout from a failed `git commit` command.\n\n**Output:** After all fixes are applied and committed, report a structured\nsummary:\n\n```\nPRE-COMMIT FIX RESULT:\n  Status: SUCCESS | PARTIAL | FAILED\n  Attempt: N/3\n  Failures fixed:\n    - [category]: [description] ([file])\n  Remaining (if any):\n    - [category]: [description]\n  Commit: [hash] (if successful)\n```\n\n### Expected Behavior Per Failure Type\n\n| Failure Type           | Fix Strategy                                                          | Auto-fixable? |\n| ---------------------- | --------------------------------------------------------------------- | ------------- |\n| ESLint errors          | Read error list, fix each in source, re-stage                         | Subagent      |\n| Pattern compliance     | Read violation, apply pattern from CODE_PATTERNS.md                   | Subagent      |\n| Cross-doc dependencies | `git add` the unstaged dependency file                                | Inline        |\n| Doc index stale        | `npm run docs:index && git add DOCUMENTATION_INDEX.md`                | Inline        |\n| Doc headers missing    | Add standard header block (template in Step 4)                        | Inline        |\n| Skill validation       | Read error, fix SKILL.md frontmatter or structure                     | Subagent      |\n| S0/S1 audit failure    | Check if real or false positive; fix or set `SKIP_AUDIT_VALIDATION=1` | Subagent      |\n| Schema validation      | Fix JSONL schema issues in the flagged file                           | Subagent      |\n\n## Context Efficiency\n\nThis skill saves context by:\n\n1. Avoiding multiple round-trips of reading error → thinking → fixing → retrying\n2. Delegating ESLint/pattern fixes to bounded subagents\n3. Using deterministic templates for doc headers instead of researching format\n4. Capping retry cycles to prevent unbounded loops\n\n---\n\n## Version History\n\n| Version | Date       | Description            |\n| ------- | ---------- | ---------------------- |\n| 1.0     | 2026-02-25 | Initial implementation |\n"},"lastSynced":"2026-03-06T07:05:19.301Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing automation of pre-commit hooks and fix-commit-retry loops.","zh":"适合需要自动化预提交钩子和修复提交重试循环的开发代理。","ja":"開発エージェントが事前コミットフックと修正コミット再試行ループの自動化を必要とする場合に最適です。","ko":"개발 에이전트가 사전 커밋 훅 및 수정 커밋 재시도 루프 자동화를 필요로 하는 경우 적합합니다.","es":"Perfecto para Agentes de Desarrollo que necesitan automatización de ganchos pre-commit y bucles de fix-commit-retry.","fr":"Parfait pour les agents de développement ayant besoin d''automatisation des hooks pre-commit et des boucles de fix-commit-retry.","de":"Perfekt für Entwicklungsmittel, die eine Automatisierung von Pre-Commit-Hooks und Fix-Commit-Retry-Schleifen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de automação de hooks de pré-commits e loops de fix-commit-retry.","ru":"Идеально для агентов разработки, которым требуется автоматизация предварительных коммит-хуков и циклов исправления-повтора коммита.","ar":"مثالي للوكلاء التطوير الذين يحتاجون إلى أتمتة hooks الالتزام السابق و حلقة إصلاح-إعادة-التزام."},"recommendation":{"en":"Empowers agents to automate the fix-commit-retry loop, reducing manual labor by automatically reading errors, fixing files, re-staging, and re-committing, utilizing pre-commit hooks and Git protocols.","zh":"赋予代理自动化修复提交重试循环的能力，通过自动读取错误、修复文件、重新暂存和重新提交，利用预提交钩子和 Git 协议，减少手动劳动。","ja":"エージェントに事前コミットフックと Git プロトコルを利用して、自動的にエラーを読み取り、ファイルを修正し、再度ステージングしてコミットすることで、修正コミット再試行ループを自動化する能力を与え、手動作業を削減します。","ko":"에이전트에 사전 커밋 훅 및 Git 프로토콜을 사용하여 자동으로 오류를 읽고 파일을 수정하고 다시 스테이징하고 커밋하여 수정 커밋 재시도 루프를 자동화하는 능력을 부여하여 수동 노동을 줄입니다.","es":"Habilita a los agentes a automatizar el bucle de fix-commit-retry, reduciendo el trabajo manual al leer automáticamente los errores, corregir archivos, re-etapar y volver a confirmar, utilizando ganchos pre-commit y protocolos Git.","fr":"Permet aux agents d''automatiser la boucle de fix-commit-retry, en réduisant le travail manuel en lisant automatiquement les erreurs, en corrigeant les fichiers, en réétageant et en réconfirmant, en utilisant les hooks pre-commit et les protocoles Git.","de":"Ermöglich es Agents, den Fix-Commit-Retry-Loop zu automatisieren, indem sie manuelle Arbeit durch automatisches Lesen von Fehlern, Korrigieren von Dateien, erneutes Stagings und erneutes Commit reduzieren, unter Verwendung von Pre-Commit-Hooks und Git-Protokollen.","pt":"Habilita os agentes a automatizar a loop de fix-commit-retry, reduzindo o trabalho manual ao ler automaticamente erros, corrigir arquivos, reorganizar e re-fazer commit, utilizando hooks de pré-commits e protocolos Git.","ru":"Наделяет агентов возможностью автоматизировать цикл исправления-повтора коммита, сокращая ручной труд путем автоматического чтения ошибок, исправления файлов, повторной подготовки и повторного коммита, используя предварительные коммит-хуки и протоколы Git.","ar":"يمكن الوكلاء من أتمتة حلقة إصلاح-إعادة-التزام، مما يقلل من العمل اليدوي من خلال قراءة الأخطاء تلقائيًا وإصلاح الملفات وإعادة الترتيب وإعادة الالتزام، باستخدام hooks الالتزام السابق وبروتوكولات Git."},"useCases":{"en":["Automating pre-commit hook failures","Streamlining fix-commit-retry loops","Enhancing developer productivity"],"zh":["自动化预提交钩子失败","简化修复提交重试循环","提高开发者生产力"],"ja":["事前コミットフックの失敗を自動化する","修正コミット再試行ループを合理化する","開発者の生産性を向上させる"],"ko":["사전 커밋 훅 실패 자동화","수정 커밋 재시도 루프 최적화","개발자 생산성 향상"],"es":["Automatización de fallos de ganchos pre-commit","Optimización de bucles de fix-commit-retry","Mejora de la productividad de los desarrolladores"],"fr":["Automatisation des échecs des hooks pre-commit","Optimisation des boucles de fix-commit-retry","Amélioration de la productivité des développeurs"],"de":["Automatisierung von Pre-Commit-Hook-Fehlern","Optimierung von Fix-Commit-Retry-Schleifen","Verbesserung der Produktivität der Entwickler"],"pt":["Automatizar falhas de hook de pré-commits","Otimizar loops de fix-commit-retry","Aumentar a produtividade do desenvolvedor"],"ru":["Автоматизация неудач предварительных коммит-хуков","Оптимизация циклов исправления-повтора коммита","Повышение производительности разработчика"],"ar":["أتمتة فشل hooks الالتزام السابق","تبسيط حلقة إصلاح-إعادة-التزام","تعزيز إنتاجية المطور"]},"limitations":{"en":["Requires Git version control system","Limited to tasks within pre-commit hook scope"],"zh":["需要 Git 版本控制系统","仅限于预提交钩子范围内的任务"],"ja":["Git バージョン管理システムが必要","事前コミットフックの範囲内でのみタスクが実行可能"],"ko":["Git 버전 관리 시스템 필요","사전 커밋 훅 범위 내의 태스크에만 제한"],"es":["Requiere sistema de control de versiones Git","Limitado a tareas dentro del alcance del gancho pre-commit"],"fr":["Nécessite le système de contrôle de version Git","Limité aux tâches dans la portée du hook pre-commit"],"de":["Erfordert Git-Versionskontrollsystem","Begrenzt auf Aufgaben im Bereich des Pre-Commit-Hooks"],"pt":["Requer sistema de controle de versão Git","Limitado a tarefas dentro do escopo do hook de pré-commits"],"ru":["Требуется система контроля версий Git","Ограничен задачами в пределах области предварительных коммит-хуков"],"ar":["يتطلب نظام التحكم في الإصدار Git","محدود بالمهام داخل نطاق hooks الالتزام السابق"]},"version":4},"contentHash":"5140c1138f847af8a0599b70095fd89fce8a9dda6aa6e21aae9a00c042792d1c","qualityScore":60}');
