INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('benjaminshoemaker/benshoemaker-us/vision-audit', 'vision-audit', 'benjaminshoemaker', 'benshoemaker-us', 'community', 'vision-audit benjaminshoemaker benshoemaker-us community The vision-audit skill evaluates toolkits against their vision, generating feature proposals with rationale. It benefits developers by creating a roadmap for achieving desired outcomes. Vision Audit 是一个全面评估工具包的工具，能够生成功能提案和路线图，帮助开发者改进开发流程 Vision Audit は、ツールキットの評価と機能提案の生成、路線図の生成をサポートする AIエージェントです 비전 오디트는 툴킷을 평가하고 기능 제안을 생성하며 로드맵을 생성하는 컴프레헨시브 오디트 도구입니다 Vision Audit es una herramienta de auditoría que evalúa la herramienta contra su visión y genera propuestas de características con justificación, enfocándose en resultados y no en prácticas o herramientas Vision Audit est un outil d''audit qui évalue l''outil par rapport à sa vision et génère des propositions de fonctionnalités avec justification, en se concentrant sur les résultats et non sur les pratiques ou les outils Vision Audit ist ein Audit-Tool, das die Werkzeuge gegen ihre Vision bewertet und Funktionsvorschläge mit Begründung generiert, mit Fokus auf Ergebnisse und nicht auf Praktiken oder Werkzeuge O Vision Audit é uma ferramenta de análise de toolkit que avalia a conformidade com a visão e gera propostas de recursos. Ele se concentra em resultados, não em práticas ou ferramentas. ИИ Агент Vision Audit - это инструмент для комплексного аудита toolkit, оценивающий соответствие видению и генерирующий предложения функций. Он фокусируется на результатах, а не на практиках или инструментах. Vision Audit هو أداة فحصToolkit الشاملة التي تقيم المطابقة مع الرؤية وتوليد مقترحات الميزات. إنها تركز على النتائج، وليس على الممارسات أو الأدوات. how to use vision-audit what is vision-audit vision-audit alternative vision-audit vs competitor vision-audit install vision-audit setup guide toolkit evaluation roadmap generation feature proposal generation Vision Audit 工具包评估 功能提案生成 路线图生成 开发流程改进 AIエージェント 结果导向的方法 与竞争对手的差异化 Generates feature proposals with rationale Compares toolkit outcomes to SDLC outcomes Researches the landscape to inform proposals Creates a roadmap for achieving desired outcomes Focuses on outcomes rather than practices or tools Aligns proposals with principles and differentiates from competitors vision-audit is a comprehensive audit tool that evaluates a toolkit''s direction and generates feature proposals to achieve desired outcomes');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Nate-Vish/Auto-Mates/summon-team-build', 'community', 'Nate-Vish', 'Auto-Mates', 'Nate-Vish/Auto-Mates', 'summon-team-build', 2, 0, 60, '2026-02-27T02:12:40Z', '2026-03-06T07:08:12.779Z', '0876b760ca840b7c222d0a6da6dd0d6e0ff6224bd8ace1f425853b63bb766b00', '{"id":"Nate-Vish/Auto-Mates/summon-team-build","name":"summon-team-build","description":{"en":"The summon-team-build skill transforms Large Language Models into a structured engineering department, enabling developers to launch a coordinated build team. This skill benefits developers by automating tasks such as studying the domain, designing, implementing, and reviewing code.","zh":"summon-team-build 是一个自动化工程团队协作工具，通过 Fetcher、Planner、Builder 和 Checker 四个角色实现协同工作","ja":"summon-team-build は、Fetcher、Planner、Builder、Checker の 4 つの役割を通じて協調的に作業する自動化エンジニアリングチームコラボレーションツールです","ko":"summon-team-build 는 Fetcher, Planner, Builder, Checker 4개의 역할을 통해 협력적으로 작업하는 자동화 엔지니어링 팀 협업 도구입니다","es":"Summon-team-build es un marco de trabajo de agente múltiple que transforma grandes modelos de lenguaje en un departamento de ingeniería estructurado","fr":"Summon-team-build est un cadre de travail d''agent multiple qui transforme les grands modèles de langage en un département d''ingénierie structuré","de":"Summon-team-build ist ein Rahmenwerk für Multiple Agenten, das große Sprachmodelle in ein strukturiertes Ingenieurteam umwandelt","pt":"O summon-team-build é uma estrutura de agente multi-rol que transforma grandes modelos de linguagem em departamentos de engenharia estruturados","ru":"summon-team-build - это многофункциональная框架 агентов, превращающая большие языковые модели в структурированные инженерные отделы","ar":"summon-team-build هو إطار متعدد الأدوار لعميل الذكاء الاصطناعي الذي يحول النماذج اللغوية الكبيرة إلى أقسام هندسية منظمة"},"seo":{"title":{"en":"summon-team-build: Coordinated Team Launch for AI Agents ...","zh":"summon-team-build 入门指南 - 自动化工程团队协作","ja":"summon-team-build セットアップガイド - AIエージェントによるチームビルド","ko":"summon-team-build 시작하기 - 자동화 엔지니어링 팀 빌드","es":"Guía de configuración de summon-team-build para equipos d...","fr":"Guide de mise en place de summon-team-build pour les équi...","de":"Einrichtungsleitfaden für summon-team-build für IA-Engine...","pt":"Guia de Configuração do summon-team-build: Equipe de Enge...","ru":"Настройка summon-team-build: ИИ Агенты для Инженерных Команд","ar":"دليل الإعداد ل summon-team-build: فريق هندسة الإصدار الذكي"},"description":{"en":"Unlock efficient team collaboration with summon-team-build. Learn how to launch a coordinated build team and streamline your development process today!","zh":"使用 summon-team-build 实现自动化工程团队协作，提升开发效率和代码质量","ja":"summon-team-build を使用して AI エージェントによるチームビルドを実現し、開発効率とコード品質を向上させる","ko":"summon-team-build 를 사용하여 자동화 엔지니어링 팀 빌드를 구현하고 개발 효율과 코드 품질을 향상시키세요","es":"Descubre cómo lanzar un equipo de construcción coordinado con summon-team-build y aprovecha al máximo tus proyectos de IA con AutoMates","fr":"Découvrez comment lancer une équipe de construction coordonnée avec summon-team-build et tirez le meilleur parti de vos projets d''IA avec AutoMates","de":"Erfahren Sie, wie Sie ein koordiniertes Build-Team mit summon-team-build starten und Ihre IA-Projekte mit AutoMates maximieren","pt":"Aprenda a configurar o summon-team-build para criar equipes de engenharia de IA para desenvolver projetos de software de forma eficiente","ru":"Узнайте, как настроить summon-team-build для создания команд ИИ-инженеров для разработки программных проектов","ar":"تعرف على كيفية ضبط summon-team-build لإنشاء فرق هندسة الإصدار الذكي لتطوير مشاريع البرمجيات بفعالية"},"definition":{"en":"summon-team-build is a role-based multi-agent framework that enables the creation of a coordinated build team, working in parallel as Agent Teams teammates.","zh":"summon-team-build 是一种自动化工程团队协作框架，使用多个 AI 代理实现并