INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Nate-Vish/Auto-Mates/summon-team-build', 'summon-team-build', 'Nate-Vish', 'Auto-Mates', 'community', 'summon-team-build Nate-Vish Auto-Mates community The summon-team-build skill transforms Large Language Models into a structured engineering department, enabling developers to launch a coordinated build team. This skill benefits developers by automating tasks such as studying the domain, designing, implementing, and reviewing code. summon-team-build 是一个自动化工程团队协作工具，通过 Fetcher、Planner、Builder 和 Checker 四个角色实现协同工作 summon-team-build は、Fetcher、Planner、Builder、Checker の 4 つの役割を通じて協調的に作業する自動化エンジニアリングチームコラボレーションツールです summon-team-build 는 Fetcher, Planner, Builder, Checker 4개의 역할을 통해 협력적으로 작업하는 자동화 엔지니어링 팀 협업 도구입니다 Summon-team-build es un marco de trabajo de agente múltiple que transforma grandes modelos de lenguaje en un departamento de ingeniería estructurado Summon-team-build est un cadre de travail d''agent multiple qui transforme les grands modèles de langage en un département d''ingénierie structuré Summon-team-build ist ein Rahmenwerk für Multiple Agenten, das große Sprachmodelle in ein strukturiertes Ingenieurteam umwandelt O summon-team-build é uma estrutura de agente multi-rol que transforma grandes modelos de linguagem em departamentos de engenharia estruturados summon-team-build - это многофункциональная框架 агентов, превращающая большие языковые модели в структурированные инженерные отделы summon-team-build هو إطار متعدد الأدوار لعميل الذكاء الاصطناعي الذي يحول النماذج اللغوية الكبيرة إلى أقسام هندسية منظمة how to use summon-team-build summon-team-build setup guide summon-team-build alternative summon-team-build vs AutoMates what is summon-team-build summon-team-build install coordinated team launch for AI agents role-based multi-agent framework Large Language Model development summon-team-build 自动化工程团队协作 AI 代理 Fetcher Planner Builder Checker CLI 命令行工具 并行工作 代码质量 Launches a coordinated build team using the /summon-team-build command Supports task automation with roles such as Fetcher, Planner, Builder, and Checker Enables parallel work as Agent Teams teammates Allows for custom task descriptions using the <task description> parameter Supports tasks such as adding user authentication with JWT tokens and refactoring database layers for PostgreSQL support summon-team-build is a role-based multi-agent framework that enables the creation of a coordinated build team, working in parallel as Agent Teams teammates.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('RoukSonix/claude-code-octopus/protractor-playwright-migrator', 'community', 'RoukSonix', 'claude-code-octopus', 'RoukSonix/claude-code-octopus', 'protractor-playwright-migrator', 2, 1, 60, '2026-02-28T14:21:26Z', '2026-03-06T07:08:13.318Z', '6103b7b701ef871cc8db3e54194291a6ac44e3f52c198eff1870fe25d501c720', '{"id":"RoukSonix/claude-code-octopus/protractor-playwright-migrator","name":"protractor-playwright-migrator","description":{"en":"The protractor-playwright-migrator skill generates a migration plan from Protractor to Playwright, matching repository rules and TestKit conventions, benefiting developers and testers.","zh":"protractor-playwright-migrator是一种AI工具，帮助开发者将Protractor测试用例迁移到Playwright，支持plan-only和plan-and-implement两种模式","ja":"protractor-playwright-migratorは、ProtractorのテストケースをPlaywrightに移行するためのAIツールです。plan-onlyとplan-and-implementの2つのモードをサポートしています","ko":"protractor-playwright-migrator는 프로트ラク터 테스트 케이스를 플레이wright로 마이그레이션하는 AI 도구입니다. plan-only와 plan-and-implement 두 가지 모드를 지원합니다","es":"El protractor-playwright-migrator es una herramienta que ayuda a migrar de Protractor a Playwright, mejorando los flujos de trabajo y siguiendo las convenciones de TestKit.","fr":"Le protractor-playwright-migrator est un outil qui aide à migrer de Protractor à Playwright, améliorant les flux de travail et suivant les conventions de TestKit.","de":"Der protractor-playwright-migrator ist ein Tool, das hilft, von Protractor zu Playwright zu migrieren, wodurch die Workflows verbessert und die TestKit-Konventionen eingehalten werden.","pt":"O protractor-playwright-migrator é uma ferramenta que ajuda a migrar testes de Protractor para Playwright, com opções de planejamento e implementação.","ru":"ИИ Агент protractor-playwright-migrator помогает мигрировать тесты из Protractor в Playwright с опциями планирования и реализации.","ar":"وحدة بروتراكتور-بلاي رايت-مايغرатор هي أداة تساعد على هجرة الاختبارات من بروتراكتور إلى بلاي رايت، مع خيارات التخطيط والتنفيذ."},"seo":{"title":{"en":"protractor-playwright-migrator: Migration Setup Guide | A...","zh":"Protractor 到 Playwright 迁移工具Setup Guide","ja":"Protractor から Playwright への移行ツールベストプラクティス","ko":"프로트ラク터에서 플레이wright로 마이그레이션하기 위한 Setup Guide","es":"Guía de migración Protractor a Playwright con protractor-...","fr":"Mise en place de la migration Protractor vers Playwright ...","de":"Leitfaden zur Migration von Protractor zu Playwright mit ...","pt":"Guia de Migração Protractor para Playwright","ru":"ИИ Агент: Миграция Protractor в Playwright","ar":"دليل هجرة بروتراكتور إلى بلاي رايت"},"description":{"en":"Discover how to seamlessly migrate from Protractor to Playwright with our expert guide. Get started today and optimize your testing workflow!","zh":"使用AIエージェント工具protractor-playwright-migrator，轻松将Protractor测试用例迁移到Playwright，提高测试效率","ja":"AIエージェントツールprotractor-playwright-migratorを使用して、ProtractorのテストケースをPlaywrightに移行し、テストの効率を向上させる","ko":"AI 에이전트 도구 protractor-playwright-migrator를 사용하여 프로트ラク터 테스트 케이스를 플레이wright로 마이그레이션하고 테스트 효율을 높여보세요","es":"Descubre cómo migrar de Protractor a Playwright de manera efectiva con protractor-playwright-migrator, herramienta de migración para mejorar tus flujos de tr...","fr":"Découvrez comment migrer de Protractor à Playwright de manière efficace avec protractor-playwright-migrator, outil de migration pour améliorer vos flux de tr...","de":"Erfahren Sie, wie Sie von Protractor zu Playwright effektiv migrieren können, mit protractor-playwright-migrator, einem Migrationstool für verbesserte Workflows","pt":"Aprenda a migrar de Protractor para Playwright com este guia passo a passo, incluindo planejamento e implementação","ru":"Мигрируйте из Protractor в Playwright с помощью этого пошагового руководства, включая планирование и реализацию","ar":"تعلم كيفية هجرة بروتراكتور إلى بلاي رايت بخطوات سهلة، بما في ذلك التخطيط والتنفيذ"},"definition":{"en":"protractor-playwright-migrator is a tool that produces a migration plan and optionally implements changes from Protractor to Playwright.","zh":"protractor-playwright-migrator是一种自动化测试迁移工具，用于将Protractor测试用例迁移到Playwright","ja":"protractor-playwright-migratorは、ProtractorのテストケースをPlaywrightに自動的に移行するツールです","ko":"protractor-playwright-migrator는 프로트ラク터 테스트 케이스를 플레이wright로 자동으로 마이그레이션하는 도구입니다","es":"El protractor-playwright-migrator es una herramienta de migración que permite trasladar código de Protractor a Playwright","fr":"Le protractor-playwright-migrator est un outil de migration qui permet de transposer du code Protractor vers Playwright","de":"Der protractor-playwright-migrator ist ein Migrationstool, das es ermöglicht, Code von Protractor zu Playwright zu übertragen","pt":"O protractor-playwright-migrator é uma ferramenta de migração que converte testes de Protractor em testes de Playwright.","ru":"ИИ Агент protractor-playwright-migrator - это инструмент миграции, который преобразует тесты Protractor в тесты Playwright.","ar":"وحدة بروتراكتور-بلاي رايت-مايغرатор هي أداة هجرة تحول الاختبارات من بروتراكتور إلى بلاي رايت."},"features":{"en":["Collects source directory and target directory inputs for migration","Supports scope modes ''plan-only'' and ''plan-and-implement'' for flexible migration","Derives missing inputs from context and state assumptions","Generates migration plans based on repository rules and TestKit conventions","Optionally implements migration changes for streamlined testing workflows"],"zh":["支持Protractor到Playwright的自动化迁移","plan-only和plan-and-implement两种模式","源目录和目标目录的指定","集成TestKit约定"],"ja":["ProtractorからPlaywrightへの自動化移行をサポート","plan-onlyとplan-and-implementの2つのモード","ソースディレクトリとターゲットディレクトリの指定","TestKit約定の統合"],"ko":["프로트ラク터에서 플레이wright로의 자동화 마이그레이션 지원","plan-only와 plan-and-implement 두 가지 모드","소스 디렉토리와 타겟 디렉토리의 지정","TestKit 규약의 통합"],"es":["Migración de código de Protractor a Playwright","Generación de un plan de migración personalizado","Compatibilidad con el modo de alcance ''plan-only'' y ''plan-and-implement''","Soporte para la configuración de directorios de origen y destino","Integración con las convenciones de TestKit"],"fr":["Migration de code Protractor vers Playwright","Génération d''un plan de migration personnalisé","Compatibilité avec les modes de portée ''plan-only'' et ''plan-and-implement''","Prise en charge de la configuration des répertoires source et cible","Intégration avec les conventions de TestKit"],"de":["Migration von Protractor-Code zu Playwright","Erstellung eines benutzerdefinierten Migrationsplans","Unterstützung für den Umfangsmodus ''plan-only'' und ''plan-and-implement''","Konfiguration von Quell- und Zielverzeichnissen","Integration mit den TestKit-Konventionen"],"pt":["Suporte a migração de testes de Protractor para Playwright","Opção de planejamento e implementação","Compatibilidade com repositórios e convenções de TestKit","Aceitação de diretórios de origem e destino como argumentos","Modo de escopo: planejamento apenas ou planejamento e implementação"],"ru":["Поддержка миграции тестов из Protractor в Playwright","Вариант планирования и реализации","Совместимость с репозиториями и конвенциями TestKit","Принятие директорий источника и назначения в качестве аргументов","Режим области: только планирование или планирование и реализация"],"ar":["دعم هجرة الاختبارات من بروتراكتور إلى بلاي رايت","خيار التخطيط والتنفيذ","توافق مع مخازن وآليات تيست كيت","قبول الدلائل المصدر والوجهة كحجج","وضع النطاق: تخطيط فقط أو تخطيط وتنفيذ"]},"keywords":{"en":["protractor to playwright migration","how to use protractor-playwright-migrator","protractor-playwright-migrator setup guide","protractor-playwright-migrator alternative","protractor-playwright-migrator vs selenium","protractor-playwright-migrator install","playwright migration tool","protractor migration best practices"],"zh":["Protractor到Playwright迁移","AIエージェント工具","自动化测试迁移","Playwright测试","Protractor测试","TestKit约定","plan-only模式","plan-and-implement模式"],"ja":["ProtractorからPlaywrightへの移行","AIエージェントツール","自動化テスト移行","Playwrightテスト","Protractorテスト","TestKit約定","plan-onlyモード","plan-and-implementモード"],"ko":["프로트ラク터에서 플레이wright로 마이그레이션","AI 에이전트 도구","자동화 테스트 마이그레이션","Playwright 테스트","Protractor 테스트","TestKit 규약","plan-only 모드","plan-and-implement 모드"],"es":["protractor-playwright-migrator","migración de protractor a playwright","herramienta de migración","testkit","playwright","protractor","automatización de pruebas","desarrollo de software"],"fr":["protractor-playwright-migrator","migration de protractor à playwright","outil de migration","testkit","playwright","protractor","automatisation de tests","développement de logiciels"],"de":["protractor-playwright-migrator","migration von protractor zu playwright","migrationstool","testkit","playwright","protractor","automatisierung von tests","softwareentwicklung"],"pt":["migração protractor para playwright","protractor playwright migrator","testes de protractor","playwright testing","ferramentas de migração","desenvolvimento de software","testes automatizados"],"ru":["миграция protractor в playwright","protractor playwright мигратор","тесты protractor","playwright тестирование","инструменты миграции","разработка программного обеспечения","автоматизированное тестирование"],"ar":["هجرة بروتراكتور إلى بلاي رايت","بروتوراكتور-بلاي رايت-مايغرатор","اختبارات بروتراكتور","اختبار بلاي رايت","أدوات الهجرة","تطوير البرمجيات","اختبارات آلية"]}},"owner":"RoukSonix","repo":"claude-code-octopus","repoPath":"RoukSonix/claude-code-octopus","stars":2,"forks":1,"updatedAt":"2026-02-28T14:21:26Z","topics":[],"category":"community","skillMd":{"name":"protractor-playwright-migrator","description":"Migrate Creatio end-to-end tests from legacy Protractor sources into Playwright TestKit-compliant feature folders, or build a full migration plan before implementation. Use when invoked as $protractor-playwright-migrator [protractor-tests-location] [playwright-tests-destination], or when a request includes source and target paths and requires business-logic preservation per test, TestKit-first patterns, gap analysis for missing TestKit components, verification on Creatio via mcp chrome-devtools, and failure debugging using mcp chrome-devtools plus Playwright artifacts from test-results and playwright-report.","bodyPreview":"# Protractor to Playwright Migrator\n\n## Goal\n\nProduce a migration plan (and optionally migration changes) from Protractor to Playwright that matches this repository rules and TestKit conventions.\n\n## Required Inputs\n\nCollect these values from the user request:\n\n- Source directory (Protractor): `ARGUMENT-1`\n- Target directory (Playwright): `ARGUMENT-2`\n- Scope mode: `plan-only` or `plan-and-implement` (default `plan-only`)\n\nIf any input is missing, derive from context and state assumptions explic","body":"# Protractor to Playwright Migrator\n\n## Goal\n\nProduce a migration plan (and optionally migration changes) from Protractor to Playwright that matches this repository rules and TestKit conventions.\n\n## Required Inputs\n\nCollect these values from the user request:\n\n- Source directory (Protractor): `ARGUMENT-1`\n- Target directory (Playwright): `ARGUMENT-2`\n- Scope mode: `plan-only` or `plan-and-implement` (default `plan-only`)\n\nIf any input is missing, derive from context and state assumptions explicitly.\n\n## Non-Negotiable Lookup Order\n\nFollow this order every time:\n\n1. Check TestKit docs first at `node_modules/@creatio/playwright-testkit/dist/docs`.\n2. Check migration rules at `docs/ai-migration/migration-patterns.md`.\n3. Check repository code and `external-source/protractor` only after steps 1-2.\n\nIf TestKit docs are missing/unreadable, stop and report blocker. Recommend `git pull` and `npm install`, then wait for user approval to continue without TestKit docs.\n\n## Required Subagent Orchestration\n\nUse subagents for non-trivial scope.\n\n- Spawn `explorer` 1: TestKit conventions extractor (pages, elements, fixtures, auth, waits).\n- Spawn `explorer` 2: Source inventory and path mapping analyzer for `ARGUMENT-1`.\n- Spawn `explorer` 3: Plan synthesizer that builds phased migration work and verification checkpoints.\n- Spawn `explorer` 4: Business-flow reconnaissance agent that reproduces target user flows in Creatio via `mcp chrome-devtools` and captures behavior notes/evidence.\n\nFor large scopes (more than 10 spec files), split implementation by feature area and assign `worker` subagents with explicit file ownership.\n\n## Workflow\n\n1. Validate paths.\n- Confirm `ARGUMENT-1` and `ARGUMENT-2` exist or create `ARGUMENT-2` when implementation mode requires it.\n\n2. Build source inventory.\n- Resolve the inventory script path relative to the skill root (do not assume repository `scripts/` and do not require `CODEX_HOME`):\n  - Preferred from skill root: `scripts/build_migration_inventory.py`\n  - Fallback: locate the script in the active CLI''s skills directory\n  - If needed, discover dynamically: `find . -path ''*/skills/protractor-playwright-migrator/scripts/build_migration_inventory.py'' -print -quit`\n- Run `<resolved-script-path> --source <ARGUMENT-1> --target <ARGUMENT-2>`.\n- Do not fail migration planning if `<repo>/scripts/build_migration_inventory.py` is missing; it is not expected to exist there.\n- Group files into `specs`, `pages`, `elements`, `data`, `utils`, `other`.\n\n3. Define target mapping.\n- Place migrated assets under `tests/_migrated/features/<feature>/...`.\n- Keep import boundary: no imports from `tests/_migrated` into `tests/features`.\n\n4. Analyze business logic of every migrated test before translation.\n- Run subagent-driven business-flow reconnaissance in parallel for test groups:\n  - assign `explorer` subagents to reproduce real user flows in Creatio with `mcp chrome-devtools`,\n  - capture screen/state transitions, important controls/markers, role constraints, and expected outcomes,\n  - attach concise evidence references (screenshots or step logs).\n- For each Protractor spec/test case, extract test intent and protected behavior from both code and live app behavior:\n  - business scenario and user role/context,\n  - critical actions and data transitions,\n  - assertions that protect business value.\n- Correlate Protractor assertions with observed application behavior from `mcp chrome-devtools` and resolve mismatches before planning.\n- Build a parity checklist per test: `original intent -> migrated coverage`.\n- Do not drop business assertions during migration; if UI details change, preserve intent with equivalent Playwright/TestKit assertions.\n- If reconnaissance cannot be completed (environment/auth/data blockers), stop and report blockers explicitly with assumptions that require user confirmation.\n\n5. Apply TestKit-first migration rules.\n- Use appropriate base pages (`BaseListPage`, `BaseFormPage`, `Base8xPage`, `Base7xPage`, `BaseSystemDesignerPage`).\n- Prefer TestKit elements and `ElementProps` (`marker` first, then `ariaLabel`, then stable attributes).\n- Use fixture-based auth (`test.use({ userType })`) and avoid routine manual login.\n- Use auto-retrying expectations and avoid hardcoded waits.\n\n6. Perform gap analysis.\n- Identify features not covered by TestKit.\n- Plan implementation of missing custom elements/helpers as part of migration under `elements/` or `utils/`.\n- Prefer reusable abstractions over one-off locators.\n\n7. Build phased migration plan.\n- Include per-file migration actions.\n- Include risk/complexity flags (7.x/extJs, dynamic grids, unsupported elements, brittle selectors).\n- Include required tests and lint/type checks.\n\n8. Define mandatory verification on real app with `mcp chrome-devtools`.\n- Execute affected migrated tests to produce artifacts before deep debug:\n  - `npx playwright test <affected-specs> --trace on`\n- Open Creatio and navigate migrated flow.\n- Validate key user path per migrated spec (open page, perform action, assert visible outcomes).\n- Capture evidence (screenshots and concise pass/fail notes).\n\n9. Debug failed validation runs.\n- If migrated tests fail or are unstable, start with live app exploration in Creatio via `mcp chrome-devtools` as the primary debugging method.\n- Use subagents to reproduce failing flows in parallel when scope is large (split by failing spec group).\n- During debugging, prioritize understanding real runtime behavior first, then correlate with test artifacts.\n- Inspect Playwright artifacts produced after each run:\n  - `test-results/` for traces, screenshots, videos, and per-test artifacts.\n  - `playwright-report/` for HTML run summary and error context.\n- Correlate artifact failures with live UI behavior in `mcp chrome-devtools` and produce:\n  - validated root-cause hypothesis,\n  - minimal fix actions,\n  - re-check steps in application before re-running full tests.\n\n## Output Contract\n\nAlways return:\n\n- Inventory summary with counts by category.\n- File mapping table: `source -> target`.\n- Application reconnaissance summary from `mcp chrome-devtools` (observed flow steps, markers/controls, role constraints, evidence links).\n- Business-logic parity matrix for every migrated test (`Protractor intent -> Playwright assertions`).\n- TestKit compliance checklist.\n- Gap analysis for missing TestKit coverage and implementation tasks.\n- Phased migration plan with execution order and parallel tracks.\n- Verification plan using `mcp chrome-devtools` with explicit steps and expected results.\n- Validation execution summary with exact Playwright command(s) and artifact locations.\n- Failure-debug plan that uses `mcp chrome-devtools` and Playwright artifacts from `test-results/` and `playwright-report/`.\n- Used references list where the first item is a TestKit docs path.\n\nUse `references/migration-plan-template.md` as the default response format.\n\n## Prompt Template\n\nInvoke the skill with positional arguments:\n\n```text\n$protractor-playwright-migrator $ARGUMENTS\n```\n\nWhere:\n\n- `$ARGUMENTS` = `[protractor-tests-location] [playwright-tests-destination]`\n- argument 1 = source directory (Protractor)\n- argument 2 = target directory (Playwright)\n\nDefault user prompt after parsing arguments:\n\n```text\nI need to migrate tests from Protractor to Playwright.\nSource directory: ARGUMENT-1\nTarget directory: ARGUMENT-2\nCreate a migration plan for all tests in this directory.\nIf something is not provided by testkit it should be implemented as part of the migration.\nThe plan must include verification of migrated tests in Creatio using mcp chrome-devtools.\n```\n\n## Context7 Rule\n\nWhen querying external docs for coding details, use Context7 and append `use context7` to the query text.\n"},"lastSynced":"2026-03-06T07:08:13.318Z","agentAnalysis":{"suitability":{"en":"Ideal for Automated Testing Agents needing seamless migration from Protractor to Playwright.","zh":"适用于需要从 Protractor 到 Playwright 进行无缝迁移的自动化测试代理。","ja":"Protractor から Playwright への無縫な移行が必要な自動テスト エージェントに適しています。","ko":"Protractor 에서 Playwright 로 무중단 마이그레이션이 필요한 자동화 테스트 에이전트에 적합합니다.","es":"Ideal para agentes de pruebas automatizadas que necesitan una migración sin problemas de Protractor a Playwright.","fr":"Idéal pour les agents de test automatisés nécessitant une migration sans heurts de Protractor à Playwright.","de":"Ideal für automatisierte Testagenten, die eine nahtlose Migration von Protractor zu Playwright benötigen.","pt":"Ideal para Agentes de Testes Automatizados que precisam de migração sem problemas do Protractor para o Playwright.","ru":"Идеально для автоматизированных агентов тестирования, которым необходима бесшовная миграция с Protractor на Playwright.","ar":"مثالي لوكلاء الاختبار الآلي الذين يحتاجون إلى chuyển من Protractor إلى Playwright بسلاسة."},"recommendation":{"en":"Empowers agents to generate migration plans and implement changes from Protractor to Playwright, adhering to repository rules and TestKit conventions, utilizing scope modes like ''plan-only'' and ''plan-and-implement'' to match specific testing needs.","zh":"赋予代理生成迁移计划和实施从 Protractor 到 Playwright 的更改的能力，遵守存储库规则和 TestKit 约定，使用诸如 ''plan-only'' 和 ''plan-and-implement'' 的范围模式以匹配特定的测试需求。","ja":"Protractor から Playwright への移行計画の生成および実施をエージェントに可能にし、リポジトリのルールや TestKit の規約を遵守し、特定のテスト要件に合わせた ''plan-only'' や ''plan-and-implement'' などのスコープ モードを使用します。","ko":"에이전트가 Protractor 에서 Playwright 로의 마이그레이션 계획을 생성하고 변경 사항을 구현할 수 있도록하며, 저장소 규칙과 TestKit 규약을 준수하고, 특정 테스트 요구 사항에 맞는 ''plan-only'' 및 ''plan-and-implement''와 같은 범위 모드를 사용합니다.","es":"Habilita a los agentes a generar planes de migración e implementar cambios de Protractor a Playwright, siguiendo las reglas del repositorio y las convenciones de TestKit, utilizando modos de alcance como ''plan-only'' y ''plan-and-implement'' para satisfacer necesidades de prueba específicas.","fr":"Permet aux agents de générer des plans de migration et de mettre en œuvre des modifications de Protractor à Playwright, en suivant les règles du référentiel et les conventions de TestKit, en utilisant des modes d''étendue tels que ''plan-only'' et ''plan-and-implement'' pour répondre à des besoins de test spécifiques.","de":"Ermächtigt die Agenten, Migrationspläne zu generieren und Änderungen von Protractor zu Playwright umzusetzen, indem sie die Regeln des Repositorys und die Konventionen von TestKit befolgen, wobei sie Bereichsmodi wie ''plan-only'' und ''plan-and-implement'' verwenden, um bestimmte Testanforderungen zu erfüllen.","pt":"Habilita os agentes a gerar planos de migração e implementar alterações do Protractor para o Playwright, respeitando regras de repositório e convenções do TestKit, utilizando modos de escopo como ''plan-only'' e ''plan-and-implement'' para atender às necessidades específicas de teste.","ru":"Наделяет агентов возможностью генерировать планы миграции и вносить изменения с Protractor на Playwright, придерживаясь правил репозитория и конвенций TestKit, используя режимы области действия, такие как ''plan-only'' и ''plan-and-implement'', для соответствия конкретным потребностям тестирования.","ar":"يمنح الوكلاء القدرة على إنشاء خطط للهجرة وتنفيذ التغييرات من Protractor إلى Playwright ، مع احترام قواعد المستودع وتوافق TestKit ، باستخدام أوضاع نطاق مثل ''plan-only'' و ''plan-and-implement'' للامتثال لاحتياجات الاختبار المحددة."},"useCases":{"en":["Migrating Protractor tests to Playwright for enhanced browser automation","Generating migration plans based on source and target directory inputs","Implementing migration changes while adhering to TestKit conventions"],"zh":["将 Protractor 测试迁移到 Playwright 以实现增强的浏览器自动化","根据源目录和目标目录输入生成迁移计划","实施迁移更改同时遵守 TestKit 约定"],"ja":["Protractor テストを Playwright に移行してブラウザーの自動化を強化する","ソース ディレクトリとターゲット ディレクトリの入力に基づいて移行計画を生成する","TestKit の規約を遵守しながら移行の変更を実施する"],"ko":["Protractor 테스트를 Playwright 로 마이그레이션하여 브라우저 자동화를 강화하는 것","소스 디렉토리와 대상 디렉토리 입력을 기반으로 마이그레이션 계획을 생성하는 것","TestKit 규약을 준수하면서 마이그레이션 변경 사항을 구현하는 것"],"es":["Migrar pruebas de Protractor a Playwright para una automatización de navegador mejorada","Generar planes de migración en función de las entradas del directorio de origen y destino","Implementar cambios de migración mientras se adhieren a las convenciones de TestKit"],"fr":["Migrer des tests Protractor vers Playwright pour une automatisation de navigateur améliorée","Générer des plans de migration en fonction des entrées du répertoire source et cible","Mettre en œuvre des modifications de migration tout en suivant les conventions de TestKit"],"de":["Migrieren von Protractor-Tests zu Playwright für eine verbesserte Browser-Automatisierung","Erstellen von Migrationsplänen auf Grundlage der Eingaben des Quell- und Zielverzeichnisses","Umsetzen von Migrationsänderungen unter Einhaltung der Konventionen von TestKit"],"pt":["Migrar testes Protractor para Playwright para automação de navegador aprimorada","Gerar planos de migração com base em entradas de diretório de origem e destino","Implementar alterações de migração enquanto se adere às convenções do TestKit"],"ru":["Мигрировать тесты Protractor в Playwright для улучшения автоматизации браузера","Генерировать планы миграции на основе входных данных каталогов источника и целевого","Реализовывать изменения миграции, придерживаясь конвенций TestKit"],"ar":["هجرة اختبارات Protractor إلى Playwright لتحسين автоматизации المتصفح","إنشاء خطط للهجرة على أساس إدخالات دليل المصدر والوجهة","تنفيذ التغييرات للهجرة مع الامتثال لتوافق TestKit"]},"limitations":{"en":["Requires source and target directory inputs","Limited to Protractor and Playwright testing frameworks","Scope mode restricted to ''plan-only'' or ''plan-and-implement''"],"zh":["需要源目录和目标目录输入","仅限 Protractor 和 Playwright 测试框架","范围模式仅限 ''plan-only'' 或 ''plan-and-implement''"],"ja":["ソース ディレクトリとターゲット ディレクトリの入力が必要","Protractor と Playwright のテスト フレームワークのみに限定される","スコープ モードは ''plan-only'' または ''plan-and-implement'' に制限される"],"ko":["소스 디렉토리와 대상 디렉토리 입력이 필요함","Protractor 와 Playwright 테스트 프레임워크에만 제한됨","범위 모드는 ''plan-only'' 또는 ''plan-and-implement''로 제한됨"],"es":["Requiere entradas del directorio de origen y destino","Limitado a los marcos de prueba Protractor y Playwright","Modo de alcance restringido a ''plan-only'' o ''plan-and-implement''"],"fr":["Nécessite des entrées du répertoire source et cible","Limité aux référentiels de test Protractor et Playwright","Mode d''étendue restreint à ''plan-only'' ou ''plan-and-implement''"],"de":["Benötigt Eingaben des Quell- und Zielverzeichnisses","Begrenzt auf die Testframeworks Protractor und Playwright","Bereichsmodus beschränkt auf ''plan-only'' oder ''plan-and-implement''"],"pt":["Exige entradas de diretório de origem e destino","Limitado aos quadros de teste Protractor e Playwright","Modo de escopo restrito a ''plan-only'' ou ''plan-and-implement''"],"ru":["Требует входных данных каталогов источника и целевого","Ограничен фреймворками тестирования Protractor и Playwright","Режим области действия ограничен ''plan-only'' или ''plan-and-implement''"],"ar":["يتطلب إدخالات دليل المصدر والوجهة","محدود بالإطارات الاختبارية Protractor و Playwright","وضع نطاق مقيد بـ ''plan-only'' أو ''plan-and-implement''"]},"version":4},"contentHash":"6103b7b701ef871cc8db3e54194291a6ac44e3f52c198eff1870fe25d501c720","qualityScore":60}');
