INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('RoukSonix/claude-code-octopus/protractor-playwright-migrator', 'protractor-playwright-migrator', 'RoukSonix', 'claude-code-octopus', 'community', 'protractor-playwright-migrator RoukSonix claude-code-octopus community The protractor-playwright-migrator skill generates a migration plan from Protractor to Playwright, matching repository rules and TestKit conventions, benefiting developers and testers. protractor-playwright-migrator是一种AI工具，帮助开发者将Protractor测试用例迁移到Playwright，支持plan-only和plan-and-implement两种模式 protractor-playwright-migratorは、ProtractorのテストケースをPlaywrightに移行するためのAIツールです。plan-onlyとplan-and-implementの2つのモードをサポートしています protractor-playwright-migrator는 프로트ラク터 테스트 케이스를 플레이wright로 마이그레이션하는 AI 도구입니다. plan-only와 plan-and-implement 두 가지 모드를 지원합니다 El protractor-playwright-migrator es una herramienta que ayuda a migrar de Protractor a Playwright, mejorando los flujos de trabajo y siguiendo las convenciones de TestKit. Le protractor-playwright-migrator est un outil qui aide à migrer de Protractor à Playwright, améliorant les flux de travail et suivant les conventions de TestKit. Der protractor-playwright-migrator ist ein Tool, das hilft, von Protractor zu Playwright zu migrieren, wodurch die Workflows verbessert und die TestKit-Konventionen eingehalten werden. O protractor-playwright-migrator é uma ferramenta que ajuda a migrar testes de Protractor para Playwright, com opções de planejamento e implementação. ИИ Агент protractor-playwright-migrator помогает мигрировать тесты из Protractor в Playwright с опциями планирования и реализации. وحدة بروتراكتور-بلاي رايت-مايغرатор هي أداة تساعد على هجرة الاختبارات من بروتراكتور إلى بلاي رايت، مع خيارات التخطيط والتنفيذ. protractor to playwright migration how to use protractor-playwright-migrator protractor-playwright-migrator setup guide protractor-playwright-migrator alternative protractor-playwright-migrator vs selenium protractor-playwright-migrator install playwright migration tool protractor migration best practices Protractor到Playwright迁移 AIエージェント工具 自动化测试迁移 Playwright测试 Protractor测试 TestKit约定 plan-only模式 plan-and-implement模式 Collects source directory and target directory inputs for migration Supports scope modes ''plan-only'' and ''plan-and-implement'' for flexible migration Derives missing inputs from context and state assumptions Generates migration plans based on repository rules and TestKit conventions Optionally implements migration changes for streamlined testing workflows protractor-playwright-migrator is a tool that produces a migration plan and optionally implements changes from Protractor to Playwright.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('telum-ai/speck/project-domain', 'community', 'telum-ai', 'speck', 'telum-ai/speck', 'project-domain', 2, 0, 60, '2026-03-01T14:49:13Z', '2026-03-06T07:08:41.402Z', 'bc974b4be549479b8cfca6296e661ab6e3e14f94bcd5c9be2ecec85978d724fa', '{"id":"telum-ai/speck/project-domain","name":"project-domain","description":{"en":"project-domain captures subject matter expertise and domain knowledge to inform product decisions. It creates a domain model using user input and command arguments.","zh":"项目域是捕获领域知识和专家意见的方法，用于指导项目决策","ja":"プロジェクトドメインは、プロジェクトの意思決定を導くために、ドメイン知識と専門知識を取得する方法です","ko":"프로젝트 도메인은 프로젝트 의사 결정에 대한 지침으로서의 도메인 지식 및 전문 지식을 캡처하는 방법","es":"Project-domain es una metodología de desarrollo basada en especificaciones que ayuda a capturar el conocimiento del dominio y la experiencia en materia","fr":"Project-domain est une méthodologie de développement basée sur des spécifications qui aide à capturer le savoir-faire et les règles de domaine","de":"Project-domain ist eine spezifikationsgetriebene Entwicklungsmethode, die dazu dient, das Domänenwissen und die Fachexpertise zu erfassen","pt":"O project-domain é uma metodologia de desenvolvimento que captura conhecimento de domínio e regras de negócios para informar decisões de produto.","ru":"Project-domain - это методология разработки, которая захватывает знания предметной области и бизнес-правила для принятия решений о продукте.","ar":"مشروع المجال هو منهجية تطوير تحقق خبرة المجال والقواعد التجارية لاتخاذ قرارات المنتج."},"seo":{"title":{"en":"project-domain: Spec-Driven Development Setup Guide | AI ...","zh":"项目域Setup Guide：捕获领域知识","ja":"プロジェクトドメインSetup Guide：AIエージェントによるドメイン知識の取得","ko":"프로젝트 도메인 Setup Guide: 도메인 지식 캡처","es":"Guía de configuración de project-domain para desarrollo d...","fr":"Guide de configuration de project-domain pour les dévelop...","de":"Einrichtungsleitfaden für project-domain: Spezifikationsg...","pt":"Guia de Configuração do Project-Domain: Desenvolvimento D...","ru":"ИИ Агенты для Project-Domain: Настройка Спецификаций","ar":"دليل إعداد مشروع المجال: تطوير مدفوع بالمواصفات"},"description":{"en":"Unlock the power of spec-driven development with project-domain. Learn how to capture subject matter expertise and create a domain model that informs product...","zh":"了解项目域的重要性和捕获领域知识的方法，提高项目决策的准确性","ja":"プロジェクトドメインの重要性とドメイン知識の取得方法を学び、プロジェクトの意思決定を改善する","ko":"프로젝트 도메인의 중요성과 도메인 지식 캡처 방법을 배우고 프로젝트 의사 결정 개선","es":"Descubre cómo project-domain ayuda a capturar el conocimiento del dominio y la experiencia en materia para informar decisiones de producto","fr":"Découvrez comment project-domain aide à capturer le savoir-faire et les règles de domaine pour éclairer les décisions de produits","de":"Erfahren Sie, wie project-domain dabei hilft, das Domänenwissen und die Fachexpertise zu erfassen, um Produktentscheidungen zu treffen","pt":"Aprenda a capturar conhecimento de domínio e regras de negócios com o project-domain, a metodologia de desenvolvimento dirigido por especificações","ru":"Поймите как захватить знания предметной области и бизнес-правила с помощью project-domain, методологии разработки на основе спецификаций","ar":"تعرف على كيفية捕уре خبرة المجال والقواعد التجارية مع مشروع المجال، منهجية التطوير الموجهة بالمواصفات"},"definition":{"en":"project-domain is a spec-driven development methodology that captures subject matter expertise and domain knowledge to inform product decisions.","zh":"项目域是指捕获领域知识和专家意见的过程","ja":"プロジェクトドメインとは、ドメイン知識と専門知識を取得するプロセスを指す","ko":"프로젝트 도메인은 도메인 지식 및 전문 지식을 캡처하는 프로세스","es":"Project-domain es una herramienta de desarrollo que captura el conocimiento del dominio y la experiencia en materia","fr":"Project-domain est un outil de développement qui capture le savoir-faire et les règles de domaine","de":"Project-domain ist ein Entwicklungstool, das das Domänenwissen und die Fachexpertise erfasst","pt":"O que é project-domain? É uma metodologia de desenvolvimento que captura conhecimento de domínio e regras de negócios.","ru":"Что такое project-domain? Это методология разработки, которая захватывает знания предметной области и бизнес-правила.","ar":"ما هو مشروع المجال؟ هو منهجية تطوير تحقق خبرة المجال والقواعد التجارية."},"features":{"en":["Captures subject matter expertise and domain knowledge using user input and command arguments","Creates a domain model that informs product decisions","Considers command arguments before proceeding with the prompt","Supports direct user input or input as a command argument","Informs product decisions using the ubiquitous language, domain rules, and principles from the field"],"zh":["捕获领域知识和专家意见","指导项目决策","支持命令行接口（CLI）","集成用户输入","创建或更新领域模型"],"ja":["ドメイン知識と専門知識の取得","プロジェクトの意思決定を導く","コマンドラインインターフェース（CLI）をサポート","ユーザー入力を統合","ドメインモデルを作成または更新"],"ko":["도메인 지식 및 전문 지식 캡처","프로젝트 의사 결정에 대한 지침","CLI 지원","사용자 입력 통합","도메인 모델 생성 또는 업데이트"],"es":["Captura del conocimiento del dominio y la experiencia en materia","Desarrollo basado en especificaciones","Uso de lenguaje ubicuo","Definición de reglas de dominio y principios","Integración con herramientas de desarrollo como CLI"],"fr":["Capture du savoir-faire et des règles de domaine","Développement basé sur des spécifications","Utilisation de langage ubiquitaire","Définition de règles de domaine et de principes","Intégration avec des outils de développement comme CLI"],"de":["Erfassung des Domänenwissens und der Fachexpertise","Spezifikationsgetriebene Entwicklung","Verwendung von ubiquitärem Sprachgebrauch","Definition von Domänenregeln und -prinzipien","Integration mit Entwicklungstools wie CLI"],"pt":["Captura de conhecimento de domínio e regras de negócios","Desenvolvimento dirigido por especificações","Integração com CLI para configuração","Suporte a linguagem ubiquitous","Definição de princípios de negócios"],"ru":["Захват знаний предметной области и бизнес-правил","Разработка на основе спецификаций","Интеграция с CLI для настройки","Поддержка универсального языка","Определение бизнес-принципов"],"ar":["التقاط خبرة المجال والقواعد التجارية","التطوير الموجهة بالمواصفات","التكامل مع CLI للاعداد","دعم لغة شاملة","تحديد مبادئ الأعمال"]},"keywords":{"en":["how to use project-domain","what is project-domain","project-domain alternative","project-domain vs spec-driven development","project-domain install","project-domain setup guide","spec-driven development methodology","domain model creation","capturing subject matter expertise"],"zh":["项目域","领域知识","专家意见","项目决策","CLI","用户输入","领域模型","AI工具","项目管理"],"ja":["プロジェクトドメイン","ドメイン知識","専門知識","プロジェクトの意思決定","CLI","ユーザー入力","ドメインモデル","AIエージェント","プロジェクト管理"],"ko":["프로젝트 도메인","도메인 지식","전문 지식","프로젝트 의사 결정","CLI","사용자 입력","도메인 모델","AI도구","프로젝트 관리"],"es":["project-domain","desarrollo basado en especificaciones","conocimiento del dominio","experiencia en materia","lenguaje ubicuo","reglas de dominio","principios de dominio","herramientas de desarrollo","CLI"],"fr":["project-domain","développement basé sur des spécifications","savoir-faire","règles de domaine","langage ubiquitaire","principes de domaine","outils de développement","CLI","méthodologie de développement"],"de":["project-domain","spezifikationsgetriebene Entwicklung","Domänenwissen","Fachexpertise","ubiquitärer Sprachgebrauch","Domänenregeln","Domänenprinzipien","Entwicklungstools","CLI","Entwicklungsmethode"],"pt":["project-domain","desenvolvimento dirigido por especificações","conhecimento de domínio","regras de negócios","CLI","linguagem ubiquitous","princípios de negócios"],"ru":["project-domain","ИИ Агенты","разработка на основе спецификаций","знания предметной области","бизнес-правила","CLI","универсальный язык","бизнес-принципы"],"ar":["مشروع المجال","أدوات الذكاء الاصطناعي","تطوير مدفوع بالمواصفات","خبرة المجال","القواعد التجارية","CLI","لغة شاملة","مبادئ الأعمال"]}},"owner":"telum-ai","repo":"speck","repoPath":"telum-ai/speck","stars":2,"forks":0,"updatedAt":"2026-03-01T14:49:13Z","topics":[],"category":"community","skillMd":{"name":"project-domain","description":"Capture subject matter expertise and domain knowledge that will inform all product decisions - the ubiquitous language, domain rules, and principles from the field","bodyPreview":"---\ndescription: Capture subject matter expertise and domain knowledge that will inform all product decisions - the ubiquitous language, domain rules, and principles from the field.\n---\n\nThe user input to you can be provided directly by the agent or as a command argument - you **MUST** consider it before proceeding with the prompt (if not empty).\n\nUser input:\n\n$ARGUMENTS\n\nCreate or update the domain model that captures subject matter expertise for this project.\n\n## Why Domain Knowledge Matters","body":"---\ndescription: Capture subject matter expertise and domain knowledge that will inform all product decisions - the ubiquitous language, domain rules, and principles from the field.\n---\n\nThe user input to you can be provided directly by the agent or as a command argument - you **MUST** consider it before proceeding with the prompt (if not empty).\n\nUser input:\n\n$ARGUMENTS\n\nCreate or update the domain model that captures subject matter expertise for this project.\n\n## Why Domain Knowledge Matters\n\nMany products operate in specialized domains (fitness, healthcare, finance, education, etc.) where:\n- **Terminology matters**: Using wrong terms confuses users and violates industry norms\n- **Domain rules exist**: Physical, scientific, or regulatory constraints that can''t be ignored\n- **Expertise is required**: Decisions must be informed by domain knowledge, not guesses\n- **User trust depends on accuracy**: Getting domain details wrong destroys credibility\n\nThis command captures that knowledge **early** so it informs all downstream decisions.\n\n## Project Identification\n\nFirst, determine the project:\n- Parse arguments for project identifier\n- If not provided, ask: \"Which project should I create/update domain model for?\"\n- List available projects in `specs/projects/`\n\nSet `PROJECT_DIR` = `specs/projects/[PROJECT_ID]`\n\n## Context Loading\n\nLoad existing project artifacts:\n```\nREQUIRED:\n- {PROJECT_DIR}/project.md → Project vision, domain type, users\n\nOPTIONAL (if exist):\n- {PROJECT_DIR}/domain-model.md → Existing domain model (update mode)\n- {PROJECT_DIR}/project-import.md → Brownfield import notes\n- {PROJECT_DIR}/project-landscape-overview.md → Brownfield code scan\n```\n\n**Detect mode**:\n- If `domain-model.md` exists: **UPDATE mode** - enhance existing model\n- If not: **CREATE mode** - build from scratch\n\n## Just-In-Time Research\n\n**Reference**: Follow the just-in-time research pattern (`.cursor/skills/just-in-time-research/SKILL.md`)\n\n### Research Strategy\n\nFor domain model creation, research is **critical**. Identify knowledge gaps and conduct research:\n\n**1. Domain Terminology**:\n- Decision: What are the canonical terms in [domain]?\n- Web Search: \"[domain] glossary\", \"[domain] terminology standards\"\n- Deep Research (if specialized): Industry-specific ontologies, taxonomies\n\n**2. Domain Principles**:\n- Decision: What scientific/industry principles govern [domain]?\n- Web Search: \"[domain] best practices\", \"[domain] principles\", \"[field] science\"\n- Deep Research (if needed): Academic research, industry standards\n\n**3. Domain Rules & Constraints**:\n- Decision: What rules must always hold true in [domain]?\n- Web Search: \"[domain] safety guidelines\", \"[domain] regulations\"\n- Deep Research (if safety-critical): Regulatory requirements, certification standards\n\n**4. Domain Entities**:\n- Decision: What are the core concepts/entities in [domain]?\n- Web Search: \"[domain] data model\", \"[domain] ontology\"\n- Context7 (if applicable): Domain-specific libraries with established models\n\n### Research Execution\n\nUse available MCP tools in this priority order:\n1. **Perplexity MCP** (preferred): `perplexity_search`, `perplexity_ask`, `perplexity_research`\n2. **Web Search** (fallback): `web_search` tool\n3. **User Input**: Ask user for SME knowledge they have\n\n**Embed all findings** directly into the domain model sections with source citations.\n\n## Interactive Domain Elicitation\n\n### Step 1: Domain Identification\n\nAsk the user:\n\n> \"Let''s capture the domain expertise for your project. I''ll ask you questions to understand the specialized knowledge that should inform this product.\n>\n> **What domain/field does this product operate in?**\n> (e.g., Exercise Science, Healthcare, Financial Services, Education, Agriculture, etc.)\n>\n> **What makes this domain specialized?** Why does someone need expertise to build this correctly?\"\n\nWait for response. Use the domain identification to guide research.\n\n### Step 2: Terminology Elicitation\n\n> \"Now let''s establish the **canonical terminology** for this domain.\n>\n> **What are the most important terms/concepts users and the product must use?**\n> For each term, provide:\n> - The precise definition\n> - Any synonyms we should AVOID (to maintain consistency)\n>\n> I''ll also research standard terminology in [domain] to ensure we''re aligned with industry norms.\"\n\nConduct terminology research and merge with user input.\n\n### Step 3: Core Concepts & Entities\n\n> \"What are the **core concepts or entities** in this domain?\n>\n> Think about:\n> - What ''things'' does the user work with? (e.g., Workouts, Exercises, Muscle Groups)\n> - How do these relate to each other?\n> - What attributes define each concept?\n>\n> I''ll help structure these into a domain model.\"\n\nBuild entity definitions and relationships.\n\n### Step 4: Domain Rules & Invariants\n\n> \"What **rules must always be true** in this domain?\n>\n> Examples:\n> - ''A workout cannot have zero exercises''\n> - ''Rest periods must be positive numbers''\n> - ''A muscle group cannot be trained on consecutive days'' (if that''s a principle you follow)\n>\n> These become validation rules and system invariants.\"\n\n### Step 5: Domain Principles\n\n> \"What **scientific or industry principles** should guide this product?\n>\n> For a fitness app, this might include:\n> - Progressive overload principle\n> - Muscle recovery requirements\n> - Volume-intensity relationship\n>\n> For each principle, I''ll research the evidence base and document how it applies to our product.\"\n\nConduct principle research and document with sources.\n\n### Step 6: Constraints & Safety\n\n> \"What is **impossible, unsafe, or inadvisable** in this domain?\n>\n> - Physical constraints (can''t do negative reps)\n> - Safety constraints (max heart rate limits)\n> - Regulatory constraints (medical advice disclaimers)\n>\n> These become hard boundaries the product must respect.\"\n\n## Domain Model Generation\n\nAfter elicitation and research, generate `{PROJECT_DIR}/domain-model.md` using:\n- Template: `.speck/templates/project/domain-model-template.md`\n- User-provided domain expertise\n- Research findings with citations\n- Structured entity relationships\n\n### Quality Checks\n\nBefore finalizing, verify:\n\n**Completeness**:\n- [ ] All user-provided terms captured in glossary\n- [ ] Core entities have attributes and relationships\n- [ ] Key invariants documented\n- [ ] At least 2-3 foundational principles with sources\n- [ ] Constraints clearly stated\n\n**Consistency**:\n- [ ] Terminology matches project.md and other artifacts\n- [ ] No conflicting rules\n- [ ] Entity relationships are bidirectional\n\n**Actionability**:\n- [ ] Glossary terms can be used in code (valid identifiers)\n- [ ] Rules are specific enough to validate\n- [ ] Principles provide clear guidance\n\n## Output\n\nCreate/update: `{PROJECT_DIR}/domain-model.md`\n\n**Summary to user**:\n```\n✅ Domain model created/updated for [PROJECT_NAME]\n\nCaptured:\n- [X] terms in glossary\n- [X] core entities with relationships\n- [X] domain invariants\n- [X] foundational principles\n- [X] constraints\n\nResearch sources:\n- [List key sources used]\n\nThis domain model will be referenced by:\n- /project-plan (epic structure informed by domain)\n- /epic-specify (feature scope uses domain terms)\n- /story-specify (user stories use glossary)\n- /story-plan (data model validates against domain)\n- /story-validate (checks domain invariants)\n\nNext steps:\n1. Review domain-model.md for accuracy\n2. Add any missing domain expertise\n3. Continue with /project-context or /project-plan\n```\n\n## Integration Notes\n\n**For brownfield projects**:\n- Extract domain terminology from existing codebase (variable names, comments, UI text)\n- Identify implicit domain rules in existing validation logic\n- Document the \"as-is\" domain model before proposing changes\n\n**For recipe-based projects**:\n- Some recipes may have domain considerations (e.g., SaaS billing → subscription domain)\n- Layer product-specific domain on top of recipe patterns\n\n## When to Run This Command\n\n**Recommended position in flow**:\n```\n/project-specify → /project-clarify → /project-domain → /project-context → /project-architecture → /project-plan\n```\n\n**Why here?**\n- After specify/clarify: We know what we''re building\n- Before context: Domain constraints inform technical constraints\n- Before architecture: Domain entities inform data architecture\n- Before plan: Domain structure informs epic organization\n\n**Can skip if**:\n- Product has no specialized domain (generic CRUD app)\n- Domain is purely technical (developer tools)\n- Team already has domain documented elsewhere (link to it)\n"},"lastSynced":"2026-03-06T07:08:41.402Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents requiring informed product decisions through subject matter expertise and domain knowledge capture.","zh":"适用于需要通过主题专业知识和领域知识捕获做出明智产品决策的AI代理。","ja":"インフォームド製品の意思決定を必要とするAIエージェントに適しています。サブジェクトマターの専門知識とドメイン知識のキャプチャを通じて。","ko":"제품 의사 결정을 위한 정보 제공이 필요한 AI 에이전트에게 적합합니다. 주제 전문 지식 및 도메인 지식 캡처를 통해","es":"Perfecto para agentes de IA que requieren decisiones informadas de productos a través de la experiencia en la materia y la captura del conocimiento del dominio.","fr":"Parfait pour les agents IA nécessitant des décisions éclairées de produits grâce à l''expertise dans le domaine et à la capture des connaissances du domaine.","de":"Perfekt für KI-Agents, die fundierte Produktentscheidungen durch Fachwissen und Erfassung von Domänenwissen erfordern.","pt":"Perfeito para Agentes de IA que exigem decisões de produto informadas por meio de especialização em matéria e captura de conhecimento de domínio.","ru":"Идеально для ИИ-агентов, требующих обоснованных решений о продуктах посредством экспертных знаний и захвата знаний домена.","ar":"مثالي للوكلاء الذكاء الاصطناعي الذين يتطلبون قرارات منتج محددة من خلال خبرة الموضوع والتقاط المعرفة المجال."},"recommendation":{"en":"Empowers agents to create and update domain models using user input and command arguments, informing product decisions with ubiquitous language, domain rules, and principles from the field, leveraging command-line interfaces and user-provided arguments.","zh":"赋予代理创建和更新领域模型的能力，使用用户输入和命令行参数，利用无处不在的语言、领域规则和原则，借助命令行接口和用户提供的参数，来告知产品决策。","ja":"ユーザー入力とコマンド引数を使用してドメインモデルを作成および更新する機能をエージェントに与え、普遍的な言語、ドメインルール、分野の原則を利用し、コマンドラインインターフェイスとユーザー提供の引数を利用して製品の意思決定を行う。","ko":"사용자 입력 및 명령 인수와 같은 사용자 제공 정보를 통해 에이전트가 도메인 모델을 생성하고 업데이트하는 기능을 제공하고 영역 규칙 및 원칙과 같은 분야의 언어를 활용하여 제품 의사 결정을 정보화합니다.","es":"Habilita a los agentes a crear y actualizar modelos de dominio utilizando la entrada del usuario y los argumentos de comando, informando las decisiones de producto con lenguaje ubicuo, reglas de dominio y principios del campo, aprovechando las interfaces de línea de comando y los argumentos proporcionados por el usuario.","fr":"Permet aux agents de créer et de mettre à jour des modèles de domaine en utilisant les entrées de l''utilisateur et les arguments de commande, informant les décisions de produit avec un langage ubiquitaire, des règles de domaine et des principes du domaine, en exploitant les interfaces de ligne de commande et les arguments fournis par l''utilisateur.","de":"Ermöglicht es Agents, Domänenmodelle mithilfe der Benutzereingabe und der Befehlsargumente zu erstellen und zu aktualisieren, informiert Produktentscheidungen mit ubiquitärem Sprachgebrauch, Domänenregeln und Prinzipien aus dem Feld, indem es die Kommandozeilen-Schnittstellen und die vom Benutzer bereitgestellten Argumente nutzt.","pt":"Habilita agentes a criar e atualizar modelos de domínio usando entrada do usuário e argumentos de comando, informando decisões de produto com linguagem ubíqua, regras de domínio e princípios do campo, aproveitando interfaces de linha de comando e argumentos fornecidos pelo usuário.","ru":"Позволяет агентам создавать и обновлять модели домена с помощью пользовательского ввода и аргументов командной строки, информируя решения о продуктах с помощью повсеместного языка, правил домена и принципов из области, используя командные интерфейсы и аргументы, предоставленные пользователем.","ar":"يمكن الوكلاء من إنشاء ونماذج مجال التحديث باستخدام مدخلات المستخدم وحجج سطر الأوامر ، وإبلاغ قرارات المنتج بلغة شاملة وقواعد مجال ومبادئ من الحقل ، واستخدام واجهات سطر الأوامر والحجج المقدمة من المستخدم."},"useCases":{"en":["Capturing subject matter expertise for product development","Informing product decisions with domain-specific rules and principles","Creating domain models from user input and command arguments"],"zh":["捕获产品开发的主题专业知识","使用领域特定规则和原则来告知产品决策","从用户输入和命令行参数创建领域模型"],"ja":["製品開発のためのサブジェクトマターの専門知識のキャプチャ","ドメイン固有のルールと原則を使用して製品の意思決定を行う","ユーザー入力とコマンド引数からドメインモデルを作成する"],"ko":["제품 개발을 위한 주제 전문 지식의 캡처","제품 의사 결정을 위한 영역 특정 규칙 및 원칙의 활용","사용자 입력 및 명령 인수로부터 도메인 모델의 생성"],"es":["Capturar la experiencia en la materia para el desarrollo de productos","Informar decisiones de producto con reglas y principios específicos del dominio","Crear modelos de dominio a partir de la entrada del usuario y los argumentos de comando"],"fr":["Capturer l''expertise dans le domaine pour le développement de produits","Informer les décisions de produit avec des règles et des principes spécifiques au domaine","Créer des modèles de domaine à partir des entrées de l''utilisateur et des arguments de commande"],"de":["Erfassung von Fachwissen für die Produktentwicklung","Informieren von Produktentscheidungen mit domänenspezifischen Regeln und Prinzipien","Erstellen von Domänenmodellen aus der Benutzereingabe und den Befehlsargumenten"],"pt":["Captura de especialização em matéria para desenvolvimento de produto","Informar decisões de produto com regras e princípios específicos de domínio","Criação de modelos de domínio a partir da entrada do usuário e argumentos de comando"],"ru":["Захват экспертных знаний для разработки продукта","Информирование решений о продуктах с помощью домен-специфических правил и принципов","Создание моделей домена из пользовательского ввода и аргументов командной строки"],"ar":["التقاط خبرة الموضوع لتطوير المنتج","إبلاغ قرارات المنتج بقواعد ومبادئ محددة للمجال","إنشاء نماذج مجال من مدخلات المستخدم وحجج سطر الأوامر"]},"limitations":{"en":["Requires user input or command arguments","Dependent on quality of user-provided information"],"zh":["需要用户输入或命令行参数","依赖于用户提供的信息质量"],"ja":["ユーザー入力またはコマンド引数が必要","ユーザー提供の情報の品質に依存する"],"ko":["사용자 입력 또는 명령 인수가 필요","사용자 제공 정보의 품질에 의존"],"es":["Requiere entrada del usuario o argumentos de comando","Dependiente de la calidad de la información proporcionada por el usuario"],"fr":["Nécessite une entrée de l''utilisateur ou des arguments de commande","Dépend de la qualité des informations fournies par l''utilisateur"],"de":["Benötigt Benutzereingabe oder Befehlsargumente","Abhängig von der Qualität der vom Benutzer bereitgestellten Informationen"],"pt":["Exige entrada do usuário ou argumentos de comando","Dependente da qualidade das informações fornecidas pelo usuário"],"ru":["Требует пользовательского ввода или аргументов командной строки","Зависит от качества информации, предоставленной пользователем"],"ar":["يتطلب مدخلات المستخدم أو حجج سطر الأوامر","يعتمد على جودة المعلومات المقدمة من المستخدم"]},"version":4},"contentHash":"bc974b4be549479b8cfca6296e661ab6e3e14f94bcd5c9be2ecec85978d724fa","qualityScore":60}');
