INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('telum-ai/speck/project-domain', 'project-domain', 'telum-ai', 'speck', 'community', 'project-domain telum-ai speck community project-domain captures subject matter expertise and domain knowledge to inform product decisions. It creates a domain model using user input and command arguments. 项目域是捕获领域知识和专家意见的方法，用于指导项目决策 プロジェクトドメインは、プロジェクトの意思決定を導くために、ドメイン知識と専門知識を取得する方法です 프로젝트 도메인은 프로젝트 의사 결정에 대한 지침으로서의 도메인 지식 및 전문 지식을 캡처하는 방법 Project-domain es una metodología de desarrollo basada en especificaciones que ayuda a capturar el conocimiento del dominio y la experiencia en materia Project-domain est une méthodologie de développement basée sur des spécifications qui aide à capturer le savoir-faire et les règles de domaine Project-domain ist eine spezifikationsgetriebene Entwicklungsmethode, die dazu dient, das Domänenwissen und die Fachexpertise zu erfassen O project-domain é uma metodologia de desenvolvimento que captura conhecimento de domínio e regras de negócios para informar decisões de produto. Project-domain - это методология разработки, которая захватывает знания предметной области и бизнес-правила для принятия решений о продукте. مشروع المجال هو منهجية تطوير تحقق خبرة المجال والقواعد التجارية لاتخاذ قرارات المنتج. how to use project-domain what is project-domain project-domain alternative project-domain vs spec-driven development project-domain install project-domain setup guide spec-driven development methodology domain model creation capturing subject matter expertise 项目域 领域知识 专家意见 项目决策 CLI 用户输入 领域模型 AI工具 项目管理 Captures subject matter expertise and domain knowledge using user input and command arguments Creates a domain model that informs product decisions Considers command arguments before proceeding with the prompt Supports direct user input or input as a command argument Informs product decisions using the ubiquitous language, domain rules, and principles from the field project-domain is a spec-driven development methodology that captures subject matter expertise and domain knowledge to inform product decisions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ahrav/scratch-scanner-rs/design-tournament', 'community', 'ahrav', 'scratch-scanner-rs', 'ahrav/scratch-scanner-rs', 'design-tournament', 0, 0, 60, '2026-03-07T12:46:33.509Z', '2026-03-07T12:56:24.003Z', '7182d23db75f25c6dd3585d734627c26ee24645d630f6039166c8cb23dd60c11', '{"id":"ahrav/scratch-scanner-rs/design-tournament","name":"design-tournament","description":{"en":"The design-tournament skill enables AI agents to explore design problems independently and merge findings into a confidence-weighted stack ranking. This benefits developers working on complex design decisions, such as new feature development or architectural approaches.","zh":"设计锦标赛是一种两阶段的设计模式，多个独立的AIエージェント探索相同的问题，然后独立的评估者对结果进行评估和合并，形成一个权重置信的栈排名","ja":"デザイントーナメントは、複数の独立したAIエージェントが同じ問題を探索し、独立した評価者が結果を評価し、マージして、信頼性の高いスタックランキングを作成する2段階の設計パターン","ko":"디자인 토너먼트는 여러개의 독립적인 AI 에이전트가 동일한 문제를 탐색한 후, 독립적인 평가자가 결과를 평가하고 병합하여 신뢰할 수 있는 스택 랭킹을 형성하는 2단계 디자인 패턴","es":"El torneo de diseño es un patrón de ''sabiduría de las multitudes'' que permite a múltiples agentes explorar problemas de diseño de forma independiente","fr":"Le tournoi de conception est un modèle de ''sagesse des foules'' qui permet à plusieurs agents d''explorer des problèmes de conception de manière indépendante","de":"Das Design-Turnier ist ein Muster der ''Weisheit der Menge'', das es mehreren Agenten ermöglicht, Probleme des Designs unabhängig zu erkunden","pt":"O Design Tournament é um padrão de ''sabedoria das multidões'' para trabalho de design, onde múltiplos agentes independentes exploram o mesmo problema em isolamento","ru":"Design Tournament - это шаблон ''мудрости толпы'' для дизайнерской работы, где несколько независимых агентов исследуют одну и ту же проблему в изоляции с помощью ИИ Агентов","ar":"تصميم البطولة هو نمط ''حكمة الجماهير'' للعمل التصميمي، حيث يستكشف عدد من الوكلاء المستقلين نفس المشكلة في العزل باستخدام أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"Design-Tournament: Wisdom of Crowds Pattern for AI Agents...","zh":"设计锦标赛 Setup Guide - AIエージェント独立评估与合并","ja":"デザイントーナメントベストプラクティス - AIエージェントによる独立的な評価とマージ","ko":"디자인 토너먼트 구현 가이드 - AI 에이전트를 통한 독립적인 평가 및 병합","es":"Guía de Configuración de Torneos de Diseño con Agentes de...","fr":"Guide de Mise en Place de Tournois de Conception avec Out...","de":"Einrichtungsleitfaden für Design-Turniere mit KI-Agenten","pt":"Guia de Configuração do Design Tournament: Melhores Práti...","ru":"ИИ Агенты: Настройка Design Tournament для Разработчиков","ar":"دليل إعداد تصميم البطولة: إرشادات أفضل للمطورين"},"description":{"en":"Unlock the power of collective intelligence with design-tournament. Learn how to implement this two-phase pattern for design work and improve your AI agent''s...","zh":"了解设计锦标赛的工作原理，如何应用独立评估和合并技术，提高设计决策的准确性","ja":"デザイントーナメントのしくみと、独立した評価とマージ技術の適用方法を学ぶ","ko":"디자인 토너먼트의 작동 원리와 독립적인 평가 및 병합 기술을 적용하여 디자인 결정의 정확도를 높이는 방법","es":"Aprende a utilizar torneos de diseño para mejorar la toma de decisiones en el desarrollo de software con agentes de inteligencia artificial","fr":"Découvrez comment utiliser les tournois de conception pour améliorer la prise de décision dans le développement de logiciels avec des outils d''intelligence a...","de":"Erfahren Sie, wie Sie Design-Turniere nutzen können, um die Entscheidungsfindung in der Softwareentwicklung mit KI-Agenten zu verbessern","pt":"Aprenda a configurar o Design Tournament para melhorar a colaboração e a tomada de decisões em projetos de desenvolvimento de software","ru":"Узнайте, как настроить Design Tournament для улучшения сотрудничества и принятия решений в проектах разработки программного обеспечения с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد تصميم البطولة لتحسين التعاون وصنع القرار في مشاريع تطوير البرمجيات باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"Design-tournament is a two-phase wisdom of crowds pattern for design work, where multiple independent agents explore a problem in isolation, and independent rankers evaluate and merge findings into a ranked list.","zh":"设计锦标赛是一种通过独立的AIエージェント和评估者实现设计决策的方法","ja":"デザイントーナメントは、独立したAIエージェントと評価者を使用して設計決定を下す手法","ko":"디자인 토너먼트는 독립적인 AI 에이전트와 평가자를 사용하여 디자인 결정하는 방법","es":"Un torneo de diseño es un enfoque de toma de decisiones que combina exploración independiente y evaluación para alcanzar un ranking ponderado","fr":"Un tournoi de conception est une approche de prise de décision qui combine exploration indépendante et évaluation pour atteindre un classement pondéré","de":"Ein Design-Turnier ist ein Entscheidungsansatz, der unabhängige Exploration und Bewertung kombiniert, um ein gewichteten Ranking zu erreichen","pt":"O que é Design Tournament? Um padrão de design que combina a sabedoria das multidões com a avaliação independente","ru":"Что такое Design Tournament? Шаблон дизайна, который сочетает мудрость толпы с независимой оценкой с помощью ИИ Агентов","ar":"ما هو تصميم البطولة? نمط تصميم يجمع بين حكمة الجماهير والتقييم المستقل باستخدام أدوات الذكاء الاصطناعي"},"features":{"en":["Exploring multiple valid architectural approaches in isolation","Merging findings into a confidence-weighted stack ranking","Supporting story/task breakdown with independent perspectives","Enabling design decisions with reduced bias through independent agents","Allowing for the evaluation of multiple design solutions simultaneously","Facilitating the identification of the most confident design solution"],"zh":["两阶段设计模式","多个独立的AIエージェント","独立的评估者","权重置信的栈排名","适用于新特性设计、数据结构设计、算法设计和API设计"],"ja":["2段階の設計パターン","複数の独立したAIエージェント","独立した評価者","信頼性の高いスタックランキング","新機能設計、データ構造設計、アルゴリズム設計、API設計に適する"],"ko":["2단계 디자인 패턴","독립적인 AI 에이전트 여러개","독립적인 평가자","신뢰할 수 있는 스택 랭킹","새로운 기능 설계, 데이터 구조 설계, 알고리즘 설계, API 설계에 적합"],"es":["Exploración independiente de problemas de diseño","Evaluación y fusión de hallazgos en un ranking ponderado","Aplicable a la diseño de características, estructuras de datos, algoritmos y API","Útil para la descomposición de historias y tareas","Mejora la toma de decisiones en el desarrollo de software"],"fr":["Exploration indépendante de problèmes de conception","Évaluation et fusion de résultats en un classement pondéré","Applicable à la conception de fonctionnalités, structures de données, algorithmes et API","Utile pour la décomposition d''histoires et de tâches","Améliore la prise de décision dans le développement de logiciels"],"de":["Unabhängige Erkundung von Designproblemen","Bewertung und Fusion von Ergebnissen in einem gewichteten Ranking","Anwendbar auf die Gestaltung von Funktionen, Datenstrukturen, Algorithmen und API","Nützlich für die Zerlegung von Geschichten und Aufgaben","Verbessert die Entscheidungsfindung in der Softwareentwicklung"],"pt":["Exploração independente de problemas de design","Avaliação e merge de resultados com pesos de confiança","Aplicação em projetos de desenvolvimento de software","Suporte à decomposição de tarefas e histórias","Integração com múltiplas abordagens arquiteturais"],"ru":["Независимое исследование проблем дизайна","Оценка и слияние результатов с весами доверия с помощью ИИ Агентов","Применение в проектах разработки программного обеспечения","Поддержка разбиения задач и историй","Интеграция с несколькими архитектурными подходами"],"ar":["استكشاف مستقل للمشاكل التصميمية","التقييم والدمج النتائج بأوزان الثقة باستخدام أدوات الذكاء الاصطناعي","التطبيق في مشاريع تطوير البرمجيات","دعم تقسيم المهام والقصص","التكامل مع عدة مناهج معمارية"]},"keywords":{"en":["how to use design-tournament","design-tournament alternative","design-tournament setup guide","what is design-tournament","design-tournament vs crowdsourcing","design-tournament install for AI agents","wisdom of crowds pattern for design work","design-tournament for complex design decisions","independent agent design patterns","confidence-weighted stack ranking"],"zh":["设计锦标赛","AIエージェント","独立评估","合并技术","设计决策","新特性设计","数据结构设计","算法设计","API设计"],"ja":["デザイントーナメント","AIエージェント","独立した評価","マージ技術","設計決定","新機能設計","データ構造設計","アルゴリズム設計","API設計"],"ko":["디자인 토너먼트","AI 에이전트","독립적인 평가","병합 기술","디자인 결정","새로운 기능 설계","데이터 구조 설계","알고리즘 설계","API 설계"],"es":["torneos de diseño","agentes de inteligencia artificial","desarrollo de software","diseño de características","estructuras de datos","algoritmos","API","toma de decisiones"],"fr":["tournois de conception","outils d''intelligence artificielle","développement de logiciels","conception de fonctionnalités","structures de données","algorithmes","API","prise de décision"],"de":["Design-Turniere","KI-Agenten","Softwareentwicklung","Gestaltung von Funktionen","Datenstrukturen","Algorithmen","API","Entscheidungsfindung"],"pt":["design tournament","desenvolvimento de software","colaboração em design","tomada de decisões em design","padrões de design","sabedoria das multidões","avaliação independente"],"ru":["design tournament","разработка программного обеспечения","сотрудничество в дизайне","принятие решений в дизайне","шаблоны дизайна","мудрость толпы","независимая оценка","ИИ Агенты"],"ar":["تصميم البطولة","تطوير البرمجيات","التعاون في التصميم","صنع القرار في التصميم","أنماط التصميم","حكمة الجماهير","التقييم المستقل","أدوات الذكاء الاصطناعي"]}},"owner":"ahrav","repo":"scratch-scanner-rs","repoPath":"ahrav/scratch-scanner-rs","stars":0,"forks":0,"updatedAt":"2026-03-07T12:46:33.509Z","topics":[],"category":"community","skillMd":{"name":"design-tournament","description":"Run a parallel diverge-then-converge design tournament — 3-5 independent agents explore a problem, then 2 ranking agents evaluate and stack-rank the results with confidence scores","bodyPreview":"# Design Tournament\n\nA two-phase \"wisdom of crowds\" pattern for design work. Multiple independent\nagents explore the same problem in isolation, then independent rankers evaluate\nand merge the findings into a confidence-weighted stack ranking.\n\n## When to Use\n\n- Designing a new feature, data structure, algorithm, or API\n- Exploring multiple valid architectural approaches\n- Story/task breakdown where the \"right\" decomposition isn''t obvious\n- Any design decision where independent perspectives reduc","body":"# Design Tournament\n\nA two-phase \"wisdom of crowds\" pattern for design work. Multiple independent\nagents explore the same problem in isolation, then independent rankers evaluate\nand merge the findings into a confidence-weighted stack ranking.\n\n## When to Use\n\n- Designing a new feature, data structure, algorithm, or API\n- Exploring multiple valid architectural approaches\n- Story/task breakdown where the \"right\" decomposition isn''t obvious\n- Any design decision where independent perspectives reduce blind spots\n\n## Invocation\n\n```\ndesign-tournament <problem statement>\n```\n\nThe `<problem statement>` is the full description of what needs to be designed.\nIf no argument is given, ask the user for the problem statement before\nproceeding.\n\n## Phase 1 — Diverge (Parallel Exploration)\n\nLaunch **5 independent agents in parallel** using the Codex agent tools (`spawn_agent`, `send_input`, `wait`) with\n`agent_type=default`. Every agent receives **identical instructions**\nso that their outputs are independently generated with zero cross-contamination.\n\n**All 5 agents MUST be launched in a single message** (one message, five `spawn_agent` calls) so they run concurrently.\n\n### Agent Prompt Template (identical for all 5)\n\nEach agent receives this prompt, with `{PROBLEM}` replaced by the user''s\nproblem statement and `{AGENT_ID}` set to a unique label (Alpha, Beta, Gamma,\nDelta, Epsilon):\n\n```\nYou are Design Agent {AGENT_ID} in an independent design tournament.\n\n## Problem\n{PROBLEM}\n\n## Your Task\n\nProduce a COMPLETE, standalone design proposal. You are working independently —\ndo not assume anyone else''s output exists.\n\n### Required Sections\n\n1. **Problem Restatement** — Restate the problem in your own words to confirm\n   understanding. Call out any ambiguities or assumptions you are making.\n\n2. **Design Proposal** — Your recommended design. Include:\n   - Core idea / approach (1-2 sentence summary)\n   - Detailed description with concrete types, signatures, or pseudocode\n   - Key invariants or contracts the design enforces\n   - How the design handles edge cases and failure modes\n\n3. **Alternatives Considered** — At least 2 alternative approaches you\n   evaluated and why you rejected them.\n\n4. **Trade-offs** — Explicit trade-off analysis:\n   - What does this design optimize for?\n   - What does it sacrifice?\n   - Under what conditions would a different design be better?\n\n5. **Risks & Open Questions** — What could go wrong? What remains uncertain?\n\n6. **Self-Assessment** — Rate your own confidence (0-100) in this design and\n   explain why.\n\n### Rules\n\n- Be specific and concrete — pseudocode or type signatures over hand-waving.\n- Do NOT hedge with \"it depends\" — commit to a design and defend it.\n- Explore the codebase if you need context (use `rg --files`, `rg`, and targeted file reads).\n- Aim for depth over breadth. One well-defended design beats three sketches.\n\n### Output Format\n\nReturn your response as a single markdown document with the sections above.\nStart with: `# Design Proposal — Agent {AGENT_ID}`\n```\n\n### Collecting Results\n\nAfter all 5 agents complete, gather their outputs. If any agent fails or times\nout, proceed with the agents that succeeded (minimum 3 required).\n\n## Phase 2 — Converge (Parallel Ranking)\n\nLaunch **2 independent ranking agents in parallel** using the Codex agent tools (`spawn_agent`, `send_input`, `wait`) with\n`agent_type=default`. Both receive **identical instructions** and\nthe collected Phase 1 outputs.\n\n**Both rankers MUST be launched in a single message** (one message, two `spawn_agent` calls) so they run concurrently.\n\n### Ranker Prompt Template (identical for both)\n\n```\nYou are Ranking Judge {JUDGE_ID} in a design tournament.\n\n## Original Problem\n{PROBLEM}\n\n## Design Proposals\n\nBelow are {N} independently generated design proposals for the same problem.\nEvaluate them WITHOUT knowing which agent produced each one (they are labeled\nAlpha through Epsilon for reference only).\n\n{PROPOSALS}\n\n## Your Task\n\n### 1. Evaluation Criteria\n\nScore each proposal on these dimensions (1-10 scale):\n\n| Criterion | Weight | Description |\n|-----------|--------|-------------|\n| **Correctness** | 25% | Does the design actually solve the problem? Are invariants sound? |\n| **Simplicity** | 20% | Is this the simplest design that could work? Minimal moving parts? |\n| **Robustness** | 20% | How well does it handle edge cases, failures, and adversarial inputs? |\n| **Extensibility** | 15% | Can the design accommodate likely future requirements without rework? |\n| **Specificity** | 10% | How concrete and implementable is the proposal? |\n| **Trade-off Awareness** | 10% | Does the author understand what they''re sacrificing? |\n\n### 2. Per-Proposal Evaluation\n\nFor EACH proposal, provide:\n- Scores on each criterion\n- Weighted total score\n- Top strength (1 sentence)\n- Top weakness (1 sentence)\n- Key insight unique to this proposal (if any)\n\n### 3. Stack Ranking\n\nProduce a final ranking from best to worst. For each position:\n- Rank position (1 = best)\n- Agent label\n- Weighted total score\n- Confidence in this ranking position (0-100):\n  - 90-100: Clear winner/loser, large score gap\n  - 70-89: Solid ranking, meaningful score gap\n  - 50-69: Close call, could reasonably swap with adjacent rank\n  - Below 50: Essentially tied, ranking is arbitrary\n\n### 4. Synthesis Recommendation\n\nAfter ranking, provide:\n- **Recommended design**: Which proposal to use as the starting point\n- **Cherry-pick list**: Specific ideas from OTHER proposals that should be\n  incorporated into the winner\n- **Composite confidence** (0-100): Your overall confidence that the #1\n  ranked proposal (with cherry-picks) is the right design\n\n### Rules\n\n- Judge designs on MERIT, not on writing quality or verbosity.\n- If two designs are substantively identical, say so — don''t force a\n  false distinction.\n- Be willing to rank a simple, correct design above an elaborate one.\n- Explore the codebase if you need context to evaluate feasibility.\n\n### Output Format\n\nReturn your response as a single markdown document.\nStart with: `# Ranking Report — Judge {JUDGE_ID}`\n```\n\n### Merging Rankings\n\nAfter both rankers complete, merge their results:\n\n1. **For each proposal**, average the weighted scores from both judges.\n2. **For each rank position**, compute:\n   - Average score\n   - Agreement: did both judges assign the same rank? (yes/no)\n   - Combined confidence: average of both judges'' per-position confidence,\n     reduced by 15 points if they disagree on rank position\n3. **Final stack ranking** by averaged weighted score (descending).\n4. **Synthesize cherry-pick lists** from both judges into a unified list.\n\n## Final Output Format\n\nPresent the merged result to the user as:\n\n```markdown\n## Design Tournament Results\n\n### Problem\n{one-line restatement}\n\n### Stack Ranking\n\n| Rank | Agent | Avg Score | Judge Agreement | Confidence | Key Strength |\n|------|-------|-----------|-----------------|------------|--------------|\n| 1    | ...   | 8.2/10    | Yes             | 92%        | ...          |\n| 2    | ...   | 7.5/10    | Yes             | 78%        | ...          |\n| 3    | ...   | 6.8/10    | No (J1:#2,J2:#4)| 54%       | ...          |\n| ...  | ...   | ...       | ...             | ...        | ...          |\n\n### Recommended Design\n\n**Base**: Agent {winner}''s proposal\n**Cherry-picks from other proposals**:\n- From Agent X: {specific idea}\n- From Agent Y: {specific idea}\n\n**Composite Confidence**: {average of both judges'' composite}%\n\n### Winning Proposal Summary\n{2-3 paragraph summary of the #1 design with cherry-picks integrated}\n\n### Full Proposals (collapsed)\n<details><summary>Agent Alpha — Score: X.X</summary>\n{full proposal text}\n</details>\n{repeat for each agent}\n\n### Ranking Details (collapsed)\n<details><summary>Judge 1 Report</summary>\n{full ranking report}\n</details>\n<details><summary>Judge 2 Report</summary>\n{full ranking report}\n</details>\n```\n\n## Configuration\n\nThe default is 5 explorers + 2 rankers (7 total agents). If the user specifies\na different count (e.g., `design-tournament 3 agents: ...`), respect it but\nenforce these minimums:\n- Phase 1: at least 3 explorer agents\n- Phase 2: always exactly 2 ranking agents\n\n## Tips\n\n- For large or ambiguous problems, include relevant file paths or context in\n  the problem statement so explorer agents can read the codebase.\n- If the problem involves existing code, tell agents which files to examine.\n- The skill works for any design task: features, data structures, algorithms,\n  API shapes, system architecture, task decomposition, migration plans.\n"},"lastSynced":"2026-03-07T12:56:24.003Z","agentAnalysis":{"suitability":{"en":"Ideal for Collaborative AI Agents seeking to leverage the wisdom of crowds for complex design decisions and feature development.","zh":"适合于寻求利用众包智慧来解决复杂设计决策和功能开发的协作AI代理。","ja":"複雑な設計決定と機能開発のためのクラウドの知恵を利用したいコラボレーションAIエージェントに最適です。","ko":"복잡한 설계 결정과 기능 개발을 위한 클라우드 지혜를 활용하고자 하는 협업 AI 에이전트에 적합합니다.","es":"Ideal para Agentes de IA Colaborativos que buscan aprovechar la sabiduría de las multitudes para tomar decisiones de diseño complejas y desarrollar funciones.","fr":"Idéal pour les Agents d''IA Collaboratifs cherchant à exploiter la sagesse des foules pour les décisions de conception complexes et le développement de fonctionnalités.","de":"Ideal für kollaborative KI-Agents, die die Weisheit der Massen für komplexe Designentscheidungen und Funktionsentwicklung nutzen möchten.","pt":"Ideal para Agentes de IA Colaborativos que buscam aproveitar a sabedoria das multidões para decisões de design complexas e desenvolvimento de recursos.","ru":"Идеально для Коллаборативных ИИ Агентов, стремящихся использовать мудрость толпы для сложных решений по проектированию и разработке функций.","ar":"مثالي لعميل الذكاء الاصطناعي التعاوني الذين يسعون إلى استخدام حكمة الحشود لاتخاذ قرارات تصميم معقدة وتطوير الميزات."},"recommendation":{"en":"Empowers agents to independently explore design problems, merging findings into a confidence-weighted stack ranking, utilizing a two-phase wisdom of crowds pattern for enhanced decision-making, especially in architectural approaches and task breakdowns.","zh":"使代理能够独立探索设计问题，将发现结果合并到一个置信度加权的栈排名中，使用两阶段的众包模式来增强决策，尤其是在架构方法和任务分解中。","ja":"エージェントが設計問題を独立して探索し、発見結果を信頼度重み付きのスタックランキングにマージすることを可能にし、特にアーキテクチャアプローチとタスク分解において、意思決定を強化するための2相のクラウドの知恵パターンを使用します。","ko":"에이전트가 디자인 문제를 독립적으로 탐색하고 발견 결과를 신뢰도 가중 스택 순위에 병합할 수 있도록 하며, 특히 아키텍처 접근 방식과 태스크 분할에서 의사 결정 강화에 대한 2단계 클라우드 지혜 패턴을 사용합니다.","es":"Habilita a los agentes a explorar de forma independiente los problemas de diseño, fusionando los hallazgos en una clasificación ponderada por confianza, utilizando un patrón de sabiduría de las multitudes de dos fases para una toma de decisiones mejorada, especialmente en enfoques arquitectónicos y desglose de tareas.","fr":"Permet aux agents d''explorer de manière indépendante les problèmes de conception, en fusionnant les résultats dans un classement pondéré par confiance, en utilisant un modèle de sagesse des foules à deux phases pour une prise de décision améliorée, en particulier dans les approches architecturales et le décomposition des tâches.","de":"Ermächtigt Agents, Designprobleme unabhängig zu erkunden, Erkenntnisse in eine gewichtete Stacksortierung zu fusionieren, unter Verwendung eines zweiphasigen Musters der Weisheit der Massen für eine verbesserte Entscheidungsfindung, insbesondere in architektonischen Ansätzen und Aufgabenzerlegungen.","pt":"Permite que os agentes explorem independentemente problemas de design, mesclando as descobertas em uma classificação ponderada por confiança, utilizando um padrão de duas fases de sabedoria das multidões para uma tomada de decisão aprimorada, especialmente em abordagens arquiteturais e quebras de tarefas.","ru":"Наделяет агентов возможностью независимо исследовать проблемы проектирования, объединяя результаты в ранжирование со взвешенной уверенностью, используя двухфазный шаблон мудрости толпы для улучшения процесса принятия решений, особенно в архитектурных подходах и разбиении задач.","ar":"تمكن الوكيل من استكشاف مشاكل التصميم بشكل مستقل ، ودمج النتائج في ترتيب ذي وزن ثقة ، باستخدام نمط حكمة الحشود من مرحلتين لتحسين اتخاذ القرارات ، لا سيما في المناهج المعمارية و كسر المهام."},"useCases":{"en":["Exploring multiple valid architectural approaches for new feature development","Evaluating and merging independent design solutions for complex problems","Facilitating story/task breakdowns where the right decomposition isn''t obvious"],"zh":["探索新的功能开发的多种有效的架构方法","评估和合并独立的设计解决方案以解决复杂问题","促进故事/任务分解，在明显不需要分解的情况下"],"ja":["新しい機能開発のための複数の有効なアーキテクチャアプローチを探索する","複雑な問題を解決するための独立した設計ソリューションの評価とマージ","明確に分解する必要がない場合のストーリー/タスク分解の促進"],"ko":["新的 기능 개발을 위한 여러 가지 유효한 아키텍처 접근 방식을 탐색합니다.","복잡한 문제를 해결하기 위한 독립적인 디자인 솔루션의 평가 및 병합","명확하게 분할할 필요가 없는 경우의 스토리/태스크 분할을 촉진합니다."],"es":["Explorar múltiples enfoques arquitectónicos válidos para el desarrollo de nuevas funciones","Evaluar y fusionar soluciones de diseño independientes para problemas complejos","Facilitar la descomposición de historias/tareas donde la descomposición correcta no es obvia"],"fr":["Explorer plusieurs approches architecturales valides pour le développement de nouvelles fonctionnalités","Évaluer et fusionner des solutions de conception indépendantes pour des problèmes complexes","Faciliter la décomposition d''histoires/tâches où la décomposition correcte n''est pas évidente"],"de":["Erkunden mehrerer gültiger architektonischer Ansätze für die Entwicklung neuer Funktionen","Unabhängige Designlösungen für komplexe Probleme bewerten und fusionieren","Erleichtern der Aufgabenzerlegung, wo die richtige Zerlegung nicht offensichtlich ist"],"pt":["Explorar várias abordagens arquiteturais válidas para o desenvolvimento de novos recursos","Avaliar e mesclar soluções de design independentes para problemas complexos","Facilitar a quebra de histórias / tarefas onde a decomposição correta não é óbvia"],"ru":["Изучать несколько действительных архитектурных подходов для разработки новых функций","Оценивать и объединять независимые решения по проектированию для сложных проблем","Облегчить разбиение историй/задач, когда правильное разбиение не очевидно"],"ar":["استكشاف مناهج معمارية صالحة متعددة لتطوير ميزات جديدة","تقييم ودمج حلول تصميم مستقلة لمشاكل معقدة","تسهيل تقسيم القصص / المهام حيث لا تكون التحليل الصحيح واضح"]},"limitations":{"en":["Requires multiple independent agents for crowdsourced design evaluation","Dependent on the quality and diversity of agent perspectives"],"zh":["需要多个独立的代理来评估众包设计","依赖于代理的质量和多样性"],"ja":["クラウドソース設計評価のために複数の独立したエージェントが必要","エージェントの質と多様性に依存する"],"ko":["클라우드소스 디자인 평가를 위해 여러 개의 독립적인 에이전트가 필요합니다.","에이전트의 품질과 다양성에 의존합니다."],"es":["Requiere múltiples agentes independientes para la evaluación de diseño en crowdsourcing","Depende de la calidad y diversidad de las perspectivas de los agentes"],"fr":["Nécessite plusieurs agents indépendants pour l''évaluation de conception en crowdsourcing","Dépend de la qualité et de la diversité des perspectives des agents"],"de":["Benötigt mehrere unabhängige Agents für die Designbewertung im Crowdsourcing","Hängt von der Qualität und Vielfalt der Agentenperspektiven ab"],"pt":["Exige vários agentes independentes para avaliação de design baseada em multidões","Dependente da qualidade e diversidade das perspectivas dos agentes"],"ru":["Требует нескольких независимых агентов для оценки проектирования на основе толпы","Зависит от качества и разнообразия перспектив агентов"],"ar":["يتطلب وكلاء مستقلة متعددة لتقييم التصميم المستند إلى الحشود","يعتمد على جودة وتنوع آراء الوكيل"]},"version":4},"contentHash":"7182d23db75f25c6dd3585d734627c26ee24645d630f6039166c8cb23dd60c11","qualityScore":60}');
