INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pnils08/GodWorld/write-edition', 'write-edition', 'pnils08', 'GodWorld', 'community', 'write-edition pnils08 GodWorld community The write-edition skill runs the complete Cycle Pulse edition production pipeline, launching 6 desk agents in parallel and compiling the final edition. It benefits developers working with AI agents and world simulation technologies. write-edition 是一个全周期生产管道，用于生成完整的エディション。它可以运行 6 个桌面代理，并编译最终的エディション write-edition はサイクルパルスエディションを生成するフルエディション生産パイプラインです。6 つのデスクエージェントを並行して実行し、最終的なエディションをコンパイルします write-edition은 완전한 에디션을 생성하는 전체 생산 파이프라인입니다. 6개의 데스크 에이전트를 병렬로 실행하고 최종 에디션을 컴파일합니다 write-edition es un pipeline de producción completo para simular mundos con Agentes de IA. Lanza 6 agentes de escritorio en paralelo y compila ediciones. write-edition est un pipeline de production complet pour simuler des mondes avec des Outils d''IA. Il lance 6 agents de bureau en parallèle et compile des éditions. write-edition ist eine vollständige Produktionspipeline, um Welten mit KI-Agenten zu simulieren. Es startet 6 Schreibtischanwendungen parallel und kompiliert Editionen. O write-edition é uma pipeline de edição completa que lança 6 agentes de mesa em paralelo e compila a edição final com aprovação do usuário write-edition — это полная производственная цепочка, которая запускает 6 столовых агентов параллельно и компилирует окончательную редакцию с одобрением пользователя write-edition هو خط إنتاج نسخة كامل يطلق 6 وكلاء المكتب بالتوازي ويدمج النسخة النهائية بموافقة المستخدم how to use write-edition write-edition alternative write-edition setup guide what is write-edition write-edition vs world simulation write-edition install cycle pulse edition production pipeline ai agent development with write-edition write-edition tutorial write-edition documentation write-edition AIエージェント 全周期生产管道 エディション生成 CLI命令 SESSION_CONTEXT.md 桌面代理 并行执行 编译エディション Runs the complete Cycle Pulse edition production pipeline using the `/write-edition [cycle-number]` command Launches 6 desk agents in parallel for efficient processing Compiles the final edition after agent execution Requires reading SESSION_CONTEXT.md for proper setup Shows a plan to the user before launching agents and gets approval before compiling Orchestrates all 6 desk skills for a streamlined workflow write-edition is a full edition production pipeline skill that orchestrates 6 desk agents and compiles the final edition, used in world simulation and AI agent development.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('friisj/jfriis/generate-boundary-objects', 'community', 'friisj', 'jfriis', 'friisj/jfriis', 'generate-boundary-objects', 1, 0, 60, '2026-02-24T15:51:24Z', '2026-03-06T07:12:26.452Z', '03d61334b4fbea2bf1fa917f73ae0bb3a6997d1bf240b677b2e2d19bbc98de2e', '{"id":"friisj/jfriis/generate-boundary-objects","name":"generate-boundary-objects","description":{"en":"The generate-boundary-objects skill creates strategic context for targeted experiment generation in studio projects. It benefits developers and researchers by providing a structured approach to portfolio, research studies, and prototypes.","zh":"生成边界对象技能创建战略边界对象，实现目标实验生成，使用JSONB块格式和特定结构","ja":"境界オブジェクトの生成スキルは、戦略的境界オブジェクトを作成し、目標の実験生成を実現します。JSONBブロック形式と特定の構造を使用します","ko":"경계 객체 생성 스킬은 전략적 경계 객체를 생성하여 목표 실험 생성을 달성합니다. JSONB 블록 형식 및 특정 구조를 사용합니다","es":"Generar objetos de límite estratégicos para proyectos de estudio. Crear contexto para la generación de experimentos dirigidos.","fr":"Générer des objets de limite stratégiques pour les projets de studio. Créer un contexte pour la génération d''expériences ciblées.","de":"Generieren von strategischen Grenzobjekten für Studio-Projekte. Erstellen von Kontext für die Generierung von gezielten Experimenten.","pt":"O generate-boundary-objects cria objetos estratégicos de fronteira para projetos de estúdio, permitindo a geração de experimentos direcionados.","ru":"Generate-boundary-objects создает стратегические объекты границы для студийных проектов, позволяя генерировать целевые эксперименты.","ar":"يخلق generate-boundary-objects كائنات حدودية استراتيجية لمشاريع الاستوديو، مما يسمح بالتجارب المستهدفة."},"seo":{"title":{"en":"generate-boundary-objects: Studio Project Setup Guide | A...","zh":"生成边界对象：AI工具设置指南","ja":"境界オブジェクトの生成：AIエージェントベストプラクティス","ko":"경계 객체 생성: AI 도구 설정 가이드","es":"Generar objetos de límite: Guía de configuración para pro...","fr":"Générer des objets de limite: Meilleures pratiques pour l...","de":"Generieren von Grenzobjekten: Einrichtungsanleitung für S...","pt":"Guia de Configuração do generate-boundary-objects para De...","ru":"Руководство по настройке generate-boundary-objects для ра...","ar":"دليل إعداد generate-boundary-objects لأصحاب المشاريع"},"description":{"en":"Discover how to generate strategic boundary objects for your studio project. Learn to create targeted experiment generation contexts with our AI agent skill.","zh":"了解如何使用生成边界对象技能创建战略边界对象，实现目标实验生成","ja":"境界オブジェクトの生成スキルを使用して戦略的境界オブジェクトを作成し、目標の実験生成を実現する方法について学びます","ko":"경계 객체 생성 스킬을 사용하여 전략적 경계 객체를 생성하고 목표 실험 생성을 달성하는 방법에 대해 알아보세요","es":"Aprende a generar objetos de límite estratégicos para proyectos de estudio con nuestra guía de configuración. Herramientas de AI Agent para desarrolladores","fr":"Découvrez comment générer des objets de limite stratégiques pour les projets de studio avec notre guide de configuration. Outils d''agent IA pour les développ...","de":"Erfahren Sie, wie Sie strategische Grenzobjekte für Studio-Projekte mit unserer Einrichtungsanleitung generieren. AI-Tool-Entwicklung","pt":"Aprenda a configurar o generate-boundary-objects para criar objetos estratégicos de fronteira para projetos de estúdio","ru":"Узнайте, как настроить generate-boundary-objects для создания стратегических объектов границы для студийных проектов","ar":"تعرف على كيفية إعداد generate-boundary-objects لإنشاء كائنات حدودية استراتيجية لمشاريع الاستوديو"},"definition":{"en":"generate-boundary-objects is a skill that generates strategic boundary objects for studio projects, creating a context for targeted experiment generation using JSONB block format.","zh":"生成边界对象是指创建战略边界对象的技能，用于实现目标实验生成","ja":"境界オブジェクトの生成は、戦略的境界オブジェクトを作成するスキルであり、目標の実験生成を実現するために使用されます","ko":"경계 객체 생성은 전략적 경계 객체를 생성하는 스킬로 목표 실험 생성을 달성하는 데 사용됩니다","es":"Un objeto de límite es un objeto que define el contexto estratégico para la generación de experimentos en un proyecto de estudio.","fr":"Un objet de limite est un objet qui définit le contexte stratégique pour la génération d''expériences dans un projet de studio.","de":"Ein Grenzobjekt ist ein Objekt, das den strategischen Kontext für die Generierung von Experimenten in einem Studio-Projekt definiert.","pt":"O generate-boundary-objects é uma ferramenta que cria objetos estratégicos de fronteira para projetos de estúdio.","ru":"Generate-boundary-objects - это инструмент, создающий стратегические объекты границы для студийных проектов.","ar":"generate-boundary-objects هو أداة لإنشاء كائنات حدودية استراتيجية لمشاريع الاستوديو."},"features":{"en":["Generates strategic boundary objects for studio projects","Uses JSONB block format for canvas data structure","Supports studio project slugs as input arguments","Creates targeted experiment generation contexts","Utilizes a structured approach to portfolio, research studies, and prototypes","Processes data in a specific format with items and id properties"],"zh":["使用JSONB块格式","特定结构的项目创建","支持studio项目slug输入","创建战略边界对象","实现目标实验生成","使用特定结构的canvas JSONB块列"],"ja":["JSONBブロック形式を使用","特定構造のプロジェクトを作成","スタジオプロジェクトスラッグ入力のサポート","戦略的境界オブジェクトの作成","目標の実験生成の実現","特定構造のキャンバスJSONBブロック列を使用"],"ko":["JSONB 블록 형식을 사용","특정 구조의 프로젝트 생성","스튜디오 프로젝트 슬러그 입력 지원","전략적 경계 객체 생성","목표 실험 생성 달성","특정 구조의 캔버스 JSONB 블록 열 사용"],"es":["Generación de objetos de límite estratégicos","Creación de contexto para la generación de experimentos","Compatibilidad con formato JSONB","Soporte para columnas de jobs, pains, gains, products_services, etc.","Integración con proyectos de estudio"],"fr":["Génération d''objets de limite stratégiques","Création de contexte pour la génération d''expériences","Compatibilité avec le format JSONB","Prise en charge des colonnes jobs, pains, gains, products_services, etc.","Intégration avec les projets de studio"],"de":["Generierung von strategischen Grenzobjekten","Erstellung von Kontext für die Generierung von Experimenten","Unterstützung für JSONB-Format","Unterstützung für Spalten jobs, pains, gains, products_services, etc.","Integration mit Studio-Projekten"],"pt":["Criação de objetos estratégicos de fronteira para projetos de estúdio","Geração de experimentos direcionados","Suporte a formato JSONB","Integração com colunas de canvas"],"ru":["Создание стратегических объектов границы для студийных проектов","Генерация целевых экспериментов","Поддержка формата JSONB","Интеграция с колонками канваса"],"ar":["إنشاء كائنات حدودية استراتيجية لمشاريع الاستوديو","التجارب المستهدفة","دعم تنسيق JSONB","التكامل مع أعمدة الخريطة"]},"keywords":{"en":["how to use generate-boundary-objects","generate-boundary-objects alternative","generate-boundary-objects setup guide","what is generate-boundary-objects","generate-boundary-objects vs competitor skills","generate-boundary-objects install for studio projects","studio project boundary object generation","targeted experiment generation with generate-boundary-objects","JSONB block format for boundary objects"],"zh":["生成边界对象","AI工具","JSONB块格式","studio项目","战略边界对象","目标实验生成","AI开发","边界对象创建","实验生成工具"],"ja":["境界オブジェクトの生成","AIエージェント","JSONBブロック形式","スタジオプロジェクト","戦略的境界オブジェクト","目標の実験生成","AI開発","境界オブジェクトの作成","実験生成ツール"],"ko":["경계 객체 생성","AI 도구","JSONB 블록 형식","스튜디오 프로젝트","전략적 경계 객체","목표 실험 생성","AI 개발","경계 객체 생성","실험 생성 도구"],"es":["generar objetos de límite","proyectos de estudio","generación de experimentos","formato JSONB","desarrollo de AI Agent","herramientas de AI para desarrolladores","generación de contexto estratégico"],"fr":["générer des objets de limite","projets de studio","génération d''expériences","format JSONB","développement d''agent IA","outils d''IA pour les développeurs","génération de contexte stratégique"],"de":["Generieren von Grenzobjekten","Studio-Projekte","Generierung von Experimenten","JSONB-Format","Entwicklung von AI-Tools","AI-Entwicklung für Entwickler","Erstellung von strategischem Kontext"],"pt":["generate-boundary-objects","objetos estratégicos de fronteira","projetos de estúdio","experimentos direcionados","JSONB","canvas","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["generate-boundary-objects","стратегические объекты границы","студийные проекты","целевые эксперименты","JSONB","канвас","разработка программного обеспечения","инструменты разработки"],"ar":["generate-boundary-objects","كائنات حدودية استراتيجية","مشاريع الاستوديو","التجارب المستهدفة","JSONB","خريطة","تطوير البرمجيات","أدوات التطوير"]}},"owner":"friisj","repo":"jfriis","repoPath":"friisj/jfriis","stars":1,"forks":0,"updatedAt":"2026-02-24T15:51:24Z","topics":[],"category":"community","skillMd":{"name":"generate-boundary-objects","description":"Generate boundary objects (BMC, VPC, customer profile, assumptions) from a studio project and link them via entity_links. Use after /studio-project-setup.","bodyPreview":"# Generate Boundary Objects\n\nYou are generating strategic boundary objects for a studio project. This creates the strategic context needed for targeted experiment generation.\n\n## Input\n\nThe user has provided: `$ARGUMENTS`\n\nThis should be a studio project slug (e.g., `chalk`, `putt`).\n\n---\n\n## JSONB Block Format\n\nAll canvas JSONB block columns (jobs, pains, gains, products_services, pain_relievers, gain_creators, key_partners, etc.) use this structure:\n\n```json\n{\n  \"items\": [\n    {\n      \"id\": \"<","body":"# Generate Boundary Objects\n\nYou are generating strategic boundary objects for a studio project. This creates the strategic context needed for targeted experiment generation.\n\n## Input\n\nThe user has provided: `$ARGUMENTS`\n\nThis should be a studio project slug (e.g., `chalk`, `putt`).\n\n---\n\n## JSONB Block Format\n\nAll canvas JSONB block columns (jobs, pains, gains, products_services, pain_relievers, gain_creators, key_partners, etc.) use this structure:\n\n```json\n{\n  \"items\": [\n    {\n      \"id\": \"<unique-id>\",\n      \"content\": \"<item text>\",\n      \"priority\": \"high|medium|low\",\n      \"created_at\": \"<ISO 8601 timestamp>\"\n    }\n  ],\n  \"assumptions\": [],\n  \"validation_status\": \"untested\"\n}\n```\n\nFor customer profile items, also include `metadata`:\n```json\n{\n  \"id\": \"<unique-id>\",\n  \"content\": \"<item text>\",\n  \"metadata\": { \"type\": \"functional|social|emotional\" },\n  \"priority\": \"high|medium|low\",\n  \"created_at\": \"<ISO 8601 timestamp>\"\n}\n```\n\nGenerate unique IDs using a prefix + sequence pattern (e.g., `job-001`, `pain-001`, `ps-001`). Use `new Date().toISOString()` for timestamps.\n\n**CRITICAL**: Do NOT store plain string arrays. The admin UI canvas views will not render them.\n\n---\n\n## Required Fields by Table\n\n> **Schema source of truth:** `lib/mcp/schemas/*.ts`\n> If any field documentation here conflicts with the Zod schemas, the schemas are correct.\n> Last synced: 2026-02-21\n\n### `business_model_canvases`\nRequired: `slug`, `name`, `status`\nOptional: `description`, `studio_project_id`, all 9 block columns (JSONB format above)\n\n### `customer_profiles`\nRequired: `slug`, `name`, `status`\nOptional: `description`, `studio_project_id`, `profile_type`, `demographics` (JSONB object), `jobs` (JSONB), `pains` (JSONB), `gains` (JSONB)\n\n### `value_maps`\nRequired: `slug`, `name`, `status`\nOptional: `description`, `studio_project_id`, `customer_profile_id`, `business_model_canvas_id`, `products_services` (JSONB), `pain_relievers` (JSONB), `gain_creators` (JSONB)\n\n### `value_proposition_canvases`\nRequired: `slug`, `name`, `status`, `value_map_id`\nOptional: `description`, `studio_project_id`, `customer_profile_id`, `addressed_jobs`, `addressed_pains`, `addressed_gains`\n\n### `assumptions`\nRequired: `slug`, `statement`, `status` (use `identified`), `importance` (`critical`|`high`|`medium`|`low`)\nOptional: `studio_project_id`, `category`, `notes`, `validation_criteria`\nNote: `is_leap_of_faith` is computed by DB trigger — do not provide\n\n### `user_journeys`\nRequired: `slug`, `name`, `status`\nOptional: `description`, `studio_project_id`, `customer_profile_id`, `journey_type` (use `end_to_end`), `goal`\n\n### `journey_stages`\nRequired: `user_journey_id`, `name`, `sequence`\nOptional: `description`, `stage_type` (pre_purchase|purchase|post_purchase|ongoing), `customer_emotion`, `customer_mindset`, `customer_goal`, `drop_off_risk` (low|medium|high)\n\n### `touchpoints`\nRequired: `journey_stage_id`, `name`, `sequence`\nOptional: `description`, `channel_type` (web|mobile_app|phone|email|in_person|chat|social|physical_location|mail|other), `interaction_type` (browse|search|read|watch|listen|form|transaction|conversation|notification|passive), `importance` (critical|high|medium|low), `pain_level` (none|minor|moderate|major|critical), `delight_potential` (low|medium|high)\n\n### `service_blueprints`\nRequired: `slug`, `name`, `status`\nOptional: `description`, `studio_project_id`, `blueprint_type` (service|product|hybrid|digital|physical), `service_scope`, `service_duration`\n\n### `blueprint_steps`\nRequired: `service_blueprint_id`, `name`, `sequence`\nOptional: `description`, `layers` (JSONB with keys: customer_action, frontstage, backstage, support_process), `cost_implication` (none|low|medium|high), `customer_value_delivery` (none|low|medium|high), `failure_risk` (low|medium|high|critical), `failure_impact`\n\n### `story_maps`\nRequired: `slug`, `name`, `status`\nOptional: `description`, `studio_project_id`, `map_type` (feature|product|release|discovery)\n\n### `activities`\nRequired: `story_map_id`, `name`, `sequence`\nOptional: `description`, `user_goal`\n\n### `user_stories`\nRequired: `activity_id`, `title`\nOptional: `description`, `acceptance_criteria`, `story_type` (feature|enhancement|bug|tech_debt|spike), `priority` (critical|high|medium|low), `status` (default: backlog), `story_points`\n\n### `entity_links`\nRequired: `source_type`, `source_id`, `target_type`, `target_id`\nOptional: `link_type` (default: ''related''), `strength` (strong|moderate|weak|tentative), `notes`, `metadata`, `position`\n\n---\n\n## Procedure\n\n### Step 1: Validate Project\n\n```bash\nscripts/sb query studio_projects \"slug=eq.<slug>\"\n```\n\nIf not found, abort with: \"No studio project found with slug ''<slug>''. Check `studio_projects` table.\"\n\nSave the project `id`, `name`, `description`, `problem_statement`, `hypothesis`, `success_criteria`, `current_focus`, `scope_out`.\n\n### Step 2: Check Existing Links\n\nQuery entity_links for existing outbound links from this project:\n\n```bash\nscripts/sb query entity_links \"source_type=eq.studio_project&source_id=eq.<project-id>\"\n```\n\nShow what''s already linked. **Skip types that already have links** to keep this idempotent. Report which types are being skipped and why.\n\n### Step 3: Read Project Context\n\nAlso query `studio_hypotheses` for this project:\n\n```bash\nscripts/sb query studio_hypotheses \"project_id=eq.<project-id>\"\n```\n\nGather all available context: name, description, problem_statement, hypothesis, success_criteria, current_focus, scope_out, plus hypothesis statements.\n\n### Step 4: Generate Business Model Canvas\n\n**Skip if** an entity_link to `business_model_canvas` already exists.\n\nCreate a `business_model_canvases` record. Populate ALL 9 blocks with initial items derived from project context:\n\n```bash\nscripts/sb create business_model_canvases ''{\n  \"slug\": \"<project-slug>-business-model\",\n  \"name\": \"<Project Name> - Business Model\",\n  \"description\": \"<1-2 sentences grounded in project context>\",\n  \"studio_project_id\": \"<project-id>\",\n  \"status\": \"draft\",\n  \"key_partners\": {\"items\": [{\"id\": \"kp-001\", \"content\": \"<partner>\", \"priority\": \"high\", \"created_at\": \"<now>\"}], \"assumptions\": [], \"validation_status\": \"untested\"},\n  \"key_activities\": {\"items\": [...], \"assumptions\": [], \"validation_status\": \"untested\"},\n  \"key_resources\": {\"items\": [...], \"assumptions\": [], \"validation_status\": \"untested\"},\n  \"value_propositions\": {\"items\": [...], \"assumptions\": [], \"validation_status\": \"untested\"},\n  \"customer_segments\": {\"items\": [...], \"assumptions\": [], \"validation_status\": \"untested\"},\n  \"customer_relationships\": {\"items\": [...], \"assumptions\": [], \"validation_status\": \"untested\"},\n  \"channels\": {\"items\": [...], \"assumptions\": [], \"validation_status\": \"untested\"},\n  \"cost_structure\": {\"items\": [...], \"assumptions\": [], \"validation_status\": \"untested\"},\n  \"revenue_streams\": {\"items\": [...], \"assumptions\": [], \"validation_status\": \"untested\"}\n}''\n```\n\nGenerate 2-4 items per block, grounded in the project''s problem statement and description. Then create the entity_link:\n\n```bash\nscripts/sb create entity_links ''{\n  \"source_type\": \"studio_project\",\n  \"source_id\": \"<project-id>\",\n  \"target_type\": \"business_model_canvas\",\n  \"target_id\": \"<bmc-id>\",\n  \"link_type\": \"explores\",\n  \"metadata\": {}\n}''\n```\n\n### Step 5: Generate Customer Profile\n\n**Skip if** an entity_link to `customer_profile` already exists.\n\nCreate a `customer_profiles` record. Use the JSONB block format for jobs, pains, and gains:\n\n```bash\nscripts/sb create customer_profiles ''{\n  \"slug\": \"<project-slug>-primary-customer\",\n  \"name\": \"<Project Name> - Primary Customer\",\n  \"description\": \"<2-3 sentences describing the target customer>\",\n  \"studio_project_id\": \"<project-id>\",\n  \"profile_type\": \"persona\",\n  \"demographics\": {\"age_range\": \"<Age range>\", \"role\": \"<Role>\", \"tech_level\": \"<level>\", \"income\": \"<range>\"},\n  \"jobs\": {\"items\": [...], \"assumptions\": [], \"validation_status\": \"untested\"},\n  \"pains\": {\"items\": [...], \"assumptions\": [], \"validation_status\": \"untested\"},\n  \"gains\": {\"items\": [...], \"assumptions\": [], \"validation_status\": \"untested\"},\n  \"status\": \"draft\"\n}''\n```\n\nGenerate 3-5 items per block. Link with `explores`.\n\n### Step 6: Generate Value Map + Value Proposition Canvas\n\n**Skip if** an entity_link to `value_proposition_canvas` already exists.\n\nThe VPC requires a `value_map_id`, so create the value map first:\n\n```bash\nscripts/sb create value_maps ''{\n  \"slug\": \"<project-slug>-value-map\",\n  \"name\": \"<Project Name> - Value Map\",\n  \"description\": \"<1-2 sentences>\",\n  \"studio_project_id\": \"<project-id>\",\n  \"customer_profile_id\": \"<profile-id>\",\n  \"business_model_canvas_id\": \"<bmc-id>\",\n  \"products_services\": {\"items\": [...], \"assumptions\": [], \"validation_status\": \"untested\"},\n  \"pain_relievers\": {\"items\": [...], \"assumptions\": [], \"validation_status\": \"untested\"},\n  \"gain_creators\": {\"items\": [...], \"assumptions\": [], \"validation_status\": \"untested\"},\n  \"status\": \"draft\"\n}''\n```\n\nThen create the VPC linked to the value map:\n\n```bash\nscripts/sb create value_proposition_canvases ''{\n  \"slug\": \"<project-slug>-value-proposition\",\n  \"name\": \"<Project Name> - Value Proposition\",\n  \"description\": \"<Value prop description>\",\n  \"studio_project_id\": \"<project-id>\",\n  \"customer_profile_id\": \"<profile-id>\",\n  \"value_map_id\": \"<value-map-id>\",\n  \"addressed_jobs\": {\"items\": [\"<job content>\", \"<job content>\"]},\n  \"addressed_pains\": {\"items\": [\"<pain content>\", \"<pain content>\"]},\n  \"addressed_gains\": {\"items\": [\"<gain content>\", \"<gain content>\"]},\n  \"status\": \"draft\"\n}''\n```\n\nLink the VPC with `explores`.\n\n### Step 7: Generate Assumptions\n\n**Skip if** entity_links to `assumption` already exist (3+ links).\n\nCreate 3-5 `assumptions` records. Distribute across risk categories (desirability, viability, feasibility, usability). **Bulk insert as an array:**\n\n```bash\nscripts/sb create assumptions ''[\n  {\n    \"slug\": \"<project-slug>-<short-name>\",\n    \"statement\": \"We assume that <specific belief>\",\n    \"status\": \"identified\",\n    \"importance\": \"critical\",\n    \"category\": \"desirability\",\n    \"studio_project_id\": \"<project-id>\",\n    \"notes\": \"<Why this matters>\"\n  },\n  { ... },\n  { ... }\n]''\n```\n\nThen bulk-create entity_links for all assumptions:\n\n```bash\nscripts/sb create entity_links ''[\n  {\"source_type\": \"studio_project\", \"source_id\": \"<project-id>\", \"target_type\": \"assumption\", \"target_id\": \"<id-1>\", \"link_type\": \"tests\", \"metadata\": {}},\n  {\"source_type\": \"studio_project\", \"source_id\": \"<project-id>\", \"target_type\": \"assumption\", \"target_id\": \"<id-2>\", \"link_type\": \"tests\", \"metadata\": {}},\n  ...\n]''\n```\n\n### Step 8: Generate User Journey + Stages + Touchpoints\n\n**Skip if** an entity_link to `user_journey` already exists.\n\nCreate the full journey cascade — journey record, stages, and touchpoints:\n\n**8a. Create the journey:**\n\n```bash\nscripts/sb create user_journeys ''{\n  \"slug\": \"<project-slug>-core-journey\",\n  \"name\": \"<Project Name> - Core Journey\",\n  \"description\": \"<Journey description grounded in project context>\",\n  \"studio_project_id\": \"<project-id>\",\n  \"customer_profile_id\": \"<profile-id>\",\n  \"journey_type\": \"end_to_end\",\n  \"goal\": \"<What success looks like for this journey>\",\n  \"status\": \"draft\"\n}''\n```\n\n**8b. Bulk-create 4-5 journey stages:**\n\n```bash\nscripts/sb create journey_stages ''[\n  {\"user_journey_id\": \"<journey-id>\", \"name\": \"Discovery\", \"description\": \"...\", \"sequence\": 1, \"stage_type\": \"pre_purchase\", \"customer_emotion\": \"...\", \"customer_mindset\": \"...\", \"customer_goal\": \"...\", \"drop_off_risk\": \"medium\"},\n  {\"user_journey_id\": \"<journey-id>\", \"name\": \"Evaluation\", \"description\": \"...\", \"sequence\": 2, \"stage_type\": \"pre_purchase\", ...},\n  {\"user_journey_id\": \"<journey-id>\", \"name\": \"Commitment\", \"description\": \"...\", \"sequence\": 3, \"stage_type\": \"purchase\", ...},\n  {\"user_journey_id\": \"<journey-id>\", \"name\": \"Onboarding\", \"description\": \"...\", \"sequence\": 4, \"stage_type\": \"post_purchase\", ...},\n  {\"user_journey_id\": \"<journey-id>\", \"name\": \"Ongoing Usage\", \"description\": \"...\", \"sequence\": 5, \"stage_type\": \"ongoing\", ...}\n]''\n```\n\nAdapt stage names to match the project domain.\n\n**8c. Bulk-create touchpoints per stage (2-3 per stage):**\n\n```bash\nscripts/sb create touchpoints ''[\n  {\"journey_stage_id\": \"<stage-1-id>\", \"name\": \"...\", \"sequence\": 1, \"channel_type\": \"web\", \"interaction_type\": \"browse\", \"importance\": \"high\", \"pain_level\": \"minor\", \"delight_potential\": \"medium\"},\n  {\"journey_stage_id\": \"<stage-1-id>\", \"name\": \"...\", \"sequence\": 2, ...},\n  {\"journey_stage_id\": \"<stage-2-id>\", \"name\": \"...\", \"sequence\": 1, ...},\n  ...\n]''\n```\n\n**8d. Create entity_link:**\n\n```bash\nscripts/sb create entity_links ''{\n  \"source_type\": \"studio_project\",\n  \"source_id\": \"<project-id>\",\n  \"target_type\": \"user_journey\",\n  \"target_id\": \"<journey-id>\",\n  \"link_type\": \"explores\",\n  \"metadata\": {}\n}''\n```\n\n### Step 9: Generate Service Blueprint + Steps\n\n**Skip if** an entity_link to `service_blueprint` already exists.\n\nThe service blueprint mirrors the journey stages, mapping what happens behind the scenes.\n\n**9a. Create the blueprint:**\n\n```bash\nscripts/sb create service_blueprints ''{\n  \"slug\": \"<project-slug>-service-blueprint\",\n  \"name\": \"<Project Name> - Service Blueprint\",\n  \"description\": \"<How the service is delivered>\",\n  \"studio_project_id\": \"<project-id>\",\n  \"blueprint_type\": \"digital\",\n  \"status\": \"draft\"\n}''\n```\n\n**9b. Bulk-create blueprint_steps (one per journey stage):**\n\n```bash\nscripts/sb create blueprint_steps ''[\n  {\"service_blueprint_id\": \"<blueprint-id>\", \"name\": \"Discovery\", \"description\": \"...\", \"sequence\": 1, \"layers\": {\"customer_action\": \"...\", \"frontstage\": \"...\", \"backstage\": \"...\", \"support_process\": \"...\"}, \"cost_implication\": \"low\", \"customer_value_delivery\": \"medium\", \"failure_risk\": \"low\"},\n  {\"service_blueprint_id\": \"<blueprint-id>\", \"name\": \"Evaluation\", ...},\n  ...\n]''\n```\n\nPopulate all 4 layer keys with project-specific content derived from the journey stages and project context.\n\n**9c. Create entity_links:**\n\n```bash\nscripts/sb create entity_links ''[\n  {\"source_type\": \"studio_project\", \"source_id\": \"<project-id>\", \"target_type\": \"service_blueprint\", \"target_id\": \"<blueprint-id>\", \"link_type\": \"prototypes\", \"metadata\": {}},\n  {\"source_type\": \"service_blueprint\", \"source_id\": \"<blueprint-id>\", \"target_type\": \"user_journey\", \"target_id\": \"<journey-id>\", \"link_type\": \"implements\", \"metadata\": {}}\n]''\n```\n\n### Step 10: Generate Story Map + Activities + Stories\n\n**Skip if** an entity_link to `story_map` already exists.\n\nThe story map translates the journey into development work.\n\n**10a. Create the story map:**\n\n```bash\nscripts/sb create story_maps ''{\n  \"slug\": \"<project-slug>-story-map\",\n  \"name\": \"<Project Name> - Story Map\",\n  \"description\": \"<Dev planning for the project>\",\n  \"studio_project_id\": \"<project-id>\",\n  \"map_type\": \"feature\",\n  \"status\": \"draft\"\n}''\n```\n\n**10b. Bulk-create activities (one per journey stage):**\n\n```bash\nscripts/sb create activities ''[\n  {\"story_map_id\": \"<story-map-id>\", \"name\": \"Discovery\", \"description\": \"...\", \"sequence\": 1, \"user_goal\": \"...\"},\n  {\"story_map_id\": \"<story-map-id>\", \"name\": \"Evaluation\", \"description\": \"...\", \"sequence\": 2, \"user_goal\": \"...\"},\n  ...\n]''\n```\n\n**10c. Bulk-create user stories (2-3 per activity):**\n\n```bash\nscripts/sb create user_stories ''[\n  {\"activity_id\": \"<activity-1-id>\", \"title\": \"As a <persona>, I want to <action> so that <benefit>\", \"description\": \"...\", \"story_type\": \"feature\", \"priority\": \"high\", \"status\": \"backlog\"},\n  {\"activity_id\": \"<activity-1-id>\", \"title\": \"As a ...\", ...},\n  {\"activity_id\": \"<activity-2-id>\", \"title\": \"As a ...\", ...},\n  ...\n]''\n```\n\nUse the user story format: \"As a [persona], I want to [action] so that [benefit]\". Ground stories in the customer profile and journey touchpoints.\n\n**10d. Create entity_links:**\n\n```bash\nscripts/sb create entity_links ''[\n  {\"source_type\": \"studio_project\", \"source_id\": \"<project-id>\", \"target_type\": \"story_map\", \"target_id\": \"<story-map-id>\", \"link_type\": \"informs\", \"metadata\": {}},\n  {\"source_type\": \"story_map\", \"source_id\": \"<story-map-id>\", \"target_type\": \"user_journey\", \"target_id\": \"<journey-id>\", \"link_type\": \"implements\", \"metadata\": {}},\n  {\"source_type\": \"story_map\", \"source_id\": \"<story-map-id>\", \"target_type\": \"service_blueprint\", \"target_id\": \"<blueprint-id>\", \"link_type\": \"implements\", \"metadata\": {}}\n]''\n```\n\n### Step 11: Summary\n\nPresent a summary of everything created:\n\n```\n## Boundary Objects Generated for <Name>\n\n### Created:\n- Business Model Canvas: \"<name>\" (id: <id>) — 9 blocks populated\n- Customer Profile: \"<name>\" (id: <id>) — jobs/pains/gains populated\n- Value Map: \"<name>\" (id: <id>) — products/relievers/creators populated\n- Value Proposition Canvas: \"<name>\" (id: <id>)\n- Assumptions: <count> created\n  - <statement summary> (<category>, <importance>)\n  - ...\n- User Journey: \"<name>\" (id: <id>) — <N> stages, <M> touchpoints\n- Service Blueprint: \"<name>\" (id: <id>) — <N> steps with 4-layer structure\n- Story Map: \"<name>\" (id: <id>) — <N> activities, <M> user stories\n\n### Cascade:\nJourney → Blueprint → Story Map (all cross-linked via entity_links)\n\n### Skipped (already linked):\n- <list any types that were skipped>\n\n### Next Steps:\n1. Review boundary objects in admin UI\n2. Run `/generate-experiments <slug>` to create context-aware experiments\n3. Refine BMC blocks and canvas items as understanding deepens\n```\n\n---\n\n## Error Handling\n\n### API Failures\n\nIf any `scripts/sb` call fails:\n\n1. **Report the error**: Show the exact error message and which step failed\n2. **Don''t continue blindly**: If a dependency fails (e.g., BMC creation fails), skip steps that depend on it (e.g., don''t create entity_link for BMC)\n3. **Partial success is OK**: If 3 of 5 assumptions succeed, report what worked and what didn''t\n4. **Common errors**:\n   - `duplicate key value violates unique constraint` — a record with that slug already exists. Suggest a different slug or offer to link the existing record instead.\n   - `violates check constraint` — a field value is invalid. Check the \"Required Fields by Table\" section for valid enum values.\n   - `violates foreign key constraint` — a referenced record doesn''t exist. Verify the ID is correct.\n\n### Reporting\n\nAfter completion, always present a clear summary showing:\n- What was created successfully (with IDs)\n- What was skipped (already existed)\n- What failed (with error details and suggested fixes)\n\n---\n\n## Important Notes\n\n- **Idempotent**: Always check existing links before creating. Never duplicate boundary objects.\n- **Use scripts/sb**: All database operations go through `scripts/sb` commands via the Bash tool.\n- **Bulk inserts**: Use array JSON for journey_stages, touchpoints, blueprint_steps, activities, user_stories, assumptions, and entity_links. This is one of the key wins — a single POST instead of N sequential calls.\n- **Draft status**: All generated objects start as `draft` — they need human review.\n- **JSONB block format**: All canvas block columns MUST use `{ items: [...], assumptions: [], validation_status: \"untested\" }` format. Plain arrays will not render in the admin UI.\n- **Context-grounded**: Every generated object should be grounded in the project''s actual problem_statement, hypothesis, and description. Don''t generate generic content.\n- **Entity link validation**: The `studio_project` source type is registered in `lib/entity-links-validation.ts` with valid link types: `explores`, `improves`, `prototypes`, `informs`, `tests`, `validates`, `spin_off`, `inspired_by`, `evolved_from`.\n- **Required fields**: Every table requires `slug`. Assumptions use `status: ''identified''` (not `untested`). User journeys use `journey_type: ''end_to_end''`. VPCs require `value_map_id`.\n"},"lastSynced":"2026-03-06T07:12:26.452Z","agentAnalysis":{"suitability":{"en":"Ideal for Studio Project Agents requiring structured approaches to portfolio and research study generation, utilizing JSONB block formats.","zh":"适用于需要结构化方法来生成项目组合和研究学习的Studio Project Agents，利用JSONB块格式。","ja":"スタジオプロジェクトエージェントがプロジェクトポートフォリオと研究スタディの生成に構造化アプローチを必要とする場合に最適です。JSONBブロック形式を利用します。","ko":"스튜디오 프로젝트 에이전트가 프로젝트 포트폴리오 및 연구 연구 생성을 위한 구조화된 접근 방식을 필요로 할 경우에 적합합니다. JSONB 블록 형식을 사용합니다.","es":"Ideal para Agentes de Proyecto de Estudio que requieren enfoques estructurados para la generación de carteras y estudios de investigación, utilizando formatos de bloques JSONB.","fr":"Idéal pour les agents de projet de studio nécessitant des approches structurées pour la génération de portefeuilles et d''études de recherche, en utilisant des formats de blocs JSONB.","de":"Ideal für Studio-Projekt-Agenten, die strukturierte Ansätze für die Erstellung von Portfolios und Forschungsstudien benötigen, unter Verwendung von JSONB-Blockformaten.","pt":"Ideal para Agentes de Projeto de Estúdio que requerem abordagens estruturadas para geração de portfólio e estudo de pesquisa, utilizando formatos de bloco JSONB.","ru":"Идеально для агентов студийных проектов, требующих структурированных подходов к генерации портфеля и исследовательских изучений, использующих форматы блоков JSONB.","ar":"مثالي لعميل مشروع الاستوديو الذي يتطلب نهجًا منظمًا لإنشاء محفظة ودراسة بحثية، باستخدام تنسيقات بلوك JSONB."},"recommendation":{"en":"Empowers agents to create strategic context for targeted experiment generation in studio projects, leveraging JSON data structures and studio project slugs, while providing a structured approach to canvas JSONB block columns such as jobs, pains, and gains.","zh":"赋予代理人在利用JSON数据结构和工作室项目别名的同时，创建工作室项目有针对性的实验生成的战略背景的能力，并为jobs、pains和gains等画布JSONB块列提供结构化的方法。","ja":"エージェントがスタジオプロジェクトのターゲット実験生成の戦略的コンテキストを作成できるようにし、JSONデータ構造やスタジオプロジェクトのスラッグを活用しながら、ジョブ、ペイン、ゲインなどのキャンバスJSONBブロック列に対する構造化アプローチを提供します。","ko":"에이전트가 스튜디오 프로젝트의 타겟 실험 생성을 위한 전략적 컨텍스트를 생성할 수 있도록 하며, JSON 데이터 구조 및 스튜디오 프로젝트 슬러그를 활용하면서, 작업, 고통, 이익 등의 캔버스 JSONB 블록 열에 대한 구조화된 접근 방식을 제공합니다.","es":"Habilita a los agentes a crear un contexto estratégico para la generación de experimentos dirigidos en proyectos de estudio, aprovechando estructuras de datos JSON y slug de proyectos de estudio, al mismo tiempo que proporciona un enfoque estructurado para columnas de bloques JSONB como trabajos, dolores y ganancias.","fr":"Permet aux agents de créer un contexte stratégique pour la génération d''expériences ciblées dans les projets de studio, en exploitant les structures de données JSON et les slug de projets de studio, tout en fournissant une approche structurée pour les colonnes de blocs JSONB telles que les emplois, les douleurs et les gains.","de":"Ermächtigt Agenten, einen strategischen Kontext für die gezielte Erstellung von Experimenten in Studio-Projekten zu erstellen, indem JSON-Datensätze und Studio-Projekt-Slug genutzt werden, während ein strukturierter Ansatz für JSONB-Blockspalten wie Jobs, Schmerzen und Gewinne bereitgestellt wird.","pt":"Habilita os agentes a criar um contexto estratégico para geração de experimentos direcionados em projetos de estúdio, aproveitando estruturas de dados JSON e slugs de projeto de estúdio, enquanto fornece uma abordagem estruturada para colunas de blocos JSONB, como trabalhos, dores e ganhos.","ru":"Наделяет агентов возможностью создавать стратегический контекст для генерации целевых экспериментов в студийных проектах, используя структуры данных JSON и слаги студийных проектов, а также обеспечивая структурированный подход к столбцам блоков JSONB, таким как работы, боли и выгоды.","ar":"تمكّن الوكلاء من إنشاء سياق استراتيجي لإنشاء تجارب موجهة في مشاريع الاستوديو، مستفيدًا من هياكل البيانات JSON واسماء مشاريع الاستوديو، في حين يوفر نهجًا منظمًا إلى أعمدة بلوكات JSONB مثل الوظائف والألم والمنافع."},"useCases":{"en":["Generating strategic boundary objects for studio projects","Creating structured approaches to portfolio and research studies","Utilizing JSONB block formats for data organization"],"zh":["为工作室项目生成战略边界对象","创建项目组合和研究学习的结构化方法","利用JSONB块格式进行数据组织"],"ja":["スタジオプロジェクトの戦略的境界オブジェクトを生成する","プロジェクトポートフォリオと研究スタディに構造化アプローチを創出する","JSONBブロック形式をデータ組織に利用する"],"ko":["스튜디오 프로젝트를 위한 전략적 경계 객체 생성","프로젝트 포트폴리오 및 연구 연구를 위한 구조화된 접근 방식 생성","데이터 조직을 위한 JSONB 블록 형식 활용"],"es":["Generación de objetos límite estratégicos para proyectos de estudio","Creación de enfoques estructurados para carteras y estudios de investigación","Utilización de formatos de bloques JSONB para la organización de datos"],"fr":["Génération d''objets limite stratégiques pour les projets de studio","Création d''approches structurées pour les portefeuilles et les études de recherche","Utilisation de formats de blocs JSONB pour l''organisation des données"],"de":["Erstellung strategischer Grenzobjekte für Studio-Projekte","Erstellung strukturierter Ansätze für Portfolios und Forschungsstudien","Verwendung von JSONB-Blockformaten für die Datenorganisation"],"pt":["Geração de objetos de limite estratégico para projetos de estúdio","Criação de abordagens estruturadas para portfólio e estudos de pesquisa","Utilização de formatos de bloco JSONB para organização de dados"],"ru":["Генерация стратегических граничных объектов для студийных проектов","Создание структурированных подходов к портфелю и исследовательским изучениям","Использование форматов блоков JSONB для организации данных"],"ar":["إنشاء كائنات حدود استراتيجية لمشاريع الاستوديو","إنشاء نهج منظم لمحفظة ودراسات بحثية","استخدام تنسيقات بلوكات JSONB لتنظيم البيانات"]},"limitations":{"en":["Requires studio project slug as input","Specific to studio project context","JSONB block format compliance necessary"],"zh":["需要工作室项目别名作为输入","特定于工作室项目上下文","JSONB块格式合规性必要"],"ja":["スタジオプロジェクトスラッグを入力として必要とする","スタジオプロジェクトコンテキストに特有の","JSONBブロック形式の準拠が必要"],"ko":["스튜디오 프로젝트 슬러그를 입력으로 필요로 함","스튜디오 프로젝트 컨텍스트에 특정","JSONB 블록 형식의 준수 필요"],"es":["Requiere slug de proyecto de estudio como entrada","Específico para el contexto del proyecto de estudio","Se requiere cumplimiento con el formato de bloques JSONB"],"fr":["Nécessite un slug de projet de studio comme entrée","Spécifique au contexte du projet de studio","Le respect du format de blocs JSONB est nécessaire"],"de":["Benötigt Studio-Projekt-Slug als Eingabe","Spezifisch für den Kontext des Studio-Projekts","Einhaltung des JSONB-Blockformats ist erforderlich"],"pt":["Exige slug de projeto de estúdio como entrada","Específico para contexto de projeto de estúdio","Conformidade com formato de bloco JSONB necessária"],"ru":["Требует слага студийного проекта в качестве входных данных","Конкретно для контекста студийного проекта","Необходимо соблюдение формата блока JSONB"],"ar":["يتطلب سلاج مشروع الاستوديو كمدخل","محدد لسياق مشروع الاستوديو","الامتثال لتنسيق بلوك JSONB ضروري"]},"version":4},"contentHash":"03d61334b4fbea2bf1fa917f73ae0bb3a6997d1bf240b677b2e2d19bbc98de2e","qualityScore":60}');
