INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Kbediako/codex-termux-pocket/babysit-pr', 'babysit-pr', 'Kbediako', 'codex-termux-pocket', 'community', 'babysit-pr Kbediako codex-termux-pocket community android cli codex codex-cli openai termux The babysit-pr skill automates PR management for AI agents, persistently monitoring until merge or closure. It benefits developers by handling CI, review comments, and potential merge conflicts. babysit-pr是一个用于Codex CLI的Android/Termux自动更新和构建的工具，帮助开发者提高效率 babysit-prは、Codex CLIのAndroid/Termux自動更新とビルドを支援するツールで、開発者の効率を向上させる babysit-pr는 Codex CLI의 안드로이드/Termux 자동 업데이트 및 빌드를 지원하는 도구로 개발자의 효율을 높여준다 babysit-pr es una herramienta para automatizar tareas de PR en Android/Termux. Permite la autoactualización y la compilación de versiones con Codex CLI. babysit-pr est un outil pour automatiser les tâches de PR sur Android/Termux. Il permet la mise à jour automatique et la compilation de versions avec Codex CLI. babysit-pr ist ein Tool zur Automatisierung von PR-Aufgaben auf Android/Termux. Es ermöglicht die Selbstaktualisierung und die Kompilierung von Versionen mit Codex CLI. O babysit-pr é uma ferramenta que automatiza a manutenção de solicitações de pull em projetos Android/Termux com Codex CLI. babysit-pr - это инструмент, автоматизирующий поддержку запросов на слияние в проектах Android/Termux с помощью Codex CLI и ИИ Агентов. babysit-pr هو أداة ت自动 صيانة طلبات السحب في مشاريع الأنْدرويد/टर्मكس مع Codex CLI وأدوات الذكاء الاصطناعي. how to use babysit-pr babysit-pr setup guide Codex CLI tweaks for Android Termux PR management automated PR workflow babysit-pr vs manual PR management babysit-pr install for AI agents resolving merge conflicts with babysit-pr babysit-pr alternative for CI management babysit-pr Codex CLI Android/Termux 自动更新 构建支持 AIエージェント 自动化测试 代码review merge conflict Monitors PRs for successful CI and absence of unaddressed review comments Detects potential merge conflicts and reports conflict risk Supports self-update and build version management via Codex CLI Integrates with Termux for Android-based development environments Automates PR management until merge, closure, or user intervention is required Handles repeated flaky failures and exhausted retry budgets babysit-pr is a Codex CLI tweak for Android/Termux that automates PR management, ensuring efficient and conflict-free merges.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('gustavo-ferreira03/my-career-toolbox/humanize-academic-writing', 'community', 'gustavo-ferreira03', 'my-career-toolbox', 'gustavo-ferreira03/my-career-toolbox', 'humanize-academic-writing', 1, 0, 60, '2026-02-25T01:29:58Z', '2026-03-06T07:14:59.057Z', '60d66b9f157175db9672952cd6d47df6b6a6c77379daa64496a2cc1b6821f18b', '{"id":"gustavo-ferreira03/my-career-toolbox/humanize-academic-writing","name":"humanize-academic-writing","description":{"en":"The humanize-academic-writing skill helps researchers refine AI-assisted writing, ensuring original ideas are naturally expressed. It benefits non-native English speakers and those seeking better academic writing patterns.","zh":"humanize-academic-writing AI工具帮助研究人员提高学术写作质量，通过自然语言处理和原创性","ja":"humanize-academic-writing AIエージェントは、研究者が学術的な文章をより自然でオリジナルのものにすることを支援する","ko":"humanize-academic-writing AI 에이전트는 연구자가 학술 논문을 더 자연스럽고 원创적으로 작성하도록 도와줍니다","es":"Esta habilidad ayuda a los investigadores a mejorar la calidad y naturalidad de sus ideas originales expresadas a través de herramientas de escritura asistidas por IA.","fr":"Cette compétence aide les chercheurs à améliorer la qualité et la naturalité de leurs idées originales exprimées à travers des outils d''écriture assistés par l''IA.","de":"Diese Fähigkeit hilft Forschern, die Qualität und Natürlichkeit ihrer eigenen Ideen zu verbessern, die durch KI-gestützte Schreibtools zum Ausdruck gebracht werden.","pt":"O skill humanize-academic-writing ajuda pesquisadores a melhorar a qualidade e naturalidade da escrita acadêmica.","ru":"Навык humanize-academic-writing помогает исследователям улучшить качество и естественность академической письменности.","ar":"مهارة humanize-academic-writing تساعد الباحثين على تحسين جودة وطبيعية الكتابة الأكاديمية."},"seo":{"title":{"en":"humanize-academic-writing: AI-Assisted Writing Improvem