INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('gustavo-ferreira03/my-career-toolbox/humanize-academic-writing', 'humanize-academic-writing', 'gustavo-ferreira03', 'my-career-toolbox', 'community', 'humanize-academic-writing gustavo-ferreira03 my-career-toolbox community The humanize-academic-writing skill helps researchers refine AI-assisted writing, ensuring original ideas are naturally expressed. It benefits non-native English speakers and those seeking better academic writing patterns. humanize-academic-writing AI工具帮助研究人员提高学术写作质量，通过自然语言处理和原创性 humanize-academic-writing AIエージェントは、研究者が学術的な文章をより自然でオリジナルのものにすることを支援する humanize-academic-writing AI 에이전트는 연구자가 학술 논문을 더 자연스럽고 원创적으로 작성하도록 도와줍니다 Esta habilidad ayuda a los investigadores a mejorar la calidad y naturalidad de sus ideas originales expresadas a través de herramientas de escritura asistidas por IA. Cette compétence aide les chercheurs à améliorer la qualité et la naturalité de leurs idées originales exprimées à travers des outils d''écriture assistés par l''IA. Diese Fähigkeit hilft Forschern, die Qualität und Natürlichkeit ihrer eigenen Ideen zu verbessern, die durch KI-gestützte Schreibtools zum Ausdruck gebracht werden. O skill humanize-academic-writing ajuda pesquisadores a melhorar a qualidade e naturalidade da escrita acadêmica. Навык humanize-academic-writing помогает исследователям улучшить качество и естественность академической письменности. مهارة humanize-academic-writing تساعد الباحثين على تحسين جودة وطبيعية الكتابة الأكاديمية. how to use humanize-academic-writing what is humanize-academic-writing humanize-academic-writing alternative humanize-academic-writing setup guide improve academic writing with AI AI-assisted writing tools for social sciences AI工具 学术写作 自然语言处理 原创性 非英语母语者 学术写作模式 humanize-academic-writing Revises AI-drafted text based on user research and ideas Improves writing quality for non-native English speakers Enhances learning of better academic writing patterns Supports ethical use, such as revising and learning, while discouraging unethical practices like idea generation without understanding humanize-academic-writing is a skill that assists researchers in improving the quality and naturalness of their original ideas expressed through AI-assisted writing tools.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Fallenproud/magmabot/review-pr', 'community', 'Fallenproud', 'magmabot', 'Fallenproud/magmabot', 'review-pr', 1, 0, 60, '2026-02-12T01:17:56Z', '2026-03-07T01:54:38.181Z', 'ed21ddf73747c2ee783476cbe250c6b3effe768a9137ea7d0374bba1c3df9859', '{"id":"Fallenproud/magmabot/review-pr","name":"review-pr","description":{"en":"The review-pr skill performs thorough PR assessments, providing structured recommendations for readiness. It benefits developers by automating the review process, ensuring consistency and accuracy.","zh":"review-pr是一个自动代码审查工具，能够对代码进行彻底的审查和评估","ja":"review-prは自動コードレビューツールであり、コードの徹底的な審査と評価を行います","ko":"review-pr은 자동 코드 리뷰 도구로 코드를彻底하게审查하고 평가합니다","es":"Review-pr es un sistema de revisión de PR que proporciona una evaluación exhaustiva y devuelve una recomendación estructurada sobre la preparación para la fusión.","fr":"Review-pr est un système de revue de PR qui fournit une évaluation exhaustive et renvoie une recommandation structurée sur la préparation pour la fusion.","de":"Review-pr ist ein PR-Überprüfungssystem, das eine gründliche Bewertung durchführt und eine strukturierte Empfehlung zur Vorbereitung auf die Zusammenführung zurückgibt.","pt":"O Review-PR é um sistema de agente autônomo que realiza avaliações de pull requests de forma eficaz, fornecendo recomendações estruturadas para preparar PRs","ru":"Review-PR - это автономная система агентов, которая выполняет оценку запросов на включение изменений, предоставляя структурированные рекомендации для подготовки PR","ar":"Review-PR هو نظام وكيل ذاتي ي thựcي تقييمات لطلبات السحب بطريقة فعالة، ويقدم توصيات منظمة لتحضير PR"},"seo":{"title":{"en":"review-pr: Automated PR Review Setup Guide | AI Agent Skill","zh":"review-pr_SETUP GUIDE：自动代码审查工具","ja":"review-pr セットアップガイド：自動コードレビューツール","ko":"review-pr 설정 가이드: 자동 코드 리뷰 도구","es":"Guía de configuración de review-pr para desarrolladores","fr":"Configurer review-pr: Guide pour les développeurs","de":"Review-pr Einrichtungsleitfaden für Entwickler","pt":"Guia de Configuração do Review-PR para Desenvolvedores","ru":"ИИ Агенты: Руководство по Настройке Review-PR","ar":"دليل إعداد Review-PR لل AI Agents"},"description":{"en":"Boost your development workflow with review-pr, an AI agent skill that streamlines PR reviews. Learn how to set it up and optimize your Git workflow today!","zh":"了解review-pr的功能和特点，自动代码审查工具，提升代码质量","ja":"review-prの機能と特徴を紹介します。自動コードレビューツールでコード品質を向上させます","ko":"review-pr의 기능과 특징을 소개합니다. 자동 코드 리뷰 도구로 코드 품질을 향상시킵니다","es":"Aprende a configurar review-pr para una revisión de PR eficiente. Descubre las mejores prácticas y características clave para desarrolladores.","fr":"Découvrez comment configurer review-pr pour une revue de PR efficace. Consultez les meilleures pratiques et les fonctionnalités clés pour les développeurs.","de":"Erfahren Sie, wie Sie review-pr für eine effiziente PR-Überprüfung einrichten. Entdecken Sie die besten Praktiken und wichtigsten Funktionen für Entwickler.","pt":"Aprenda a configurar o Review-PR para avaliar pull requests de forma eficaz, com dicas e práticas recomendadas para desenvolvedores","ru":"Узнайте, как настроить Review-PR для оценки запросов на включение изменений, с советами и рекомендациями для разработчиков","ar":"تعرف على كيفية إعداد Review-PR لتقييم طلبات السحب بكفاءة، مع نصائح وأفضل الممارسات للمطورين"},"definition":{"en":"review-pr is a main-full-autonomous-agentic-system that assesses pull requests and returns readiness recommendations, ensuring a streamlined Git workflow.","zh":"review-pr是一种AIエージェント，用于自动代码审查和评估","ja":"review-prはAIエージェントの一種で、自動コードレビューと評価を行う","ko":"review-pr은 자동 코드 리뷰와 평가를 위한 AI 에이전트입니다","es":"Un agente de IA para revisión de PR que realiza una evaluación exhaustiva y proporciona recomendaciones para la preparación de la fusión.","fr":"Un outil d''IA pour la revue de PR qui effectue une évaluation exhaustive et fournit des recommandations pour la préparation de la fusion.","de":"Ein AI-Tool für die PR-Überprüfung, das eine gründliche Bewertung durchführt und Empfehlungen für die Vorbereitung auf die Zusammenführung bereitstellt.","pt":"O que é Review-PR? É um sistema de agente autônomo que avalia pull requests e fornece recomendações para preparar PRs","ru":"Что такое Review-PR? Это автономная система агентов, которая оценивает запросы на включение изменений и предоставляет рекомендации для подготовки PR","ar":"ما هو Review-PR؟ هو نظام وكيل ذاتي يقيّم طلبات السحب ويوفر توصيات لتحضير PR"},"features":{"en":["Asks for PR number or URL to initiate review","Never pushes to main or origin/main, ensuring a read-only review process","Treats review as read-only, avoiding git push commands","Provides structured recommendations for PR readiness","Supports manual input for PR number or URL, avoiding auto-detection"],"zh":["自动代码审查","代码评估和推荐","支持PR号或URL输入","安全的只读审查模式","无自动推送到main分支"],"ja":["自動コードレビュー","コード評価と推奨","PR番号またはURL入力のサポート","安全な読み取り専用モード","mainブランチへの自動プッシュなし"],"ko":["자동 코드 리뷰","코드 평가와 추천","PR 번호 또는 URL 입력 지원","안전한 읽기 전용 모드","main 브랜치への 자동 푸시 없음"],"es":["Solicitud de número o URL de PR","Evaluación exhaustiva de la preparación para la fusión","Recomendaciones estructuradas para la preparación","No ejecuta comandos de git push durante la revisión","Trata la revisión como de solo lectura"],"fr":["Demande de numéro ou d''URL de PR","Évaluation exhaustive de la préparation pour la fusion","Recommandations structurées pour la préparation","N''exécute pas de commandes git push pendant la revue","Traite la revue comme en lecture seule"],"de":["Anfrage nach PR-Nummer oder -URL","Gründliche Bewertung der Vorbereitung auf die Zusammenführung","Strukturierte Empfehlungen für die Vorbereitung","Führt keine git push-Befehle während der Überprüfung aus","Behandelt die Überprüfung als schreibgeschützt"],"pt":["Avaliação de pull requests de forma eficaz","Fornecimento de recomendações estruturadas para preparar PRs","Suporte à solicitação de número de PR ou URL","Tratamento de leitura apenas durante a revisão, sem push para ''main'' ou ''origin/main''","Compatibilidade com comandos Git","Segurança reforçada com restrições de push e stop"],"ru":["Эффективная оценка запросов на включение изменений","Предоставление структурированных рекомендаций для подготовки PR","Поддержка запроса номера PR или URL","Только чтение во время ревью, без пуша в ''main'' или ''origin/main''","Совместимость с командами Git","Усиленная безопасность с ограничениями пуша и стопа"],"ar":["تقييم طلبات السحب بطريقة فعالة","تقديم توصيات منظمة لتحضير PR","دعم طلب رقم PR أو URL","معالجة القراءة فقط خلال المراجعة، بدون دفع إلى ''main'' أو ''origin/main''","توافق مع أوامر Git","أمان معزز مع قيود الدفع وايقاف"]},"keywords":{"en":["how to use review-pr","review-pr setup guide","what is review-pr","review-pr alternative","review-pr vs git review","review-pr install","automated pr review","git workflow optimization","review-pr tutorial"],"zh":["review-pr","自动代码审查","代码评估","AIエージェント","代码质量","自动代码审查工具","代码审查最佳实践"],"ja":["review-pr","自動コードレビュー","コード評価","AIエージェント","コード品質","自動コードレビューツール","コードレビューのベストプラクティス"],"ko":["review-pr","자동 코드 리뷰","코드 평가","AI 에이전트","코드 품질","자동 코드 리뷰 도구","코드 리뷰의 베스트 프랙티스"],"es":["review-pr","revisión de PR","agente de IA para revisión de PR","evaluación de PR","preparación para la fusión","recomendaciones para la preparación","herramientas de desarrollador","desarrollo de software"],"fr":["review-pr","revue de PR","outil d''IA pour la revue de PR","évaluation de PR","préparation pour la fusion","recommandations pour la préparation","outils de développeur","développement de logiciel"],"de":["review-pr","PR-Überprüfung","AI-Tool für die PR-Überprüfung","Bewertung von PR","Vorbereitung auf die Zusammenführung","Empfehlungen für die Vorbereitung","Entwickler-Tools","Software-Entwicklung"],"pt":["Review-PR","Avaliação de pull requests","Recomendações para preparar PRs","Sistema de agente autônomo","Desenvolvimento de software","Ferramentas de desenvolvimento","Git","CLI","Segurança em desenvolvimento"],"ru":["Review-PR","Оценка запросов на включение изменений","Рекомендации для подготовки PR","Автономная система агентов","Разработка программного обеспечения","Инструменты разработки","Git","CLI","Безопасность разработки"],"ar":["Review-PR","تقييم طلبات السحب","توصيات لتحضير PR","نظام وكيل ذاتي","تطوير البرمجيات","أدوات التطوير","Git","CLI","أمان التطوير"]}},"owner":"Fallenproud","repo":"magmabot","repoPath":"Fallenproud/magmabot","stars":1,"forks":0,"updatedAt":"2026-02-12T01:17:56Z","topics":[],"category":"community","skillMd":{"name":"review-pr","description":"Review-only GitHub pull request analysis with the gh CLI. Use when asked to review a PR, provide structured feedback, or assess readiness to land. Do not merge, push, or make code changes you intend to keep.","bodyPreview":"# Review PR\n\n## Overview\n\nPerform a thorough review-only PR assessment and return a structured recommendation on readiness for /preparepr.\n\n## Inputs\n\n- Ask for PR number or URL.\n- If missing, always ask. Never auto-detect from conversation.\n- If ambiguous, ask.\n\n## Safety\n\n- Never push to `main` or `origin/main`, not during review, not ever.\n- Do not run `git push` at all during review. Treat review as read only.\n- Do not stop or kill the gateway. Do not run gateway stop commands. Do not kill p","body":"# Review PR\n\n## Overview\n\nPerform a thorough review-only PR assessment and return a structured recommendation on readiness for /preparepr.\n\n## Inputs\n\n- Ask for PR number or URL.\n- If missing, always ask. Never auto-detect from conversation.\n- If ambiguous, ask.\n\n## Safety\n\n- Never push to `main` or `origin/main`, not during review, not ever.\n- Do not run `git push` at all during review. Treat review as read only.\n- Do not stop or kill the gateway. Do not run gateway stop commands. Do not kill processes on port 18792.\n\n## Execution Rule\n\n- Execute the workflow. Do not stop after printing the TODO checklist.\n- If delegating, require the delegate to run commands and capture outputs, not a plan.\n\n## Known Failure Modes\n\n- If you see \"fatal: not a git repository\", you are in the wrong directory. Use `~/openclaw`.\n- Do not stop after printing the checklist. That is not completion.\n\n## Writing Style for Output\n\n- Write casual and direct.\n- Avoid em dashes and en dashes. Use commas or separate sentences.\n\n## Completion Criteria\n\n- Run the commands in the worktree and inspect the PR directly.\n- Produce the structured review sections A through J.\n- Save the full review to `.local/review.md` inside the worktree.\n\n## First: Create a TODO Checklist\n\nCreate a checklist of all review steps, print it, then continue and execute the commands.\n\n## Setup: Use a Worktree\n\nUse an isolated worktree for all review work.\n\n```sh\ncd ~/Development/openclaw\n# Sanity: confirm you are in the repo\ngit rev-parse --show-toplevel\n\nWORKTREE_DIR=\".worktrees/pr-<PR>\"\ngit fetch origin main\n\n# Reuse existing worktree if it exists, otherwise create new\nif [ -d \"$WORKTREE_DIR\" ]; then\n  cd \"$WORKTREE_DIR\"\n  git checkout temp/pr-<PR> 2>/dev/null || git checkout -b temp/pr-<PR>\n  git fetch origin main\n  git reset --hard origin/main\nelse\n  git worktree add \"$WORKTREE_DIR\" -b temp/pr-<PR> origin/main\n  cd \"$WORKTREE_DIR\"\nfi\n\n# Create local scratch space that persists across /reviewpr to /preparepr to /mergepr\nmkdir -p .local\n```\n\nRun all commands inside the worktree directory.\nStart on `origin/main` so you can check for existing implementations before looking at PR code.\n\n## Steps\n\n1. Identify PR meta and context\n\n```sh\ngh pr view <PR> --json number,title,state,isDraft,author,baseRefName,headRefName,headRepository,url,body,labels,assignees,reviewRequests,files,additions,deletions --jq ''{number,title,url,state,isDraft,author:.author.login,base:.baseRefName,head:.headRefName,headRepo:.headRepository.nameWithOwner,additions,deletions,files:.files|length,body}''\n```\n\n2. Check if this already exists in main before looking at the PR branch\n\n- Identify the core feature or fix from the PR title and description.\n- Search for existing implementations using keywords from the PR title, changed file paths, and function or component names from the diff.\n\n```sh\n# Use keywords from the PR title and changed files\nrg -n \"<keyword_from_pr_title>\" -S src packages apps ui || true\nrg -n \"<function_or_component_name>\" -S src packages apps ui || true\n\ngit log --oneline --all --grep=\"<keyword_from_pr_title>\" | head -20\n```\n\nIf it already exists, call it out as a BLOCKER or at least IMPORTANT.\n\n3. Claim the PR\n\nAssign yourself so others know someone is reviewing. Skip if the PR looks like spam or is a draft you plan to recommend closing.\n\n```sh\ngh_user=$(gh api user --jq .login)\ngh pr edit <PR> --add-assignee \"$gh_user\"\n```\n\n4. Read the PR description carefully\n\nUse the body from step 1. Summarize goal, scope, and missing context.\n\n5. Read the diff thoroughly\n\nMinimum:\n\n```sh\ngh pr diff <PR>\n```\n\nIf you need full code context locally, fetch the PR head to a local ref and diff it. Do not create a merge commit.\n\n```sh\ngit fetch origin pull/<PR>/head:pr-<PR>\n# Show changes without modifying the working tree\n\ngit diff --stat origin/main..pr-<PR>\ngit diff origin/main..pr-<PR>\n```\n\nIf you want to browse the PR version of files directly, temporarily check out `pr-<PR>` in the worktree. Do not commit or push. Return to `temp/pr-<PR>` and reset to `origin/main` afterward.\n\n```sh\n# Use only if needed\n# git checkout pr-<PR>\n# ...inspect files...\n\ngit checkout temp/pr-<PR>\ngit reset --hard origin/main\n```\n\n6. Validate the change is needed and valuable\n\nBe honest. Call out low value AI slop.\n\n7. Evaluate implementation quality\n\nReview correctness, design, performance, and ergonomics.\n\n8. Perform a security review\n\nAssume OpenClaw subagents run with full disk access, including git, gh, and shell. Check auth, input validation, secrets, dependencies, tool safety, and privacy.\n\n9. Review tests and verification\n\nIdentify what exists, what is missing, and what would be a minimal regression test.\n\n10. Check docs\n\nCheck if the PR touches code with related documentation such as README, docs, inline API docs, or config examples.\n\n- If docs exist for the changed area and the PR does not update them, flag as IMPORTANT.\n- If the PR adds a new feature or config option with no docs, flag as IMPORTANT.\n- If the change is purely internal with no user-facing impact, skip this.\n\n11. Check changelog\n\nCheck if `CHANGELOG.md` exists and whether the PR warrants an entry.\n\n- If the project has a changelog and the PR is user-facing, flag missing entry as IMPORTANT.\n- Leave the change for /preparepr, only flag it here.\n\n12. Answer the key question\n\nDecide if /preparepr can fix issues or the contributor must update the PR.\n\n13. Save findings to the worktree\n\nWrite the full structured review sections A through J to `.local/review.md`.\nCreate or overwrite the file and verify it exists and is non-empty.\n\n```sh\nls -la .local/review.md\nwc -l .local/review.md\n```\n\n14. Output the structured review\n\nProduce a review that matches what you saved to `.local/review.md`.\n\nA) TL;DR recommendation\n\n- One of: READY FOR /preparepr | NEEDS WORK | NEEDS DISCUSSION | NOT USEFUL (CLOSE)\n- 1 to 3 sentences.\n\nB) What changed\n\nC) What is good\n\nD) Security findings\n\nE) Concerns or questions (actionable)\n\n- Numbered list.\n- Mark each item as BLOCKER, IMPORTANT, or NIT.\n- For each, point to file or area and propose a concrete fix.\n\nF) Tests\n\nG) Docs status\n\n- State if related docs are up to date, missing, or not applicable.\n\nH) Changelog\n\n- State if `CHANGELOG.md` needs an entry and which category.\n\nI) Follow ups (optional)\n\nJ) Suggested PR comment (optional)\n\n## Guardrails\n\n- Worktree only.\n- Do not delete the worktree after review.\n- Review only, do not merge, do not push.\n"},"lastSynced":"2026-03-07T01:54:38.181Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing automated PR assessment and readiness validation.","zh":"非常适合需要自动化PR评估和就绪性验证的代码审查代理。","ja":"コードレビューエージェントが自動化されたPR評価と就緒性検証を必要とする場合に最適です。","ko":"자동화된 PR 평가 및 준비 확인이 필요한 코드 리뷰 에이전트에게 적합합니다.","es":"Perfecto para agentes de revisión de código que necesitan una evaluación automatizada de PR y validación de preparación.","fr":"Parfait pour les agents de révision de code nécessitant une évaluation automatique de PR et une validation de préparation.","de":"Perfekt für Code-Review-Agents, die eine automatisierte PR-Bewertung und Validierung der Bereitschaft benötigen.","pt":"Perfeito para Agentes de Revisão de Código que precisam de avaliação automática de PR e validação de prontidão.","ru":"Идеально для Агентов Кодового Обзора, которым необходима автоматизированная оценка PR и проверка готовности.","ar":"مثالي للوكلاء المراجعة الكودية الذين يحتاجون إلى تقييم آلي للطلبات السريعة وتحقق الجاهزية."},"recommendation":{"en":"Empowers agents to perform thorough PR reviews, providing structured recommendations for readiness using git and ensuring consistency and accuracy, while enforcing safety protocols such as never pushing to main or running git push commands during review.","zh":"赋予代理执行彻底的PR审查的能力，使用git提供结构化的就绪性建议，确保一致性和准确性，同时强制执行安全协议，例如永远不推送到主分支或在审查期间运行git推送命令。","ja":"エージェントが徹底的なPRレビューを実行できるようにし、gitを使用して一貫性と正確性を確保しながら、安全性プロトコル（例：メインブランチへのプッシュやレビュー中にgitプッシュコマンドを実行しない）を強制して、就緒性の構造化された推奨事項を提供します。","ko":"에이전트가 철저한 PR 검토를 수행할 수 있도록 하며, git를 사용하여 일관성과 정확성을 보장同时 안전 프로토콜(예: 메인 브랜치로 푸시하거나 검토 중에 git 푸시 명령을 실행하지 않음)을 시행하여 준비 확인에 대한 구조화된 추천을 제공합니다.","es":"Habilita a los agentes a realizar revisiones exhaustivas de PR, proporcionando recomendaciones estructuradas para la preparación utilizando git y garantizando la consistencia y precisión, al tiempo que se aplican protocolos de seguridad como nunca empujar a main o ejecutar comandos git push durante la revisión.","fr":"Permet aux agents d''effectuer des révisions de PR approfondies, en fournissant des recommandations structurées pour la préparation en utilisant git et en garantissant la cohérence et l''exactitude, tout en appliquant des protocoles de sécurité tels que ne jamais pousser vers main ou exécuter des commandes git push pendant la révision.","de":"Ermächtigt Agenten, umfassende PR-Überprüfungen durchzuführen, indem strukturierte Empfehlungen für die Vorbereitung unter Verwendung von git bereitgestellt werden und Konsistenz und Genauigkeit gewährleistet werden, während Sicherheitsprotokolle wie das Nie-Pushen auf main oder Ausführen von git push-Befehlen während der Überprüfung durchgesetzt werden.","pt":"Habilita os agentes a realizar revisões de PR abrangentes, fornecendo recomendações estruturadas para prontidão usando git e garantindo consistência e precisão, enquanto impõe protocolos de segurança, como nunca empurrar para o main ou executar comandos git push durante a revisão.","ru":"Наделяет агентов возможностью проводить тщательные обзоры PR, предоставляя структурированные рекомендации по готовности с использованием git и гарантируя последовательность и точность, а также обеспечивающие протоколы безопасности, такие как никогда не пушить в основную ветку или выполнять команды git push во время обзора.","ar":"يسمح للوكلاء بإجراء مراجعات شاملة للاستدعاءات السريعة، وتقديم توصيات منظمة للجاهزية باستخدام git وضمان الاتساق والدقة، مع فرض بروتوكولات أمان مثل أبدا دفع إلى الرئيسي أو تشغيل أوامر git push أثناء المراجعة."},"useCases":{"en":["Automating PR assessments for developers","Generating readiness recommendations for /preparepr","Ensuring consistency and accuracy in code reviews"],"zh":["为开发人员自动化PR评估","为/preparepr生成就绪性建议","确保代码审查的一致性和准确性"],"ja":["開発者向けのPR評価の自動化","/preparepr向けの就緒性推奨の生成","コードレビューの一貫性と正確性の確保"],"ko":["개발자용 PR 평가 자동화","/preparepr용 준비 확인 추천 생성","코드 검토의 일관성 및 정확성 보장"],"es":["Automatización de evaluaciones de PR para desarrolladores","Generación de recomendaciones de preparación para /preparepr","Garantía de consistencia y precisión en las revisiones de código"],"fr":["Automatisation des évaluations de PR pour les développeurs","Génération de recommandations de préparation pour /preparepr","Assurance de la cohérence et de l''exactitude dans les révisions de code"],"de":["Automatisierung von PR-Bewertungen für Entwickler","Generierung von Vorbereitungsempfehlungen für /preparepr","Gewährleistung von Konsistenz und Genauigkeit bei Code-Überprüfungen"],"pt":["Automatizar avaliações de PR para desenvolvedores","Gerar recomendações de prontidão para /preparepr","Garantir consistência e precisão em revisões de código"],"ru":["Автоматизировать оценки PR для разработчиков","Генерировать рекомендации по готовности для /preparepr","Обеспечивать последовательность и точность в обзорах кода"],"ar":["تأتمتة تقييمات الطلبات السريعة للمطورين","توليد توصيات الجاهزية ل /preparepr","ضمان الاتساق والدقة في مراجعات الكود"]},"limitations":{"en":["Requires PR number or URL as input","Does not support auto-detection of PR from conversation","Treats review as read-only, never pushing to main or origin/main"],"zh":["需要PR编号或URL作为输入","不支持从会话中自动检测PR","以只读方式处理审查，永远不推送到主分支或origin/main"],"ja":["入力としてPR番号またはURLが必要","会話からPRを自動検知しない","レビューを読み取り専用で処理し、メインブランチまたはorigin/mainにプッシュしない"],"ko":["입력으로 PR 번호 또는 URL이 필요","대화에서 PR을 자동으로 감지하지 않음","검토를 읽기 전용으로 처리하며, 메인 브랜치 또는 origin/main으로 푸시하지 않음"],"es":["Requiere número o URL de PR como entrada","No admite la detección automática de PR desde la conversación","Trata la revisión como de solo lectura, nunca empujando a main o origin/main"],"fr":["Nécessite un numéro ou une URL de PR comme entrée","Ne prend pas en charge la détection automatique de PR à partir de la conversation","Traite la révision comme en lecture seule, ne poussant jamais vers main ou origin/main"],"de":["Benötigt PR-Nummer oder URL als Eingabe","Unterstützt keine automatische Erkennung von PR aus der Konversation","Behandelt die Überprüfung als schreibgeschützt, nie auf main oder origin/main pushen"],"pt":["Exige número de PR ou URL como entrada","Não suporta detecção automática de PR a partir da conversa","Trata a revisão como somente leitura, nunca empurrando para o main ou origin/main"],"ru":["Требует номера PR или URL в качестве входных данных","Не поддерживает автоматическое обнаружение PR из разговора","Рассматривает обзор как только для чтения, никогда не пушит в основную ветку или origin/main"],"ar":["يتطلب رقم الطلب السريع أو URL كمدخل","لا يدعم الكشف التلقائي عن الطلبات السريعة من المحادثة","يعامل المراجعة على أنها للقراءة فقط، أبدا دفع إلى الرئيسي أو origin/main"]},"version":4},"contentHash":"ed21ddf73747c2ee783476cbe250c6b3effe768a9137ea7d0374bba1c3df9859","qualityScore":60}');
