INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Fallenproud/magmabot/review-pr', 'review-pr', 'Fallenproud', 'magmabot', 'community', 'review-pr Fallenproud magmabot community The review-pr skill performs thorough PR assessments, providing structured recommendations for readiness. It benefits developers by automating the review process, ensuring consistency and accuracy. review-pr是一个自动代码审查工具，能够对代码进行彻底的审查和评估 review-prは自動コードレビューツールであり、コードの徹底的な審査と評価を行います review-pr은 자동 코드 리뷰 도구로 코드를彻底하게审查하고 평가합니다 Review-pr es un sistema de revisión de PR que proporciona una evaluación exhaustiva y devuelve una recomendación estructurada sobre la preparación para la fusión. Review-pr est un système de revue de PR qui fournit une évaluation exhaustive et renvoie une recommandation structurée sur la préparation pour la fusion. Review-pr ist ein PR-Überprüfungssystem, das eine gründliche Bewertung durchführt und eine strukturierte Empfehlung zur Vorbereitung auf die Zusammenführung zurückgibt. O Review-PR é um sistema de agente autônomo que realiza avaliações de pull requests de forma eficaz, fornecendo recomendações estruturadas para preparar PRs Review-PR - это автономная система агентов, которая выполняет оценку запросов на включение изменений, предоставляя структурированные рекомендации для подготовки PR Review-PR هو نظام وكيل ذاتي ي thựcي تقييمات لطلبات السحب بطريقة فعالة، ويقدم توصيات منظمة لتحضير PR how to use review-pr review-pr setup guide what is review-pr review-pr alternative review-pr vs git review review-pr install automated pr review git workflow optimization review-pr tutorial review-pr 自动代码审查 代码评估 AIエージェント 代码质量 自动代码审查工具 代码审查最佳实践 Asks for PR number or URL to initiate review Never pushes to main or origin/main, ensuring a read-only review process Treats review as read-only, avoiding git push commands Provides structured recommendations for PR readiness Supports manual input for PR number or URL, avoiding auto-detection review-pr is a main-full-autonomous-agentic-system that assesses pull requests and returns readiness recommendations, ensuring a streamlined Git workflow.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sskarz/nanoclawbster/x-integration', 'community', 'sskarz', 'nanoclawbster', 'sskarz/nanoclawbster', 'x-integration', 1, 0, 60, '2026-02-28T09:18:47Z', '2026-03-06T07:18:44.735Z', '655b77268a439e729feb4c100a148ca07fdeec8bf6053bf53ecda04f5554c584', '{"id":"sskarz/nanoclawbster/x-integration","name":"x-integration","description":{"en":"The x-integration skill enables browser automation for X interactions via WhatsApp, supporting features like posting, liking, and replying to tweets. It benefits developers seeking a lightweight alternative to Clawdbot and OpenClaw.","zh":"x-integration是一种轻量级的Clawdbot / OpenClaw替代品，运行在容器中以实现安全性，连接WhatsApp，具有内存和调度作业功能，并直接在Anthropic的Agents SDK上运行","ja":"x-integrationは、Clawdbot / OpenClawの軽量代替品で、セキュリティを実現するためにコンテナ内で実行され、WhatsApp接続、メモリ、スケジュールジョブ機能を持ち、AnthropicのAgents SDK上で直接実行されます","ko":"x-integration은 보안을 위해 컨테이너에서 실행되는 Clawdbot / OpenClaw의 경량 대체품으로, WhatsApp 연결, 메모리 및 스케줄 작업 기능을 가지고 Anthropic의 Agents SDK에서 직접 실행됩니다","es":"x-integration es una alternativa ligera para interactuar con Twitter a través de WhatsApp de forma segura","fr":"x-integration est une alternative légère pour interagir avec Twitter via WhatsApp de manière sécurisée","de":"x-integration ist eine leichte Alternative, um mit Twitter über WhatsApp sicher zu interagieren","pt":"O x-integration é uma solução leve para integração com o WhatsApp, oferecendo memória e trabalhos agendados, além de executar diretamente no Anthropic Agents SDK","ru":"x-integration - это лёгкое решение для интеграции с WhatsApp, предлагающее память и запланированные задания, а также выполняющееся直接 на Anthropic Agents SDK","ar":"x-integration هو حل خفيف لدمج WhatsApp، يوفر الذاكرة والمهام المجدولة، بالإضافة إلى التشغيل المباشر على Anthropic Agents SDK"},"seo":{"title":{"en":"x-integration: WhatsApp Automation Setup Guide | AI Agent...","zh":"x-integration.setup指南：安全容器化WhatsApp连接","ja":"x-integrationセットアップガイド：セキュアなコンテナ化WhatsApp接続","ko":"x-integration 설정 가이드: 보안 컨테이너화 WhatsApp 연결","es":"Guía de configuración de x-integration para WhatsApp","fr":"Guide d''intégration x-integration pour WhatsApp","de":"Einrichtungs-Anleitung für x-integration mit WhatsApp","pt":"Guia de Configuração do x-integration: Integração com Wha...","ru":"Настройка x-integration: ИИ Агенты для интеграции с Whats...","ar":"دليل إعداد x-integration: دمج WhatsApp و Anthropic Agents..."},"description":{"en":"Discover how to automate WhatsApp interactions with x-integration. Learn to post, like, and reply to tweets via WhatsApp and get started with our setup guide.","zh":"了解x-integration的特点和优势，包括安全容器化、WhatsApp连接和内存功能，实现Anthropic Agents SDK的高效集成","ja":"x-integrationの特徴と利点を学びます。セキュアなコンテナ化、WhatsApp接続、メモリ機能を含み、Anthropic Agents SDKとの効率的な統合を実現します","ko":"x-integration의 특징과 장점을 알아보세요. 보안 컨테이너화, WhatsApp 연결 및 메모리 기능을 포함하여 Anthropic Agents SDK와의 효율적인 통합을实现합니다","es":"Descubre cómo integrar x-integration con WhatsApp para publicar tweets, dar me gusta y responder a comentarios de forma segura","fr":"Découvrez comment intégrer x-integration avec WhatsApp pour publier des tweets, liker et répondre aux commentaires de manière sécurisée","de":"Erfahren Sie, wie Sie x-integration mit WhatsApp integrieren, um Tweets zu veröffentlichen, zu liken und auf Kommentare zu antworten","pt":"Aprenda a configurar o x-integration para interagir com o WhatsApp e aproveite os recursos de memória e trabalhos agendados","ru":"Узнайте, как настроить x-integration для взаимодействия с WhatsApp и воспользуйтесь функциями памяти и запланированных заданий","ar":"تعلم كيفية إعداد x-integration للتفاعل مع WhatsApp واستفد من ميزات الذاكرة والمهام المجدولة"},"definition":{"en":"x-integration is a lightweight container-based alternative to Clawdbot and OpenClaw, designed for secure WhatsApp automation and integration with Anthropic''s Agents SDK.","zh":"x-integration是一种用于Twitter交互的浏览器自动化工具，通过WhatsApp连接实现安全容器化和内存功能","ja":"x-integrationは、Twitterとのやり取りのためのブラウザ自動化ツールで、WhatsApp接続を通じてセキュアなコンテナ化とメモリ機能を実現します","ko":"x-integration은 보안 컨테이너화와 메모리 기능을 구현하는 WhatsApp 연결을 통해 Twitter 상호 작용을 위한 브라우저 자동화 도구입니다","es":"x-integration es un agente de AI que permite la integración con WhatsApp para interactuar con Twitter","fr":"x-integration est un agent d''IA qui permet l''intégration avec WhatsApp pour interagir avec Twitter","de":"x-integration ist ein AI-Agent, der die Integration mit WhatsApp für die Interaktion mit Twitter ermöglicht","pt":"O x-integration é uma ferramenta de integração com o WhatsApp que executa em contêineres para segurança","ru":"x-integration - это инструмент интеграции с WhatsApp, который выполняется в контейнерах для безопасности","ar":"x-integration هو أداة دمج WhatsApp التي تعمل في حاويات للأمان"},"features":{"en":["Publish new tweets using the `x_post` command","Like any tweet with the `x_like` tool","Reply to tweets using the `x_reply` feature","Retweet without comment via the `x_retweet` action","Quote tweet with comment using the `x_quote` functionality"],"zh":["安全容器化","WhatsApp连接","内存功能","调度作业功能","直接在Anthropic的Agents SDK上运行","支持Post、Like、Reply、Retweet和Quote等Twitter操作"],"ja":["セキュアなコンテナ化","WhatsApp接続","メモリ機能","スケジュールジョブ機能","AnthropicのAgents SDK上で直接実行","Post、Like、Reply、Retweet、QuoteなどのTwitter操作をサポート"],"ko":["보안 컨테이너화","WhatsApp 연결","메모리 기능","스케줄 작업 기능","Anthropic의 Agents SDK에서 직접 실행","Post, Like, Reply, Retweet, Quote 등의 Twitter 작업 지원"],"es":["Publicar tweets con x_post","Dar me gusta a tweets con x_like","Responder a tweets con x_reply","Retwittear sin comentario con x_retweet","Citar tweets con comentario con x_quote"],"fr":["Publier des tweets avec x_post","Liker des tweets avec x_like","Répondre aux tweets avec x_reply","Retweeter sans commentaire avec x_retweet","Citer des tweets avec commentaire avec x_quote"],"de":["Tweets mit x_post veröffentlichen","Tweets mit x_like liken","Auf Tweets mit x_reply antworten","Ohne Kommentar retweeten mit x_retweet","Tweets mit Kommentar zitieren mit x_quote"],"pt":["Publicação de tweets novos via WhatsApp","Curtir tweets","Responder tweets","Retuitar sem comentário","Citar tweets com comentário","Execução direta no Anthropic Agents SDK"],"ru":["Публикация новых твитов через WhatsApp","Лайкать твиты","Отвечать на твиты","Ретвитить без комментария","Цитировать твиты с комментарием","Прямое выполнение на Anthropic Agents SDK"],"ar":["نشر توييتات جديدة عبر WhatsApp","إعجاب بالتوييتات","الرد على التوييتات","إعادة توييت بدون تعليق","اقتباس التوييتات مع تعليق","التشغيل المباشر على Anthropic Agents SDK"]},"keywords":{"en":["how to use x-integration","x-integration alternative to Clawdbot","x-integration vs OpenClaw","x-integration install guide","x-integration setup for WhatsApp automation","what is x-integration","x-integration documentation","x-integration tutorial","x-integration and Anthropic''s Agents SDK"],"zh":["x-integration","AIエージェント","WhatsApp连接","安全容器化","内存功能","调度作业功能","Anthropic Agents SDK","Twitter自动化","浏览器自动化"],"ja":["x-integration","AIエージェント","WhatsApp接続","セキュアなコンテナ化","メモリ機能","スケジュールジョブ機能","Anthropic Agents SDK","Twitter自動化","ブラウザ自動化"],"ko":["x-integration","AI 에이전트","WhatsApp 연결","보안 컨테이너화","메모리 기능","스케줄 작업 기능","Anthropic Agents SDK","Twitter 자동화","브라우저 자동화"],"es":["x-integration","integación con WhatsApp","publicar tweets","dar me gusta","responder a comentarios","retwittear","citar tweets","agente de AI","herramientas de AI","desarrollo de chatbots"],"fr":["x-integration","intégration avec WhatsApp","publier des tweets","liker des tweets","répondre aux commentaires","retweeter","citer des tweets","agent d''IA","outils d''IA","développement de chatbots"],"de":["x-integration","Integration mit WhatsApp","Tweets veröffentlichen","Tweets liken","Auf Kommentare antworten","retweeten","Tweets zitieren","AI-Agent","AI-Tools","Chatbot-Entwicklung"],"pt":["x-integration","integração com WhatsApp","Anthropic Agents SDK","memória","trabalhos agendados","contêineres","segurança","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["x-integration","ИИ Агенты","интеграция с WhatsApp","Anthropic Agents SDK","память","запланированные задания","контейнеры","безопасность","разработка программного обеспечения","инструменты разработки"],"ar":["x-integration","أدوات الذكاء الاصطناعي","دمج WhatsApp","Anthropic Agents SDK","الذاكرة","المهام المجدولة","الحاويات","الأمان","تطوير البرمجيات","أدوات التطوير"]}},"owner":"sskarz","repo":"nanoclawbster","repoPath":"sskarz/nanoclawbster","stars":1,"forks":0,"updatedAt":"2026-02-28T09:18:47Z","topics":[],"category":"community","skillMd":{"name":"x-integration","description":"X (Twitter) integration for NanoClawbster. Post tweets, like, reply, retweet, and quote. Use for setup, testing, or troubleshooting X functionality. Triggers on setup x, x integration, twitter, post tweet, tweet.","bodyPreview":"# X (Twitter) Integration\n\nBrowser automation for X interactions via WhatsApp.\n\n> **Compatibility:** NanoClawbster v1.0.0. Directory structure may change in future versions.\n\n## Features\n\n| Action | Tool | Description |\n|--------|------|-------------|\n| Post | `x_post` | Publish new tweets |\n| Like | `x_like` | Like any tweet |\n| Reply | `x_reply` | Reply to tweets |\n| Retweet | `x_retweet` | Retweet without comment |\n| Quote | `x_quote` | Quote tweet with comment |\n\n## Prerequisites\n\nBefore usi","body":"# X (Twitter) Integration\n\nBrowser automation for X interactions via WhatsApp.\n\n> **Compatibility:** NanoClawbster v1.0.0. Directory structure may change in future versions.\n\n## Features\n\n| Action | Tool | Description |\n|--------|------|-------------|\n| Post | `x_post` | Publish new tweets |\n| Like | `x_like` | Like any tweet |\n| Reply | `x_reply` | Reply to tweets |\n| Retweet | `x_retweet` | Retweet without comment |\n| Quote | `x_quote` | Quote tweet with comment |\n\n## Prerequisites\n\nBefore using this skill, ensure:\n\n1. **NanoClawbster is installed and running** - WhatsApp connected, service active\n2. **Dependencies installed**:\n   ```bash\n   npm ls playwright dotenv-cli || npm install playwright dotenv-cli\n   ```\n3. **CHROME_PATH configured** in `.env` (if Chrome is not at default location):\n   ```bash\n   # Find your Chrome path\n   mdfind \"kMDItemCFBundleIdentifier == ''com.google.Chrome''\" 2>/dev/null | head -1\n   # Add to .env\n   CHROME_PATH=/path/to/Google Chrome.app/Contents/MacOS/Google Chrome\n   ```\n\n## Quick Start\n\n```bash\n# 1. Setup authentication (interactive)\nnpx dotenv -e .env -- npx tsx .claude/skills/x-integration/scripts/setup.ts\n# Verify: data/x-auth.json should exist after successful login\n\n# 2. Rebuild container to include skill\n./container/build.sh\n# Verify: Output shows \"COPY .claude/skills/x-integration/agent.ts\"\n\n# 3. Rebuild host and restart service\nnpm run build\nlaunchctl kickstart -k gui/$(id -u)/com.nanoclawbster  # macOS\n# Linux: systemctl --user restart nanoclawbster\n# Verify: launchctl list | grep nanoclawbster (macOS) or systemctl --user status nanoclawbster (Linux)\n```\n\n## Configuration\n\n### Environment Variables\n\n| Variable | Default | Description |\n|----------|---------|-------------|\n| `CHROME_PATH` | `/Applications/Google Chrome.app/Contents/MacOS/Google Chrome` | Chrome executable path |\n| `NANOCLAWBSTER_ROOT` | `process.cwd()` | Project root directory |\n| `LOG_LEVEL` | `info` | Logging level (debug, info, warn, error) |\n\nSet in `.env` file (loaded via `dotenv-cli` at runtime):\n\n```bash\n# .env\nCHROME_PATH=/Applications/Google Chrome.app/Contents/MacOS/Google Chrome\n```\n\n### Configuration File\n\nEdit `lib/config.ts` to modify defaults:\n\n```typescript\nexport const config = {\n    // Browser viewport\n    viewport: { width: 1280, height: 800 },\n\n    // Timeouts (milliseconds)\n    timeouts: {\n        navigation: 30000,    // Page navigation\n        elementWait: 5000,    // Wait for element\n        afterClick: 1000,     // Delay after click\n        afterFill: 1000,      // Delay after form fill\n        afterSubmit: 3000,    // Delay after submit\n        pageLoad: 3000,       // Initial page load\n    },\n\n    // Tweet limits\n    limits: {\n        tweetMaxLength: 280,\n    },\n};\n```\n\n### Data Directories\n\nPaths relative to project root:\n\n| Path | Purpose | Git |\n|------|---------|-----|\n| `data/x-browser-profile/` | Chrome profile with X session | Ignored |\n| `data/x-auth.json` | Auth state marker | Ignored |\n| `logs/nanoclawbster.log` | Service logs (contains X operation logs) | Ignored |\n\n## Architecture\n\n```\n┌─────────────────────────────────────────────────────────────┐\n│  Container (Linux VM)                                       │\n│  └── agent.ts → MCP tool definitions (x_post, etc.)    │\n│      └── Writes IPC request to /workspace/ipc/tasks/       │\n└──────────────────────┬──────────────────────────────────────┘\n                       │ IPC (file system)\n                       ▼\n┌─────────────────────────────────────────────────────────────┐\n│  Host (macOS)                                               │\n│  └── src/ipc.ts → processTaskIpc()                         │\n│      └── host.ts → handleXIpc()                         │\n│          └── spawn subprocess → scripts/*.ts               │\n│              └── Playwright → Chrome → X Website           │\n└─────────────────────────────────────────────────────────────┘\n```\n\n### Why This Design?\n\n- **API is expensive** - X official API requires paid subscription ($100+/month) for posting\n- **Bot browsers get blocked** - X detects and bans headless browsers and common automation fingerprints\n- **Must use user''s real browser** - Reuses the user''s actual Chrome on Host with real browser fingerprint to avoid detection\n- **One-time authorization** - User logs in manually once, session persists in Chrome profile for future use\n\n### File Structure\n\n```\n.claude/skills/x-integration/\n├── SKILL.md          # This documentation\n├── host.ts           # Host-side IPC handler\n├── agent.ts          # Container-side MCP tool definitions\n├── lib/\n│   ├── config.ts     # Centralized configuration\n│   └── browser.ts    # Playwright utilities\n└── scripts/\n    ├── setup.ts      # Interactive login\n    ├── post.ts       # Post tweet\n    ├── like.ts       # Like tweet\n    ├── reply.ts      # Reply to tweet\n    ├── retweet.ts    # Retweet\n    └── quote.ts      # Quote tweet\n```\n\n### Integration Points\n\nTo integrate this skill into NanoClawbster, make the following modifications:\n\n---\n\n**1. Host side: `src/ipc.ts`**\n\nAdd import after other local imports:\n```typescript\nimport { handleXIpc } from ''../.claude/skills/x-integration/host.js'';\n```\n\nModify `processTaskIpc` function''s switch statement default case:\n```typescript\n// Find:\ndefault:\nlogger.warn({ type: data.type }, ''Unknown IPC task type'');\n\n// Replace with:\ndefault:\nconst handled = await handleXIpc(data, sourceGroup, isAdmin, DATA_DIR);\nif (!handled) {\n    logger.warn({ type: data.type }, ''Unknown IPC task type'');\n}\n```\n\n---\n\n**2. Container side: `container/agent-runner/src/ipc-mcp.ts`**\n\nAdd import after `cron-parser` import:\n```typescript\n// @ts-ignore - Copied during Docker build from .claude/skills/x-integration/\nimport { createXTools } from ''./skills/x-integration/agent.js'';\n```\n\nAdd to the end of tools array (before the closing `]`):\n```typescript\n    ...createXTools({ groupFolder, isAdmin })\n```\n\n---\n\n**3. Build script: `container/build.sh`**\n\nChange build context from `container/` to project root (required to access `.claude/skills/`):\n```bash\n# Find:\ndocker build -t \"${IMAGE_NAME}:${TAG}\" .\n\n# Replace with:\ncd \"$SCRIPT_DIR/..\"\ndocker build -t \"${IMAGE_NAME}:${TAG}\" -f container/Dockerfile .\n```\n\n---\n\n**4. Dockerfile: `container/Dockerfile`**\n\nFirst, update the build context paths (required to access `.claude/skills/` from project root):\n```dockerfile\n# Find:\nCOPY agent-runner/package*.json ./\n...\nCOPY agent-runner/ ./\n\n# Replace with:\nCOPY container/agent-runner/package*.json ./\n...\nCOPY container/agent-runner/ ./\n```\n\nThen add COPY line after `COPY container/agent-runner/ ./` and before `RUN npm run build`:\n```dockerfile\n# Copy skill MCP tools\nCOPY .claude/skills/x-integration/agent.ts ./src/skills/x-integration/\n```\n\n## Setup\n\nAll paths below are relative to project root (`NANOCLAWBSTER_ROOT`).\n\n### 1. Check Chrome Path\n\n```bash\n# Check if Chrome exists at configured path\ncat .env | grep CHROME_PATH\nls -la \"$(grep CHROME_PATH .env | cut -d= -f2)\" 2>/dev/null || \\\necho \"Chrome not found - update CHROME_PATH in .env\"\n```\n\n### 2. Run Authentication\n\n```bash\nnpx dotenv -e .env -- npx tsx .claude/skills/x-integration/scripts/setup.ts\n```\n\nThis opens Chrome for manual X login. Session saved to `data/x-browser-profile/`.\n\n**Verify success:**\n```bash\ncat data/x-auth.json  # Should show {\"authenticated\": true, ...}\n```\n\n### 3. Rebuild Container\n\n```bash\n./container/build.sh\n```\n\n**Verify success:**\n```bash\n./container/build.sh 2>&1 | grep -i \"agent.ts\"  # Should show COPY line\n```\n\n### 4. Restart Service\n\n```bash\nnpm run build\nlaunchctl kickstart -k gui/$(id -u)/com.nanoclawbster  # macOS\n# Linux: systemctl --user restart nanoclawbster\n```\n\n**Verify success:**\n```bash\nlaunchctl list | grep nanoclawbster  # macOS — should show PID and exit code 0 or -\n# Linux: systemctl --user status nanoclawbster\n```\n\n## Usage via WhatsApp\n\nReplace `@Assistant` with your configured trigger name (`ASSISTANT_NAME` in `.env`):\n\n```\n@Assistant post a tweet: Hello world!\n\n@Assistant like this tweet https://x.com/user/status/123\n\n@Assistant reply to https://x.com/user/status/123 with: Great post!\n\n@Assistant retweet https://x.com/user/status/123\n\n@Assistant quote https://x.com/user/status/123 with comment: Interesting\n```\n\n**Note:** Only the main group can use X tools. Other groups will receive an error.\n\n## Testing\n\nScripts require environment variables from `.env`. Use `dotenv-cli` to load them:\n\n### Check Authentication Status\n\n```bash\n# Check if auth file exists and is valid\ncat data/x-auth.json 2>/dev/null && echo \"Auth configured\" || echo \"Auth not configured\"\n\n# Check if browser profile exists\nls -la data/x-browser-profile/ 2>/dev/null | head -5\n```\n\n### Re-authenticate (if expired)\n\n```bash\nnpx dotenv -e .env -- npx tsx .claude/skills/x-integration/scripts/setup.ts\n```\n\n### Test Post (will actually post)\n\n```bash\necho ''{\"content\":\"Test tweet - please ignore\"}'' | npx dotenv -e .env -- npx tsx .claude/skills/x-integration/scripts/post.ts\n```\n\n### Test Like\n\n```bash\necho ''{\"tweetUrl\":\"https://x.com/user/status/123\"}'' | npx dotenv -e .env -- npx tsx .claude/skills/x-integration/scripts/like.ts\n```\n\nOr export `CHROME_PATH` manually before running:\n\n```bash\nexport CHROME_PATH=\"/path/to/chrome\"\necho ''{\"content\":\"Test\"}'' | npx tsx .claude/skills/x-integration/scripts/post.ts\n```\n\n## Troubleshooting\n\n### Authentication Expired\n\n```bash\nnpx dotenv -e .env -- npx tsx .claude/skills/x-integration/scripts/setup.ts\nlaunchctl kickstart -k gui/$(id -u)/com.nanoclawbster  # macOS\n# Linux: systemctl --user restart nanoclawbster\n```\n\n### Browser Lock Files\n\nIf Chrome fails to launch:\n\n```bash\nrm -f data/x-browser-profile/SingletonLock\nrm -f data/x-browser-profile/SingletonSocket\nrm -f data/x-browser-profile/SingletonCookie\n```\n\n### Check Logs\n\n```bash\n# Host logs (relative to project root)\ngrep -i \"x_post\\|x_like\\|x_reply\\|handleXIpc\" logs/nanoclawbster.log | tail -20\n\n# Script errors\ngrep -i \"error\\|failed\" logs/nanoclawbster.log | tail -20\n```\n\n### Script Timeout\n\nDefault timeout is 2 minutes (120s). Increase in `host.ts`:\n\n```typescript\nconst timer = setTimeout(() => {\n  proc.kill(''SIGTERM'');\n  resolve({ success: false, message: ''Script timed out (120s)'' });\n}, 120000);  // ← Increase this value\n```\n\n### X UI Selector Changes\n\nIf X updates their UI, selectors in scripts may break. Current selectors:\n\n| Element | Selector |\n|---------|----------|\n| Tweet input | `[data-testid=\"tweetTextarea_0\"]` |\n| Post button | `[data-testid=\"tweetButtonInline\"]` |\n| Reply button | `[data-testid=\"reply\"]` |\n| Like | `[data-testid=\"like\"]` |\n| Unlike | `[data-testid=\"unlike\"]` |\n| Retweet | `[data-testid=\"retweet\"]` |\n| Unretweet | `[data-testid=\"unretweet\"]` |\n| Confirm retweet | `[data-testid=\"retweetConfirm\"]` |\n| Modal dialog | `[role=\"dialog\"][aria-modal=\"true\"]` |\n| Modal submit | `[data-testid=\"tweetButton\"]` |\n\n### Container Build Issues\n\nIf MCP tools not found in container:\n\n```bash\n# Verify build copies skill\n./container/build.sh 2>&1 | grep -i skill\n\n# Check container has the file\ndocker run nanoclawbster-agent ls -la /app/src/skills/\n```\n\n## Security\n\n- `data/x-browser-profile/` - Contains X session cookies (in `.gitignore`)\n- `data/x-auth.json` - Auth state marker (in `.gitignore`)\n- Only main group can use X tools (enforced in `agent.ts` and `host.ts`)\n- Scripts run as subprocesses with limited environment"},"lastSynced":"2026-03-06T07:18:44.735Z","agentAnalysis":{"suitability":{"en":"Perfect for Social Media Agents needing automated Twitter interactions via WhatsApp","zh":"非常适合需要通过 WhatsApp 进行自动化 Twitter 交互的社交媒体代理","ja":"WhatsApp を介して自動化された Twitter インタラクションを必要とするソーシャルメディアエージェントに最適","ko":"WhatsApp를 통해 자동화된 Twitter 상호작용이 필요한 소셜미디어 에이전트에게 완벽","es":"Perfecto para agentes de redes sociales que necesitan interacciones automatizadas de Twitter a través de WhatsApp","fr":"Parfait pour les agents de médias sociaux ayant besoin d''interactions Twitter automatisées via WhatsApp","de":"Perfekt für Social Media-Agents, die automatisierte Twitter-Interaktionen über WhatsApp benötigen","pt":"Perfeito para Agentes de Mídia Social que precisam de interações automatizadas do Twitter via WhatsApp","ru":"Идеально для Социальных Медиа Агентов, которым необходимы автоматизированные взаимодействия с Twitter через WhatsApp","ar":"مثالي ليعملاء الوسائط الاجتماعية الذين يحتاجون إلى تفاعلات تويتر آليّة عبر واتساب"},"recommendation":{"en":"Empowers agents to automate Twitter actions like posting, liking, and replying to tweets using browser automation, leveraging tools like x_post, x_like, and x_reply, and supporting protocols via WhatsApp","zh":"赋予代理人使用浏览器自动化、利用工具如 x_post、x_like 和 x_reply 以及通过 WhatsApp 支持的协议来自动化 Twitter 操作，如发布、点赞和回复推文","ja":"エージェントは、ブラウザ自動化を使用し、x_post、x_like、x_reply などのツールを利用し、WhatsApp を介してサポートされるプロトコルを使用して、投稿、いいね、ツイートへの返信などの Twitter アクションを自動化できる","ko":"에이전트가 브라우저 자동화 및 툴(x_post, x_like, x_reply)을 사용하여 WhatsApp를 통해 지원되는 프로토콜을 사용하여 트위터 동작(게시, 좋아요, 트윗에 대한 회신)을 자동화 할 수 있도록 함","es":"Habilita a los agentes a automatizar acciones de Twitter como publicar, dar me gusta y responder a tweets utilizando la automatización del navegador, aprovechando herramientas como x_post, x_like y x_reply, y soportando protocolos a través de WhatsApp","fr":"Permet aux agents d''automatiser les actions Twitter comme la publication, les likes et les réponses aux tweets en utilisant l''automatisation du navigateur, en exploitant des outils comme x_post, x_like et x_reply, et en prenant en charge les protocoles via WhatsApp","de":"Ermächtigt Agenten, Twitter-Aktionen wie das Posten, Liken und Antworten auf Tweets mithilfe der Browserautomatisierung zu automatisieren, indem Tools wie x_post, x_like und x_reply genutzt und Protokolle über WhatsApp unterstützt werden","pt":"Habilita agentes a automatizar ações do Twitter, como postar, curtir e responder a tweets, usando automação de navegador, aproveitando ferramentas como x_post, x_like e x_reply, e suportando protocolos via WhatsApp","ru":"Наделяет агентов возможностью автоматизировать действия в Twitter, такие как публикация, лайки и ответы на твиты, используя автоматизацию браузера, используя инструменты like x_post, x_like и x_reply, и поддержку протоколов через WhatsApp","ar":"يمنح الوكلاء القدرة على توفير إجراءات تويتر مثل النشر والإعجاب والرد على التغريدات باستخدام 자동 браузر ، واستخدام أدوات مثل x_post و x_like و x_reply ، ودعم البروتوكولات عبر واتساب"},"useCases":{"en":["Automating Twitter posts using x_post","Liking tweets with x_like for social media engagement","Replying to tweets using x_reply for customer support"],"zh":["使用 x_post 自动化 Twitter 发布","使用 x_like 点赞推文以提高社交媒体参与度","使用 x_reply 回复推文以提供客户支持"],"ja":["x_post を使用して Twitter 投稿を自動化する","x_like を使用してツイートにいいねしてソーシャルメディアのエンゲージメントを高める","x_reply を使用してツイートに返信してカスタマーサポートを提供する"],"ko":["x_post를 사용하여 트위터 게시물을 자동화","x_like를 사용하여 트윗에 좋아요를 누르고 소셜 미디어 참여도를 높임","x_reply를 사용하여 트윗에 회신하고 고객 지원을 제공"],"es":["Automatizar publicaciones de Twitter con x_post","Dar me gusta a tweets con x_like para la participación en las redes sociales","Responder a tweets con x_reply para el soporte al cliente"],"fr":["Automatiser les publications Twitter avec x_post","Aimer des tweets avec x_like pour l''engagement sur les médias sociaux","Répondre à des tweets avec x_reply pour le support client"],"de":["Twitter-Beiträge mit x_post automatisieren","Tweets mit x_like für soziales Engagement liken","Auf Tweets mit x_reply für Kundensupport antworten"],"pt":["Automatizar postagens do Twitter usando x_post","Curtir tweets com x_like para engajamento nas mídias sociais","Responder a tweets usando x_reply para suporte ao cliente"],"ru":["Автоматизация публикаций в Twitter с помощью x_post","Лайки твитов с помощью x_like для вовлеченности в социальных сетях","Ответы на твиты с помощью x_reply для поддержки клиентов"],"ar":["توفير منشورات تويتر باستخدام x_post","المعجبين التغريدات مع x_like لإشراك الوسائط الاجتماعية","الرد على التغريدات باستخدام x_reply لدعم العملاء"]},"limitations":{"en":["Requires NanoClawbster v1.0.0","Directory structure may change in future versions","Limited to Twitter interactions via WhatsApp"],"zh":["需要 NanoClawbster v1.0.0","目录结构可能在将来的版本中更改","仅限通过 WhatsApp 进行 Twitter 交互"],"ja":["NanoClawbster v1.0.0 が必要","ディレクトリ構造は将来的に変更される可能性がある","WhatsApp を介した Twitter インタラクションのみに制限される"],"ko":["NanoClawbster v1.0.0 필요","디렉토리 구조는 향후 버전에서 변경될 수 있음","WhatsApp를 통해 트위터 상호작용만 제한"],"es":["Requiere NanoClawbster v1.0.0","La estructura del directorio puede cambiar en versiones futuras","Limitado a interacciones de Twitter a través de WhatsApp"],"fr":["Nécessite NanoClawbster v1.0.0","La structure du répertoire peut changer dans les versions futures","Limité aux interactions Twitter via WhatsApp"],"de":["Benötigt NanoClawbster v1.0.0","Das Verzeichnis kann sich in zukünftigen Versionen ändern","Begrenzt auf Twitter-Interaktionen über WhatsApp"],"pt":["Requer NanoClawbster v1.0.0","Estrutura de diretório pode mudar em versões futuras","Limitado a interações do Twitter via WhatsApp"],"ru":["Требуется NanoClawbster v1.0.0","Структура директории может измениться в будущих версиях","Ограничен до взаимодействий с Twitter через WhatsApp"],"ar":["يتطلب NanoClawbster v1.0.0","قد تتغير بنية الدليل في الإصدارات المستقبلية","محدود بالتفاعلات مع تويتر عبر واتساب"]},"version":4},"contentHash":"655b77268a439e729feb4c100a148ca07fdeec8bf6053bf53ecda04f5554c584","qualityScore":60}');
