INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sskarz/nanoclawbster/x-integration', 'x-integration', 'sskarz', 'nanoclawbster', 'community', 'x-integration sskarz nanoclawbster community The x-integration skill enables browser automation for X interactions via WhatsApp, supporting features like posting, liking, and replying to tweets. It benefits developers seeking a lightweight alternative to Clawdbot and OpenClaw. x-integration是一种轻量级的Clawdbot / OpenClaw替代品，运行在容器中以实现安全性，连接WhatsApp，具有内存和调度作业功能，并直接在Anthropic的Agents SDK上运行 x-integrationは、Clawdbot / OpenClawの軽量代替品で、セキュリティを実現するためにコンテナ内で実行され、WhatsApp接続、メモリ、スケジュールジョブ機能を持ち、AnthropicのAgents SDK上で直接実行されます x-integration은 보안을 위해 컨테이너에서 실행되는 Clawdbot / OpenClaw의 경량 대체품으로, WhatsApp 연결, 메모리 및 스케줄 작업 기능을 가지고 Anthropic의 Agents SDK에서 직접 실행됩니다 x-integration es una alternativa ligera para interactuar con Twitter a través de WhatsApp de forma segura x-integration est une alternative légère pour interagir avec Twitter via WhatsApp de manière sécurisée x-integration ist eine leichte Alternative, um mit Twitter über WhatsApp sicher zu interagieren O x-integration é uma solução leve para integração com o WhatsApp, oferecendo memória e trabalhos agendados, além de executar diretamente no Anthropic Agents SDK x-integration - это лёгкое решение для интеграции с WhatsApp, предлагающее память и запланированные задания, а также выполняющееся直接 на Anthropic Agents SDK x-integration هو حل خفيف لدمج WhatsApp، يوفر الذاكرة والمهام المجدولة، بالإضافة إلى التشغيل المباشر على Anthropic Agents SDK how to use x-integration x-integration alternative to Clawdbot x-integration vs OpenClaw x-integration install guide x-integration setup for WhatsApp automation what is x-integration x-integration documentation x-integration tutorial x-integration and Anthropic''s Agents SDK x-integration AIエージェント WhatsApp连接 安全容器化 内存功能 调度作业功能 Anthropic Agents SDK Twitter自动化 浏览器自动化 Publish new tweets using the `x_post` command Like any tweet with the `x_like` tool Reply to tweets using the `x_reply` feature Retweet without comment via the `x_retweet` action Quote tweet with comment using the `x_quote` functionality x-integration is a lightweight container-based alternative to Clawdbot and OpenClaw, designed for secure WhatsApp automation and integration with Anthropic''s Agents SDK.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('rzx007/nanobot-ts/agent-browser', 'community', 'rzx007', 'nanobot-ts', 'rzx007/nanobot-ts', 'agent-browser', 1, 0, 60, '2026-03-04T08:00:39Z', '2026-03-06T07:18:54.740Z', 'bb56836161e6742c3da245b775c194164a202b4580deabe109dc6e66e3356d47', '{"id":"rzx007/nanobot-ts/agent-browser","name":"agent-browser","description":{"en":"agent-browser is a TypeScript-based personal AI assistant framework for ultra-lightweight browser automation, benefiting developers and testers. It enables automated browsing and interaction with web pages.","zh":"agent-browser 是一个用于浏览器自动化的 AI 框架，支持导航、快照和交互等功能","ja":"agent-browser は、ナビゲーション、スナップショット、インタラクションなどの機能をサポートするブラウザ自動化の AI フレームワークです","ko":"agent-browser는 네비게이션, 스냅샷, 상호작용 등을 지원하는 브라우저 자동화용 AI 프레임워크입니다","es":"Agent-browser es un framework de asistente de IA personal para la automatización de navegadores, que permite la interacción con elementos de la página web.","fr":"Agent-browser est un framework d''assistant de IA personnel pour l''automatisation des navigateurs, qui permet l''interaction avec les éléments de la page web.","de":"Agent-browser ist ein Framework für persönliche IA-Assistenten zur Browser-Automatisierung, das die Interaktion mit Elementen der Webseite ermöglicht.","pt":"O agent-browser é um framework de assistente de IA ultra-leve para automação de navegador com TypeScript e nanobot-ts.","ru":"Agent-browser - это ультралёгкий фреймворк помощника ИИ для автоматизации браузера с помощью TypeScript и nanobot-ts.","ar":"agent-browser هو إطار عمل مساعد ذكاء اصطناعي خفيف الوزن لتحكم المتصفح باستخدام TypeScript و nanobot-ts."},"seo":{"title":{"en":"agent-browser: Browser Automation Setup Guide | AI Agent ...","zh":"agent-browser 入门指南：AI 浏览器自动化","ja":"agent-browser セットアップガイド：AI エージェントによるブラウザ自動化","ko":"agent-browser 시작하기: AI 브라우저 자동화 솔루션","es":"Guía de configuración de agent-browser para automatizació...","fr":"Guide d''installation d''agent-browser pour l''automatisatio...","de":"Einrichtungsleitfaden für agent-browser zur Browser-Autom...","pt":"Guia de Configuração do agent-browser para Automação de N...","ru":"Руководство по настройке agent-browser для автоматизации ...","ar":"دليل إعداد agent-browser لتحكم المتصفح بالعربية باستخدام ..."},"description":{"en":"Unlock efficient browser automation with agent-browser. Learn how to navigate, snapshot, and interact with web pages using commands like ''agent-browser open''...","zh":"了解 agent-browser 的核心工作流程，包括导航、快照、交互和重新快照，实现 AI 浏览器自动化","ja":"agent-browser の核心ワークフローを学び、ナビゲーション、スナップショット、インタラクション、再スナップショットを実現して AI ブラウザ自動化を実現する","ko":"agent-browser의 핵심 워크플로우에 대해 알아보고, 네비게이션, 스냅샷, 상호작용 및 재스냅샷을 통해 AI 브라우저 자동화를 실현하세요","es":"Aprende a utilizar agent-browser para automatizar tareas en el navegador con comandos como ''open'' y ''snapshot''","fr":"Découvrez comment utiliser agent-browser pour automatiser des tâches dans le navigateur avec des commandes comme ''open'' et ''snapshot''","de":"Erfahren Sie, wie Sie agent-browser verwenden, um Aufgaben im Browser mit Befehlen wie ''open'' und ''snapshot'' zu automatisieren","pt":"Aprenda a utilizar o agent-browser para automação de navegador com TypeScript e nanobot-ts, incluindo navegação, captura de tela e interação com elementos","ru":"Узнайте, как использовать agent-browser для автоматизации браузера с помощью TypeScript и nanobot-ts, включая навигацию, создание снимков и взаимодействие с ...","ar":"تعلم كيفية استخدام agent-browser لتحكم المتصفح باستخدام TypeScript و nanobot-ts، بما في ذلك التنقل وتحديد الشاشة والتفاعل مع العناصر باستخدام أدوات الذكاء ال..."},"definition":{"en":"agent-browser is an ultra-lightweight personal AI assistant framework for browser automation, utilizing TypeScript and commands like ''agent-browser open'' and ''agent-browser snapshot'' for navigation and interaction","zh":"agent-browser 是一个用于浏览器自动化的 AI 框架","ja":"agent-browser はブラウザ自動化の AI フレームワークである","ko":"agent-browser는 브라우저 자동화를 위한 AI 프레임워크이다","es":"Agent-browser es un framework de automatización de navegador que utiliza comandos como ''open'' y ''snapshot'' para interactuar con la página web.","fr":"Agent-browser est un framework d''automatisation du navigateur qui utilise des commandes comme ''open'' et ''snapshot'' pour interagir avec la page web.","de":"Agent-browser ist ein Framework zur Browser-Automatisierung, das Befehle wie ''open'' und ''snapshot'' verwendet, um mit der Webseite zu interagieren.","pt":"O que é agent-browser? Um framework de automação de navegador com TypeScript e nanobot-ts para criação de assistentes de IA.","ru":"Что такое agent-browser? Фреймворк для автоматизации браузера с помощью TypeScript и nanobot-ts для создания помощников ИИ.","ar":"ما هو agent-browser؟ إطار عمل لتحكم المتصفح باستخدام TypeScript و nanobot-ts لإنشاء مساعدين ذكاء اصطناعي."},"features":{"en":["Navigates to web pages using ''agent-browser open'' command","Captures snapshots of web pages with ''agent-browser snapshot'' command","Enables interaction with web page elements using refs like ''@e1'', ''@e2''","Supports re-snapshotting after navigation or DOM changes","Utilizes TypeScript for ultra-lightweight browser automation"],"zh":["支持导航功能：agent-browser open <url>","支持快照功能：agent-browser snapshot -i","支持交互功能：使用 refs 点击、填充、选择","支持重新快照功能：在导航或 DOM 变化后获取新鲜的 refs","基于 TypeScript 的 nanobot 框架","轻量级的个人 AI 助手框架"],"ja":["ナビゲーション機能のサポート：agent-browser open <url>","スナップショット機能のサポート：agent-browser snapshot -i","インタラクション機能のサポート：refs を使用してクリック、入力、選択","再スナップショット機能のサポート：ナビゲーションまたは DOM 変化後に新しい refs を取得","TypeScript ベースの nanobot フレームワーク","軽量の個人 AI アシスタント フレームワーク"],"ko":["네비게이션 기능 지원: agent-browser open <url>","스냅샷 기능 지원: agent-browser snapshot -i","상호작용 기능 지원: refs를 사용하여 클릭, 입력, 선택","재스냅샷 기능 지원: 네비게이션 또는 DOM 변경 후 새로운 refs를 얻기","TypeScript 기반의 nanobot 프레임워크","軽量의 개인 AI アシスタント 프레임워크"],"es":["Automatización de navegadores con comandos como ''open'' y ''snapshot''","Interacción con elementos de la página web utilizando referencias como ''@e1'' y ''@e2''","Soporte para la navegación y la interacción con formularios","Capacidad para obtener referencias frescas después de cambios en la página web","Integración con la versión de TypeScript de nanobot, nanobot-ts"],"fr":["Automatisation des navigateurs avec des commandes comme ''open'' et ''snapshot''","Interaction avec les éléments de la page web en utilisant des références comme ''@e1'' et ''@e2''","Prise en charge de la navigation et de l''interaction avec les formulaires","Capacité à obtenir des références fraîches après des modifications de la page web","Intégration avec la version TypeScript de nanobot, nanobot-ts"],"de":["Browser-Automatisierung mit Befehlen wie ''open'' und ''snapshot''","Interaktion mit Elementen der Webseite unter Verwendung von Referenzen wie ''@e1'' und ''@e2''","Unterstützung für die Navigation und die Interaktion mit Formularen","Fähigkeit, nach Änderungen der Webseite frische Referenzen zu erhalten","Integration mit der TypeScript-Version von nanobot, nanobot-ts"],"pt":["Automação de navegador com TypeScript","Uso de nanobot-ts para criação de assistentes de IA","Navegação e captura de tela com agent-browser","Interação com elementos da página com agent-browser","Suporte a comandos CLI para automação"],"ru":["Автоматизация браузера с помощью TypeScript","Использование nanobot-ts для создания помощников ИИ","Навигация и создание снимков с помощью agent-browser","Взаимодействие с элементами страницы с помощью agent-browser","Поддержка команд CLI для автоматизации с помощью ИИ Агентов"],"ar":["تحكم المتصفح باستخدام TypeScript","استخدام nanobot-ts لإنشاء مساعدين ذكاء اصطناعي","التنقل وتحديد الشاشة باستخدام agent-browser","التفاعل مع العناصر باستخدام agent-browser","دعم أوامر CLI لتحكم المتصفح باستخدام أدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use agent-browser","agent-browser setup guide","agent-browser vs nanobot","agent-browser install","what is agent-browser","browser automation with agent-browser","agent-browser alternative","agent-browser tutorial"],"zh":["agent-browser","AI 浏览器自动化","nanobot","TypeScript","浏览器自动化框架","AI 工具","个人 AI 助手"],"ja":["agent-browser","AI ブラウザ自動化","nanobot","TypeScript","ブラウザ自動化フレームワーク","AI エージェント","個人 AI アシスタント"],"ko":["agent-browser","AI 브라우저 자동화","nanobot","TypeScript","브라우저 자동화 프레임워크","AI 에이전트","개인 AI 어시스턴트"],"es":["agent-browser","automatización de navegador","nanobot-ts","ai agent","herramientas de ia","automatización de formularios","referencias de elementos","navegación web"],"fr":["agent-browser","automatisation du navigateur","nanobot-ts","agent de ia","outils de ia","automatisation de formulaires","références d''éléments","navigation web"],"de":["agent-browser","browser-automatisierung","nanobot-ts","ia-agent","ia-tools","formularautomatisierung","elementreferenzen","webnavigation"],"pt":["agent-browser","automação de navegador","TypeScript","nanobot-ts","assistente de IA","comandos CLI","navegação","captura de tela"],"ru":["agent-browser","автоматизация браузера","TypeScript","nanobot-ts","помощник ИИ","команды CLI","навигация","создание снимков","ИИ Агенты"],"ar":["agent-browser","تحكم المتصفح","TypeScript","nanobot-ts","مساعد ذكاء اصطناعي","أوامر CLI","التنقل","تحديد الشاشة","أدوات الذكاء الاصطناعي"]}},"owner":"rzx007","repo":"nanobot-ts","repoPath":"rzx007/nanobot-ts","stars":1,"forks":0,"updatedAt":"2026-03-04T08:00:39Z","topics":["ai-agent","nanobot","nanobot-ts"],"category":"community","skillMd":{"name":"agent-browser","description":"Browser automation CLI for AI agents. Use when the user needs to interact with websites, including navigating pages, filling forms, clicking buttons, taking screenshots, extracting data, testing web apps, or automating any browser task. Triggers include requests to open a website, fill out a form, click a button, take a screenshot, scrape data from a page, test this web app, login to a site, automate browser actions, or any task requiring programmatic web interaction.","bodyPreview":"# Browser Automation with agent-browser\n\n## Core Workflow\n\nEvery browser automation follows this pattern:\n\n1. **Navigate**: `agent-browser open <url>`\n2. **Snapshot**: `agent-browser snapshot -i` (get element refs like `@e1`, `@e2`)\n3. **Interact**: Use refs to click, fill, select\n4. **Re-snapshot**: After navigation or DOM changes, get fresh refs\n\n```bash\nagent-browser open https://example.com/form\nagent-browser snapshot -i\n# Output: @e1 [input type=\"email\"], @e2 [input type=\"password\"], @e3 [b","body":"# Browser Automation with agent-browser\n\n## Core Workflow\n\nEvery browser automation follows this pattern:\n\n1. **Navigate**: `agent-browser open <url>`\n2. **Snapshot**: `agent-browser snapshot -i` (get element refs like `@e1`, `@e2`)\n3. **Interact**: Use refs to click, fill, select\n4. **Re-snapshot**: After navigation or DOM changes, get fresh refs\n\n```bash\nagent-browser open https://example.com/form\nagent-browser snapshot -i\n# Output: @e1 [input type=\"email\"], @e2 [input type=\"password\"], @e3 [button] \"Submit\"\n\nagent-browser fill @e1 \"user@example.com\"\nagent-browser fill @e2 \"password123\"\nagent-browser click @e3\nagent-browser wait --load networkidle\nagent-browser snapshot -i  # Check result\n```\n\n## Command Chaining\n\nCommands can be chained with `&&` in a single shell invocation. The browser persists between commands via a background daemon, so chaining is safe and more efficient than separate calls.\n\n```bash\n# Chain open + wait + snapshot in one call\nagent-browser open https://example.com && agent-browser wait --load networkidle && agent-browser snapshot -i\n\n# Chain multiple interactions\nagent-browser fill @e1 \"user@example.com\" && agent-browser fill @e2 \"password123\" && agent-browser click @e3\n\n# Navigate and capture\nagent-browser open https://example.com && agent-browser wait --load networkidle && agent-browser screenshot page.png\n```\n\n**When to chain:** Use `&&` when you don''t need to read the output of an intermediate command before proceeding (e.g., open + wait + screenshot). Run commands separately when you need to parse the output first (e.g., snapshot to discover refs, then interact using those refs).\n\n## Essential Commands\n\n```bash\n# Navigation\nagent-browser open <url>              # Navigate (aliases: goto, navigate)\nagent-browser close                   # Close browser\n\n# Snapshot\nagent-browser snapshot -i             # Interactive elements with refs (recommended)\nagent-browser snapshot -i -C          # Include cursor-interactive elements (divs with onclick, cursor:pointer)\nagent-browser snapshot -s \"#selector\" # Scope to CSS selector\n\n# Interaction (use @refs from snapshot)\nagent-browser click @e1               # Click element\nagent-browser click @e1 --new-tab     # Click and open in new tab\nagent-browser fill @e2 \"text\"         # Clear and type text\nagent-browser type @e2 \"text\"         # Type without clearing\nagent-browser select @e1 \"option\"     # Select dropdown option\nagent-browser check @e1               # Check checkbox\nagent-browser press Enter             # Press key\nagent-browser keyboard type \"text\"    # Type at current focus (no selector)\nagent-browser keyboard inserttext \"text\"  # Insert without key events\nagent-browser scroll down 500         # Scroll page\nagent-browser scroll down 500 --selector \"div.content\"  # Scroll within a specific container\n\n# Get information\nagent-browser get text @e1            # Get element text\nagent-browser get url                 # Get current URL\nagent-browser get title               # Get page title\n\n# Wait\nagent-browser wait @e1                # Wait for element\nagent-browser wait --load networkidle # Wait for network idle\nagent-browser wait --url \"**/page\"    # Wait for URL pattern\nagent-browser wait 2000               # Wait milliseconds\n\n# Downloads\nagent-browser download @e1 ./file.pdf          # Click element to trigger download\nagent-browser wait --download ./output.zip     # Wait for any download to complete\nagent-browser --download-path ./downloads open <url>  # Set default download directory\n\n# Capture\nagent-browser screenshot              # Screenshot to temp dir\nagent-browser screenshot --full       # Full page screenshot\nagent-browser screenshot --annotate   # Annotated screenshot with numbered element labels\nagent-browser pdf output.pdf          # Save as PDF\n\n# Diff (compare page states)\nagent-browser diff snapshot                          # Compare current vs last snapshot\nagent-browser diff snapshot --baseline before.txt    # Compare current vs saved file\nagent-browser diff screenshot --baseline before.png  # Visual pixel diff\nagent-browser diff url <url1> <url2>                 # Compare two pages\nagent-browser diff url <url1> <url2> --wait-until networkidle  # Custom wait strategy\nagent-browser diff url <url1> <url2> --selector \"#main\"  # Scope to element\n```\n\n## Common Patterns\n\n### Form Submission\n\n```bash\nagent-browser open https://example.com/signup\nagent-browser snapshot -i\nagent-browser fill @e1 \"Jane Doe\"\nagent-browser fill @e2 \"jane@example.com\"\nagent-browser select @e3 \"California\"\nagent-browser check @e4\nagent-browser click @e5\nagent-browser wait --load networkidle\n```\n\n### Authentication with Auth Vault (Recommended)\n\n```bash\n# Save credentials once (encrypted with AGENT_BROWSER_ENCRYPTION_KEY)\n# Recommended: pipe password via stdin to avoid shell history exposure\necho \"pass\" | agent-browser auth save github --url https://github.com/login --username user --password-stdin\n\n# Login using saved profile (LLM never sees password)\nagent-browser auth login github\n\n# List/show/delete profiles\nagent-browser auth list\nagent-browser auth show github\nagent-browser auth delete github\n```\n\n### Authentication with State Persistence\n\n```bash\n# Login once and save state\nagent-browser open https://app.example.com/login\nagent-browser snapshot -i\nagent-browser fill @e1 \"$USERNAME\"\nagent-browser fill @e2 \"$PASSWORD\"\nagent-browser click @e3\nagent-browser wait --url \"**/dashboard\"\nagent-browser state save auth.json\n\n# Reuse in future sessions\nagent-browser state load auth.json\nagent-browser open https://app.example.com/dashboard\n```\n\n### Session Persistence\n\n```bash\n# Auto-save/restore cookies and localStorage across browser restarts\nagent-browser --session-name myapp open https://app.example.com/login\n# ... login flow ...\nagent-browser close  # State auto-saved to ~/.agent-browser/sessions/\n\n# Next time, state is auto-loaded\nagent-browser --session-name myapp open https://app.example.com/dashboard\n\n# Encrypt state at rest\nexport AGENT_BROWSER_ENCRYPTION_KEY=$(openssl rand -hex 32)\nagent-browser --session-name secure open https://app.example.com\n\n# Manage saved states\nagent-browser state list\nagent-browser state show myapp-default.json\nagent-browser state clear myapp\nagent-browser state clean --older-than 7\n```\n\n### Data Extraction\n\n```bash\nagent-browser open https://example.com/products\nagent-browser snapshot -i\nagent-browser get text @e5           # Get specific element text\nagent-browser get text body > page.txt  # Get all page text\n\n# JSON output for parsing\nagent-browser snapshot -i --json\nagent-browser get text @e1 --json\n```\n\n### Parallel Sessions\n\n```bash\nagent-browser --session site1 open https://site-a.com\nagent-browser --session site2 open https://site-b.com\n\nagent-browser --session site1 snapshot -i\nagent-browser --session site2 snapshot -i\n\nagent-browser session list\n```\n\n### Connect to Existing Chrome\n\n```bash\n# Auto-discover running Chrome with remote debugging enabled\nagent-browser --auto-connect open https://example.com\nagent-browser --auto-connect snapshot\n\n# Or with explicit CDP port\nagent-browser --cdp 9222 snapshot\n```\n\n### Color Scheme (Dark Mode)\n\n```bash\n# Persistent dark mode via flag (applies to all pages and new tabs)\nagent-browser --color-scheme dark open https://example.com\n\n# Or via environment variable\nAGENT_BROWSER_COLOR_SCHEME=dark agent-browser open https://example.com\n\n# Or set during session (persists for subsequent commands)\nagent-browser set media dark\n```\n\n### Visual Browser (Debugging)\n\n```bash\nagent-browser --headed open https://example.com\nagent-browser highlight @e1          # Highlight element\nagent-browser record start demo.webm # Record session\nagent-browser profiler start         # Start Chrome DevTools profiling\nagent-browser profiler stop trace.json # Stop and save profile (path optional)\n```\n\n### Local Files (PDFs, HTML)\n\n```bash\n# Open local files with file:// URLs\nagent-browser --allow-file-access open file:///path/to/document.pdf\nagent-browser --allow-file-access open file:///path/to/page.html\nagent-browser screenshot output.png\n```\n\n### iOS Simulator (Mobile Safari)\n\n```bash\n# List available iOS simulators\nagent-browser device list\n\n# Launch Safari on a specific device\nagent-browser -p ios --device \"iPhone 16 Pro\" open https://example.com\n\n# Same workflow as desktop - snapshot, interact, re-snapshot\nagent-browser -p ios snapshot -i\nagent-browser -p ios tap @e1          # Tap (alias for click)\nagent-browser -p ios fill @e2 \"text\"\nagent-browser -p ios swipe up         # Mobile-specific gesture\n\n# Take screenshot\nagent-browser -p ios screenshot mobile.png\n\n# Close session (shuts down simulator)\nagent-browser -p ios close\n```\n\n**Requirements:** macOS with Xcode, Appium (`npm install -g appium && appium driver install xcuitest`)\n\n**Real devices:** Works with physical iOS devices if pre-configured. Use `--device \"<UDID>\"` where UDID is from `xcrun xctrace list devices`.\n\n## Security\n\nAll security features are opt-in. By default, agent-browser imposes no restrictions on navigation, actions, or output.\n\n### Content Boundaries (Recommended for AI Agents)\n\nEnable `--content-boundaries` to wrap page-sourced output in markers that help LLMs distinguish tool output from untrusted page content:\n\n```bash\nexport AGENT_BROWSER_CONTENT_BOUNDARIES=1\nagent-browser snapshot\n# Output:\n# --- AGENT_BROWSER_PAGE_CONTENT nonce=<hex> origin=https://example.com ---\n# [accessibility tree]\n# --- END_AGENT_BROWSER_PAGE_CONTENT nonce=<hex> ---\n```\n\n### Domain Allowlist\n\nRestrict navigation to trusted domains. Wildcards like `*.example.com` also match the bare domain `example.com`. Sub-resource requests, WebSocket, and EventSource connections to non-allowed domains are also blocked. Include CDN domains your target pages depend on:\n\n```bash\nexport AGENT_BROWSER_ALLOWED_DOMAINS=\"example.com,*.example.com\"\nagent-browser open https://example.com        # OK\nagent-browser open https://malicious.com       # Blocked\n```\n\n### Action Policy\n\nUse a policy file to gate destructive actions:\n\n```bash\nexport AGENT_BROWSER_ACTION_POLICY=./policy.json\n```\n\nExample `policy.json`:\n```json\n{\"default\": \"deny\", \"allow\": [\"navigate\", \"snapshot\", \"click\", \"scroll\", \"wait\", \"get\"]}\n```\n\nAuth vault operations (`auth login`, etc.) bypass action policy but domain allowlist still applies.\n\n### Output Limits\n\nPrevent context flooding from large pages:\n\n```bash\nexport AGENT_BROWSER_MAX_OUTPUT=50000\n```\n\n## Diffing (Verifying Changes)\n\nUse `diff snapshot` after performing an action to verify it had the intended effect. This compares the current accessibility tree against the last snapshot taken in the session.\n\n```bash\n# Typical workflow: snapshot -> action -> diff\nagent-browser snapshot -i          # Take baseline snapshot\nagent-browser click @e2            # Perform action\nagent-browser diff snapshot        # See what changed (auto-compares to last snapshot)\n```\n\nFor visual regression testing or monitoring:\n\n```bash\n# Save a baseline screenshot, then compare later\nagent-browser screenshot baseline.png\n# ... time passes or changes are made ...\nagent-browser diff screenshot --baseline baseline.png\n\n# Compare staging vs production\nagent-browser diff url https://staging.example.com https://prod.example.com --screenshot\n```\n\n`diff snapshot` output uses `+` for additions and `-` for removals, similar to git diff. `diff screenshot` produces a diff image with changed pixels highlighted in red, plus a mismatch percentage.\n\n## Timeouts and Slow Pages\n\nThe default Playwright timeout is 25 seconds for local browsers. This can be overridden with the `AGENT_BROWSER_DEFAULT_TIMEOUT` environment variable (value in milliseconds). For slow websites or large pages, use explicit waits instead of relying on the default timeout:\n\n```bash\n# Wait for network activity to settle (best for slow pages)\nagent-browser wait --load networkidle\n\n# Wait for a specific element to appear\nagent-browser wait \"#content\"\nagent-browser wait @e1\n\n# Wait for a specific URL pattern (useful after redirects)\nagent-browser wait --url \"**/dashboard\"\n\n# Wait for a JavaScript condition\nagent-browser wait --fn \"document.readyState === ''complete''\"\n\n# Wait a fixed duration (milliseconds) as a last resort\nagent-browser wait 5000\n```\n\nWhen dealing with consistently slow websites, use `wait --load networkidle` after `open` to ensure the page is fully loaded before taking a snapshot. If a specific element is slow to render, wait for it directly with `wait <selector>` or `wait @ref`.\n\n## Session Management and Cleanup\n\nWhen running multiple agents or automations concurrently, always use named sessions to avoid conflicts:\n\n```bash\n# Each agent gets its own isolated session\nagent-browser --session agent1 open site-a.com\nagent-browser --session agent2 open site-b.com\n\n# Check active sessions\nagent-browser session list\n```\n\nAlways close your browser session when done to avoid leaked processes:\n\n```bash\nagent-browser close                    # Close default session\nagent-browser --session agent1 close   # Close specific session\n```\n\nIf a previous session was not closed properly, the daemon may still be running. Use `agent-browser close` to clean it up before starting new work.\n\n## Ref Lifecycle (Important)\n\nRefs (`@e1`, `@e2`, etc.) are invalidated when the page changes. Always re-snapshot after:\n\n- Clicking links or buttons that navigate\n- Form submissions\n- Dynamic content loading (dropdowns, modals)\n\n```bash\nagent-browser click @e5              # Navigates to new page\nagent-browser snapshot -i            # MUST re-snapshot\nagent-browser click @e1              # Use new refs\n```\n\n## Annotated Screenshots (Vision Mode)\n\nUse `--annotate` to take a screenshot with numbered labels overlaid on interactive elements. Each label `[N]` maps to ref `@eN`. This also caches refs, so you can interact with elements immediately without a separate snapshot.\n\n```bash\nagent-browser screenshot --annotate\n# Output includes the image path and a legend:\n#   [1] @e1 button \"Submit\"\n#   [2] @e2 link \"Home\"\n#   [3] @e3 textbox \"Email\"\nagent-browser click @e2              # Click using ref from annotated screenshot\n```\n\nUse annotated screenshots when:\n- The page has unlabeled icon buttons or visual-only elements\n- You need to verify visual layout or styling\n- Canvas or chart elements are present (invisible to text snapshots)\n- You need spatial reasoning about element positions\n\n## Semantic Locators (Alternative to Refs)\n\nWhen refs are unavailable or unreliable, use semantic locators:\n\n```bash\nagent-browser find text \"Sign In\" click\nagent-browser find label \"Email\" fill \"user@test.com\"\nagent-browser find role button click --name \"Submit\"\nagent-browser find placeholder \"Search\" type \"query\"\nagent-browser find testid \"submit-btn\" click\n```\n\n## JavaScript Evaluation (eval)\n\nUse `eval` to run JavaScript in the browser context. **Shell quoting can corrupt complex expressions** -- use `--stdin` or `-b` to avoid issues.\n\n```bash\n# Simple expressions work with regular quoting\nagent-browser eval ''document.title''\nagent-browser eval ''document.querySelectorAll(\"img\").length''\n\n# Complex JS: use --stdin with heredoc (RECOMMENDED)\nagent-browser eval --stdin <<''EVALEOF''\nJSON.stringify(\n  Array.from(document.querySelectorAll(\"img\"))\n    .filter(i => !i.alt)\n    .map(i => ({ src: i.src.split(\"/\").pop(), width: i.width }))\n)\nEVALEOF\n\n# Alternative: base64 encoding (avoids all shell escaping issues)\nagent-browser eval -b \"$(echo -n ''Array.from(document.querySelectorAll(\"a\")).map(a => a.href)'' | base64)\"\n```\n\n**Why this matters:** When the shell processes your command, inner double quotes, `!` characters (history expansion), backticks, and `$()` can all corrupt the JavaScript before it reaches agent-browser. The `--stdin` and `-b` flags bypass shell interpretation entirely.\n\n**Rules of thumb:**\n- Single-line, no nested quotes -> regular `eval ''expression''` with single quotes is fine\n- Nested quotes, arrow functions, template literals, or multiline -> use `eval --stdin <<''EVALEOF''`\n- Programmatic/generated scripts -> use `eval -b` with base64\n\n## Configuration File\n\nCreate `agent-browser.json` in the project root for persistent settings:\n\n```json\n{\n  \"headed\": true,\n  \"proxy\": \"http://localhost:8080\",\n  \"profile\": \"./browser-data\"\n}\n```\n\nPriority (lowest to highest): `~/.agent-browser/config.json` < `./agent-browser.json` < env vars < CLI flags. Use `--config <path>` or `AGENT_BROWSER_CONFIG` env var for a custom config file (exits with error if missing/invalid). All CLI options map to camelCase keys (e.g., `--executable-path` -> `\"executablePath\"`). Boolean flags accept `true`/`false` values (e.g., `--headed false` overrides config). Extensions from user and project configs are merged, not replaced.\n\n## Deep-Dive Documentation\n\n| Reference | When to Use |\n|-----------|-------------|\n| [references/commands.md](references/commands.md) | Full command reference with all options |\n| [references/snapshot-refs.md](references/snapshot-refs.md) | Ref lifecycle, invalidation rules, troubleshooting |\n| [references/session-management.md](references/session-management.md) | Parallel sessions, state persistence, concurrent scraping |\n| [references/authentication.md](references/authentication.md) | Login flows, OAuth, 2FA handling, state reuse |\n| [references/video-recording.md](references/video-recording.md) | Recording workflows for debugging and documentation |\n| [references/profiling.md](references/profiling.md) | Chrome DevTools profiling for performance analysis |\n| [references/proxy-support.md](references/proxy-support.md) | Proxy configuration, geo-testing, rotating proxies |\n\n## Experimental: Native Mode\n\nagent-browser has an experimental native Rust daemon that communicates with Chrome directly via CDP, bypassing Node.js and Playwright entirely. It is opt-in and not recommended for production use yet.\n\n```bash\n# Enable via flag\nagent-browser --native open example.com\n\n# Enable via environment variable (avoids passing --native every time)\nexport AGENT_BROWSER_NATIVE=1\nagent-browser open example.com\n```\n\nThe native daemon supports Chromium and Safari (via WebDriver). Firefox and WebKit are not yet supported. All core commands (navigate, snapshot, click, fill, screenshot, cookies, storage, tabs, eval, etc.) work identically in native mode. Use `agent-browser close` before switching between native and default mode within the same session.\n\n## Ready-to-Use Templates\n\n| Template | Description |\n|----------|-------------|\n| [templates/form-automation.sh](templates/form-automation.sh) | Form filling with validation |\n| [templates/authenticated-session.sh](templates/authenticated-session.sh) | Login once, reuse state |\n| [templates/capture-workflow.sh](templates/capture-workflow.sh) | Content extraction with screenshots |\n\n```bash\n./templates/form-automation.sh https://example.com/form\n./templates/authenticated-session.sh https://app.example.com/login\n./templates/capture-workflow.sh https://example.com ./output\n```\n"},"lastSynced":"2026-03-06T07:18:54.740Z","agentAnalysis":{"suitability":{"en":"Perfect for Automation Agents needing lightweight browser interaction and ultra-fast webpage navigation capabilities.","zh":"适用于需要轻量级浏览器交互和超快网页导航能力的自动化Agent。","ja":"自動化エージェントが軽量のブラウザーとのやり取りと超高速のウェブページナビゲーション機能を必要とする場合に最適です。","ko":"자동화 에이전트가 가벼운 브라우저 상호작용과 초고속 웹 페이지导航 기능을 필요로 할 때 적합합니다.","es":"Perfecto para Agentes de Automatización que necesitan interacción con el navegador ligero y capacidades de navegación de páginas web ultra rápidas.","fr":"Parfait pour les Agents d''Automatisation ayant besoin d''une interaction avec le navigateur légère et de capacités de navigation de pages web ultra rapides.","de":"Perfekt für Automatisierungsagenten, die eine leichte Browserinteraktion und ultrraschnelle Webseitennavigationsfunktionen benötigen.","pt":"Perfeito para Agentes de Automação que necessitam de interação de navegador leve e capacidades de navegação de página ultra-rápidas.","ru":"Идеально подходит для агентов автоматизации, которым необходима лёгкая интеракция с браузером и сверхбыстрая навигация по страницам.","ar":"مثالي للوكلاء الآليين الذين يحتاجون إلى تفاعل مع متصفح خفيف وسمات التنقل في الصفحة فائقة السرعة."},"recommendation":{"en":"Empowers agents to automate browsing and interaction with web pages using TypeScript, enabling seamless navigation, snapshotting, and interaction with web elements via refs like @e1, @e2, leveraging protocols and libraries for efficient browser automation.","zh":"赋予代理人使用TypeScript自动化浏览和与网页交互的能力，实现无缝导航、快照和通过refs（如@e1、@e2）与网页元素交互，利用协议和库实现高效的浏览器自动化。","ja":"TypeScriptを使用してエージェントがブラウザーの自動化とWebページとのやり取りを可能にし、シームレスなナビゲーション、スナップショットの取得、@e1、@e2などのrefsを介したWeb要素とのやり取りを可能にし、プロトコルとライブラリを利用して効率的なブラウザーの自動化を実現します。","ko":"에이전트가 TypeScript를 사용하여 브라우징과 웹 페이지 상호작용을 자동화할 수 있도록 하며, 無縫な 네비게이션, 스냅샷ting, @e1, @e2 등의 refs를 통해 웹 요소와 상호작용할 수 있도록 하며, 프로토콜 및 라이브러리를 활용하여 효율적인 브라우저 자동화를 실現합니다.","es":"Habilita a los agentes a automatizar la navegación y la interacción con páginas web utilizando TypeScript, lo que permite una navegación fluida, la captura de instantáneas y la interacción con elementos web a través de referencias como @e1, @e2, aprovechando protocolos y bibliotecas para una automatización de navegador eficiente.","fr":"Permet aux agents d''automatiser la navigation et l''interaction avec les pages web en utilisant TypeScript, permettant ainsi une navigation fluide, la capture d''images et l''interaction avec les éléments web via des références comme @e1, @e2, en exploitant les protocoles et les bibliothèques pour une automation de navigateur efficace.","de":"Ermöglicht es den Agenten, die Navigation und Interaktion mit Webseiten mithilfe von TypeScript zu automatisieren, wodurch eine nahtlose Navigation, Momentaufnahmen und Interaktion mit Web-Elementen über Referenzen wie @e1, @e2 ermöglicht wird, wobei Protokolle und Bibliotheken für eine effiziente Browser-Automatisierung genutzt werden.","pt":"Habilita agentes a automatizar a navegação e interação com páginas da web usando TypeScript, permitindo navegação sem problemas, captura de imagens e interação com elementos da web via refs como @e1, @e2, aproveitando protocolos e bibliotecas para automação de navegador eficiente.","ru":"Наделяет агентов возможностью автоматизировать навигацию и взаимодействие с веб-страницами с помощью TypeScript, обеспечивая бесшовную навигацию, создание снимков и взаимодействие с веб-элементами через ссылки wie @e1, @e2, используя протоколы и библиотеки для эффективной автоматизации браузера.","ar":"تمكين الوكلاء من توفير التفاعل مع صفحات الويب باستخدام TypeScript، وتمكين التنقل السلس والتصوير والتفاعل مع عناصر الويب عبر المراجع مثل @e1، @e2، وتحقيق البروتوكولات والمكتبات لتحقيق автомatisation الكفاءة لمتصفح الويب."},"useCases":{"en":["Automating web form submissions","Interacting with dynamic web pages","Debugging web application workflows"],"zh":["自动化网页表单提交","与动态网页交互","调试网页应用程序工作流"],"ja":["Webフォームの自動送信","動的Webページとのやり取り","Webアプリケーションのワークフローのデバッグ"],"ko":["웹 폼 자동 제출","동적 웹 페이지와의 상호작용","웹 애플리케이션 워크플로우 디버깅"],"es":["Automatización de envíos de formularios web","Interacción con páginas web dinámicas","Depuración de flujos de trabajo de aplicaciones web"],"fr":["Automatisation de l''envoi de formulaires web","Interaction avec des pages web dynamiques","Débogage des flux de travail d''applications web"],"de":["Automatisierung von Webformulareinreichungen","Interaktion mit dynamischen Webseiten","Fehlerbehebung von Webanwendungs-Workflows"],"pt":["Automatizar envios de formulários da web","Interagir com páginas da web dinâmicas","Depurar fluxos de trabalho de aplicativos da web"],"ru":["Автоматизировать отправку веб-форм","Взаимодействовать с динамическими веб-страницами","Отладить рабочие процессы веб-приложений"],"ar":["التحكم الآلي في إرسال أشكال الويب","التفاعل مع صفحات الويب الديناميكية","تصحيح أخطاء تدفقات عمل التطبيقات الويب"]},"limitations":{"en":["Requires TypeScript environment","Browser compatibility limitations"],"zh":["需要TypeScript环境","浏览器兼容性限制"],"ja":["TypeScript環境が必要","ブラウザーの互換性制限"],"ko":["TypeScript 환경 필요","브라우저 호환성 제한"],"es":["Requiere entorno de TypeScript","Limitaciones de compatibilidad del navegador"],"fr":["Nécessite un environnement TypeScript","Limitations de compatibilité du navigateur"],"de":["Benötigt eine TypeScript-Umgebung","Einschränkungen der Browser-Kompatibilität"],"pt":["Requer ambiente TypeScript","Limitações de compatibilidade de navegador"],"ru":["Требуется среда TypeScript","Ограничения совместимости браузера"],"ar":["يتطلب بيئة TypeScript","قيود متعلقّة بتوافق المتصفح"]},"version":4},"contentHash":"bb56836161e6742c3da245b775c194164a202b4580deabe109dc6e66e3356d47","qualityScore":60}');
