INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('rzx007/nanobot-ts/agent-browser', 'agent-browser', 'rzx007', 'nanobot-ts', 'community', 'agent-browser rzx007 nanobot-ts community ai-agent nanobot nanobot-ts agent-browser is a TypeScript-based personal AI assistant framework for ultra-lightweight browser automation, benefiting developers and testers. It enables automated browsing and interaction with web pages. agent-browser 是一个用于浏览器自动化的 AI 框架，支持导航、快照和交互等功能 agent-browser は、ナビゲーション、スナップショット、インタラクションなどの機能をサポートするブラウザ自動化の AI フレームワークです agent-browser는 네비게이션, 스냅샷, 상호작용 등을 지원하는 브라우저 자동화용 AI 프레임워크입니다 Agent-browser es un framework de asistente de IA personal para la automatización de navegadores, que permite la interacción con elementos de la página web. Agent-browser est un framework d''assistant de IA personnel pour l''automatisation des navigateurs, qui permet l''interaction avec les éléments de la page web. Agent-browser ist ein Framework für persönliche IA-Assistenten zur Browser-Automatisierung, das die Interaktion mit Elementen der Webseite ermöglicht. O agent-browser é um framework de assistente de IA ultra-leve para automação de navegador com TypeScript e nanobot-ts. Agent-browser - это ультралёгкий фреймворк помощника ИИ для автоматизации браузера с помощью TypeScript и nanobot-ts. agent-browser هو إطار عمل مساعد ذكاء اصطناعي خفيف الوزن لتحكم المتصفح باستخدام TypeScript و nanobot-ts. how to use agent-browser agent-browser setup guide agent-browser vs nanobot agent-browser install what is agent-browser browser automation with agent-browser agent-browser alternative agent-browser tutorial agent-browser AI 浏览器自动化 nanobot TypeScript 浏览器自动化框架 AI 工具 个人 AI 助手 Navigates to web pages using ''agent-browser open'' command Captures snapshots of web pages with ''agent-browser snapshot'' command Enables interaction with web page elements using refs like ''@e1'', ''@e2'' Supports re-snapshotting after navigation or DOM changes Utilizes TypeScript for ultra-lightweight browser automation agent-browser is an ultra-lightweight personal AI assistant framework for browser automation, utilizing TypeScript and commands like ''agent-browser open'' and ''agent-browser snapshot'' for navigation and interaction');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('JustinWangJP/cc-agent-teams-action-monitor/prompt-engineering-patterns', 'community', 'JustinWangJP', 'cc-agent-teams-action-monitor', 'JustinWangJP/cc-agent-teams-action-monitor', 'prompt-engineering-patterns', 1, 0, 60, '2026-03-05T09:02:22Z', '2026-03-06T07:19:56.421Z', '747cb530259ee0d6f77d9b57fd649ec49c292f7a9808939f5a64cd0aa7d8f4c6', '{"id":"JustinWangJP/cc-agent-teams-action-monitor/prompt-engineering-patterns","name":"prompt-engineering-patterns","description":{"en":"The prompt-engineering-patterns skill helps developers maximize LLM performance, reliability, and controllability by providing advanced techniques for designing complex prompts and optimizing prompt performance.","zh":"Prompt Engineering Patterns 是一种高级提示工程技术，用于优化 LLM 性能和可靠性。该技术包括设计复杂提示、优化提示性能和一致性等","ja":"Prompt Engineering Patterns は、AIエージェントの性能を最大化するための高度なプロンプトエンジニアリング技術です","ko":"Prompt Engineering Patterns는 LLM 성능과 안정성을 최적화하기 위한 고급提示 엔지니어링 기술입니다","es":"Los patrones de ingeniería de prompt permiten maximizar el rendimiento y la confiabilidad de los modelos de lenguaje grande","fr":"Les modèles de conception de prompt permettent d''optimiser les performances et la fiabilité des modèles de langage","de":"Prompt-Engineering-Muster ermöglichen die Maximierung der Leistung und Zuverlässigkeit von Sprachmodellen","pt":"O padrão de engenharia de prompt é uma técnica avançada para maximizar o desempenho e a confiabilidade das aplicações LLM.","ru":"Шаблоны инженерии промтов - это продвинутая техника для максимизации производительности и надежности приложений LLM.","ar":"نمط هندسة البرمجة هو تقنية متقدمة لتعزيز أداء وتوفر تطبيقات LLM."},"seo":{"title":{"en":"prompt-engineering-patterns: Mastering LLM Performance fo...","zh":"Prompt Engineering Patterns 设置指南 - 优化 LLM 性能","ja":"Prompt Engineering Patterns のベストプラクティス - AIエージェントの強化","ko":"Prompt Engineering Patterns 구축 가이드 - LLM 성능 최적화","es":"Guía de Patrones de Ingeniería de Prompt para Agentes de IA","fr":"Guide des Modèles de Conception de Prompt pour les Agents...","de":"Leitfaden für Prompt-Engineering-Muster für KI-Agents","pt":"Padrões de Engenharia de Prompt: Guia de Configuração par...","ru":"Шаблоны инженерии промтов: Руководство по настройке для И...","ar":"نماذج هندسة البرمجة: دليل الإعداد لأدوات الذكاء الاصطناعي"},"description":{"en":"Unlock advanced prompt engineering techniques for production LLM applications. Learn how to optimize prompt performance, implement structured reasoning patte...","zh":"了解 Prompt Engineering Patterns 的技术细节，优化 LLM 性能和可靠性，实现高级提示工程技术","ja":"AIエージェントの性能を最大化するために、Prompt Engineering Patterns の技術的な側面を学びましょう","ko":"LLM 성능과 안정성을 최적화하기 위한 Prompt Engineering Patterns의 기술적 세부사항을 알아보세요","es":"Aprende a maximizar el rendimiento de los modelos de lenguaje grande con patrones de ingeniería de prompt avanzados","fr":"Améliorez les performances des modèles de langage avec des modèles de conception de prompt avancés","de":"Erhöhen Sie die Leistung von Sprachmodellen mit fortschrittlichen Prompt-Engineering-Mustern","pt":"Aprenda a maximizar o desempenho e a confiabilidade das aplicações LLM com padrões de engenharia de prompt avançados","ru":"Узнайте, как максимизировать производительность и надежность приложений LLM с помощью продвинутых шаблонов инженерии промтов","ar":"تعلم كيفية تعزيز أداء وتوفر تطبيقات LLM باستخدام أنماط هندسة البرمجة المتقدمة"},"definition":{"en":"prompt-engineering-patterns is a skill that enables developers to master advanced prompt engineering techniques for production LLM applications, including structured reasoning patterns and few-shot learning systems.","zh":"Prompt Engineering Patterns 是一种用于优化 LLM 性能和可靠性的提示工程技术","ja":"Prompt Engineering Patterns は、AIエージェントの性能を向上させるためのプロンプトエンジニアリング技術です","ko":"Prompt Engineering Patterns는 LLM 성능과 안정성을 최적화하기 위한 기술입니다","es":"Un patrón de ingeniería de prompt es una técnica para diseñar entradas de modelo de lenguaje para maximizar su rendimiento","fr":"Un modèle de conception de prompt est une technique pour concevoir des entrées de modèle de langage pour maximiser ses performances","de":"Ein Prompt-Engineering-Muster ist eine Technik zum Entwerfen von Sprachmodell-Eingaben für maximale Leistung","pt":"Padrão de engenharia de prompt é uma técnica para projetar prompts complexos para aplicações LLM","ru":"Шаблон инженерии промтов - это техника для проектирования сложных промтов для приложений LLM","ar":"نمط هندسة البرمجة هو تقنية لتصميم برمجات معقدة لتطبيقات LLM"},"features":{"en":["Designing complex prompts for production LLM applications","Optimizing prompt performance and consistency","Implementing structured reasoning patterns (chain-of-thought, tree-of-thought)","Building few-shot learning systems with dynamic example selection","Creating reusable prompt templates with variable interpolation","Debugging prompt performance issues"],"zh":["设计复杂提示","优化提示性能和一致性","实现结构化推理模式（chain-of-thought、tree-of-thought）","构建少样本学习系统","创建可重用提示模板"],"ja":["複雑なプロンプトの設計","プロンプト性能と一貫性の最適化","構造化推論パターン（chain-of-thought、tree-of-thought）を実現","少샘플学習システムの構築","再利用可能なプロンプトテンプレートの作成"],"ko":["복잡한 프롬프트 설계","프롬프트 성능과 일관성 최적화","구조화된 추론 패턴 구현","소량 샘플 학습 시스템 구축","재사용 가능한 프롬프트 템플릿 생성"],"es":["Diseño de prompts complejos para aplicaciones de producción","Optimización del rendimiento y la consistencia de los prompts","Implementación de patrones de razonamiento estructurado","Creación de sistemas de aprendizaje con pocos ejemplos","Desarrollo de plantillas de prompt reutilizables"],"fr":["Conception de prompts complexes pour les applications de production","Optimisation des performances et de la cohérence des prompts","Mise en œuvre de modèles de raisonnement structuré","Création de systèmes d''apprentissage avec peu d''exemples","Développement de modèles de prompt réutilisables"],"de":["Entwurf komplexer Prompts für Produktionsanwendungen","Optimierung der Leistung und Konsistenz von Prompts","Implementierung von Mustern für strukturiertes Denken","Erstellung von Lernsystemen mit wenigen Beispielen","Entwicklung von wiederverwendbaren Prompt-Vorlagen"],"pt":["Criação de prompts complexos para aplicações LLM de produção","Otimização do desempenho e consistência dos prompts","Implementação de padrões de raciocínio estruturados","Criação de sistemas de aprendizado com exemplo dinâmico","Criação de modelos de prompt reutilizáveis com interpolação de variáveis"],"ru":["Создание сложных промтов для приложений LLM производства","Оптимизация производительности и согласованности промтов","Реализация структурированных шаблонов рассуждений","Создание систем обучения с динамическим выбором примеров","Создание многократно используемых шаблонов промтов с интерполяцией переменных"],"ar":["إنشاء برمجات معقدة لتطبيقات LLM الإنتاج","تحسين أداء وتوافق البرمجات","تنفيذ أنماط التفكير المنظمة","إنشاء أنظمة التعلم مع اختيار الأمثلة الديناميكي","إنشاء قوالب برمجة قابلة لإعادة الاستخدام مع استبدال المتغيرات"]},"keywords":{"en":["how to use prompt-engineering-patterns","what is prompt-engineering-patterns","prompt-engineering-patterns alternative","prompt-engineering-patterns vs LLM","prompt-engineering-patterns install","prompt-engineering-patterns setup guide","LLM performance optimization","structured reasoning patterns","few-shot learning systems"],"zh":["Prompt Engineering Patterns","LLM 性能优化","提示工程技术","AIエージェント","结构化推理","少样本学习"],"ja":["Prompt Engineering Patterns","AIエージェントの性能向上","プロンプトエンジニアリング技術","構造化推論","少샘플学習","AIツール"],"ko":["Prompt Engineering Patterns","LLM 성능 최적화","프롬프트 엔지니어링 기술","AI 에이전트","구조화된 추론","소량 샘플 학습"],"es":["patrones de ingeniería de prompt","agentes de ia","modelos de lenguaje grande","diseño de prompts","optimización de rendimiento","aprendizaje con pocos ejemplos","herramientas de ia","tecnologías de ia","desarrollo de ia"],"fr":["modèles de conception de prompt","agents d''ia","modèles de langage","conception de prompts","optimisation des performances","apprentissage avec peu d''exemples","outils d''ia","technologies d''ia","développement d''ia"],"de":["Prompt-Engineering-Muster","KI-Agents","Sprachmodelle","Prompt-Entwurf","Leistungsoptimierung","Lernen mit wenigen Beispielen","KI-Tools","KI-Technologien","KI-Entwicklung"],"pt":["padrões de engenharia de prompt","aplicações LLM","prompts complexos","otimização de desempenho","raciocínio estruturado","aprendizado com exemplo dinâmico","modelos de prompt reutilizáveis"],"ru":["шаблоны инженерии промтов","приложения LLM","сложные промты","оптимизация производительности","структурированные шаблоны рассуждений","обучение с динамическим выбором примеров","многократно используемые шаблоны промтов"],"ar":["نماذج هندسة البرمجة","تطبيقات LLM","برمجات معقدة","تحسين الأداء","أنماط التفكير المنظمة","التعلم مع اختيار الأمثلة الديناميكي","قوالب برمجة قابلة لإعادة الاستخدام"]}},"owner":"JustinWangJP","repo":"cc-agent-teams-action-monitor","repoPath":"JustinWangJP/cc-agent-teams-action-monitor","stars":1,"forks":0,"updatedAt":"2026-03-05T09:02:22Z","topics":["agent-teams","claude-code","dashboard","skills"],"category":"community","skillMd":{"name":"prompt-engineering-patterns","description":"Master advanced prompt engineering techniques to maximize LLM performance, reliability, and controllability in production. Use when optimizing prompts, improving LLM outputs, or designing production prompt templates.","bodyPreview":"# Prompt Engineering Patterns\n\nMaster advanced prompt engineering techniques to maximize LLM performance, reliability, and controllability.\n\n## When to Use This Skill\n\n- Designing complex prompts for production LLM applications\n- Optimizing prompt performance and consistency\n- Implementing structured reasoning patterns (chain-of-thought, tree-of-thought)\n- Building few-shot learning systems with dynamic example selection\n- Creating reusable prompt templates with variable interpolation\n- Debuggin","body":"# Prompt Engineering Patterns\n\nMaster advanced prompt engineering techniques to maximize LLM performance, reliability, and controllability.\n\n## When to Use This Skill\n\n- Designing complex prompts for production LLM applications\n- Optimizing prompt performance and consistency\n- Implementing structured reasoning patterns (chain-of-thought, tree-of-thought)\n- Building few-shot learning systems with dynamic example selection\n- Creating reusable prompt templates with variable interpolation\n- Debugging and refining prompts that produce inconsistent outputs\n- Implementing system prompts for specialized AI assistants\n- Using structured outputs (JSON mode) for reliable parsing\n\n## Core Capabilities\n\n### 1. Few-Shot Learning\n\n- Example selection strategies (semantic similarity, diversity sampling)\n- Balancing example count with context window constraints\n- Constructing effective demonstrations with input-output pairs\n- Dynamic example retrieval from knowledge bases\n- Handling edge cases through strategic example selection\n\n### 2. Chain-of-Thought Prompting\n\n- Step-by-step reasoning elicitation\n- Zero-shot CoT with \"Let''s think step by step\"\n- Few-shot CoT with reasoning traces\n- Self-consistency techniques (sampling multiple reasoning paths)\n- Verification and validation steps\n\n### 3. Structured Outputs\n\n- JSON mode for reliable parsing\n- Pydantic schema enforcement\n- Type-safe response handling\n- Error handling for malformed outputs\n\n### 4. Prompt Optimization\n\n- Iterative refinement workflows\n- A/B testing prompt variations\n- Measuring prompt performance metrics (accuracy, consistency, latency)\n- Reducing token usage while maintaining quality\n- Handling edge cases and failure modes\n\n### 5. Template Systems\n\n- Variable interpolation and formatting\n- Conditional prompt sections\n- Multi-turn conversation templates\n- Role-based prompt composition\n- Modular prompt components\n\n### 6. System Prompt Design\n\n- Setting model behavior and constraints\n- Defining output formats and structure\n- Establishing role and expertise\n- Safety guidelines and content policies\n- Context setting and background information\n\n## Quick Start\n\n```python\nfrom langchain_anthropic import ChatAnthropic\nfrom langchain_core.prompts import ChatPromptTemplate\nfrom pydantic import BaseModel, Field\n\n# Define structured output schema\nclass SQLQuery(BaseModel):\n    query: str = Field(description=\"The SQL query\")\n    explanation: str = Field(description=\"Brief explanation of what the query does\")\n    tables_used: list[str] = Field(description=\"List of tables referenced\")\n\n# Initialize model with structured output\nllm = ChatAnthropic(model=\"claude-sonnet-4-6\")\nstructured_llm = llm.with_structured_output(SQLQuery)\n\n# Create prompt template\nprompt = ChatPromptTemplate.from_messages([\n    (\"system\", \"\"\"You are an expert SQL developer. Generate efficient, secure SQL queries.\n    Always use parameterized queries to prevent SQL injection.\n    Explain your reasoning briefly.\"\"\"),\n    (\"user\", \"Convert this to SQL: {query}\")\n])\n\n# Create chain\nchain = prompt | structured_llm\n\n# Use\nresult = await chain.ainvoke({\n    \"query\": \"Find all users who registered in the last 30 days\"\n})\nprint(result.query)\nprint(result.explanation)\n```\n\n## Key Patterns\n\n### Pattern 1: Structured Output with Pydantic\n\n```python\nfrom anthropic import Anthropic\nfrom pydantic import BaseModel, Field\nfrom typing import Literal\nimport json\n\nclass SentimentAnalysis(BaseModel):\n    sentiment: Literal[\"positive\", \"negative\", \"neutral\"]\n    confidence: float = Field(ge=0, le=1)\n    key_phrases: list[str]\n    reasoning: str\n\nasync def analyze_sentiment(text: str) -> SentimentAnalysis:\n    \"\"\"Analyze sentiment with structured output.\"\"\"\n    client = Anthropic()\n\n    message = client.messages.create(\n        model=\"claude-sonnet-4-6\",\n        max_tokens=500,\n        messages=[{\n            \"role\": \"user\",\n            \"content\": f\"\"\"Analyze the sentiment of this text.\n\nText: {text}\n\nRespond with JSON matching this schema:\n{{\n    \"sentiment\": \"positive\" | \"negative\" | \"neutral\",\n    \"confidence\": 0.0-1.0,\n    \"key_phrases\": [\"phrase1\", \"phrase2\"],\n    \"reasoning\": \"brief explanation\"\n}}\"\"\"\n        }]\n    )\n\n    return SentimentAnalysis(**json.loads(message.content[0].text))\n```\n\n### Pattern 2: Chain-of-Thought with Self-Verification\n\n```python\nfrom langchain_core.prompts import ChatPromptTemplate\n\ncot_prompt = ChatPromptTemplate.from_template(\"\"\"\nSolve this problem step by step.\n\nProblem: {problem}\n\nInstructions:\n1. Break down the problem into clear steps\n2. Work through each step showing your reasoning\n3. State your final answer\n4. Verify your answer by checking it against the original problem\n\nFormat your response as:\n## Steps\n[Your step-by-step reasoning]\n\n## Answer\n[Your final answer]\n\n## Verification\n[Check that your answer is correct]\n\"\"\")\n```\n\n### Pattern 3: Few-Shot with Dynamic Example Selection\n\n```python\nfrom langchain_voyageai import VoyageAIEmbeddings\nfrom langchain_core.example_selectors import SemanticSimilarityExampleSelector\nfrom langchain_chroma import Chroma\n\n# Create example selector with semantic similarity\nexample_selector = SemanticSimilarityExampleSelector.from_examples(\n    examples=[\n        {\"input\": \"How do I reset my password?\", \"output\": \"Go to Settings > Security > Reset Password\"},\n        {\"input\": \"Where can I see my order history?\", \"output\": \"Navigate to Account > Orders\"},\n        {\"input\": \"How do I contact support?\", \"output\": \"Click Help > Contact Us or email support@example.com\"},\n    ],\n    embeddings=VoyageAIEmbeddings(model=\"voyage-3-large\"),\n    vectorstore_cls=Chroma,\n    k=2  # Select 2 most similar examples\n)\n\nasync def get_few_shot_prompt(query: str) -> str:\n    \"\"\"Build prompt with dynamically selected examples.\"\"\"\n    examples = await example_selector.aselect_examples({\"input\": query})\n\n    examples_text = \"\\n\".join(\n        f\"User: {ex[''input'']}\\nAssistant: {ex[''output'']}\"\n        for ex in examples\n    )\n\n    return f\"\"\"You are a helpful customer support assistant.\n\nHere are some example interactions:\n{examples_text}\n\nNow respond to this query:\nUser: {query}\nAssistant:\"\"\"\n```\n\n### Pattern 4: Progressive Disclosure\n\nStart with simple prompts, add complexity only when needed:\n\n```python\nPROMPT_LEVELS = {\n    # Level 1: Direct instruction\n    \"simple\": \"Summarize this article: {text}\",\n\n    # Level 2: Add constraints\n    \"constrained\": \"\"\"Summarize this article in 3 bullet points, focusing on:\n- Key findings\n- Main conclusions\n- Practical implications\n\nArticle: {text}\"\"\",\n\n    # Level 3: Add reasoning\n    \"reasoning\": \"\"\"Read this article carefully.\n1. First, identify the main topic and thesis\n2. Then, extract the key supporting points\n3. Finally, summarize in 3 bullet points\n\nArticle: {text}\n\nSummary:\"\"\",\n\n    # Level 4: Add examples\n    \"few_shot\": \"\"\"Read articles and provide concise summaries.\n\nExample:\nArticle: \"New research shows that regular exercise can reduce anxiety by up to 40%...\"\nSummary:\n• Regular exercise reduces anxiety by up to 40%\n• 30 minutes of moderate activity 3x/week is sufficient\n• Benefits appear within 2 weeks of starting\n\nNow summarize this article:\nArticle: {text}\n\nSummary:\"\"\"\n}\n```\n\n### Pattern 5: Error Recovery and Fallback\n\n```python\nfrom pydantic import BaseModel, ValidationError\nimport json\n\nclass ResponseWithConfidence(BaseModel):\n    answer: str\n    confidence: float\n    sources: list[str]\n    alternative_interpretations: list[str] = []\n\nERROR_RECOVERY_PROMPT = \"\"\"\nAnswer the question based on the context provided.\n\nContext: {context}\nQuestion: {question}\n\nInstructions:\n1. If you can answer confidently (>0.8), provide a direct answer\n2. If you''re somewhat confident (0.5-0.8), provide your best answer with caveats\n3. If you''re uncertain (<0.5), explain what information is missing\n4. Always provide alternative interpretations if the question is ambiguous\n\nRespond in JSON:\n{{\n    \"answer\": \"your answer or ''I cannot determine this from the context''\",\n    \"confidence\": 0.0-1.0,\n    \"sources\": [\"relevant context excerpts\"],\n    \"alternative_interpretations\": [\"if question is ambiguous\"]\n}}\n\"\"\"\n\nasync def answer_with_fallback(\n    context: str,\n    question: str,\n    llm\n) -> ResponseWithConfidence:\n    \"\"\"Answer with error recovery and fallback.\"\"\"\n    prompt = ERROR_RECOVERY_PROMPT.format(context=context, question=question)\n\n    try:\n        response = await llm.ainvoke(prompt)\n        return ResponseWithConfidence(**json.loads(response.content))\n    except (json.JSONDecodeError, ValidationError) as e:\n        # Fallback: try to extract answer without structure\n        simple_prompt = f\"Based on: {context}\\n\\nAnswer: {question}\"\n        simple_response = await llm.ainvoke(simple_prompt)\n        return ResponseWithConfidence(\n            answer=simple_response.content,\n            confidence=0.5,\n            sources=[\"fallback extraction\"],\n            alternative_interpretations=[]\n        )\n```\n\n### Pattern 6: Role-Based System Prompts\n\n```python\nSYSTEM_PROMPTS = {\n    \"analyst\": \"\"\"You are a senior data analyst with expertise in SQL, Python, and business intelligence.\n\nYour responsibilities:\n- Write efficient, well-documented queries\n- Explain your analysis methodology\n- Highlight key insights and recommendations\n- Flag any data quality concerns\n\nCommunication style:\n- Be precise and technical when discussing methodology\n- Translate technical findings into business impact\n- Use clear visualizations when helpful\"\"\",\n\n    \"assistant\": \"\"\"You are a helpful AI assistant focused on accuracy and clarity.\n\nCore principles:\n- Always cite sources when making factual claims\n- Acknowledge uncertainty rather than guessing\n- Ask clarifying questions when the request is ambiguous\n- Provide step-by-step explanations for complex topics\n\nConstraints:\n- Do not provide medical, legal, or financial advice\n- Redirect harmful requests appropriately\n- Protect user privacy\"\"\",\n\n    \"code_reviewer\": \"\"\"You are a senior software engineer conducting code reviews.\n\nReview criteria:\n- Correctness: Does the code work as intended?\n- Security: Are there any vulnerabilities?\n- Performance: Are there efficiency concerns?\n- Maintainability: Is the code readable and well-structured?\n- Best practices: Does it follow language idioms?\n\nOutput format:\n1. Summary assessment (approve/request changes)\n2. Critical issues (must fix)\n3. Suggestions (nice to have)\n4. Positive feedback (what''s done well)\"\"\"\n}\n```\n\n## Integration Patterns\n\n### With RAG Systems\n\n```python\nRAG_PROMPT = \"\"\"You are a knowledgeable assistant that answers questions based on provided context.\n\nContext (retrieved from knowledge base):\n{context}\n\nInstructions:\n1. Answer ONLY based on the provided context\n2. If the context doesn''t contain the answer, say \"I don''t have information about that in my knowledge base\"\n3. Cite specific passages using [1], [2] notation\n4. If the question is ambiguous, ask for clarification\n\nQuestion: {question}\n\nAnswer:\"\"\"\n```\n\n### With Validation and Verification\n\n```python\nVALIDATED_PROMPT = \"\"\"Complete the following task:\n\nTask: {task}\n\nAfter generating your response, verify it meets ALL these criteria:\n✓ Directly addresses the original request\n✓ Contains no factual errors\n✓ Is appropriately detailed (not too brief, not too verbose)\n✓ Uses proper formatting\n✓ Is safe and appropriate\n\nIf verification fails on any criterion, revise before responding.\n\nResponse:\"\"\"\n```\n\n## Performance Optimization\n\n### Token Efficiency\n\n```python\n# Before: Verbose prompt (150+ tokens)\nverbose_prompt = \"\"\"\nI would like you to please take the following text and provide me with a comprehensive\nsummary of the main points. The summary should capture the key ideas and important details\nwhile being concise and easy to understand.\n\"\"\"\n\n# After: Concise prompt (30 tokens)\nconcise_prompt = \"\"\"Summarize the key points concisely:\n\n{text}\n\nSummary:\"\"\"\n```\n\n### Caching Common Prefixes\n\n```python\nfrom anthropic import Anthropic\n\nclient = Anthropic()\n\n# Use prompt caching for repeated system prompts\nresponse = client.messages.create(\n    model=\"claude-sonnet-4-6\",\n    max_tokens=1000,\n    system=[\n        {\n            \"type\": \"text\",\n            \"text\": LONG_SYSTEM_PROMPT,\n            \"cache_control\": {\"type\": \"ephemeral\"}\n        }\n    ],\n    messages=[{\"role\": \"user\", \"content\": user_query}]\n)\n```\n\n## Best Practices\n\n1. **Be Specific**: Vague prompts produce inconsistent results\n2. **Show, Don''t Tell**: Examples are more effective than descriptions\n3. **Use Structured Outputs**: Enforce schemas with Pydantic for reliability\n4. **Test Extensively**: Evaluate on diverse, representative inputs\n5. **Iterate Rapidly**: Small changes can have large impacts\n6. **Monitor Performance**: Track metrics in production\n7. **Version Control**: Treat prompts as code with proper versioning\n8. **Document Intent**: Explain why prompts are structured as they are\n\n## Common Pitfalls\n\n- **Over-engineering**: Starting with complex prompts before trying simple ones\n- **Example pollution**: Using examples that don''t match the target task\n- **Context overflow**: Exceeding token limits with excessive examples\n- **Ambiguous instructions**: Leaving room for multiple interpretations\n- **Ignoring edge cases**: Not testing on unusual or boundary inputs\n- **No error handling**: Assuming outputs will always be well-formed\n- **Hardcoded values**: Not parameterizing prompts for reuse\n\n## Success Metrics\n\nTrack these KPIs for your prompts:\n\n- **Accuracy**: Correctness of outputs\n- **Consistency**: Reproducibility across similar inputs\n- **Latency**: Response time (P50, P95, P99)\n- **Token Usage**: Average tokens per request\n- **Success Rate**: Percentage of valid, parseable outputs\n- **User Satisfaction**: Ratings and feedback\n\n## Resources\n\n- [Anthropic Prompt Engineering Guide](https://docs.anthropic.com/en/docs/build-with-claude/prompt-engineering)\n- [Claude Prompt Caching](https://docs.anthropic.com/en/docs/build-with-claude/prompt-caching)\n- [OpenAI Prompt Engineering](https://platform.openai.com/docs/guides/prompt-engineering)\n- [LangChain Prompts](https://python.langchain.com/docs/concepts/prompts/)\n"},"lastSynced":"2026-03-06T07:19:56.421Z","agentAnalysis":{"suitability":{"en":"Ideal for Advanced Language Model Agents requiring sophisticated prompt engineering techniques to maximize performance and reliability.","zh":"非常适合需要复杂提示工程技术来最大化性能和可靠性的高级语言模型Agent。","ja":"パフォーマンスと信頼性を最大化するために高度なプロンプトエンジニアリング技術を必要とする高度な言語モデルAgentに理想的です。","ko":"성능과 신뢰성을 극대화하기 위해 정교한 프롬프트 엔지니어링 기술이 필요한 고급 언어 모델 에이전트에 이상적입니다.","es":"Ideal para Agentes de Modelo de Lenguaje Avanzado que requieren técnicas de ingeniería de prompts sofisticadas para maximizar el rendimiento y la confiabilidad.","fr":"Idéal pour les Agents de Modèle de Langage Avancé nécessitant des techniques d''ingénierie de prompts sophistiquées pour maximiser les performances et la fiabilité.","de":"Ideal für Advanced Language Model Agents, die anspruchsvolle Prompt-Engineering-Techniken erfordern, um Leistung und Zuverlässigkeit zu maximieren.","pt":"Ideal para Agentes de Modelo de Linguagem Avançados que exigem técnicas de engenharia de prompt sofisticadas para maximizar o desempenho e a confiabilidade.","ru":"Идеально подходит для продвинутых агентов языковых моделей, требующих сложных техник инженерии запросов для максимизации производительности и надежности.","ar":"مثالي للوكلاء النموذجية اللغوية المتقدمة الذين يتطلبون تقنيات هندسة الاستعلامات المتطورة لتحقيق أقصى أداء وموثوقية."},"recommendation":{"en":"Empowers agents to design complex prompts, optimize prompt performance, and implement structured reasoning patterns like chain-of-thought and tree-of-thought, leveraging techniques such as few-shot learning and dynamic example selection.","zh":"使Agent能够设计复杂的提示，优化提示性能，并利用小样本学习和动态示例选择等技术，实现思维链和思维树等结构化推理模式。","ja":"Agentが複雑なプロンプトを設計し、プロンプトのパフォーマンスを最適化し、few-shot学習や動的例選択などの技術を活用して、連鎖思考や木構造思考のような構造化された推論パターンを実装することを可能にします。","ko":"에이전트가 복잡한 프롬프트를 설계하고, 프롬프트 성능을 최적화하며, few-shot 학습 및 동적 예제 선택과 같은 기술을 활용하여 사고의 연쇄(chain-of-thought) 및 사고의 나무(tree-of-thought)와 같은 구조화된 추론 패턴을 구현할 수 있도록 합니다.","es":"Habilita a los agentes a diseñar prompts complejos, optimizar el rendimiento de los prompts y implementar patrones de razonamiento estructurados como cadena de pensamiento y árbol de pensamiento, aprovechando técnicas como few-shot learning y selección dinámica de ejemplos.","fr":"Permet aux agents de concevoir des prompts complexes, d''optimiser les performances des prompts et de mettre en œuvre des modèles de raisonnement structurés tels que la chaîne de pensée et l''arbre de pensée, en exploitant des techniques telles que l''apprentissage à quelques exemples et la sélection dynamique d''exemples.","de":"Ermächtigt Agenten, komplexe Prompts zu entwerfen, die Leistung von Prompts zu optimieren und strukturierte Denkmuster wie Denkverkettung und Denkbaum umzusetzen, indem Techniken wie few-shot learning und dynamische Beispielauswahl genutzt werden.","pt":"Habilita os agentes a projetar prompts complexos, otimizar o desempenho dos prompts e implementar padrões de raciocínio estruturados, como cadeia de pensamento e árvore de pensamento, aproveitando técnicas como aprendizado com poucos exemplos e seleção dinâmica de exemplos.","ru":"Наделяет агентов возможностью проектировать сложные запросы, оптимизировать производительность запросов и реализовывать структурированные модели рассуждений, такие как цепочка мыслей и дерево мыслей, используя такие техники, как обучение на нескольких примерах и динамический выбор примеров.","ar":"تمكّن الوكلاء من تصميم استعلامات معقدة وتحسين أداء الاستعلامات وتنفيذ أنماط استدلالية منظمة، مثل سلسلة التفكير وشجرة التفكير، بالاستفادة من تقنيات مثل التعلم بالعديد من الأمثلة والاختيار الديناميكي للأمثلة."},"useCases":{"en":["Designing complex prompts for production LLM applications","Optimizing prompt performance and consistency","Implementing structured reasoning patterns for advanced inference"],"zh":["为生产环境的LLM应用程序设计复杂提示","优化提示的性能和一致性","为高级推理实现结构化推理模式"],"ja":["本番LLMアプリケーションのための複雑なプロンプトの設計","プロンプトのパフォーマンスと一貫性の最適化","高度な推論のための構造化された推論パターンの実装"],"ko":["프로덕션 LLM 애플리케이션을 위한 복잡한 프롬프트 설계","프롬프트 성능과 일관성 최적화","고급 추론을 위한 구조화된 추론 패턴 구현"],"es":["Diseñar prompts complejos para aplicaciones LLM de producción","Optimizar el rendimiento y la consistencia de los prompts","Implementar patrones de razonamiento estructurados para inferencia avanzada"],"fr":["Concevoir des prompts complexes pour les applications LLM de production","Optimiser les performances et la cohérence des prompts","Mettre en œuvre des modèles de raisonnement structurés pour l''inférence avancée"],"de":["Komplexe Prompts für Produktions-LLM-Anwendungen entwerfen","Die Leistung und Konsistenz von Prompts optimieren","Strukturierte Denkmuster für fortschrittliche Inferenz implementieren"],"pt":["Projeto de prompts complexos para aplicações de produção de LLM","Otimização do desempenho e consistência dos prompts","Implementação de padrões de raciocínio estruturados para inferência avançada"],"ru":["Проектирование сложных запросов для приложений производственной модели LLM","Оптимизация производительности и согласованности запросов","Реализация структурированных моделей рассуждений для продвинутого вывода"],"ar":["تصميم استعلامات معقدة لتطبيقات الإنتاج نموذج LLM","تحسين أداء الاستعلامات والاتساق","تنفيذ أنماط استدلالية منظمة للاستدلال المتقدم"]},"limitations":{"en":["Requires understanding of LLM architectures and prompt engineering principles","May necessitate significant computational resources for large-scale prompt optimization"],"zh":["需要理解LLM架构和提示工程原理","大规模提示优化可能需要大量的计算资源"],"ja":["LLMアーキテクチャとプロンプトエンジニアリングの原則の理解が必要","大規模なプロンプト最適化には相当な計算リソースが必要となる場合がある"],"ko":["LLM 아키텍처와 프롬프트 엔지니어링 원리에 대한 이해가 필요함","대규모 프롬프트 최적화에는 상당한 컴퓨팅 리소스가 필요할 수 있음"],"es":["Requiere comprensión de las arquitecturas LLM y los principios de ingeniería de prompts","Puede necesitar recursos computacionales significativos para la optimización de prompts a gran escala"],"fr":["Nécessite une compréhension des architectures LLM et des principes d''ingénierie de prompts","Peut nécessiter des ressources informatiques importantes pour l''optimisation de prompts à grande échelle"],"de":["Erfordert das Verständnis von LLM-Architekturen und Prompt-Engineering-Prinzipien","Kann erhebliche Rechenressourcen für die Optimierung von Prompts im großen Maßstab erfordern"],"pt":["Exige compreensão das arquiteturas de LLM e princípios de engenharia de prompt","Pode necessitar de recursos computacionais significativos para otimização de prompts em larga escala"],"ru":["Требует понимания архитектур LLM и принципов инженерии запросов","Может потребовать значительных вычислительных ресурсов для оптимизации запросов в крупном масштабе"],"ar":["يتطلب فهمًا للهياكل نموذج LLM ومبادئ هندسة الاستعلامات","قد يحتاج إلى موارد حسابية كبيرة لتحسين الاستعلامات على نطاق واسع"]},"version":4},"contentHash":"747cb530259ee0d6f77d9b57fd649ec49c292f7a9808939f5a64cd0aa7d8f4c6","qualityScore":60}');
